def t_prepush_passes_touched_list_to_doctor():
    """推送前的閘要把「這次推了哪些檔」算給自檢,別人的逾期預告才不會擋到你的推送。

    這支是真跑整支 pre-push,不是檢查腳本裡有沒有那個字串——只比對字串的話,
    把旗標拼錯、或算出來的清單是空的,測試照樣綠(測試假綠形態第①型)。
    翻紅釘:把掛鉤裡傳清單那行拿掉 → ③紅(沒碰到的那條會把推送擋下來)。
    """
    import subprocess as _sp, os as _os, datetime, tempfile
    pre_push = str(Path(__file__).resolve().parent / "hooks" / "pre-push")
    lumos_real = str(Path(__file__).resolve().parent / "lumos")
    old = (datetime.date.today() - datetime.timedelta(days=3)).isoformat()

    def _build(d, home_about, touch_file):
        g = lambda *a: _sp.run(["git", *a], cwd=d, capture_output=True, text=True)
        g("init", "-q", "-b", "main"); g("config", "user.email", "t@t.t"); g("config", "user.name", "t")
        vault = Path(d) / "docs" / "t-knowledge"
        for sub in ("Systems", "Verification", "Projects", "MOC"):
            (vault / sub).mkdir(parents=True, exist_ok=True)
        (vault / "MOC" / "idx.md").write_text("---\ntype: moc\n---\n# idx\n", encoding="utf-8")
        (vault / "Systems" / "Pay.md").write_text(
            f"---\ntype: system\nstatus: doing\nabout_code:\n  - {home_about}\n"
            "summary: |-\n  FLOW:a\n---\n# Pay\n", encoding="utf-8")
        (vault / "Projects" / "P.md").write_text("---\ntype: project\nstatus: doing\n---\n# P\n", encoding="utf-8")
        Path(d, "scripts").mkdir(exist_ok=True)
        (Path(d) / "scripts" / "lumos").symlink_to(lumos_real)
        _sp.run([sys.executable, lumos_real, "--vault", str(vault), "guard", "plan",
                 "Systems/Pay", "逾期的那條", "--plan", "Projects/P", "--phase", "P1",
                 "--due", old, "--why", "還沒做", "--owner", "enzo", "--name", "逾期的那條"],
                capture_output=True, text=True)
        (Path(d) / touch_file).parent.mkdir(parents=True, exist_ok=True)
        (Path(d) / touch_file).write_text("x = 1\n", encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "init")
        (Path(d) / touch_file).write_text("x = 2\n", encoding="utf-8")
        g("add", "-A"); g("commit", "-qm", "change")
        head = g("rev-parse", "HEAD").stdout.strip()
        base = g("rev-parse", "HEAD~1").stdout.strip()
        env = dict(_os.environ); env["GIT_DIR"] = str(Path(d) / ".git")
        return _sp.run(["bash", pre_push], cwd=d, env=env, capture_output=True, text=True,
                       input=f"refs/heads/main {head} refs/heads/main {base}\n")

    with tempfile.TemporaryDirectory() as d:
        r = _build(d, "app/pay.py", "app/other.py")
        check("③ 這次沒碰到那條合約管的檔 → 推送不被擋",
              r.returncode == 0, f"rc={r.returncode}\n{r.stdout[-1200:]}\n{r.stderr[-600:]}")
        check("③ 但那條還是有被列出來(不是靜音)",
              "逾期的那條" in r.stdout, r.stdout[-1200:])
    with tempfile.TemporaryDirectory() as d:
        r = _build(d, "app/pay.py", "app/pay.py")
        check("④ 這次真的碰到了 → 推送被擋下",
              r.returncode != 0, f"rc={r.returncode}\n{r.stdout[-1200:]}\n{r.stderr[-600:]}")
        check("④ 訊息說得出是你改到哪支檔踩到它",
              "app/pay.py" in r.stdout, r.stdout[-1200:])


def t_guard_overdue_local_skips_home_without_code():
    """家節點沒寫「管哪幾支檔」時,本機那一層算不出有沒有碰到,照設計不擋(CI 仍擋)。

    出身:必要合約清單_計劃〈擋的範圍〉——本機那一層的定位是窄而準,誤擋一次的代價是
    有人被卡住又解不開;算不出來就交給 CI,不會真的漏掉。
    翻紅釘:把「算不出來就不擋」改成「算不出來也擋」 → ②紅。
    """
    import datetime, re as _re
    v = mkvault()
    write(v, "Systems/NoCode.md", "type: system\nstatus: doing\nsummary: |-\n  FLOW:a", body="# NoCode\n")
    write(v, "Projects/退款_計劃.md", "type: project\nstatus: doing", body="# 退款\n")
    old = (datetime.date.today() - datetime.timedelta(days=3)).isoformat()
    _gp(v, "guard", "plan", "Systems/NoCode", "沒寫管哪幾支檔的那條", "--plan", "Projects/退款_計劃",
        "--phase", "Phase 1", "--due", old, "--why", "還沒做", "--owner", "enzo")
    touched = v.parent / "touched3.txt"
    touched.write_text("scripts/pay.py\n", encoding="utf-8")
    r = run(v, "doctor", "--ci", "--touched-from", str(touched))
    seg = _section_of(r.stdout, "S15")
    check("② 本機那一層不擋", r.returncode == 0, f"rc={r.returncode}\n" + seg)
    check("② 但還是列出來,而且講明為什麼這次沒擋",
          "沒寫管哪幾支檔的那條" in seg, seg)
    ci = run(v, "doctor", "--ci")
    check("③ CI(不給清單)照舊擋", ci.returncode != 0, ci.stdout[-400:])


def t_context_shows_planned_contract():
    """查功能節點時,預告中的合約要另起一段印出來,不能跟已生效的混在一起。

    出身:Enzo 追問「預告期間我去看那篇節點會不會看不到」。原設計把預告移出節點,
    實測發現它會掉出最顯眼的位置——而預告中的合約最該被看見,因為還沒有測試在守。
    翻紅釘:拿掉印預告那段 → ②③紅;把它併進已生效那段 → ④紅。
    """
    v = mkvault()
    write(v, "Systems/Pay.md",
          "type: system\nstatus: doing\nsummary: |-\n"
          "  KEY:★INVARIANT★ 已經生效的那條 [test:t_a] [audit:sonnet/2026-09-01]",
          body="# Pay\n")
    write(v, "Projects/退款_計劃.md", "type: project\nstatus: doing", body="# 退款\n")
    _gp(v, "guard", "plan", "Systems/Pay", "還沒做的那條", "--plan", "Projects/退款_計劃",
        "--phase", "Phase 4", "--due", "2099-12-31", "--why", "介面沒定", "--owner", "enzo")
    r = run(v, "context", "Systems/Pay")
    out = r.stdout
    check("① 查得到", r.returncode == 0, out + r.stderr)
    # ★只看「開頭那幾段提醒」,不看整份輸出★:摘要區塊本來就會原樣印出每一行,
    # 拿整份輸出當判準的話,不實作也會綠——那是假綠(2026-09-22 當場抓到並改掉)。
    head_zone = out.split("summary:", 1)[0]
    check("② 開頭那幾段提醒裡印得出預告中的合約", "還沒做的那條" in head_zone, head_zone)
    check("③ 連最遲日期一起印", "2099-12-31" in head_zone, head_zone)
    check("④ 預告另起一段,講清楚它還沒生效",
          "還沒有測試在守" in head_zone, head_zone)
    # ⑤ 不准混進「動了會壞」那一段
    head = "動手前一定要看"
    if head in head_zone:
        seg = head_zone.split(head, 1)[1].split("提醒:", 1)[0]
        check("⑤ 預告的沒混進已生效那一段", "還沒做的那條" not in seg, seg)
    else:
        check("⑤ 已生效那段還在", False, head_zone)
    check("⑥ 已生效那條照舊印在原來的位置", "已經生效的那條" in head_zone, head_zone)


def t_abandoned_excluded_and_marker_kept():
    """棄置的節點不該永遠出現在「還活著」的查詢裡;新記號要跟既有合約記號一樣留得住。

    出身:設計審 r2 指出查證表漏了「查還活著」那份寫死的收案狀態集合;
    以及長跑壓縮的白名單抓不到新記號,預告提醒會被當成可丟的散文丟掉。
    翻紅釘:把 abandoned 從收案集合拿掉 → ②紅;把新記號從壓縮白名單拿掉 → ③紅。
    """
    import importlib.util
    from importlib.machinery import SourceFileLoader
    v = mkvault()
    write(v, "Verification/棄了的.md",
          "type: verification\nstatus: abandoned\ncreated: 2026-09-22\n"
          "tags:\n  - type/verification\n  - status/abandoned\nsummary: |-\n  TEST:決定不做了",
          body="# 棄了的\n")
    write(v, "Verification/還活著的.md",
          "type: verification\nstatus: pending\ncreated: 2026-09-22\n"
          "tags:\n  - type/verification\n  - status/pending\nsummary: |-\n  TEST:還沒做",
          body="# 還活著的\n")
    r = run(v, "query", "--tag", "type/verification", "--active")
    out = r.stdout
    check("① 查得動", r.returncode == 0, out + r.stderr)
    check("② 棄置的不算還活著", "棄了的" not in out, out[:500])
    check("② 待完成的算還活著", "還活著的" in out, out[:500])

    # ★原本這裡要測「新記號有沒有進長跑壓縮白名單」,查證後拿掉★:
    # 全庫沒有任何白名單機制(只有一支唯讀的用量統計腳本會數壓縮事件),
    # 壓縮是 harness 自己做的,這個 repo 控制不了。審查席那條的前提不成立,
    # 照做等於發明一個不存在的機制。這件事寫進計劃的誠實界線,不在這裡假裝有守衛。


def t_guard_plan_hostile_claims():
    """合約那句話的惡意輸入:換行會吃掉既有合約、空白造不出東西、重複會改錯行。

    出身:代碼審 r1 四條 blocker,每一條都是審查席實際跑出來的。
    翻紅釘:拿掉換行檢查 → ②紅(而且既有合約真的會消失);拿掉完整比對 → ④紅。
    """
    v = mkvault()
    write(v, "Systems/Pay.md",
          "type: system\nstatus: doing\nsummary: |-\n"
          "  KEY:★INVARIANT★ 很重要的真合約 [test:t_a] [audit:sonnet/2026-09-01]",
          body="# Pay\n")
    write(v, "Projects/退款_計劃.md", "type: project\nstatus: doing", body="# 退款\n")
    ok_args = ["--plan", "Projects/退款_計劃", "--phase", "P4",
               "--due", "2099-12-31", "--why", "理由", "--owner", "enzo"]

    r = _gp(v, "guard", "plan", "Systems/Pay", "A\nB: 壞掉", *ok_args)
    check("① 含換行的合約要擋", r.returncode != 0, f"rc={r.returncode} {r.stdout}{r.stderr}")
    # ★真正的傷害面★:擋不住的話,這篇原本那條綁了測試又審計過的合約會整段消失
    gl = run(v, "guard", "list")
    check("② 既有的真合約還在(換行沒把摘要區塊打斷)",
          "很重要的真合約" in gl.stdout, gl.stdout[:400])

    r2 = _gp(v, "guard", "plan", "Systems/Pay", "   ", *ok_args)
    check("③ 純空白的合約要擋", r2.returncode != 0, f"rc={r2.returncode} {r2.stdout}{r2.stderr}")

    # ④ 同一篇預告兩條、前段文字相同:轉正必須改到對的那一條
    _gp(v, "guard", "plan", "Systems/Pay", "退費流程必須先做這件事情:甲案要人工核可", *ok_args, "--name", "甲案")
    _gp(v, "guard", "plan", "Systems/Pay", "退費流程必須先做這件事情:乙案要雙人覆核", *ok_args, "--name", "乙案")
    # ★前 12 字必須真的相同★:第一版用「退費規則甲/乙」,第 5 個字就不同,
    # 所以把比對改回前綴也不會紅——測不到它要測的 bug(當場植入驗證抓到)。
    gn = [x for x in (v / "Verification").glob("*.md") if "乙案" in x.stem]
    check("④ 兩條都建得起來", len(gn) == 1, str(list((v / "Verification").glob("*.md"))))
    if gn:
        r3 = run(v, "guard", "settle", "Verification/" + gn[0].stem, "--test", "t_b")
        check("④ 轉正成功", r3.returncode == 0, r3.stdout + r3.stderr)
        pay = (v / "Systems" / "Pay.md").read_text(encoding="utf-8")
        planned = [l for l in pay.split("\n") if "★INVARIANT-PLANNED★" in l]
        formal = [l for l in pay.split("\n") if "★INVARIANT★" in l and "PLANNED" not in l]
        check("④ 只有乙案被轉正", any("乙案" in l for l in formal) and not any("甲案" in l for l in formal),
              "正式:" + " | ".join(formal))
        check("④ 甲案還留在預告", any("甲案" in l for l in planned), "預告:" + " | ".join(planned))


def t_guard_abandon_wrong_home_blocks():
    """守衛節點的家被改指到別篇時,棄置要擋,不能靜默成功留下矛盾的預告行。

    翻紅釘:把 abandon 裡「找不到預告行就擋」改回靜默略過 → ②紅。
    """
    v = mkvault()
    write(v, "Systems/Pay.md", "type: system\nstatus: doing\nsummary: |-\n  FLOW:a", body="# Pay\n")
    write(v, "Systems/Other.md", "type: system\nstatus: doing\nsummary: |-\n  FLOW:b", body="# Other\n")
    write(v, "Projects/退款_計劃.md", "type: project\nstatus: doing", body="# 退款\n")
    _gp(v, "guard", "plan", "Systems/Pay", "某條合約", "--plan", "Projects/退款_計劃",
        "--phase", "P4", "--due", "2099-12-31", "--why", "理由", "--owner", "enzo")
    gp = list((v / "Verification").glob("*.md"))[0]
    gref = "Verification/" + gp.stem
    # 把家改指到另一篇(模擬手改)
    txt = gp.read_text(encoding="utf-8").replace("  - Systems/Pay", "  - Systems/Other")
    gp.write_text(txt, encoding="utf-8")
    run(v, "signoff", gref, "--note", "確認不做", "--ref", gref)
    r = run(v, "guard", "abandon", gref, "--why", "不做了")
    check("① 家對不上 → 擋", r.returncode != 0, f"rc={r.returncode} {r.stdout}{r.stderr}")
    check("② 真正的家沒被留下沒人管的預告行(因為整件事被擋住了)",
          "★INVARIANT-PLANNED★" in (v / "Systems" / "Pay.md").read_text(encoding="utf-8"),
          "預告行應該還在原地,等人先把 guards 指對")
    check("③ 墓碑也沒立(不留半套)", "status: pending" in gp.read_text(encoding="utf-8"),
          gp.read_text(encoding="utf-8")[:200])


def t_guard():
    """guard list/scaffold/bind — 對談驅動守衛 scaffold(2026-06-15)。
    需 repo_root + 真 .cs(discover_test_methods),故自建 docs/ 結構而非 mkvault。"""
    import shutil
    root = Path(tempfile.mkdtemp(prefix="gctl-guard-"))
    vault = root / "docs" / "demo-knowledge"
    for sub in ("Systems", "Verification", "Projects", "MOC"):
        (vault / sub).mkdir(parents=True)
    (vault / "MOC" / "idx.md").write_bytes("---\ntype: moc\n---\n# idx\n".encode("utf-8"))
    (vault / "Systems" / "Demo.md").write_bytes(
        ("---\ntype: system\nstatus: done\nsummary: |-\n"
        "  KEY:★INVARIANT★ 已綁的合約 [test:RealGuardX]\n"
        "  KEY:★INVARIANT★ 還沒綁的合約\n"
        "---\n# Demo\n").encode("utf-8"))
    td = root / "Demo.IntegrationTests"
    td.mkdir()
    (td / "RealGuard.cs").write_bytes(
        "using Xunit;\npublic class RealGuard {\n  [Fact]\n  public void RealGuardX() { }\n}\n"
        .encode("utf-8"))
    tpl = root / ".lumos" / "guard-templates"
    tpl.mkdir(parents=True)
    (tpl / "behavioral.tmpl").write_bytes(
        ("// {{NODE}} | {{INVARIANT}} | {{CLAIM}} | {{PREFIX}}\n"
        "public class {{CLASS}} {\n  public void {{METHOD}}() "
        "{ Assert.Fail(\"unfilled\"); }\n}\n").encode("utf-8"))
    try:
        r = run(vault, "guard", "list")
        check("guard list: real/naked 分類", "真綁 1" in r.stdout and "裸 1" in r.stdout, r.stdout)
        r = run(vault, "guard", "list", "--unbound")
        check("guard list --unbound: 列裸不列 real",
              "還沒綁的合約" in r.stdout and "已綁的合約" not in r.stdout, r.stdout)
        outd = root / "out"
        outd.mkdir()
        r = run(vault, "guard", "scaffold", "--node", "Systems/Demo", "--invariant", "還沒綁",
                "--method", "NewGuardX", "--type", "behavioral", "--claim", "具體可驗斷言",
                "--out", str(outd))
        f = outd / "NewGuardXTests.cs"
        txt = f.read_text(encoding="utf-8") if f.exists() else ""
        check("guard scaffold: 產出檔", f.exists(), r.stdout + r.stderr)
        check("guard scaffold: 預設紅燈 Assert.Fail", "Assert.Fail" in txt, txt)
        check("guard scaffold: placeholder 全替換", "{{" not in txt, txt)
        r = run(vault, "guard", "scaffold", "--node", "Systems/Demo", "--invariant", "還沒綁",
                "--method", "1bad", "--type", "behavioral", "--claim", "x", "--out", str(outd))
        check("guard scaffold: 非法 method 擋(rc2)", r.returncode == 2, r.stdout + r.stderr)
        r = run(vault, "guard", "scaffold", "--node", "Systems/Demo",
                "--invariant", "RealGuardX", "--method", "Zz", "--type", "behavioral",
                "--claim", "x", "--out", str(outd))
        check("guard scaffold: --invariant 不誤命中 [test:] 名(rc2)",
              r.returncode == 2, r.stdout + r.stderr)
        r = run(vault, "guard", "bind", "Systems/Demo", "還沒綁", "NewGuardX")
        nt = (vault / "Systems" / "Demo.md").read_text(encoding="utf-8")
        check("guard bind: [test:] 寫回 KEY 行", "[test:NewGuardX]" in nt, r.stdout + r.stderr)
        check("guard bind: 已綁行不受影響", nt.count("[test:RealGuardX]") == 1, nt)
    finally:
        shutil.rmtree(root, ignore_errors=True)


def t_guard_trace():
    """guard trace — 合約→守衛測試→Verification 證據鏈(reverse lookup)。"""
    v = mkvault()
    write(v, "Systems/Mod.md",
          "type: system\nstatus: done\nsummary: |-\n"
          "  KEY:★INVARIANT★ 某合約 [test:MyGuardTest]",
          body="# Mod\n")
    write(v, "Verification/2026-01-02_g.md", "type: verification\nstatus: pass",
          body="# g\n本守衛 MyGuardTest 跑 lab PASS\n")
    r = run(v, "guard", "trace", "Systems/Mod")
    check("guard trace: 合約→測試→Verification 鏈",
          "MyGuardTest" in r.stdout and "2026-01-02_g" in r.stdout, r.stdout)
    write(v, "Systems/Lonely.md",
          "type: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ 沒人測 [test:NobodyTestsThis]",
          body="# Lonely\n")
    r = run(v, "guard", "trace", "Systems/Lonely")
    check("guard trace: 無 Verification 提到 → 明示",
          "無 Verification 提到" in r.stdout, r.stdout)
    # Finding 4: 只有裸合約的節點不可印「無合約」矛盾 footer
    write(v, "Systems/NakedOnly.md",
          "type: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ 裸合約A\n  KEY:★INVARIANT★ 裸合約B",
          body="# NakedOnly\n")
    r = run(v, "guard", "trace", "Systems/NakedOnly")
    check("guard trace: 裸合約節點不印『無合約』矛盾",
          "★INVARIANT★" in r.stdout and "無 ★INVARIANT★ 合約" not in r.stdout, r.stdout)
    # Finding 3: code block 內方法名不算證據
    write(v, "Systems/Cb.md",
          "type: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ 某 [test:OnlyInCodeBlock]",
          body="# Cb\n")
    write(v, "Verification/2026-01-03_cb.md", "type: verification\nstatus: pass",
          body="# cb\n```\nOnlyInCodeBlock 只出現在 code block\n```\n")
    r = run(v, "guard", "trace", "Systems/Cb")
    check("guard trace: code block 內方法名不算證據",
          "無 Verification 提到" in r.stdout, r.stdout)


