def t_loop_rewrite_mark():
    """rewrite 寫入端(2026-08-25 第一次真實事件時補建):事件+血緣 note/連續第二次警告/同號 rc2。"""
    import json as _json
    import subprocess as _sp
    v = mkvault()
    _sp.run(["git", "init", "-q"], cwd=str(v.parent))
    _sp.run(["git", "add", "-A"], cwd=str(v.parent))
    _sp.run(["git", "-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "init"], cwd=str(v.parent))
    r1 = run(v, "loop", "rewrite", "lf-a", "--successor", "lf-b", "--note", "測試判重寫")
    check("rewrite: rc0+白話收尾訊息", r1.returncode == 0 and "人裁整份重寫」收尾" in r1.stdout, r1.stdout)
    gl = v.parent / ".governance-log.jsonl"
    recs = [_json.loads(x) for x in gl.read_text(encoding="utf-8").splitlines() if x.strip()]
    rw = [o for o in recs if o.get("gate") == "design-loop" and o.get("kind") == "rewrite"]
    check("rewrite: 事件入帳+血緣 note 帶 prev 與 successor",
          len(rw) == 1 and "prev=lf-a" in rw[0]["note"] and "successor=lf-b" in rw[0]["note"], str(rw))
    r2 = run(v, "loop", "rewrite", "lf-b", "--successor", "lf-c", "--note", "又判重寫")
    check("rewrite: 連續第二次→強制攤人警告", "連續第二次判重寫" in r2.stdout and "不得三開" in r2.stdout, r2.stdout)
    check("rewrite: 同號 rc2", run(v, "loop", "rewrite", "lf-x", "--successor", "lf-x", expect_rc=2).returncode == 2, "")
    # 前綴碰撞不得偽造血緣(clf r1 主審 F1:successor=lf-a 不可誤中 successor=lf-a2 的帳)
    run(v, "loop", "rewrite", "pfx-src", "--successor", "pfx-a2", "--note", "鋪前綴")
    r3 = run(v, "loop", "rewrite", "pfx-a", "--successor", "pfx-b", "--note", "全新編號")
    check("rewrite: 前綴編號不誤判連續重寫", "連續第二次判重寫" not in r3.stdout, r3.stdout)
    # 壞 JSON 行(非物件)不炸血緣查找
    gl2 = v.parent / ".governance-log.jsonl"
    with open(gl2, "a", encoding="utf-8") as f:
        f.write('"just a string"\n[1,2]\n')
    r4 = run(v, "loop", "rewrite", "pfx-c", "--successor", "pfx-d")
    check("rewrite: 帳內非物件 JSON 行不炸", r4.returncode == 0, str(r4.returncode))
    print("  ✓ t_loop_rewrite_mark")


def t_disposal_roster_tail():
    """roster對帳併入問閘 [S1]:問閘尾端異常才發聲。翻紅釘:拿掉 anomalies_only 抑制 → 第 3 條翻紅;
    拿掉 __seqN 跳過 → 第 4 條翻紅。"""
    import json as _j
    vault = mkvault()
    ldir = vault.parent / "governance" / "review-reports" / "code-tail"
    ldir.mkdir(parents=True)
    log = vault.parent / ".canary-log.jsonl"
    def _rec(loop, rid=None, **kw):
        r = {"ts": "2026-08-26T10:00:00+08:00", "kind": "none", "auditor": kw.get("auditor", "s1"),
             "token": "CANARY-x", "note": "", "loop": loop, "severity": "minor", "findings": 0,
             "tier": "standard", **({"round": rid} if rid else {})}
        r.update(kw); return r
    # 異常 fixture:真 rN、外家缺(code/standard 應派含外家 finder?→用 design/standard:外家 note-if-absent→單家族)
    rows = [_rec("code-tail", "r1", auditor="s1", findings_set=["a"], folded_set=["a"], accepted_set=[])]
    log.write_text("\n".join(_j.dumps(r) for r in rows) + "\n")
    (ldir / "r1-dispatch.json").write_text(_j.dumps({"seats": [{"seat": "s1", "auditor": "sonnet"}]}))
    spec = vault.parent / "spec.md"; spec.write_text("x")
    import hashlib
    sha = hashlib.sha256(spec.read_bytes()).hexdigest()
    # 帶齊處置帳欄位讓 gate 可跑(report/snapshot 同檔充當)
    rows = [_rec("code-tail", "r1", auditor="s1", findings_set=["a"], folded_set=["a"], accepted_set=[],
                 report={"path": str(spec), "sha256": sha}, snapshot={"path": str(spec), "sha256": sha},
                 result_sha256=sha, reviewed_sha256=sha)]
    log.write_text("\n".join(_j.dumps(r) for r in rows) + "\n")
    r = run(vault, "loop", "status", "code-tail", "--disposal", "--spec", str(spec), "--repo", str(vault.parent))
    check("tail: 異常輪印轉述行(外家 finder 缺)", "[roster]" in r.stdout and ("external_missing" in r.stdout or "單家族" in r.stdout), r.stdout[-400:])
    check("tail: 異常留痕檔多一行", (ldir / "roster-alerts.log").exists(), str(list(ldir.iterdir())))
    check("tail: 摘要/診斷行被抑制(無「實派」字樣)", "實派" not in r.stdout, r.stdout[-300:])
    # __seqN(round-less)fixture:零 roster 行——★loop 目錄+快照必須存在★,
    # 否則拔掉 __seqN 跳過也會被「無快照」抑制吞掉=假釘(code-batch2 s3-f2 突變實測抓到)
    ldir2 = vault.parent / "governance" / "review-reports" / "code-tail2"
    ldir2.mkdir(parents=True)
    # ★快照檔名必須是 __seq0-dispatch.json★:round-less 的合成 rid=__seq0,glob 找的是這個名字;
    # 用 r1-dispatch.json 永不匹配=拔 guard 也不紅的假釘(r2 d-f4 突變實測抓到,第二次)
    (ldir2 / "__seq0-dispatch.json").write_text(_j.dumps({"seats": [{"seat": "s1", "auditor": "sonnet"}]}))
    log2 = vault.parent / ".canary-log.jsonl"
    rows2 = [_rec("code-tail2", None, auditor="s1", findings_set=["a"], folded_set=["a"], accepted_set=[],
                  report={"path": str(spec), "sha256": sha}, snapshot={"path": str(spec), "sha256": sha},
                  result_sha256=sha, reviewed_sha256=sha)]
    log2.write_text("\n".join(_j.dumps(r) for r in rows2) + "\n")
    r2 = run(vault, "loop", "status", "code-tail2", "--disposal", "--spec", str(spec), "--repo", str(vault.parent))
    check("tail: __seqN 合成鍵零 roster 行(縱深雙防:tier 只認判定輪+startswith guard,兩道齊拔才會響——單拔 guard 由 d-f1 規則接住)", "[roster]" not in r2.stdout, r2.stdout[-300:])
    # s2-f2 釘:健康輪零輸出且 log 無新行——編制滿員 fixture(design/standard 3 claude+arch 也 claude 家)
    ldir3 = vault.parent / "governance" / "review-reports" / "ok-loop"
    ldir3.mkdir(parents=True)
    (ldir3 / "r1-dispatch.json").write_text(_j.dumps({"seats": [
        {"seat": "s1", "auditor": "sonnet"}, {"seat": "s2", "auditor": "sonnet"},
        {"seat": "s3", "auditor": "sonnet"}, {"seat": "arch", "auditor": "sonnet"},
        {"seat": "ext", "auditor": "codex"}]}))
    rows3 = [_rec("ok-loop", "r1", auditor="s1", tier="standard", findings_set=["a"], folded_set=["a"],
                  accepted_set=[], report={"path": str(spec), "sha256": sha},
                  snapshot={"path": str(spec), "sha256": sha}, result_sha256=sha, reviewed_sha256=sha)]
    log2.write_text("\n".join(_j.dumps(r) for r in rows3) + "\n")
    r3 = run(vault, "loop", "status", "ok-loop", "--disposal", "--spec", str(spec), "--repo", str(vault.parent))
    check("tail: 健康輪(席滿+外家在)零 roster 行", "[roster]" not in r3.stdout, r3.stdout[-400:])
    check("tail: 健康輪 log 無新檔", not (ldir3 / "roster-alerts.log").exists(), "")
    # s1-f1 釘:跨輪 tier 不同——r1 standard、r2 high(判定輪),對帳要用 high 編制(fail-closed 措辭)
    ldir4 = vault.parent / "governance" / "review-reports" / "code-xtier"
    ldir4.mkdir(parents=True)
    (ldir4 / "r2-dispatch.json").write_text(_j.dumps({"seats": [{"seat": "s1", "auditor": "sonnet"}]}))
    rows4 = [_rec("code-xtier", "r1", auditor="s1", tier="standard", findings_set=["a"], folded_set=["a"],
                  accepted_set=[], report={"path": str(spec), "sha256": sha},
                  snapshot={"path": str(spec), "sha256": sha}, result_sha256=sha, reviewed_sha256=sha),
             _rec("code-xtier", "r2", auditor="s1", tier="high", findings_set=["b"], folded_set=["b"],
                  accepted_set=[], report={"path": str(spec), "sha256": sha},
                  snapshot={"path": str(spec), "sha256": sha}, result_sha256=sha, reviewed_sha256=sha)]
    log2.write_text("\n".join(_j.dumps(r) for r in rows4) + "\n")
    r4 = run(vault, "loop", "status", "code-xtier", "--disposal", "--spec", str(spec), "--repo", str(vault.parent))
    check("tail: 跨輪 tier 用判定輪的 high 編制(fail-closed 轉述出現;s1-f1 純 CLI 重現修)",
          "fail-closed" in r4.stdout and "external_missing" in r4.stdout, r4.stdout[-500:])
    # d-f1 釘:判定輪自己沒記 tier → 不借別輪的,零 roster 行(沒編制可對照實安靜)
    ldir6 = vault.parent / "governance" / "review-reports" / "code-notier"
    ldir6.mkdir(parents=True)
    (ldir6 / "r2-dispatch.json").write_text(_j.dumps({"seats": [{"seat": "s1", "auditor": "sonnet"}]}))
    rows6 = [_rec("code-notier", "r1", auditor="s1", tier="standard", findings_set=["a"], folded_set=["a"],
                  accepted_set=[], report={"path": str(spec), "sha256": sha},
                  snapshot={"path": str(spec), "sha256": sha}, result_sha256=sha, reviewed_sha256=sha),
             dict(_rec("code-notier", "r2", auditor="s1", findings_set=["b"], folded_set=["b"],
                  accepted_set=[], report={"path": str(spec), "sha256": sha},
                  snapshot={"path": str(spec), "sha256": sha}, result_sha256=sha, reviewed_sha256=sha))]
    rows6[1].pop("tier", None)
    log2.write_text("\n".join(_j.dumps(r) for r in rows6) + "\n")
    r6 = run(vault, "loop", "status", "code-notier", "--disposal", "--spec", str(spec), "--repo", str(vault.parent))
    check("tail: 判定輪無 tier→不借別輪編制、零 roster 行(r2 d-f1)", "[roster]" not in r6.stdout, r6.stdout[-300:])
    # s2-f2 釘:對帳段炸例外→rc 不變+降級一行(以壞 dispatch 逼不動,改 monkeypatch 層級:
    # 用環境開關?——採實體打樁:把 loop 目錄換成無法列目錄的檔案,逼 _roster_observe 內部炸)
    ldir5 = vault.parent / "governance" / "review-reports" / "code-boom"
    ldir5.mkdir(parents=True)
    (ldir5 / "r1-dispatch.json").write_text("{{{半包壞 JSON")   # dispatch 壞=內部自行跳過,不炸——
    rows5 = [_rec("code-boom", "r1", auditor="s1", tier="standard", findings_set=["a"], folded_set=["a"],
                  accepted_set=[], report={"path": str(spec), "sha256": sha},
                  snapshot={"path": str(spec), "sha256": sha}, result_sha256=sha, reviewed_sha256=sha)]
    log2.write_text("\n".join(_j.dumps(r) for r in rows5) + "\n")
    r5 = run(vault, "loop", "status", "code-boom", "--disposal", "--spec", str(spec), "--repo", str(vault.parent))
    r5b = run(vault, "loop", "status", "code-boom", "--disposal", "--roster", "--spec", str(spec), "--repo", str(vault.parent))
    check("tail: 壞 dispatch 快照不炸(內部容錯)", r5.returncode == r5b.returncode, f"{r5.returncode} vs {r5b.returncode}")
    # d-f3 真 raise 釘:in-process monkeypatch 讓 _roster_observe 真的炸,驗外層 except 降級+rc 不變
    import importlib.util as _ilu
    from importlib.machinery import SourceFileLoader as _SFL
    _spec2 = _ilu.spec_from_loader("lumos_inproc", _SFL("lumos_inproc", str(GRAPHCTL)))
    _lm = _ilu.module_from_spec(_spec2)
    import sys as _sys
    _argv0 = _sys.argv; _sys.argv = ["lumos"]
    try:
        try: _spec2.loader.exec_module(_lm)
        except SystemExit: pass
    finally:
        _sys.argv = _argv0
    _env2 = _lm.Env(vault)
    _rows5 = [dict(r) for r in rows5]
    import io, contextlib
    def _boom(*a, **k): raise RuntimeError("釘:對帳炸了")
    _lm._roster_observe = _boom
    _buf = io.StringIO()
    with contextlib.redirect_stdout(_buf):
        _rc_boom = _lm._loop_status_disposal(_rows5, "code-boom", str(spec), 0, str(vault.parent), env=_env2, repo=str(vault.parent))
    check("tail: 對帳段真炸→rc 與正常輪一致(外層 except 接住)", _rc_boom == r5.returncode, f"{_rc_boom} vs {r5.returncode}")
    check("tail: 真炸時印降級一行", "席位對帳失敗(降級不擋)" in _buf.getvalue(), _buf.getvalue()[-300:])
    print("  ✓ t_disposal_roster_tail")


def t_doctor_lint_declaration():
    """lint接線收口 [S1]:doctor [F] 檢——宣告在 repo root、vault 在 docs/x-knowledge
    (=Landmark 形狀,釘 r2 d-f2「env.vault 直拼永遠讀不到」);無宣告跳過不擋、
    壞 JSON/壞 schema 紅、合法綠。翻紅釘:把 [F] 的路徑解析改 env.vault 直拼 → 第 2-5 條翻紅
    (壞宣告全被吞成「無宣告」假綠;code-batch2 s3-f3 突變實測校正原「第 3、4 條」低估)。"""
    import json as _j, shutil as _sh
    # Landmark 形狀 fixture:repo/docs/proj-knowledge 佈局(宣告在 repo root)
    src = mkvault()
    repo_root = Path(tempfile.mkdtemp(prefix="gctl-lintdecl-")) / "repo"
    vault = repo_root / "docs" / "proj-knowledge"
    vault.parent.mkdir(parents=True)
    _sh.copytree(src, vault)
    (repo_root / ".git").mkdir()   # git 感知解析(_vault_repo_root)的錨——真實 repo 必有
    # 無宣告
    r = run(vault, "doctor", "--ci")
    # ★2026-08-29 改:原本釘「未宣告跳過」這句散文(改一次文字就紅,守的是 diff 不是行為;
    # 見 Systems/測試假綠形態 ③ 的散文文字釘子型)。改成測真行為:無宣告時要「出聲提醒但不擋」——
    # 空轉不說話正是這次要修的病(別的 repo 才會發現自己沒接 linter、去裝)。
    check("[F] 無宣告:出聲提醒(不是靜默綠勾)", "⚠" in r.stdout, r.stdout[-400:])
    check("[F] 無宣告:提醒但不擋(rc 不因此變紅)", r.returncode == 0, f"rc={r.returncode}")
    # 壞 JSON
    (repo_root / ".lumos").mkdir(exist_ok=True)
    (repo_root / ".lumos" / "lint.json").write_text("{{{壞")
    r = run(vault, "doctor", "--ci")
    check("[F] 壞 JSON:rc1 且訊息白話", r.returncode == 1 and "不是合法 JSON" in r.stdout, f"rc={r.returncode}")
    # 壞 schema(value 非 list)
    (repo_root / ".lumos" / "lint.json").write_text(_j.dumps({"kt": "not-a-list"}))
    r = run(vault, "doctor", "--ci")
    check("[F] 壞 schema:rc1 且列出問題", r.returncode == 1 and "宣告問題" in r.stdout, f"rc={r.returncode}")
    # 合法宣告(Landmark 形狀:宣告在 repo root、vault 在 docs/ 下——直拼 vault 讀不到這份)
    (repo_root / ".lumos" / "lint.json").write_text(_j.dumps({"kt": ["detekt {LINT_SARIF_OUT}"]}))
    r = run(vault, "doctor", "--ci")
    check("[F] 合法宣告(Landmark 形狀):rc0 且格式健康", r.returncode == 0 and "格式健康" in r.stdout, f"rc={r.returncode} {r.stdout[-300:]}")
    # ★2026-08-29 改:原釘「留手動」三個字(散文文字釘,改措辭即紅)。真正該守的行為是
    # 「格式健康 ≠ linter 真的在跑」這個界線有講出來——用 smoke 指令名(機器也用的穩定 token)
    # 當錨,而不是釘某一句話怎麼寫。
    check("[F] 健康訊息要指路到真跑驗證(不得讓人以為格式健康=linter 有在跑)",
          "lint-check --smoke" in r.stdout, r.stdout[-300:])
    # ext-f2 釘:編碼損壞=受控紅不 traceback
    (repo_root / ".lumos" / "lint.json").write_bytes(b"\xff\xfe\x00 broken bytes")
    rb = run(vault, "doctor", "--ci")
    check("[F] 編碼損壞:受控紅(訊息白話,無 traceback)", rb.returncode == 1
          and "不是合法 JSON" in rb.stdout and "Traceback" not in rb.stderr, f"rc={rb.returncode} {rb.stderr[-150:]}")
    (repo_root / ".lumos" / "lint.json").write_text(_j.dumps({"kt": ["detekt {LINT_SARIF_OUT}"]}))
    # ext-f1 釘:standalone 形狀(.git 在 vault 內)→ root=vault 自身,宣告在 vault/.lumos
    sv = mkvault()
    (sv / ".git").mkdir()
    (sv / ".lumos").mkdir()
    (sv / ".lumos" / "lint.json").write_text(_j.dumps({"kt": "bad"}))
    rs = run(sv, "doctor", "--ci")
    check("[F] standalone(.git 在 vault 內):宣告讀得到且壞 schema 紅", rs.returncode == 1 and "宣告問題" in rs.stdout, f"rc={rs.returncode}")
    # s3-f3:位置斷言——[F] 在最後(摘要線前、所有其他段之後;案 A 切窗類)
    _pos_f = r.stdout.rfind("[F]")
    _pos_sum = r.stdout.rfind("─────")
    check("[F] 位置=其他檢之後、摘要線之前", 0 < _pos_f < _pos_sum
          and max(r.stdout.rfind(f"[{c}]") for c in ("N", "P", "Y")) < _pos_f, f"F@{_pos_f} sum@{_pos_sum}")
    print("  ✓ t_doctor_lint_declaration")


def t_canary_record_outcome_usd():
    """自主迴圈結局帳(auto-loop-repair-v2 [S3]):record 的 --outcome/--usd 結構化欄。
    要點:合法值落欄、主類白名單外 rc2、細類壞字元 rc2、負 usd rc2、不給不寫鍵(舊格式桶前提)。"""
    import json as _j
    vault = mkvault()
    run(vault, "canary", "record", "none", "--loop", "auto-2026-08-26", "--auditor", "orch",
        "--outcome", "pipeline_fail:api_error", "--usd", "33.9", expect_rc=0)
    run(vault, "canary", "record", "none", "--loop", "auto-2026-08-27", "--auditor", "orch",
        "--outcome", "converged", expect_rc=0)
    run(vault, "canary", "record", "none", "--report", _sevrep(vault.parent), "--severity", "clean", "--loop", "auto-2026-08-28", "--auditor", "orch", expect_rc=0)
    lines = [_j.loads(l) for l in (vault.parent / ".canary-log.jsonl").read_text(encoding="utf-8").splitlines()]
    check("outcome+usd 落欄", lines[0].get("outcome") == "pipeline_fail:api_error" and lines[0].get("usd") == 33.9, str(lines[0]))
    check("outcome 單主類合法", lines[1].get("outcome") == "converged" and "usd" not in lines[1], str(lines[1]))
    check("不給不寫鍵", "outcome" not in lines[2] and "usd" not in lines[2], str(lines[2]))
    r = run(vault, "canary", "record", "none", "--loop", "x", "--outcome", "exploded")
    check("主類白名單外 rc2", r.returncode == 2 and "封閉列舉" in r.stderr, f"rc={r.returncode}")
    r = run(vault, "canary", "record", "none", "--loop", "x", "--outcome", "converged:大寫壞字元")
    check("細類壞字元 rc2", r.returncode == 2, f"rc={r.returncode}")
    r = run(vault, "canary", "record", "none", "--loop", "x", "--outcome", "pipeline_fail:zzz")
    check("字元合法但未宣告的細類 rc2(封閉列舉)", r.returncode == 2 and "封閉列舉" in r.stderr, f"rc={r.returncode}")
    r = run(vault, "canary", "record", "none", "--report", _sevrep(vault.parent), "--loop", "x", "--usd", "-3")
    check("負 usd rc2", r.returncode == 2 and "美元" in r.stderr, f"rc={r.returncode}")
    print("  ✓ t_canary_record_outcome_usd")


def t_panel_probe_retired():
    """probe輪退場 d1/d2(Enzo 甲裁 2026-08-25)行為級三釘:(a)新迴圈問 panel 被拒+指路
    (b)code-* major 席+非空 accepted → disposal FAIL;同構散文案 PASS (c)舊迴圈 panel 印行
    為觀測語意(不含義務句)。"""
    import subprocess as _sp
    import os as _os
    v = mkvault()
    env2 = dict(_os.environ)
    env2["LUMOS_PANEL_RETIRE_CUTOFF"] = "2000-01-01"   # 一切迴圈都算「新」→驗拒判
    # (a) 新迴圈問 panel 被拒
    run(v, "canary", "record", "none", "--loop", "pr-new", "--round", "r1", "--auditor", "a",
        "--severity", "minor", "--findings", "1", "--report", _sevrep(v.parent, "minor", 1), expect_rc=0)
    ra = _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "loop", "status", "pr-new",
                  "--gate", "--panel"], capture_output=True, text=True, env=env2)
    check("retired: 新迴圈問 panel 拒判 rc2", ra.returncode == 2, f"{ra.returncode} {ra.stderr[-200:]}")
    check("retired: 拒判訊息指路 --disposal", "--disposal" in ra.stderr and "僅供舊迴圈回放" in ra.stderr, ra.stderr[-300:])
    # (b) code-* major+accepted → FAIL;散文同構 → PASS(用 --disposal,無 spec 綁定的最小帳)
    specf = v / "Systems" / "strict-spec.md"
    specf.write_text("severity: major\n## f1\nseverity: major\n引句素材行,長度超過十個字元。\n", encoding="utf-8")   # 兼當席報告:檔首檔級行+一條宣告(2026-09-09 寫側拒收沒正規化的報告)
    specm = v / "Systems" / "strict-spec-minor.md"; specm.write_text("severity: minor\n## f1\nseverity: minor\n引句素材行,長度超過十個字元。\n", encoding="utf-8")   # minor 記帳用的報告(帳面不得低於報告最高)
    import hashlib as _hl
    sha = _hl.sha256(specf.read_bytes()).hexdigest()
    for lp, sev in (("code-strict-t", "major"), ("prose-strict-t", "major")):
        run(v, "canary", "record", "none", "--loop", lp, "--round", "r1", "--auditor", "s1",
            "--severity", sev, "--findings", "1",
            "--findings-set", "f1", "--refuted-set", "none", "--accepted-set", "f1", "--accept-reason", "f1=測試放行",
            "--report", str(specf), "--snapshot", str(specf),
            "--spec", str(specf), "--reviewed", sha, expect_rc=0)
    rb = run(v, "loop", "status", "code-strict-t", "--disposal", "--spec", str(specf))
    check("retired: code-* major+accepted → FAIL 且訊息講 major 一律折",
          rb.returncode == 1 and "major 一律折" in rb.stdout, rb.stdout[-400:])
    rc_ = run(v, "loop", "status", "prose-strict-t", "--disposal", "--spec", str(specf))
    check("retired: 散文同構(major+accepted)不觸發 code 嚴格則訊息",
          "major 一律折" not in rc_.stdout, rc_.stdout[-400:])
    # (c) 舊迴圈(harness cutoff=9999 → 視為舊)panel PASS 印行=觀測語意
    _u = _sec.token_hex(3)
    for rnd in ("r1", "r2"):
        for seat in ("a1", "a2"):
            run(v, "canary", "record", "none", "--loop", f"pr-old-{_u}", "--round", rnd,
                "--auditor", seat, "--severity", "clean", "--findings", "0",
                "--report", _sevrep(v.parent), expect_rc=0)
    envk2 = dict(_os.environ, LUMOS_PANEL_K2_CUTOFF="2000-01-01")
    rd = _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "loop", "status", f"pr-old-{_u}",
                  "--gate", "--panel"], capture_output=True, text=True, env=envk2)
    if rd.returncode == 0:
        check("retired: 舊迴圈 PASS 印行不含義務句", "加開一輪 probe-* 抽查" not in rd.stdout and "要——加開一輪" not in rd.stdout, rd.stdout[-300:])  # 「才算做完」半條係文件用語非 CLI 輸出,cpr r1 主審抓的裝飾斷言已拔;紅證靠 sha 硬幣的限制照實承認
        check("retired: 舊迴圈 PASS 印行含觀測字樣", ("抽查判定" in rd.stdout and "觀測" in rd.stdout), rd.stdout[-300:])
    else:
        check("retired: 舊迴圈 panel 應可判(fixture 帳問題)", False, rd.stdout[-300:] + rd.stderr[-200:])
    # 第四釘(cpr r1 主審 B):退役迴圈+多 carrier 的分流訊息
    for seat in ("x1", "x2"):
        run(v, "canary", "record", "none", "--loop", "code-mc-t", "--round", "r1", "--auditor", seat,
            "--severity", "minor", "--findings", "1", "--findings-set", "f1", "--refuted-set", "none", "--folded-set", "f1",
            "--report", str(specm), "--snapshot", str(specf), "--spec", str(specf), "--reviewed", sha,
            expect_rc=0)
    re2 = _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "loop", "status", "code-mc-t",
                   "--disposal", "--spec", str(specf)], capture_output=True, text=True, env=env2)
    check("retired: 多 carrier 分流訊息(新迴圈不再指路 panel)", re2.returncode == 2
          and "彙總記帳" in re2.stderr and "--gate --panel" not in re2.stderr, re2.stderr[-300:])
    print("  ✓ t_panel_probe_retired")


def t_gov_stats_rewrite_bucket():
    """d3(設計審收斂重定義 2026-08-25):rewrite 收尾獨立計數——只有 rewrite 的編號
    不再悄悄掉出 conv/capped 兩桶讓放行率失真。"""
    import shutil
    gov = [
        '{"ts":"2026-06-01T09:00:00","commit":"aaa","gate":"design-loop","kind":"converged","hard":false,"nodes":["L1"]}\n',
        '{"ts":"2026-06-02T09:00:00","commit":"bbb","gate":"design-loop","kind":"rewrite","hard":false,"nodes":["L2"],"note":"prev=L2-v0"}\n',
        # L3=先 cap-reached 後人裁 rewrite(最貼近真實流程的組合;r1 主審 F6:漏排除會掉回「人裁放行」桶)
        '{"ts":"2026-06-03T09:00:00","commit":"ccc","gate":"design-loop","kind":"cap-reached","hard":false,"nodes":["L3"]}\n',
        '{"ts":"2026-06-03T10:00:00","commit":"ddd","gate":"design-loop","kind":"rewrite","hard":false,"nodes":["L3"],"note":"prev=L3-v0"}\n',
    ]
    root, vault = _stats_fixture("gctl-rw-", gov)
    try:
        out = run(vault, "gov", "--since", "9999", "--stats", expect_rc=0).stdout
        check("stats: rewrite 收尾獨立計數(含 cap-reached+rewrite 組合共 2 個)", "人裁判整份重寫收尾 2 個" in out, out)
        check("stats: 分母含 rewrite 編號(3 個)", "只算有記帳的 3 個編號" in out, out)
        check("stats: converged 照算", "閘過了 1 個" in out, out)
        check("stats: cap-reached+rewrite 不落「人裁放行」桶(F6)", "跑滿上限沒過關(人裁放行) 0 個" in out, out)
    finally:
        shutil.rmtree(root, ignore_errors=True)


