def t_pitfalls_diff_node_flavor_by_package_json():
    """[iOS/Node 補棧 2026-09-08]同樣是 .ts 檔,後端專案(package.json 沒前端框架)附 node 效能追問
    + node-idioms;前端專案(依賴有 vue)維持舊行為:不附 node 追問、慣例 skill 仍是 vue-idioms;
    沒有 package.json 也維持舊行為。.swift 檔附 swift 追問 + swift-idioms。
    翻紅釘:把 _stack_key_for_file 的 package.json 分流拔掉 → ①或②翻紅。"""
    import json as _json, subprocess as sp

    def mkrepo(pkg_deps, ext="ts"):
        root = Path(tempfile.mkdtemp(prefix="gctl-nodeflv-"))
        def git(*a): sp.run(["git", *a], cwd=root, capture_output=True)
        def commit(msg): git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", msg)
        git("init")
        if pkg_deps is not None:
            (root / "package.json").write_text(_json.dumps({"name": "x", "dependencies": pkg_deps}), encoding="utf-8")
        svc = root / "src" / "services"; svc.mkdir(parents=True)
        (svc / f"OrderService.{ext}").write_text("export const a = 1;\n", encoding="utf-8")
        commit("init")
        (svc / f"RefundService.{ext}").write_text("export const b = 2;\n", encoding="utf-8")
        commit("add")
        r = run(root, "pitfalls", "--diff", "HEAD~1..HEAD", "--repo", str(root), "--json")
        return _json.loads([l for l in r.stdout.splitlines() if l.strip().startswith("{")][0])

    d_node = mkrepo({"fastify": "^5"})
    check("①後端 .ts:附 node 效能追問 + node-idioms",
          "node" in (d_node.get("stack_questions") or {}) and "node-idioms" in (d_node.get("arch_alignment") or {}).get("idiom_skills", []),
          str(d_node.get("stack_questions", {}).keys()) + str(d_node.get("arch_alignment")))
    d_vue = mkrepo({"vue": "^3"})
    check("②前端 .ts(依賴有 vue):不附 node 追問、慣例仍 vue-idioms",
          "node" not in (d_vue.get("stack_questions") or {}) and "vue-idioms" in (d_vue.get("arch_alignment") or {}).get("idiom_skills", []),
          str(d_vue.get("stack_questions", {}).keys()) + str(d_vue.get("arch_alignment")))
    d_none = mkrepo(None)
    check("③沒 package.json:舊行為(不附 node 追問、vue-idioms)",
          "node" not in (d_none.get("stack_questions") or {}) and "vue-idioms" in (d_none.get("arch_alignment") or {}).get("idiom_skills", []),
          str(d_none.get("arch_alignment")))
    d_swift = mkrepo(None, ext="swift")
    check("④.swift:附 swift 效能追問 + swift-idioms",
          "swift" in (d_swift.get("stack_questions") or {}) and "swift-idioms" in (d_swift.get("arch_alignment") or {}).get("idiom_skills", []),
          str(d_swift.get("stack_questions", {}).keys()) + str(d_swift.get("arch_alignment")))
    print("  ✓ t_pitfalls_diff_node_flavor_by_package_json")


def t_pitfalls_diff_prints_impact_lens_hint_human_only():
    """★2026-08-02:code-loop 的「派 reviewer 前跑 impact --diff 附 manifest」原本
    純紀律層、沒有任何機械提醒——當天編排者自己就忘了跑,而事後補跑第一行就是後來
    被證實違反合約的那個節點。★本測試釘住那句提示存在,而且只存在於人可讀輸出。★

    兩個斷言方向缺一不可:
    ① 人可讀輸出要有提示,★且必須帶真實的 range★(印成寫死的佔位符等於沒用——
       使用者無法直接複製貼上,提示的價值就沒了)。
    ② `--json` ★絕不能★有這行。`--json` 是 pre-push 讀 verdict 的路徑
       (scripts/hooks/pre-push:98),混進非 JSON 文字會讓解析端直接壞掉。

    ★刻意不驗的事★:不驗「impact 真的被跑了」「manifest 真的餵進 reviewer」——
    那不可觀測(派工在模型腦內),見 Projects/送審前impact鏡頭機械化_計劃 的誠實天花板。
    這條只買「提示印得出來、且沒污染 JSON」。

    ★翻紅釘★:把那行 print 拿掉 → ①翻紅;把它從 else 分支移到 as_json 分支外
    (兩邊都印)→ ②翻紅。"""
    import json as _json, subprocess as sp
    root = Path(tempfile.mkdtemp(prefix="gctl-pflens-"))
    def git(*a): sp.run(["git", *a], cwd=root, capture_output=True)
    git("init"); git("config", "user.email", "t@t"); git("config", "user.name", "t")
    (root / "app.py").write_text("x = 1\n", encoding="utf-8")
    git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "init")
    (root / "app.py").write_text("x = 2\n", encoding="utf-8")
    git("add", "-A"); git("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-m", "c2")

    rng = "HEAD~1..HEAD"
    r = run(root, "pitfalls", "--diff", rng, "--repo", str(root))
    check("★前置★ 現場成立:人可讀分支真的跑到了(印得出 tier 行)",
          any(l.startswith("tier: ") for l in r.stdout.splitlines()), r.stdout)
    check("★人可讀輸出要有送審前 impact 鏡頭提示★",
          "lumos impact --diff" in r.stdout, r.stdout)
    check("★提示必須帶真實 range,不能是寫死的佔位符(否則無法直接複製)★",
          f"lumos impact --diff {rng}" in r.stdout, r.stdout)
    check("★提示要接上最後一里(2026-08-30 爆炸半徑供糧案唯一交付):跑完要貼進派工詞★",
          "貼進每一席的派工詞" in r.stdout and "貼內容不貼路徑" in r.stdout, r.stdout)

    rj = run(root, "pitfalls", "--diff", rng, "--repo", str(root), "--json")
    check("★前置★ 現場成立:--json 這一跑確實產出了 JSON",
          any(l.strip().startswith("{") for l in rj.stdout.splitlines()), rj.stdout)
    check("★--json 絕不能混進提示文字(pre-push 讀它拿 verdict,混了就解析壞)★",
          "lumos impact --diff" not in rj.stdout, rj.stdout)
    body = [l for l in rj.stdout.splitlines() if l.strip()]
    ok = True
    for l in body:
        try:
            _json.loads(l)
        except Exception:
            ok = False
    check("★--json 的每一行都必須是合法 JSON(沒有夾雜任何散文)★", ok, rj.stdout)


def t_pitfalls_spec():
    root = Path(tempfile.mkdtemp(prefix="gctl-pf-"))
    (root / ".git").mkdir()
    # 命中 payment + external-send
    md_hit = root / "hit.md"
    md_hit.write_text("# s\n## 目標\n接 stripe 收款後寄送通知。\n## 組件\n扣款流程。\n", encoding="utf-8")
    r = run(root, "pitfalls", str(md_hit), "--repo", str(root))
    check("pitfalls spec: 印通用 3 問", "併發" in r.stdout and "效能" in r.stdout and "資源" in r.stdout, r.stdout)
    check("pitfalls spec: 命中 payment 追問", "冪等" in r.stdout, r.stdout)
    check("pitfalls spec: 命中 external-send 追問", "去重" in r.stdout or "重試" in r.stdout, r.stdout)
    # --check 命中且無節 → rc 1
    r = run(root, "pitfalls", str(md_hit), "--repo", str(root), "--check")
    check("pitfalls --check: 命中無節 rc 1", r.returncode == 1, f"rc={r.returncode}\n{r.stdout}")
    # 補節 → rc 0
    md_ok = root / "ok.md"
    md_ok.write_text("# s\n## 目標\n接 stripe 收款。\n## 實務隱患\n冪等鍵用訂單號。\n", encoding="utf-8")
    r = run(root, "pitfalls", str(md_ok), "--repo", str(root), "--check")
    check("pitfalls --check: 有節 rc 0", r.returncode == 0, f"rc={r.returncode}\n{r.stdout}")
    # 零命中 → rc 0(無節也不擋)
    md_clean = root / "clean.md"
    md_clean.write_text("# s\n## 目標\n重構內部排序,無外部行為。\n## 組件\n拆函數。\n", encoding="utf-8")
    r = run(root, "pitfalls", str(md_clean), "--repo", str(root), "--check")
    check("pitfalls --check: 零命中無節 rc 0", r.returncode == 0, f"rc={r.returncode}\n{r.stdout}")
    check("pitfalls spec: 零命中只印通用問", "冪等" not in r.stdout, r.stdout)
    # 剝除:風險詞只在黑名單樣板節 → 不觸發
    md_tmpl = root / "tmpl.md"
    md_tmpl.write_text("# s\n## 目標\n" + "純內部整理。" * 20 +
                       "\n## 組件\n" + "改函數命名。" * 20 +
                       "\n## 審計修正紀錄\nr1 canary 抓到金流 stripe 扣款壞 ref。\n", encoding="utf-8")
    r = run(root, "pitfalls", str(md_tmpl), "--repo", str(root), "--check")
    check("pitfalls 剝除: 風險詞只在審計紀錄節 → --check rc 0", r.returncode == 0, f"rc={r.returncode}\n{r.stdout}")
    # md 不存在 → rc 2
    r = run(root, "pitfalls", str(root / "ghost.md"), "--repo", str(root))
    check("pitfalls: md 不存在 rc 2", r.returncode == 2, f"rc={r.returncode}")


def t_pitfalls_ask_risk_classes():
    """[已知坑機械前置 S0]pitfalls spec 模式加「反問風險類」廣度問——在場 LLM 自我分類,
    補寫死 4 類太少。①反問行出現(子字串對齊實際問句)②固定 3 問仍在③--check rc 語意不變。
    翻紅釘:拔反問行 → ①翻紅。"""
    print("t_pitfalls_ask_risk_classes")
    v = mkvault()
    root = v.parent
    md = root / "feat.md"
    md.write_text("# s\n## 目標\n前端加 refresh token 靜默續期。\n## 實務隱患\n併發見下。\n",
                  encoding="utf-8")
    r = run(root, "pitfalls", str(md), "--repo", str(root))
    check("★反問行:列出此功能碰到的風險類★", "列出此功能碰到的風險類" in r.stdout, r.stdout[:500])
    check("固定 3 問仍在(併發/效能/資源)",
          all(w in r.stdout for w in ("併發", "效能", "資源")), r.stdout[:500])
