    old_version_start = ("<!-- LUMOS:GRAPH-DISCIPLINE:START v0.9"
                         " — 自動注入/更新,勿手改本區塊;改範本 scripts/templates/graph-discipline.md -->")
    END = "<!-- LUMOS:GRAPH-DISCIPLINE:END -->"
