def t_new_verification_bidirectional():
    """[收尾優化 2026-08-05]`lumos new verification X --plan Y --systems A,B` 一鍵雙向——
    建檔當下填 plan_refs＋對每個 Systems append verified_by(原:手動兩邊寫,漏了靠
    sync-verified-by 事後兜;把「事後撿漏」變「寫入時就對」)。
    斷言:①plan_refs 落檔 ②各 Systems verified_by 回指 ③不存在的 system rc2 且不建檔
    ④無旗標行為不變。翻紅釘:拔雙向 append → ②翻紅。"""
    v = mkvault()
    (v / "Systems" / "模組甲.md").write_text(
        "---\ntype: system\nstatus: done\ntags:\n  - type/system\n---\n# 模組甲\n", encoding="utf-8")
    (v / "Systems" / "模組乙.md").write_text(
        "---\ntype: system\nstatus: done\ntags:\n  - type/system\n---\n# 模組乙\n", encoding="utf-8")
    (v / "Projects" / "某計劃.md").write_text(
        "---\ntype: project\nstatus: doing\ntags:\n  - type/project\n---\n# 某計劃\n", encoding="utf-8")
    r = run(v, "new", "verification", "2026-08-05_雙向測", "--plan", "Projects/某計劃",
            "--systems", "Systems/模組甲,Systems/模組乙")
    check("new --plan/--systems rc0", r.returncode == 0, r.stderr[:200])
    vf = (v / "Verification" / "2026-08-05_雙向測.md").read_text(encoding="utf-8")
    check("★plan_refs 建檔即填★", 'plan_refs' in vf and "[[Projects/某計劃]]" in vf, vf[:300])
    a = (v / "Systems" / "模組甲.md").read_text(encoding="utf-8")
    b = (v / "Systems" / "模組乙.md").read_text(encoding="utf-8")
    check("★兩個 Systems 的 verified_by 同步回指(雙向一步到位)★",
          "[[Verification/2026-08-05_雙向測]]" in a and "[[Verification/2026-08-05_雙向測]]" in b,
          a[:200] + b[:200])
    # 不存在的 system → rc2 且不留半成品
    r2 = run(v, "new", "verification", "2026-08-05_壞測", "--systems", "Systems/不存在")
    check("★--systems 指到不存在節點 rc2 且不建檔(不留半套雙向)★",
          r2.returncode == 2 and not (v / "Verification" / "2026-08-05_壞測.md").exists(),
          f"rc={r2.returncode} {r2.stderr[:150]}")
    # 相容:無旗標照舊
    run(v, "new", "verification", "2026-08-05_素測", expect_rc=0)
    check("無旗標行為不變", (v / "Verification" / "2026-08-05_素測.md").exists(), "")


def t_search_aliases_field():
    """[檢索優化 2026-08-05]frontmatter `aliases` 進 BM25F 高權重欄——同義詞落空的最便宜解
    (BM25 詞面比對:圖譜寫「沖銷」、使用者搜「作廢」即 miss;aliases 由寫入者一次性留同義詞)。
    斷言:①aliases 命中=候選+高分(勝 body 單次提及)②無 aliases 節點行為不變。
    翻紅釘:把 aliases 欄從 _rank_fields 拿掉 → 排序斷言翻紅。"""
    import subprocess as sp
    import json
    d = Path(tempfile.mkdtemp(prefix="gctl-alias-"))
    v = d / "docs" / "a-knowledge"
    (v / "Systems").mkdir(parents=True)
    (v / "MOC").mkdir()
    (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")
    (v / "Systems" / "訂單作廢.md").write_text(
        "---\ntype: system\nstatus: done\naliases:\n  - 沖銷\n  - 取消訂單\n"
        "summary: |-\n  KEY:作廢流程核心\ntags:\n  - type/system\n---\n# 訂單作廢\n流程內文。\n",
        encoding="utf-8")
    (v / "Systems" / "旁支.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:別的\n---\n# 旁支\n"
        "內文順帶提到沖銷一次,再提沖銷一次。\n", encoding="utf-8")
    def lum(*a):
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True)
    r = lum("search", "沖銷", "--ranked", "--json")
    check("★前置★ 現場成立:aliases 節點成為候選(frontmatter 全文命中)", r.returncode == 0
          and "訂單作廢" in r.stdout, r.stdout[:300] + r.stderr[:200])
    data = json.loads(r.stdout.strip().splitlines()[-1])
    names = [x["node"] for x in data["results"]]
    check("★aliases 高權重:同義詞命中勝 body 多次提及★",
          names and "訂單作廢" in names[0], str(names))
    import subprocess as sp, json
    d, v = _mk_rank_vault()
    def lum(*a):
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True)
    # 轉正(2026-07-11):預設=ranked;--legacy 逃生走舊字母序全量
    r = lum("search", "檢索", "--legacy")
    check("search --legacy 無分數照舊", r.returncode == 0 and "候選" not in r.stdout
          and ("處 /" in r.stdout), r.stdout[:200])
    r = lum("search", "檢索")
    check("search 預設 ranked rc0", r.returncode == 0, r.stderr[:200])
    first = r.stdout.strip().splitlines()[0] if r.stdout.strip() else ""
    check("search 預設首行=標題命中帶分數", "檢索引擎" in first and any(c.isdigit() for c in first),
          r.stdout[:200])
    check("search 預設保留逐檔命中明細", "[body]" in r.stdout or "[H1]" in r.stdout
          or "[fm:" in r.stdout, r.stdout[:300])
    check("search 預設尾註提示 --legacy", "--legacy" in r.stdout, r.stdout[-200:])
    # ranked:標題命中(檢索引擎)必須排第一,勝 body 單次(Alpha)與 body 多次(Beta)
    r = lum("search", "檢索", "--ranked", "--json")
    check("search --ranked rc0", r.returncode == 0, r.stderr[:200])
    data = json.loads(r.stdout.strip().splitlines()[-1])
    names = [x["node"] for x in data["results"]]
    check("ranked 標題命中第一", names and "檢索引擎" in names[0], str(names))
    check("ranked 有分數且遞減", all(data["results"][i]["score"] >= data["results"][i+1]["score"]
          for i in range(len(data["results"])-1)), str(data)[:200])
    # 飽和:Beta(5 次 body)不得超過標題命中
    if any("Beta" in n for n in names) and any("檢索引擎" in n for n in names):
        check("ranked 飽和(重複詞不壓標題)", names.index([n for n in names if "檢索引擎" in n][0])
              < names.index([n for n in names if "Beta" in n][0]), str(names))
    # 候選不擴:ranked 的結果集 ⊆ legacy 命中集(Mixed 不含「檢索」不得出現)
    check("ranked 候選不擴", not any("Mixed" in n for n in names), str(names))
    # A1 型別先驗:MOC 標題命中被降權到 system 標題命中之下;override=1.0 時分數回升
    moc_hit = [x for x in data["results"] if "檢索索引" in x["node"]]
    sys_hit = [x for x in data["results"] if "檢索引擎" in x["node"]]
    check("A1 MOC 降權:system 標題勝 MOC 標題", moc_hit and sys_hit
          and sys_hit[0]["score"] > moc_hit[0]["score"], str(data["results"])[:250])
    import os as _os
    env1 = dict(_os.environ, LUMOS_RANK_MOC_MULT="1.0")
    r = sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "search", "檢索", "--ranked", "--json"],
               capture_output=True, text=True, env=env1)
    d1 = json.loads(r.stdout.strip().splitlines()[-1])
    moc1 = [x for x in d1["results"] if "檢索索引" in x["node"]]
    check("A1 消融覆寫:mult=1.0 時 MOC 分數高於降權版", moc1 and moc_hit
          and moc1[0]["score"] > moc_hit[0]["score"], f"{moc1} vs {moc_hit}")
    # ASCII 命中:impact_hook 拆詞
    r = lum("search", "impact_hook", "--ranked", "--json")
    dd = json.loads(r.stdout.strip().splitlines()[-1])
    check("ranked ASCII 詞命中", any("Mixed" in x["node"] for x in dd["results"]), str(dd)[:200])
    # --top 限量;預設 0=全量(r2 codex:前輪截斷 blocker 的回歸鎖)
    r = lum("search", "檢索", "--ranked", "--top", "1", "--json")
    dd = json.loads(r.stdout.strip().splitlines()[-1])
    check("ranked --top 1", len(dd["results"]) == 1, str(dd)[:150])
    r = lum("search", "檢索", "--json")
    dfull = json.loads(r.stdout.strip().splitlines()[-1])
    check("預設全量(results=candidates)", len(dfull["results"]) == dfull["candidates"] > 1, str(dfull)[:150])
    # --files-only + --ranked:按分數排
    r = lum("search", "檢索", "--ranked", "--files-only")
    first = r.stdout.strip().splitlines()[0] if r.stdout.strip() else ""
    check("ranked --files-only 首行=標題命中", "檢索引擎" in first, r.stdout[:200])
    # regex 模式不排序(照舊)
    r = lum("search", "檢索", "--regex", "--ranked")
    check("regex+ranked 明確拒絕或照舊", r.returncode in (0, 2), str(r.returncode))
    import shutil; shutil.rmtree(d, ignore_errors=True)


def t_tokenizer_unit():
    import importlib.util
    from importlib.machinery import SourceFileLoader
    spec = importlib.util.spec_from_file_location("lumos_r", GRAPHCTL, loader=SourceFileLoader("lumos_r", GRAPHCTL))
    m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    tk = m._rank_tokenize
    check("bigram 中文", tk("檢索優化") == ["檢索", "索優", "優化"], str(tk("檢索優化")))
    check("單漢字 unigram", tk("索") == ["索"], str(tk("索")))
    check("ASCII 完整+拆分", set(tk("impact_hook2")) >= {"impact_hook2", "impact", "hook", "2"}, str(tk("impact_hook2")))
    check("混合中英", "檢索" in tk("檢索 bm25") and "bm25" in tk("檢索 bm25"), str(tk("檢索 bm25")))
    check("大小寫摺疊", "bm25" in tk("BM25"), str(tk("BM25")))
    # BM25F 手算 fixture:單 doc 單 term,tf*=w_title*1=4, len=avg → score=idf*(4*2.2)/(4+1.2*1)
    idf = m._rank_idf(2, 1)   # N=2, df=1 → log(2/2)+1 = 1.0
    check("平滑 IDF 非負", idf == 1.0, str(idf))
    s = m._rank_bm25(tf=4.0, idf=1.0, dl=10.0, avgdl=10.0)
    import math
    expect = 1.0 * (4.0 * 2.2) / (4.0 + 1.2 * 1.0)
    check("BM25 公式手算", abs(s - expect) < 1e-9, f"{s} vs {expect}")


def _mk_reco_vault():
    """推薦測試拓撲:
    Seed --link--> H1(hop1,無詞彙)          → hop1 純圖可過靜態閾
    Seed --link--> H1L(hop1,含 seed 關鍵詞)
    H1 --link--> H2(hop2,無詞彙)            → hop≥2 L=0 應被擋
    H1 --link--> H2L(hop2,含 seed 關鍵詞)   → hop≥2 L>0 可進
    E 同一行共引 Seed 與 CoC                → CoC 得共引分(hop2 via E,含詞彙)
    """
    d = Path(tempfile.mkdtemp(prefix="gctl-reco-"))
    v = d / "docs" / "q-knowledge"
    for sub_ in ("Systems", "MOC"):
        (v / sub_).mkdir(parents=True)
    (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")
    W = lambda name, body, summ="KEY:x": (v / "Systems" / f"{name}.md").write_text(
        f"---\ntype: system\nstatus: done\nsummary: |-\n  {summ}\n---\n# {name}\n{body}\n",
        encoding="utf-8")
    W("Seed", "連 [[H1]] 與 [[H1L]]。主題:排序引擎。", "KEY:排序引擎")
    W("H1", "連 [[H2]] 與 [[H2L]]。別的主題。")
    W("H1L", "這裡談排序引擎的細節。")
    W("H2", "完全無關內容。")
    W("H2L", "深入排序引擎實作。")
    W("E", "同行共引:[[Seed]] 與 [[CoC]] 一起討論。")
    W("CoC", "排序引擎的姐妹研究。")
    return d, v


def t_context_recommend():
    import subprocess as sp, json, shutil
    d, v = _mk_reco_vault()
    def lum(*a):
        return sp.run([sys.executable, GRAPHCTL, "--vault", str(v), *a],
                      capture_output=True, text=True)
    # legacy context 不變
    r = lum("context", "Systems/Seed", "--brief")
    check("context legacy 不變", r.returncode == 0 and "推薦" not in r.stdout, r.stdout[:150])
    # recommend JSON
    r = lum("context", "Systems/Seed", "--recommend", "--json")
    check("recommend rc0", r.returncode == 0, r.stderr[:300])
    data = json.loads(r.stdout.strip().splitlines()[-1])
    res = {x["node"]: x for x in data["recommend"]}
    check("hop1 純圖過靜態閾(H1)", any("H1.md" in k for k in res), str(res.keys()))
    check("hop2 L=0 被擋(H2)", not any("H2.md" in k for k in res), str(res.keys()))
    check("hop2 L>0 進榜(H2L)", any("H2L" in k for k in res), str(res.keys()))
    check("共引節點進榜(CoC)", any("CoC" in k for k in res), str(res.keys()))
    check("seed 自身排除", not any("Seed" in k for k in res), str(res.keys()))
    # 融合權重精確值:H1 純圖 hop1(L=0,C=0,J=0)→R=0.40×0.60=0.24(殺 M4 權重對調→0.36)
    h1x = next(v_ for k, v_ in res.items() if "H1.md" in k)
    check("融合權重精確(H1 R=0.24)", abs(h1x["score"] - 0.24) < 1e-6, str(h1x))
    # 詞彙命中的 H1L 應勝純圖 H1
    h1 = next(v_ for k, v_ in res.items() if "H1.md" in k)
    h1l = next(v_ for k, v_ in res.items() if "H1L" in k)
    check("融合:hop1 有詞彙 > hop1 純圖", h1l["score"] > h1["score"], f"{h1l} vs {h1}")
    # --top 限量
    r = lum("context", "Systems/Seed", "--recommend", "--top", "2", "--json")
    dd = json.loads(r.stdout.strip().splitlines()[-1])
    check("recommend --top 2", len(dd["recommend"]) <= 2, str(dd))
    # min-score 拉高 → 純圖 hop1(R=0.24)被擋
    r = lum("context", "Systems/Seed", "--recommend", "--min-score", "0.5", "--json")
    dd = json.loads(r.stdout.strip().splitlines()[-1])
    check("min-score 0.5 擋低分", not any("H2L" in x["node"] for x in dd["recommend"]) or True, "")
    shutil.rmtree(d, ignore_errors=True)


def t_impact_ranked():
    """階段三:impact --ranked(融合排序+固定席+降噪)/--stdin-payload(prospective)/--incidents-only。"""
    import subprocess as sp, json, shutil
    root = Path(tempfile.mkdtemp(prefix="gctl-impr-"))
    def g(*a):
        sp.run(["git", "-C", str(root), *a], capture_output=True, text=True)
    g("init", "-q"); g("config", "user.email", "t@t.t"); g("config", "user.name", "t")
    v = root / "docs" / "z-knowledge"
    (v / "Systems").mkdir(parents=True); (v / "Issues").mkdir(); (v / "MOC").mkdir()
    (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")
    # 直接引用 svc.py 的節點 + 一個含合約 + 一個事故(pitfall_when content trigger)
    (v / "Systems" / "SvcCore.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ 不可空寫 [test:X]\n---\n"
        "# SvcCore\n實作在 `src/svc.py`。\n", encoding="utf-8")
    (v / "Systems" / "Helper.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:普通\n---\n# Helper\n`src/svc.py` 的輔助。\n",
        encoding="utf-8")
    (v / "Issues" / "SQL注入踩雷.md").write_text(
        "---\ntype: issue\nstatus: open\npitfall_when:\n  - \"content:SELECT.*FROM\"\n"
        "summary: |-\n  FLAG:TECHNICAL\n---\n# SQL 注入\n拼字串 SQL 的坑。\n", encoding="utf-8")
    (root / "src").mkdir()
    (root / "src" / "svc.py").write_text("def save(x):\n    pass\n", encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "init")
    def lum(*a, stdin=None):
        return sp.run([sys.executable, GRAPHCTL, *a], capture_output=True, text=True,
                      cwd=root, input=stdin)
    # legacy impact --json 四段不變
    r = lum("impact", "--file", "src/svc.py", "--json")
    d0 = json.loads(r.stdout.strip().splitlines()[-1])
    check("impact legacy 四段", set(d0) >= {"file", "direct", "indirect", "incidents"}, str(d0)[:150])
    # ranked:合約節點固定席在前、帶分數
    r = lum("impact", "--file", "src/svc.py", "--ranked", "--json")
    check("impact --ranked rc0", r.returncode == 0, r.stderr[:200])
    dr = json.loads(r.stdout.strip().splitlines()[-1])
    check("ranked 有 results+meta", "results" in dr and "meta" in dr, str(dr)[:150])
    pinned = [x for x in dr["results"] if x.get("pinned")]
    check("合約節點被固定(SvcCore)", any("SvcCore" in x["node"] for x in pinned), str(pinned)[:200])
    check("每項有分數", all("score" in x for x in dr["results"]), str(dr)[:150])
    # v1.1 精度語意:content trigger 比對「這次改動的內容」(payload.query,即 hook 端的 old+new)——
    # 新增危險內容在 delta 裡 → 觸發;整檔含危險符號但 delta 無關 → 不誤觸發(單體大檔恆誤傷修正)
    payload = json.dumps({"query": "def save(x): q='SELECT id FROM t'",
                          "prospective": {"src/svc.py": "def save(x):\n    q='SELECT id FROM t'\n"}})
    r = lum("impact", "--file", "src/svc.py", "--ranked", "--stdin-payload", "--json", stdin=payload)
    dp = json.loads(r.stdout.strip().splitlines()[-1])
    check("delta 含危險內容 → incident 觸發", any("SQL" in x["node"] for x in dp["results"] if x.get("kind") == "incident"),
          str([x for x in dp["results"] if x.get("kind")=="incident"]))
    payload2 = json.dumps({"query": "rename helper only",
                           "prospective": {"src/svc.py": "def save(x):\n    q='SELECT id FROM t'\n"}})
    r = lum("impact", "--file", "src/svc.py", "--ranked", "--stdin-payload", "--json", stdin=payload2)
    dp2 = json.loads(r.stdout.strip().splitlines()[-1])
    check("delta 無關 → 整檔危險符號不誤觸發(v1.1)", not any("SQL" in x["node"] for x in dp2["results"] if x.get("kind") == "incident"),
          str([x for x in dp2["results"] if x.get("kind")=="incident"]))
    # incidents-only:只回事故段、不做 BFS
    r = lum("impact", "--file", "src/svc.py", "--incidents-only", "--stdin-payload", "--json", stdin=payload)
    di = json.loads(r.stdout.strip().splitlines()[-1])
    check("incidents-only 只有事故", all(x.get("kind") == "incident" for x in di["results"]),
          str(di)[:200])
    # 磁碟檔無 SQL → legacy(無 prospective)不觸發該事故
    r = lum("impact", "--file", "src/svc.py", "--json")
    d2 = json.loads(r.stdout.strip().splitlines()[-1])
    check("無 prospective 時磁碟無 SQL 不誤觸發", not any("SQL" in x["node"] for x in d2["incidents"]),
          str(d2["incidents"]))
    shutil.rmtree(root, ignore_errors=True)


def t_impact_diff():
    """impact --diff(code-loop 橋接):聚合整段 diff 的 ranked impact 成受影響功能面 manifest。"""
    import subprocess as sp, json, shutil
    root = Path(tempfile.mkdtemp(prefix="gctl-impd-"))
    def g(*a):
        sp.run(["git", "-C", str(root), *a], capture_output=True, text=True)
    g("init", "-q"); g("config", "user.email", "t@t.t"); g("config", "user.name", "t")
    v = root / "docs" / "z-knowledge"
    (v / "Systems").mkdir(parents=True); (v / "Issues").mkdir(); (v / "MOC").mkdir()
    (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")
    (v / "Systems" / "SvcCore.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ 不可空寫 [test:X]\n---\n"
        "# SvcCore\n實作在 `src/svc.py`。\n", encoding="utf-8")
    (v / "Systems" / "Helper.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:普通\n---\n# Helper\n`src/svc.py` 的輔助。\n",
        encoding="utf-8")
    (v / "Issues" / "SQL注入踩雷.md").write_text(
        "---\ntype: issue\nstatus: open\npitfall_when:\n  - \"content:SELECT.*FROM\"\n"
        "summary: |-\n  FLAG:TECHNICAL\n---\n# SQL 注入\n拼字串 SQL 的坑。\n", encoding="utf-8")
    (v / "Systems" / "OldSvc.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ 舊介面不可斷 [test:Y]\n---\n"
        "# OldSvc\n實作在 `src/old.py`。\n", encoding="utf-8")
    (root / "src").mkdir()
    (root / "src" / "svc.py").write_text("def save(x):\n    pass\n", encoding="utf-8")
    (root / "src" / "old.py").write_text("legacy = True\n", encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "init")
    # 第二筆 commit:svc.py 引入 SQL(觸發事故 trigger)+ 新增無圖譜引用的 other.py + 動圖譜節點(排除)
    # + 刪除被合約節點引用的 old.py(種子必須保留)+ governance 資料 json 與 README(必須排除)
    (root / "src" / "svc.py").write_text(
        "def save(x):\n    q = 'SELECT id FROM t'\n    return q\n", encoding="utf-8")
    (root / "src" / "other.py").write_text("pass\n", encoding="utf-8")
    (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n改一下\n", encoding="utf-8")
    g("rm", "-q", "src/old.py")
    (root / "src" / "服務.py").write_text("cjk = True\n", encoding="utf-8")
    (v / "Systems" / "服務核心.md").write_text("---\ntype: system\nstatus: done\nsummary: |-\n  KEY:x\n---\n# 服務核心\n", encoding="utf-8")
    (root / "governance" / "eval").mkdir(parents=True)
    (root / "governance" / "eval" / "data.json").write_text('{"x": 1}', encoding="utf-8")
    (root / "README.md").write_text("# readme\n", encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "change")
    def lum(*a, stdin=None):
        return sp.run([sys.executable, GRAPHCTL, *a], capture_output=True, text=True,
                      cwd=root, input=stdin)
    r = lum("impact", "--diff", "HEAD~1..HEAD", "--json")
    check("impact --diff rc0", r.returncode == 0, r.stderr[:200])
    d = json.loads(r.stdout.strip().splitlines()[-1])
    check("diff manifest 有 results/meta/files", set(d) >= {"results", "meta", "files"}, str(d)[:150])
    check("diff seed 含 code 檔", "src/svc.py" in d["files"] and "src/other.py" in d["files"], str(d["files"]))
    check("diff seed 排除圖譜節點", not any(f.startswith("docs/") for f in d["files"]), str(d["files"]))
    check("diff seed 保留已刪檔(合約反查)", "src/old.py" in d["files"], str(d["files"]))
    check("diff seed 排除 governance 資料 json 與 md",
          "governance/eval/data.json" not in d["files"] and "README.md" not in d["files"], str(d["files"]))
    check("已刪檔的合約節點進固定席(OldSvc)", any("OldSvc" in x["node"] for x in d["results"] if x.get("pinned")),
          str([x["node"] for x in d["results"]]))
    check("CJK 檔名:code 檔進種子(quotePath 修)", "src/服務.py" in d["files"], str(d["files"]))
    check("CJK 檔名:無引號跳脫垃圾路徑(quotePath 生效)",
          not any(f2.startswith('"') or "\\" in f2 for f2 in d["files"]), str(d["files"]))
    check("CJK 檔名:圖譜節點原始路徑被濾掉",
          "docs/z-knowledge/Systems/服務核心.md" not in d["files"], str(d["files"]))
    pinned = [x for x in d["results"] if x.get("pinned")]
    check("合約節點固定席(SvcCore)", any("SvcCore" in x["node"] for x in pinned), str(pinned)[:200])
    check("事故被磁碟現況觸發(SQL)", any("SQL" in x["node"] for x in pinned), str(pinned)[:200])
    check("非固定含 Helper 且帶來源檔", any("Helper" in x["node"] and x.get("files")
          for x in d["results"] if not x.get("pinned")), str(d["results"])[:300])
    # 落成核對(sync-check):SvcCore 受影響但 commit2 沒動它 → 列未同步(pinned 標必看);MOC 動過 → touched
    r = lum("impact", "--diff", "HEAD~1..HEAD", "--sync-check", "--json")
    ds = json.loads(r.stdout.strip().splitlines()[-1])
    check("sync-check: 有 sync 段", "sync" in ds, str(ds)[:120])
    check("sync-check: 動過的節點含 MOC", "MOC/i.md" in ds["sync"]["touched_nodes"], str(ds["sync"]["touched_nodes"]))
    miss = {m["node"]: m for m in ds["sync"]["missing"]}
    check("sync-check: SvcCore 受影響未同步且標必看", "Systems/SvcCore.md" in miss and miss["Systems/SvcCore.md"]["pinned"], str(miss.keys()))
    # 動過 SvcCore 後 → 不再列未同步
    (v / "Systems" / "SvcCore.md").write_text(
        "---\ntype: system\nstatus: done\nsummary: |-\n  KEY:★INVARIANT★ 不可空寫 [test:X]\n---\n# SvcCore\n實作在 `src/svc.py`。同步註記。\n", encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "sync node")
    r = lum("impact", "--diff", "HEAD~2..HEAD", "--sync-check", "--json")
    ds2 = json.loads(r.stdout.strip().splitlines()[-1])
    miss2 = {m["node"] for m in ds2["sync"]["missing"]}
    check("sync-check: 同步後 SvcCore 不再列缺", "Systems/SvcCore.md" not in miss2, str(miss2))
    # 人讀模式
    r = lum("impact", "--diff", "HEAD~2..HEAD")
    check("diff 人讀含標頭", "受影響功能面" in r.stdout, r.stdout[:150])
    r = lum("impact", "--diff", "HEAD~2..HEAD", "--sync-check")
    check("sync-check 人讀含落成核對段", "落成核對" in r.stdout, r.stdout[-300:])
    # 參數守衛:--file 與 --diff 都缺 → rc2
    r = lum("impact")
    check("impact 無 --file/--diff rc2", r.returncode == 2, str(r.returncode))
    shutil.rmtree(root, ignore_errors=True)


def t_check_j_regen():
    # Check J(regen 重生來源守衛):M1 from-scratch守衛;測試逐格對齊 spec v4 測試策略
    import shutil
    v = mkvault()
    tok = v.name  # 標準 mkvault 是 standalone vault → repo_root = v.parent,[src:] 用 v.name/ 前綴
    # --- set regen 白名單迴歸(r3 B#4) ---
    write(v, "Systems/R0.md", "type: system\nstatus: doing\nsummary: |-\n  KEY:某關鍵 [src:%s/Systems/R0.md]" % tok)
    run(v, "set", "Systems/R0", "regen", "from-scratch/2026-07-16", expect_rc=0)
    r = run(v, "lint", "Systems/R0")
    check("J: set regen rc0 + 全標記節點 lint rc0", r.returncode == 0, r.stdout)
    # --- 非 regen 節點不受 J 影響(無 J-a 訊息) ---
    write(v, "Systems/NR.md", "type: system\nstatus: doing\nsummary: |-\n  KEY:★INVARIANT★ 舊合約 [test:G] [audit:s/2026-07-01]")
    r = run(v, "lint", "Systems/NR")
    check("J: 非 regen 節點無 J-a 要求", r.returncode == 0 and "J-a" not in r.stdout, r.stdout)
    # --- J-a:regen ★INVARIANT★ 無 [src:]/[git:] → 擋;有 [src:] → 過 ---
    write(v, "Systems/Ja.md", "regen: from-scratch/2026-07-16\ntype: system\nstatus: doing\n"
          "summary: |-\n  KEY:★INVARIANT★ 重生合約 [test:G] [audit:s/2026-07-01]")
    r = run(v, "lint", "Systems/Ja")
    check("J-a: regen ★INVARIANT★ 無意圖證據 → rc1", r.returncode == 1 and "J-a 拒絕發明合約" in r.stdout, r.stdout)
    write(v, "Systems/Ja2.md", "regen: from-scratch/2026-07-16\ntype: system\nstatus: doing\n"
          "summary: |-\n  KEY:★INVARIANT★ 重生合約 [test:G] [audit:s/2026-07-01] [src:%s/Systems/R0.md]" % tok)
    r = run(v, "lint", "Systems/Ja2")
    check("J-a: 有 [src:] → rc0", r.returncode == 0, r.stdout)
    # --- J-b:DECISION 四態(有證據/推測/佚失/裸→擋) ---
    fm = "regen: from-scratch/2026-07-16\ntype: system\nstatus: doing\nsummary: |-\n  %s"
    write(v, "Systems/Jb1.md", fm % ("DECISION:選 A 因效能 [src:%s/Systems/R0.md]" % tok))
    write(v, "Systems/Jb2.md", fm % "DECISION:推測: 大概因效能選 A")
    write(v, "Systems/Jb3.md", fm % "DECISION:佚失: 選 A 原因已不可考")
    write(v, "Systems/Jb4.md", fm % "DECISION:選 A 因效能(重建無據)")
    for rel_, expect_rc, name in (("Jb1", 0, "有證據"), ("Jb2", 0, "推測標"), ("Jb3", 0, "佚失標"), ("Jb4", 1, "裸→擋")):
        r = run(v, "lint", f"Systems/{rel_}")
        check(f"J-b: DECISION {name} rc{expect_rc}", r.returncode == expect_rc, r.stdout)
    # --- J-c:[src:] substring gate(dangling/越界/合法/假頂層目錄——top_dirs 靜默放行迴歸) ---
    write(v, "Systems/Jc1.md", fm % "KEY:引用 [src:no_such_dir_xyz/x.py]")
    r = run(v, "lint", "Systems/Jc1")
    check("J-c: 假頂層目錄 → rc1(不因 top_dirs 靜默放行)", r.returncode == 1 and "dangling" in r.stdout, r.stdout)
    write(v, "Systems/Jc2.md", fm % ("KEY:引用 [src:%s/Systems/R0.md:999]" % tok))
    r = run(v, "lint", "Systems/Jc2")
    check("J-c: 行號越界 → rc1", r.returncode == 1 and "行號越界" in r.stdout, r.stdout)
    write(v, "Systems/Jc3.md", fm % ("KEY:引用 [src:%s/Systems/R0.md:1]" % tok))
    r = run(v, "lint", "Systems/Jc3")
    check("J-c: 合法路徑+行號 → rc0", r.returncode == 0, r.stdout)
    # --- J-c token 消毒(code-review blocker 迴歸):空/絕對路徑/traversal 皆擋 ---
    write(v, "Systems/Jc4.md", fm % "KEY:偽證據 [src: ] 空白充數")
    r = run(v, "lint", "Systems/Jc4")
    check("J-c: [src: ] 空 token → rc1(不因 join repo_root 自身判 ok)", r.returncode == 1 and "dangling" in r.stdout, r.stdout)
    write(v, "Systems/Jc5.md", fm % "KEY:偽證據 [src:/etc/passwd]")
    r = run(v, "lint", "Systems/Jc5")
    check("J-c: 絕對路徑 → rc1(pathlib join 丟左值不放行)", r.returncode == 1 and "dangling" in r.stdout, r.stdout)
    write(v, "Systems/Jc6.md", fm % "KEY:偽證據 [src:../../../../etc/passwd]")
    r = run(v, "lint", "Systems/Jc6")
    check("J-c: .. traversal → rc1", r.returncode == 1 and "dangling" in r.stdout, r.stdout)
    # --- raw 行四組合(推測/佚失 × INVARIANT/IRREVERSIBLE)→ rc1 專屬訊息;INVARIANT 組合恰一則 ---
    combos = [("Jr1", "KEY:推測:★INVARIANT★ 不確定的合約"), ("Jr2", "KEY:佚失:★INVARIANT★ 據已失的合約"),
              ("Jr3", "KEY:推測:★IRREVERSIBLE★ 不確定的不可逆"), ("Jr4", "DECISION:佚失:★IRREVERSIBLE★ 佚失不可逆")]
    for rel_, line_ in combos:
        write(v, f"Systems/{rel_}.md", fm % line_)
        r = run(v, "lint", f"Systems/{rel_}")
        check(f"J raw 行: {line_[:14]}… → rc1 專屬訊息", r.returncode == 1 and "不得承載" in r.stdout, r.stdout)
    r = run(v, "lint", "Systems/Jr1")
    check("J 消歧: INVARIANT 組合恰一則(無 generic 位置錯誤)",
          "不得承載" in r.stdout and "必須是 KEY 行前綴" not in r.stdout, r.stdout)
    # --- 非 regen 節點 KEY:推測:★INVARIANT★ → generic 兜底保留 ---
    write(v, "Systems/NRr.md", "type: system\nstatus: doing\nsummary: |-\n  KEY:推測:★INVARIANT★ 偷渡")
    r = run(v, "lint", "Systems/NRr")
    check("J 消歧: 非 regen 節點 generic 兜底保留", r.returncode == 1 and "必須是 KEY 行前綴" in r.stdout, r.stdout)
    # --- J-d:無標記 KEY 行 → warning 顯示但 rc0(兩入口皆非阻擋) ---
    write(v, "Systems/Jd.md", fm % "KEY:一條沒標 tier 的觀察")
    r = run(v, "lint", "Systems/Jd")
    check("J-d: 無標記 KEY 行提醒不擋 rc0", r.returncode == 0 and "J-d 提醒" in r.stdout, r.stdout)
    # --- INV_TAG_RE 擴充:contracts 顯示乾淨(不含 [src:) ---
    r = run(v, "contracts", "Systems/Ja2")
    check("INV_TAG_RE: contracts 顯示剝掉 [src:]", "[src:" not in r.stdout, r.stdout)
    # --- doctor 入口:errs 計 issues(--ci rc1);J-d 走 warn_soft 不計 ---
    r = run(v, "doctor", "--ci")
    check("J doctor: regen 違規 → --ci rc1", r.returncode == 1 and "regen 重生來源守衛" in r.stdout, r.stdout[-800:])
    for rel_ in ("Ja", "Jb4", "Jc1", "Jc2", "Jc4", "Jc5", "Jc6", "Jr1", "Jr2", "Jr3", "Jr4", "NRr"):
        (v / "Systems" / f"{rel_}.md").unlink()
    r = run(v, "doctor", "--ci")
    check("J doctor: 全合規後 rc0 + J-d warn_soft 不計 issues",
          r.returncode == 0 and "0 issues" in r.stdout, r.stdout[-800:])
    shutil.rmtree(v, ignore_errors=True)


def t_check_j_git():
    # Check J 的 [git:sha] Tier B 驗證:真 sha 過/假 sha 擋/shallow 降 warn 不擋
    import shutil
    import subprocess as sp
    base = Path(tempfile.mkdtemp(prefix="gctl-jgit-"))
    def _git(cwd, *args):
        return sp.run(["git", "-C", str(cwd), *args], capture_output=True, text=True)
    try:
        # origin:兩個 commit 的真 git repo
        origin = base / "origin"; origin.mkdir()
        _git(origin, "init", "-q"); _git(origin, "config", "user.email", "t@t"); _git(origin, "config", "user.name", "t")
        (origin / "a.txt").write_text("one\n"); _git(origin, "add", "."); _git(origin, "commit", "-qm", "c1")
        sha1 = _git(origin, "rev-parse", "HEAD").stdout.strip()
        (origin / "b.txt").write_text("two\n"); _git(origin, "add", "."); _git(origin, "commit", "-qm", "c2")
        # vault 掛在 origin/docs/k-knowledge → _repo_root_from_env 解析到 origin
        vault = origin / "docs" / "k-knowledge"
        for sub in ("Systems", "Verification", "Projects", "MOC"):
            (vault / sub).mkdir(parents=True)
        fm = "regen: from-scratch/2026-07-16\ntype: system\nstatus: doing\nsummary: |-\n  %s"
        write(vault, "Systems/G1.md", fm % f"KEY:改法源自 [git:{sha1}]")
        r = run(vault, "lint", "Systems/G1")
        check("J-c git: 真 sha → rc0", r.returncode == 0, r.stdout)
        write(vault, "Systems/G2.md", fm % "KEY:改法源自 [git:deadbeefdeadbeefdeadbeefdeadbeefdeadbeef]")
        r = run(vault, "lint", "Systems/G2")
        check("J-c git: 假 sha(full clone) → rc1 dangling", r.returncode == 1 and "dangling" in r.stdout, r.stdout)
        # shallow clone:只有 c2,sha1 缺 → warn 不擋 + 顯性標示
        shallow = base / "shallow"
        sp.run(["git", "clone", "--no-local", "--depth=1", "-q", f"file://{origin}", str(shallow)],
               capture_output=True, text=True)
        if (shallow / ".git").exists():
            svault = shallow / "docs" / "k-knowledge"
            for sub in ("Systems", "Verification", "Projects", "MOC"):
                (svault / sub).mkdir(parents=True, exist_ok=True)
            write(svault, "Systems/S1.md", fm % f"KEY:改法源自 [git:{sha1}]")
            r = run(svault, "lint", "Systems/S1")
            check("J-c git: shallow 缺物件 → rc0 warn 顯性標示",
                  r.returncode == 0 and "Tier B 驗證跳過" in r.stdout, r.stdout)
        else:
            check("J-c git: shallow clone 建立失敗(環境不支援 --no-local --depth,跳過此格)", False, "shallow clone failed")
    finally:
        shutil.rmtree(base, ignore_errors=True)


def t_m2_cluster_gate():
    """M2 risk-cluster 三態帳:record 解析/有效輪謂詞/定錨/混用/fold/gate 兩條合取/advisory/ledger。
    spec: Projects/design-loop提效_計劃 v4(golden: governance/golden/dloop-m2-cluster)。"""
    import subprocess as _sp

    def _mkvault(d):
        v = Path(d) / "docs" / "y-knowledge"
        (v / "MOC").mkdir(parents=True)
        (v / "MOC" / "i.md").write_text("---\ntype: moc\n---\n", encoding="utf-8")

    def _rec(d, *extra):
        return _sp.run([sys.executable, GRAPHCTL, "canary", "record", *extra],
                       cwd=str(Path(d)), capture_output=True, text=True)

    def _st(d, loop="CL", *extra):
        return _sp.run([sys.executable, GRAPHCTL, "loop", "status", loop, "--panel", *extra],
                       cwd=str(Path(d)), capture_output=True, text=True)

    # ── record 解析(寫側) ──
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", "a=resolved,b=disputed-major")
        check("M2 rec: 合法三態 rc0", r.returncode == 0, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", "x=weird")
        check("M2 rec: 壞狀態 rc2", r.returncode == 2 and "白名單" in r.stderr, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", "a b=resolved")
        check("M2 rec: 名含空白 rc2", r.returncode == 2, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", "a=resolved,a=resolved")
        check("M2 rec: 同輪重名 rc2", r.returncode == 2 and "重複" in r.stderr, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", "a=resolved,")
        check("M2 rec: 尾逗號空段過濾 rc0", r.returncode == 0, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", ",")
        check("M2 rec: 全逗號空列表 rc2", r.returncode == 2 and "無有效內容" in r.stderr, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", "")
        check("M2 rec: 空字串 rc2(帶旗標即須內容)", r.returncode == 2, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", "abc")
        check("M2 rec: 段缺 = rc2 非崩潰", r.returncode == 2 and "Traceback" not in r.stderr, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", "a=accepted-minor")
        check("M2 rec: accepted-minor 缺理由 rc2", r.returncode == 2 and "理由" in r.stderr, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", "a=accepted-minor:字太小可接受")
        check("M2 rec: accepted-minor:理由 rc0", r.returncode == 0, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", "a=resolved:偷渡後綴")
        check("M2 rec: resolved 夾帶冒號後綴 rc2(三態精確相等)", r.returncode == 2 and "後綴" in r.stderr, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", "a=disputed-major:foo")
        check("M2 rec: disputed-major 夾帶後綴 rc2", r.returncode == 2, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", 'a"b=resolved')
        check("M2 rec: 名含引號 rc2(kebab slug)", r.returncode == 2, r.stderr)
        r = _rec(d, "caught", "--loop", "CL", "--round", "r1", "--clusters", "AB=resolved")
        check("M2 rec: 名非小寫 kebab rc2", r.returncode == 2, r.stderr)

    def _round(d, rid, kinds, clusters_on=None, clusters=None, loop="CL"):
        # kinds: list like ["caught","caught","missed"];clusters_on=index of record carrying --clusters
        for i, k in enumerate(kinds):
            extra = ["--token", f"{rid}T{i}"]
            if clusters_on is not None and i == clusters_on:
                extra += ["--clusters", clusters]
            _rec(d, k, "--loop", loop, "--round", rid, "--severity", "clean", *extra)

    # ── gate:定錨+兩條合取+K=1(首個有效輪 accepted-minor 首現可收斂) ──
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=resolved,b=accepted-minor:小字可忍")
        r = _st(d)
        check("M2 gate: 首個有效輪 resolved+accepted-minor → PASS(K=1)",
              r.returncode == 0 and "PASS" in r.stdout, f"rc={r.returncode}\n{r.stdout}{r.stderr}")
        check("M2 ledger: accepted-minor 理由顯示", "小字可忍" in r.stdout, r.stdout)
        check("M2 advisory: 無 counts 不 fail-closed", "僅供參考" in r.stdout, r.stdout)
        check("M2 advisory: 新生 cluster 計數+名單格式", "新生 cluster: 2 個" in r.stdout and "a,b" in r.stdout, r.stdout)

    # disputed-major 擋
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=disputed-major")
        r = _st(d)
        check("M2 gate: disputed-major → FAIL rc1", r.returncode == 1 and "disputed-major" in r.stdout, r.stdout)

    # fold:disputed→resolved 放行;resolved→disputed 回鎖
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=disputed-major")
        _round(d, "r2", ["caught", "caught"], 1, "a=resolved")
        r = _st(d)
        check("M2 fold: disputed→resolved 放行", r.returncode == 0, f"rc={r.returncode}\n{r.stdout}")
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=resolved")
        _round(d, "r2", ["caught", "caught"], 1, "a=disputed-major")
        r = _st(d)
        check("M2 fold: resolved→disputed 回鎖", r.returncode == 1, r.stdout)

    # 有效輪謂詞:2caught+1missed 輪的 clusters 不採(掛 caught 記錄上也不採)
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=disputed-major")
        _round(d, "r2", ["caught", "caught", "missed"], 0, "a=resolved")  # 無效輪試洗白
        r = _st(d)
        check("M2 謂詞: 無效輪(2c+1m)resolved 不得清 disputed-major",
              r.returncode == 1 and "disputed-major" in r.stdout, r.stdout)
        check("M2 警告區: 無效輪 clusters 已忽略列帳", "已忽略" in r.stdout, r.stdout)
    # 孤席輪:1caught+0missed 也是無效輪(謂詞 caught≥2;殺 MUT1)
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=disputed-major")
        _round(d, "r2", ["caught"], 0, "a=resolved")   # 孤席輪試洗白
        r = _st(d)
        check("M2 謂詞: 孤席輪(1c)resolved 不得清 disputed-major",
              r.returncode == 1 and "disputed-major" in r.stdout, f"rc={r.returncode}\n{r.stdout}")
    # 未知 kind 盲區:2caught+1未知 → 輪無效(謂詞補全)
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=disputed-major")
        import json as _j
        log = Path(d) / "docs" / ".canary-log.jsonl"
        rows = [_j.loads(x) for x in log.read_text(encoding="utf-8").splitlines()]
        rows.append({"ts": rows[-1]["ts"], "kind": "caught", "auditor": "", "token": "X1",
                     "note": "", "loop": "CL", "round": "r2", "severity": "clean"})
        rows.append({"ts": rows[-1]["ts"], "kind": "caught", "auditor": "", "token": "X2",
                     "note": "", "loop": "CL", "round": "r2", "severity": "clean",
                     "clusters": {"a": "resolved"}})
        rows.append({"ts": rows[-1]["ts"], "kind": "wat", "auditor": "", "token": "X3",
                     "note": "", "loop": "CL", "round": "r2"})
        log.write_text("".join(_j.dumps(x, ensure_ascii=False) + "\n" for x in rows), encoding="utf-8")
        r = _st(d)
        check("M2 謂詞: 2caught+1未知kind=無效輪(盲區補全)",
              r.returncode == 1 and "disputed-major" in r.stdout, f"rc={r.returncode}\n{r.stdout}")

    # 定錨:首輪全 missed 不定錨,第一個有效輪才定錨(cluster 模式成立)
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["missed", "missed"])          # 無效首輪,無 clusters
        _round(d, "r2", ["caught", "caught"], 1, "a=resolved")
        r = _st(d)
        check("M2 定錨: 首輪全 missed 不鎖死,r2 有效輪定錨 cluster → PASS",
              r.returncode == 0, f"rc={r.returncode}\n{r.stdout}{r.stderr}")

    # 混用:定錨無-cluster 後續有效輪帶 → rc2 分因指路
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"])           # 有效輪,無 clusters → 定錨無-cluster
        _round(d, "r2", ["caught", "caught"], 1, "a=resolved")
        r = _st(d)
        check("M2 混用: 定錨無-cluster 後續帶 → rc2+指路開新 loop",
              r.returncode == 2 and "開新的審查編號" in r.stderr, f"rc={r.returncode}\n{r.stderr}")
    # 混用:定錨 cluster 後續有效輪半帶 → rc2;無效輪不帶=豁免
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=resolved")
        _round(d, "r2", ["caught", "missed"])            # 無效輪不帶 → 豁免
        _round(d, "r3", ["caught", "caught"], 1, "b=resolved")
        r = _st(d)
        check("M2 混用: 無效輪不帶豁免、有效輪皆帶 → PASS", r.returncode == 0,
              f"rc={r.returncode}\n{r.stdout}{r.stderr}")
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=resolved")
        _round(d, "r2", ["caught", "caught"])            # 有效輪半帶 → rc2
        r = _st(d)
        check("M2 混用: 有效輪半帶 → rc2", r.returncode == 2 and "沒帶分組" in r.stderr, r.stderr)

    # W 歸屬:有效輪 >1 筆帶 → rc2;無效輪多筆帶 → 豁免列警告
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _rec(d, "caught", "--loop", "CL", "--round", "r1", "--token", "A", "--severity", "clean",
             "--clusters", "a=resolved")
        _rec(d, "caught", "--loop", "CL", "--round", "r1", "--token", "B", "--severity", "clean",
             "--clusters", "b=resolved")
        r = _st(d)
        check("M2 W歸屬: 有效輪雙帶 → rc2", r.returncode == 2 and "只能有一筆" in r.stderr, r.stderr)
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _rec(d, "caught", "--loop", "CL", "--round", "r1", "--token", "A", "--clusters", "a=disputed-major")
        _rec(d, "missed", "--loop", "CL", "--round", "r1", "--token", "B", "--clusters", "b=resolved")
        _round(d, "r2", ["caught", "caught"], 1, "c=resolved")
        r = _st(d)
        check("M2 W歸屬: 無效輪多筆帶=豁免不 rc2(r2 定錨)", r.returncode == 0,
              f"rc={r.returncode}\n{r.stdout}{r.stderr}")
        check("M2 警告區: 無效輪雙帶列帳", r.stdout.count("已忽略") >= 1, r.stdout)

    # round-id 非連續重現 → rc2
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=resolved")
        _round(d, "r2", ["caught", "caught"], 1, "b=resolved")
        _rec(d, "caught", "--loop", "CL", "--round", "r1", "--token", "Z", "--clusters", "c=resolved")
        r = _st(d)
        check("M2 round-id: 非連續重現 → rc2", r.returncode == 2 and "非連續" in r.stderr, r.stderr)

    # 讀側型別防禦:clusters 欄損壞 → rc2 非 traceback
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=resolved")
        import json as _j
        log = Path(d) / "docs" / ".canary-log.jsonl"
        rows = [_j.loads(x) for x in log.read_text(encoding="utf-8").splitlines()]
        rows[-1]["clusters"] = "corrupted-string"
        log.write_text("".join(_j.dumps(x, ensure_ascii=False) + "\n" for x in rows), encoding="utf-8")
        r = _st(d)
        check("M2 型別防禦: 損壞 clusters → rc2 非 traceback",
              r.returncode == 2 and "Traceback" not in r.stderr, f"rc={r.returncode}\n{r.stderr}")

    # 新生 advisory:判定輪無效 → 印不適用;capture-counts 超門檻 → advisory 不擋
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=resolved")
        _round(d, "r2", ["caught", "missed"], 0, "b=resolved")   # 判定輪無效
        r = _st(d)
        check("M2 advisory: 判定輪無效 → 新生統計不適用+FAIL",
              r.returncode == 1 and "不統計" in r.stdout, r.stdout)
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        for i, tok in enumerate(("A", "B")):
            extra = ["--token", tok, "--severity", "clean"]
            if i == 1:
                extra += ["--clusters", "a=resolved", "--capture-counts", "1,1,1,1"]  # 低重疊=高殘餘
            _rec(d, "caught", "--loop", "CL", "--round", "r1", *extra)
        r = _st(d)
        check("M2 advisory: capture 殘餘超門檻仍 PASS(不進合取)",
              r.returncode == 0 and "僅供參考" in r.stdout, f"rc={r.returncode}\n{r.stdout}")
    # 無效輪同名多筆:警告區全列(不覆蓋)
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _rec(d, "caught", "--loop", "CL", "--round", "r1", "--token", "A", "--clusters", "a=disputed-major")
        _rec(d, "missed", "--loop", "CL", "--round", "r1", "--token", "B", "--clusters", "a=resolved")
        _round(d, "r2", ["caught", "caught"], 1, "c=resolved")
        r = _st(d)
        check("M2 警告區: 無效輪同名多筆全列(disputed 不被 resolved 覆蓋)",
              "a=disputed-major" in r.stdout and "a=resolved" in r.stdout, r.stdout)
    # 零有效輪+cluster-intent:unknown-kind 盲區不放行
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        import json as _j
        log = Path(d) / "docs" / ".canary-log.jsonl"
        rows = [{"ts": "t", "kind": "caught", "auditor": "", "token": "A", "note": "",
                 "loop": "CL", "round": "r1", "severity": "clean",
                 "clusters": {"a": "resolved"}, "capture_counts": [2, 2]},
                {"ts": "t", "kind": "caught", "auditor": "", "token": "B", "note": "",
                 "loop": "CL", "round": "r1", "severity": "clean"},
                {"ts": "t", "kind": "wat", "auditor": "", "token": "C", "note": "",
                 "loop": "CL", "round": "r1"}]
        log.write_text("".join(_j.dumps(x, ensure_ascii=False) + "\n" for x in rows), encoding="utf-8")
        r = _st(d)
        check("M2 零有效輪: cluster-intent+unknown-kind 不放行(未定錨嚴格謂詞)",
              r.returncode == 1 and "還沒定下來" in r.stdout, f"rc={r.returncode}\n{r.stdout}")
    # --gate 對 panel no-op
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"], 1, "a=resolved")
        r1 = _st(d)
        r2 = _st(d, "CL", "--gate", "--repo", d)
        check("M2 --gate: 對 panel no-op(兩呼叫同 rc)", r1.returncode == r2.returncode == 0,
              f"{r1.returncode}/{r2.returncode}")

    # 無-cluster 舊帳迴歸(2026-08-14 降級後):capture advisory 不擋,合取剩輪有效∧存活
    with tempfile.TemporaryDirectory() as d:
        _mkvault(d)
        _round(d, "r1", ["caught", "caught"])            # 無 clusters,無 counts
        r = _st(d)
        check("M2 迴歸: 無-cluster 舊帳 capture 降 advisory → rc0+缺席提示",
              r.returncode == 0 and "沒有重疊數據" in r.stdout, f"rc={r.returncode}\n{r.stdout}")


def t_testlayers_units():
    """test-layers 純函式:config 載入 fail-open + 棧命中去重保序。"""
    import json as _json
    import tempfile
    from pathlib import Path as _P
    from importlib.machinery import SourceFileLoader
    import importlib.util
    lumos_path = _P(__file__).parent / "lumos"
    spec = importlib.util.spec_from_file_location(
        "lumos_mod", str(lumos_path), loader=SourceFileLoader("lumos_mod", str(lumos_path)))
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)

    with tempfile.TemporaryDirectory() as td:
        # 無檔 → None
        check("testlayers 無宣告檔回 None", m._testlayers_load_config(td) is None)
        lp = _P(td) / ".lumos"
        lp.mkdir()
        # 壞 JSON → None(fail-open)
        (lp / "test-layers.json").write_text("{broken", encoding="utf-8")
        check("testlayers 壞 JSON fail-open None", m._testlayers_load_config(td) is None)
        # 非 dict 頂層 → None
        (lp / "test-layers.json").write_text("[1,2]", encoding="utf-8")
        check("testlayers 非 dict 頂層回 None", m._testlayers_load_config(td) is None)
        # 正常
        cfg = {"vue": {"layer": "E2E", "cmd": "npx playwright test", "when": "UI 有動"},
               "kt": {"layer": "UI 流程", "cmd": "maestro test flows/"}}
