def t_slim_gen_nested_loop_registration():
    """★缺陷重現★(審查以合成 fixture 實地示範):保留指令用迴圈註冊「自己的」
    巢狀子指令時,那段迴圈不得被當成頂層指令迴圈整段砍空。

    `_is_registration_loop` 只看 body 有沒有 `X.add_parser(迴圈變數, ...)`,
    完全沒查 receiver `X` 是不是頂層 subparsers 變數(top_var)。otherkeep 底下
    的 `osub`(它自己的 add_subparsers 產物)長得跟頂層 `sub` 一樣的呼叫形狀,
    若不限 receiver,`collect_edits()`(以及 `main()` 印診斷用的 allc 掃描——
    兩邊是同一段未防護邏輯,不是各自獨立的問題)會把 osub 迴圈的元素("removeme"/
    "x2")拿去跟『頂層』keep 名單比對——這兩個名字當然不在裡面,於是判定
    kept=[]、整段迴圈砍空,即使 otherkeep 本身在保留清單裡。"""
    import tempfile as _tf
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimgen-nestedloop-"))
    src = root / "toy.py"
    src.write_text(
        "import argparse, sys\n"
        "def cmd_keepme():\n    print('keep'); return 0\n"
        "def cmd_dropme():\n    print('drop'); return 0\n"
        "def cmd_ocmd_removeme():\n    print('removeme'); return 0\n"
        "def cmd_ocmd_x2():\n    print('x2'); return 0\n"
        "def main():\n"
        "    ap = argparse.ArgumentParser()\n"
        "    sub = ap.add_subparsers(dest='cmd')\n"
        "    for name, hlp in (('keepme','k'), ('dropme','d')):\n"
        "        sub.add_parser(name, help=hlp)\n"
        "    p2 = sub.add_parser('otherkeep')\n"
        "    osub = p2.add_subparsers(dest='ocmd', required=True)\n"
        "    for _n, _h in (('removeme','h1'), ('x2','h2')):\n"
        "        osub.add_parser(_n, help=_h)\n"
        "    args = ap.parse_args()\n"
        "    if args.cmd == 'keepme':\n        return cmd_keepme()\n"
        "    if args.cmd == 'dropme':\n        return cmd_dropme()\n"
        "    if args.cmd == 'otherkeep':\n"
        "        if args.ocmd == 'removeme':\n            return cmd_ocmd_removeme()\n"
        "        if args.ocmd == 'x2':\n            return cmd_ocmd_x2()\n"
        "    return 2\n"
        "if __name__ == '__main__':\n    sys.exit(main())\n",
        encoding="utf-8")

    gen = str(_P(GRAPHCTL).parent / "slim-gen.py")
    out = root / "out.py"
    r = subprocess.run([sys.executable, gen, "--src", str(src), "--outfile", str(out),
                        "--keep", "keepme", "otherkeep", "--no-update-inject"], capture_output=True, text=True)
    check("slim-gen 巢狀迴圈 fixture rc0", r.returncode == 0, r.stdout + r.stderr)
    txt = out.read_text(encoding="utf-8")
    # ★缺陷重現★:直接查『迴圈本體』(osub.add_parser 呼叫)還在不在——不能只
    # 查 'removeme'/'x2' 字面值,那兩個字串在保留的 dispatch if 條件
    # (`args.ocmd == 'removeme'`)裡也會出現,不是可靠的氧化指標。
    check("★缺陷重現★ otherkeep 的巢狀註冊迴圈本體仍在",
          "osub.add_parser(_n" in txt, txt)
    check("cmd_ocmd_removeme 函式未被誤刪", "def cmd_ocmd_removeme" in txt, txt[:800])
    check("cmd_ocmd_x2 函式未被誤刪", "def cmd_ocmd_x2" in txt, txt[:800])
    check("otherkeep 本身仍在", "'otherkeep'" in txt, txt[:800])
    # ★頂層行為不得退化★:與 t_slim_gen_loop_registration 同款頂層迴圈砍法
    check("頂層迴圈 dropme 仍正確被砍", "'dropme'" not in txt and '"dropme"' not in txt, txt)
    check("頂層迴圈 keepme 仍在", "'keepme'" in txt, txt[:400])
    check("cmd_dropme 函式被移除", "def cmd_dropme" not in txt, txt[:400])

    h = subprocess.run([sys.executable, str(out), "--help"], capture_output=True, text=True)
    check("產物 --help 頂層不含 dropme", "dropme" not in h.stdout, h.stdout)
    check("產物 --help 頂層含 otherkeep", "otherkeep" in h.stdout, h.stdout)

    h2 = subprocess.run([sys.executable, str(out), "otherkeep", "--help"],
                        capture_output=True, text=True)
    check("otherkeep --help 列得出巢狀子指令 removeme",
          "removeme" in h2.stdout, h2.stdout + h2.stderr)
    check("otherkeep --help 列得出巢狀子指令 x2",
          "x2" in h2.stdout, h2.stdout + h2.stderr)


def t_slim_gen():
    """對真實 scripts/lumos 生成:產物 --help 只剩保留指令、compileall 過、無 dangling handler。"""
    import tempfile as _tf
    import re as _re
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimgen-"))
    gen = str(_P(GRAPHCTL).parent / "slim-gen.py")
    out = root / "lumos"

    r = subprocess.run([sys.executable, gen, "--outfile", str(out)],
                       capture_output=True, text=True)
    check("slim-gen 真檔 rc0", r.returncode == 0, r.stdout + r.stderr)

    h = subprocess.run([sys.executable, str(out), "--help"], capture_output=True, text=True)
    m = _re.search(r"\{([a-z0-9,\-]+)\}", h.stdout)
    got = set(m.group(1).split(",")) if m else set()
    keep = set("""append archive backlinks context contracts decision-add decision-reindex
decision-supersede decisions delguard doctor export guard links lint map new query recent
rel-cascade search set show stale stats sync-verified-by""".split())
    check("產物 --help == 保留 26 支", got == keep, f"多={sorted(got-keep)} 少={sorted(keep-got)}")

    c = subprocess.run([sys.executable, "-W", "error::SyntaxWarning",
                        "-m", "py_compile", str(out)], capture_output=True, text=True)
    check("產物 py_compile 0 SyntaxWarning", c.returncode == 0, c.stderr)

    # dangling handler = 0:產物內被呼叫但未定義的 cmd_*/run_* 名稱
    import ast as _ast
    tree = _ast.parse(out.read_text(encoding="utf-8"))
    # ★類別也算「定義過」★(2026-09-07 全 repo 審視 #9):這條原本只認 FunctionDef,
    # 於是新加的 _LumosParser(自訂錯誤訊息用的 ArgumentParser 子類)被誤判成懸空——
    # 它其實好好地在產物裡。判準漏了一種定義形式,不是產物有問題。
    defined = {n.name for n in _ast.walk(tree)
               if isinstance(n, (_ast.FunctionDef, _ast.AsyncFunctionDef, _ast.ClassDef))}
    called = {c.func.id for c in _ast.walk(tree)
              if isinstance(c, _ast.Call) and isinstance(c.func, _ast.Name)}
    dangling = {n for n in (called - defined) if n.startswith(("cmd_", "run_", "_"))}
    check("產物 dangling handler = 0", not dangling, str(sorted(dangling)))

    # slim 產物 delguard 功能煙霧(AST 閉包完整性:helper/常數都要被帶進產物)
    droot, dgr = _mk_delguard_repo()
    ds = subprocess.run([sys.executable, str(out), "delguard", "--staged"],
                        capture_output=True, text=True, cwd=str(droot))
    check("slim delguard rc0", ds.returncode == 0, ds.stderr[:300])
    check("slim delguard 命中警告", "refreshPaywayCredentials" in ds.stdout and "退場前自問" in ds.stdout, ds.stdout[:300])

    # slim 交付範本的「N 支」宣稱與 keep 清單同步(2026-08-11 code review 抓到三處 24 支殘留)
    tpl_root = _P(GRAPHCTL).parent.parent / "slim"
    for tpl in ("README.md", "claude-block.md", "skills/lumos-project-notes/reference.md"):
        txt = (tpl_root / tpl).read_text(encoding="utf-8")
        claims = _re.findall(r"(\d+) 支(?:指令|頂層命令|子集)", txt)
        check(f"slim 範本 {tpl} 支數宣稱與 keep 同步", claims and all(int(c) == len(keep) for c in claims),
              f"{tpl}: claims={claims} keep={len(keep)}")
    import shutil as _sh
    _sh.rmtree(droot, ignore_errors=True)


def t_slim_gen_keeps_comments():
    """★行級手術的存在理由★:產物必須保住註解密度。
    若有人把生成器改回 ast.unparse(語法樹無註解),密度會掉到 0,這條翻紅。

    2026-07-31 二次校正(接手收尾,對抗實測後再改一次):任意百分比門檻(≥50%/
    ≥60%)沒有意義——砍多砍少都會動它,不是行級手術這個設計本身的性質。真正
    該鎖的是「註解密度沒有下降」,那才是行級手術(相對 ast.unparse)的實質保證,
    照樣抓得住 ast.unparse(密度歸零)。哨兵改成 test_lumos.py 260→94 那條事故
    脈絡註解——它出現兩處:一處在模組層 TEST_PROFILES dict 字面值裡(module-level
    語句,不受函式級刪除影響)、一處在保留指令可達閉包內的 discover_test_methods()
    裡,兩種情況都保證留在產物中,比綁在某支可能被砍的函式內更穩。原哨兵 W4
    位於 _link_or_copy(只被 _install_skills → cmd_install/cmd_uninstall 呼叫,
    兩支都在移除清單),被正當砍掉不是生成器的錯,是 brief 挑錯哨兵。"""
    import tempfile as _tf
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).parent.parent
    out = _P(_tf.mkdtemp(prefix="gctl-slimcmt-")) / "lumos"
    r = subprocess.run([sys.executable, str(repo / "scripts" / "slim-gen.py"),
                        "--outfile", str(out)], capture_output=True, text=True)
    check("slim-gen rc0", r.returncode == 0, r.stdout + r.stderr)

    def _density(p):
        lines = _P(p).read_text(encoding="utf-8").splitlines()
        c = sum(1 for ln in lines if ln.lstrip().startswith("#"))
        return c, len(lines), (c / len(lines) if lines else 0)

    sc, sl, sd = _density(repo / "scripts" / "lumos")
    oc, ol, od = _density(out)
    # ★密度不得低於原檔的 90%★:抓得住 unparse(密度歸零),又不因砍多砍少假紅
    check(f"★產物註解密度未下降★(原 {sc}/{sl}={sd:.1%} → 產物 {oc}/{ol}={od:.1%})",
          od >= sd * 0.9, f"密度掉到 {od:.1%}")
    # 哨兵:一條確實留在產物裡的事故脈絡註解(選在保留側函式內)
    txt = _P(out).read_text(encoding="utf-8")
    check("事故脈絡註解仍在(實測 test_lumos.py 260→94 那條)",
          "260→94" in txt, "哨兵註解不見了")


def t_slim_install_no_project_touch():
    """★反事實(2026-07-31 [S3] 第三次裁定,換形狀非放鬆)★:安裝器**會**動專案層
    的 CLAUDE.md——當專案沒有完整版 `LUMOS:GRAPH-DISCIPLINE` 區塊時,精簡版區塊
    插在檔首「# 標題」之後(不是檔尾),既有內容原封不動地被保留、只是位置往後
    挪。斷言:①既有內容仍完整存在(順序不變,只是被插入點隔開)②`.git/config`
    前後相同(裁定沒開放碰 git 設定)③除 CLAUDE.md 外,worktree 內不新增/修改
    任何檔案。且不得無備份覆寫既有機器層資產。"""
    import tempfile as _tf, os as _os, shutil as _sh
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-"))

    # 造一個假交付包
    pkg = root / "pkg"
    (pkg / "scripts").mkdir(parents=True)
    (pkg / "skills" / "lumos-project-notes").mkdir(parents=True)
    (pkg / "scripts" / "lumos").write_text("#!/usr/bin/env python3\nprint('slim')\n",
                                           encoding="utf-8")
    (pkg / "scripts" / "lumos").chmod(0o755)
    (pkg / "skills" / "lumos-project-notes" / "SKILL.md").write_text("# skill\n",
                                                                     encoding="utf-8")
    repo = _P(GRAPHCTL).parent.parent
    _slim_copy_install_files(pkg)

    # 造一個假專案 repo —— CLAUDE.md 帶既有內容、無完整版紀律區塊(模擬一般專案)
    proj = root / "proj"
    proj.mkdir()
    subprocess.run(["git", "init", "-q", str(proj)], check=True)
    heading = "# 專案紀律\n"
    rest = "\n這是既有內容,一個位元組都不該被動。\n引用 lumos-project-notes 9 次(模擬 Landmark)。\n"
    claude_md_original = heading + rest
    (proj / "CLAUDE.md").write_text(claude_md_original, encoding="utf-8")
    (proj / "scripts").mkdir()
    (proj / "scripts" / "own.py").write_text("print(1)\n", encoding="utf-8")
    subprocess.run(["git", "-C", str(proj), "add", "-A"], check=True)
    subprocess.run(["git", "-C", str(proj), "-c", "user.email=t@t", "-c", "user.name=t",
                    "commit", "-qm", "init"], check=True)
    cfg_before = (proj / ".git" / "config").read_text(encoding="utf-8")

    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))
    r = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                       capture_output=True, text=True, env=env)
    check("安裝器 rc0", r.returncode == 0, r.stdout + r.stderr)

    st = subprocess.run(["git", "-C", str(proj), "status", "--porcelain"],
                        capture_output=True, text=True)
    porcelain_lines = [ln for ln in st.stdout.splitlines() if ln.strip()]
    check("★除 CLAUDE.md 外不新增/修改任何檔案★ porcelain 只有一條且是 CLAUDE.md",
          porcelain_lines == [" M CLAUDE.md"], st.stdout)
    check("★專案 .git/config 前後相同★",
          (proj / ".git" / "config").read_text(encoding="utf-8") == cfg_before, "")

    claude_md_after = (proj / "CLAUDE.md").read_text(encoding="utf-8")
    check("★插入點=檔首標題之後★ 精簡版區塊緊接在第一行標題後",
          claude_md_after.startswith(heading + "<!-- LUMOS-SLIM:START -->"),
          claude_md_after[:200])
    check("★sentinel 外內容 byte-equal★ 標題之後的原內容原封不動接在區塊之後",
          claude_md_after.endswith(rest), claude_md_after[-200:])
    check("★純插入,不動既有 byte★ 挖掉中間插入的區塊後可還原成原檔",
          claude_md_after[:len(heading)] + claude_md_after[-len(rest):] == claude_md_original,
          "")
    check("★附加而非覆蓋★ sentinel 區塊確實被加上",
          "<!-- LUMOS-SLIM:START -->" in claude_md_after
          and "<!-- LUMOS-SLIM:END -->" in claude_md_after, "")
    check("沒有完整版區塊時不產生 FULL-BACKUP",
          "<!-- LUMOS-SLIM:FULL-BACKUP:NONE -->" in claude_md_after, claude_md_after)

    check("全域指令已裝", (fake_home / ".local" / "bin" / "lumos").exists(), "")
    check("skill 已實體複製(非 symlink)",
          (fake_home / ".claude" / "skills" / "lumos-project-notes" / "SKILL.md").is_file()
          and not (fake_home / ".claude" / "skills" / "lumos-project-notes").is_symlink(), "")
    check("不裝任何 Claude hook",
          not (fake_home / ".claude" / "hooks").exists(), "")

    # ★反誤傷★:既有一般檔不得被刪
    (fake_home / ".local" / "bin" / "lumos").unlink()
    (fake_home / ".local" / "bin" / "lumos").write_text("USER OWN\n", encoding="utf-8")
    r2 = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("既有一般檔 → 拒絕 rc2", r2.returncode == 2, r2.stdout + r2.stderr)
    check("既有一般檔內容未被動",
          (fake_home / ".local" / "bin" / "lumos").read_text(encoding="utf-8") == "USER OWN\n", "")


def t_slim_install_claude_md_idempotent():
    """★冪等★:install.sh 對 CLAUDE.md 的附加重跑兩次,只應出現一塊 sentinel
    區塊,且第二次跑完的檔案內容與第一次完全 byte-equal(不疊出第二塊、不因
    重跑而漂移)。用 --force 讓第二次的 bin/skill 碰撞放行,聚焦驗證 CLAUDE.md
    這一段的冪等性。"""
    import tempfile as _tf, os as _os, shutil as _sh
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-idem-"))

    pkg = root / "pkg"
    (pkg / "scripts").mkdir(parents=True)
    (pkg / "skills" / "lumos-project-notes").mkdir(parents=True)
    (pkg / "scripts" / "lumos").write_text("#!/usr/bin/env python3\nprint('slim')\n",
                                           encoding="utf-8")
    (pkg / "scripts" / "lumos").chmod(0o755)
    (pkg / "skills" / "lumos-project-notes" / "SKILL.md").write_text("# skill\n",
                                                                     encoding="utf-8")
    _slim_copy_install_files(pkg)

    proj = root / "proj"
    proj.mkdir()
    (proj / "CLAUDE.md").write_text("# 既有專案紀律\n\n不該被動的一段文字。\n",
                                    encoding="utf-8")

    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    r1 = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("第一次安裝 rc0", r1.returncode == 0, r1.stdout + r1.stderr)
    after_1 = (proj / "CLAUDE.md").read_text(encoding="utf-8")
    check("第一次跑完只有一塊 sentinel",
          after_1.count("<!-- LUMOS-SLIM:START -->") == 1, after_1)

    r2 = subprocess.run(["bash", str(pkg / "install.sh"), "--force"], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("第二次安裝(--force)rc0", r2.returncode == 0, r2.stdout + r2.stderr)
    after_2 = (proj / "CLAUDE.md").read_text(encoding="utf-8")

    check("★冪等★ 重跑後仍只有一塊 sentinel(沒疊出第二塊)",
          after_2.count("<!-- LUMOS-SLIM:START -->") == 1, after_2)
    check("★冪等★ 重跑後 CLAUDE.md 內容與第一次 byte-equal",
          after_2 == after_1, "第一次:\n" + after_1 + "\n第二次:\n" + after_2)


def t_slim_uninstall_removes_claude_md_block():
    """★可移除★:uninstall.sh 要能乾淨拿掉 install.sh 附加的 CLAUDE.md 區塊,
    卸載後 CLAUDE.md 回到原樣 byte-equal(既有內容原封不動,sentinel 區塊消失)。
    另驗「CLAUDE.md 原本不存在」這個邊界:安裝時新建的檔案,卸載後應連檔案本身
    一起消失(回到「原本沒有這個檔案」的狀態),不是留一個空檔。"""
    import tempfile as _tf, os as _os, shutil as _sh
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-rm-"))
    repo = _P(GRAPHCTL).parent.parent

    pkg = root / "pkg"
    (pkg / "scripts").mkdir(parents=True)
    (pkg / "skills" / "lumos-project-notes").mkdir(parents=True)
    (pkg / "scripts" / "lumos").write_text("#!/usr/bin/env python3\nprint('slim')\n",
                                           encoding="utf-8")
    (pkg / "scripts" / "lumos").chmod(0o755)
    (pkg / "skills" / "lumos-project-notes" / "SKILL.md").write_text("# skill\n",
                                                                     encoding="utf-8")
    _slim_copy_install_files(pkg)
    _slim_copy_uninstall_files(pkg)

    # 情境一:CLAUDE.md 已有既有內容
    proj_a = root / "proj_a"
    proj_a.mkdir()
    original_a = "# 既有專案紀律\n\n不該被動的一段文字,卸載後要原封不動。\n"
    (proj_a / "CLAUDE.md").write_text(original_a, encoding="utf-8")

    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj_a),
                        capture_output=True, text=True, env=env)
    check("移除測試前置:install.sh rc0", ri.returncode == 0, ri.stdout + ri.stderr)
    check("移除測試前置:sentinel 確實已附加",
          "<!-- LUMOS-SLIM:START -->" in (proj_a / "CLAUDE.md").read_text(encoding="utf-8"), "")

    ru = subprocess.run(["bash", str(pkg / "uninstall.sh"), "--force"], cwd=str(proj_a),
                        capture_output=True, text=True, env=env)
    check("uninstall.sh rc0", ru.returncode == 0, ru.stdout + ru.stderr)
    check("★可移除★ 卸載後 CLAUDE.md 回到原樣 byte-equal",
          (proj_a / "CLAUDE.md").read_text(encoding="utf-8") == original_a,
          (proj_a / "CLAUDE.md").read_text(encoding="utf-8"))

    # 情境二:CLAUDE.md 原本不存在 → 安裝時新建 → 卸載後應連檔案一起消失
    proj_b = root / "proj_b"
    proj_b.mkdir()
    (proj_b / ".git").mkdir()   # ★install.sh 注入目標守衛第一層要求★:CLAUDE.md
                                 # 情境本身就是「原本不存在」,守衛改靠 .git 判定專案根
    fake_home_b = root / "home_b"
    (fake_home_b / ".local" / "bin").mkdir(parents=True)
    env_b = dict(_os.environ, HOME=str(fake_home_b))

    rib = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj_b),
                         capture_output=True, text=True, env=env_b)
    check("情境二前置:install.sh rc0", rib.returncode == 0, rib.stdout + rib.stderr)
    check("情境二前置:CLAUDE.md 因安裝而新建",
          (proj_b / "CLAUDE.md").exists(), "")

    rub = subprocess.run(["bash", str(pkg / "uninstall.sh"), "--force"], cwd=str(proj_b),
                         capture_output=True, text=True, env=env_b)
    check("情境二:uninstall.sh rc0", rub.returncode == 0, rub.stdout + rub.stderr)
    check("★可移除(邊界)★ 原本不存在的 CLAUDE.md,卸載後連檔案本身一併消失",
          not (proj_b / "CLAUDE.md").exists(), "")

    # 情境三([S3] 第三次裁定核心):CLAUDE.md 已有完整版 LUMOS:GRAPH-DISCIPLINE
    # 區塊 —— install 應把它整段換成精簡版區塊(原位置),uninstall 應能位元組
    # 級把完整版區塊原文還原回去,最終與安裝前完全 byte-equal(含完整版內容
    # 一字不差)。
    proj_c = root / "proj_c"
    proj_c.mkdir()
    original_c = (
        "# 專案標題\n\n"
        "<!-- LUMOS:GRAPH-DISCIPLINE:START v1.0 — 自動注入/更新,勿手改本區塊 -->\n"
        "## 完整版紀律\n\n這裡引用 design-loop/code-loop 一堆本包沒交付的指令。\n"
        "<!-- LUMOS:GRAPH-DISCIPLINE:END -->\n\n"
        "## 專案自訂章節\n\n這段在完整版區塊之後,卸載後要一字不差還原。\n"
    )
    (proj_c / "CLAUDE.md").write_text(original_c, encoding="utf-8")
    fake_home_c = root / "home_c"
    (fake_home_c / ".local" / "bin").mkdir(parents=True)
    env_c = dict(_os.environ, HOME=str(fake_home_c))

    ric = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj_c),
                         capture_output=True, text=True, env=env_c)
    check("情境三前置:install.sh rc0", ric.returncode == 0, ric.stdout + ric.stderr)
    after_install_c = (proj_c / "CLAUDE.md").read_text(encoding="utf-8")
    check("情境三:完整版區塊已消失", "LUMOS:GRAPH-DISCIPLINE" not in after_install_c,
          after_install_c)

    ruc = subprocess.run(["bash", str(pkg / "uninstall.sh"), "--force"], cwd=str(proj_c),
                         capture_output=True, text=True, env=env_c)
    check("情境三:uninstall.sh rc0", ruc.returncode == 0, ruc.stdout + ruc.stderr)
    check("★位元組級還原★ 卸載後 CLAUDE.md 與安裝前完全 byte-equal(含完整版原文)",
          (proj_c / "CLAUDE.md").read_text(encoding="utf-8") == original_c,
          (proj_c / "CLAUDE.md").read_text(encoding="utf-8"))


def t_slim_install_replaces_full_discipline_block_in_place():
    """★[S3] 第三次裁定核心,正向細節★:完整版 `LUMOS:GRAPH-DISCIPLINE` 區塊被
    整段換成精簡版區塊時,①換的位置是原地(不是搬到檔尾)②區塊前後的既有內容
    byte-equal 保留③備份標記(FULL-BACKUP:BASE64)base64 解碼後與完整版原文
    (含 START/END sentinel 本身)逐位元組相同——這是 uninstall 能位元組級還原
    的前提,若編碼時漏字/多字,還原一定跟著錯,故單獨對備份內容本身斷言,不能
    只靠「跑完 uninstall 剛好對上」這種間接驗法。"""
    import base64 as _b64, tempfile as _tf, os as _os, shutil as _sh
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-full-"))
    repo = _P(GRAPHCTL).parent.parent

    pkg = root / "pkg"
    (pkg / "scripts").mkdir(parents=True)
    (pkg / "skills" / "lumos-project-notes").mkdir(parents=True)
    (pkg / "scripts" / "lumos").write_text("#!/usr/bin/env python3\nprint('slim')\n",
                                           encoding="utf-8")
    (pkg / "scripts" / "lumos").chmod(0o755)
    (pkg / "skills" / "lumos-project-notes" / "SKILL.md").write_text("# skill\n",
                                                                     encoding="utf-8")
    _slim_copy_install_files(pkg)

    proj = root / "proj"
    proj.mkdir()
    prefix = "# 專案標題\n\n這段在完整版區塊之前,不該被動。\n\n"
    full_block = (
        "<!-- LUMOS:GRAPH-DISCIPLINE:START v1.0 — 自動注入/更新,勿手改本區塊 -->\n"
        "## 完整版紀律\n\n這裡引用 design-loop/code-loop 一堆本包沒交付的指令。\n"
        "<!-- LUMOS:GRAPH-DISCIPLINE:END -->\n"
    )
    suffix = "\n## 專案自訂章節\n\n這段在完整版區塊之後,不該被動。\n"
    original = prefix + full_block + suffix
    (proj / "CLAUDE.md").write_text(original, encoding="utf-8")

    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    r = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                       capture_output=True, text=True, env=env)
    check("install.sh rc0", r.returncode == 0, r.stdout + r.stderr)

    after = (proj / "CLAUDE.md").read_text(encoding="utf-8")
    check("★完整版區塊整段消失★", "LUMOS:GRAPH-DISCIPLINE" not in after, after)
    check("★原地取代,非搬到檔尾★ 區塊前的內容緊接精簡版區塊開頭",
          after.startswith(prefix + "<!-- LUMOS-SLIM:START -->"), after[:len(prefix) + 60])
    check("★區塊後的既有內容 byte-equal★", after.endswith(suffix), after[-100:])
    check("只有一塊精簡版 sentinel", after.count("<!-- LUMOS-SLIM:START -->") == 1, after)

    import re as _re
    m = _re.search(r"<!-- LUMOS-SLIM:FULL-BACKUP:BASE64:([A-Za-z0-9+/=]*) -->", after)
    check("★備份標記存在且是 BASE64(非 NONE)★", m is not None, after)
    if m:
        decoded = _b64.b64decode(m.group(1)).decode("utf-8")
        check("★備份逐位元組等於完整版原文(含 sentinel 本身)★", decoded == full_block,
              f"decoded={decoded!r}\nexpected={full_block!r}")


def t_slim_install_backup_survives_idempotent_reinstall():
    """★冪等 × 備份不可漂移★:已用完整版區塊裝過一次(備份已編碼進精簡版區塊)
    後,重跑安裝器(--force,繞過 bin/skill 已存在的碰撞檢查)不應該:①因為這次
    掃描不到「活著的」完整版區塊(它已被第一次跑掉換走了)就誤判成「原本沒有」
    把備份洗成 NONE ②把備份重新 base64 一次疊出雙層編碼。斷言重跑後 CLAUDE.md
    內容與第一次跑完 byte-equal。"""
    import tempfile as _tf, os as _os, shutil as _sh
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-full-idem-"))
    repo = _P(GRAPHCTL).parent.parent

    pkg = root / "pkg"
    (pkg / "scripts").mkdir(parents=True)
    (pkg / "skills" / "lumos-project-notes").mkdir(parents=True)
    (pkg / "scripts" / "lumos").write_text("#!/usr/bin/env python3\nprint('slim')\n",
                                           encoding="utf-8")
    (pkg / "scripts" / "lumos").chmod(0o755)
    (pkg / "skills" / "lumos-project-notes" / "SKILL.md").write_text("# skill\n",
                                                                     encoding="utf-8")
    _slim_copy_install_files(pkg)

    proj = root / "proj"
    proj.mkdir()
    original = (
        "<!-- LUMOS:GRAPH-DISCIPLINE:START v1.0 -->\n完整版內容\n"
        "<!-- LUMOS:GRAPH-DISCIPLINE:END -->\n"
    )
    (proj / "CLAUDE.md").write_text(original, encoding="utf-8")

    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    r1 = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("第一次安裝(有完整版區塊)rc0", r1.returncode == 0, r1.stdout + r1.stderr)
    after_1 = (proj / "CLAUDE.md").read_text(encoding="utf-8")
    check("第一次跑完備份是 BASE64(前置條件)",
          "FULL-BACKUP:BASE64:" in after_1, after_1)

    r2 = subprocess.run(["bash", str(pkg / "install.sh"), "--force"], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("第二次安裝(--force)rc0", r2.returncode == 0, r2.stdout + r2.stderr)
    after_2 = (proj / "CLAUDE.md").read_text(encoding="utf-8")

    check("★冪等★ 重跑後仍只有一塊 sentinel", after_2.count("<!-- LUMOS-SLIM:START -->") == 1,
          after_2)
    check("★備份沒被洗掉/沒被二次包裹★ 重跑後內容與第一次 byte-equal",
          after_2 == after_1, "第一次:\n" + after_1 + "\n第二次:\n" + after_2)

    # 收尾:確認這份備份仍然能被 uninstall 正確用來還原
    _slim_copy_uninstall_files(pkg)
    ru = subprocess.run(["bash", str(pkg / "uninstall.sh"), "--force"], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("重跑兩次後仍可正確卸載還原 rc0", ru.returncode == 0, ru.stdout + ru.stderr)
    check("★重跑後的備份依然位元組級可還原★",
          (proj / "CLAUDE.md").read_text(encoding="utf-8") == original,
          (proj / "CLAUDE.md").read_text(encoding="utf-8"))


def t_slim_claude_block_curation():
    """★策展正確性(spec [S3] 第三次裁定)★:`slim/claude-block.md` 是策展後的
    「取代完整版紀律區塊」範本——斷言①不含依賴已移除指令才有意義的字串(這些
    技能/指令本包沒交付,留著會讓接手者的 Claude 去撲空)②含仍然有效、已從
    完整版策展吸收進來的內容(合約鏈/summary 符號/regen 重生標記/frontmatter
    欄位)。"""
    from pathlib import Path as _P
    p = _P(GRAPHCTL).parent.parent / "slim" / "claude-block.md"
    txt = p.read_text(encoding="utf-8")

    for bad in ("design-loop", "code-loop", "core-knowledge", "pitfalls",
                "spec-trace", "signoff", "lumos init", "lumos update"):
        check(f"★策展:不含已移除指令/skill 字串★ 「{bad}」", bad not in txt, "")

    for good in ("★INVARIANT★", "★DEBT★", "[test:", "FLOW:", "KEY:", "valid_under",
                 "佚失:"):
        check(f"★策展:含仍有效的內容★ 「{good}」", good in txt, "")

    # ★交付文字掃描器也要掃這份範本★(它會被原封不動裝進使用者的 CLAUDE.md)
    scanner = str(_P(GRAPHCTL).parent / "slim-scan.py")
    r = subprocess.run([sys.executable, scanner, str(p), "--json"],
                       capture_output=True, text=True)
    import json as _j5
    cands = _j5.loads(r.stdout)["candidates"] if r.stdout.strip() else []
    check("claude-block.md 無懸空引用(移除指令/skill 名)", not cands, str(cands))

    # sentinel 完整性 + FULL-BACKUP 佔位符存在(install.sh 靠字面替換這個佔位符)
    check("含開始 sentinel", "<!-- LUMOS-SLIM:START -->" in txt, "")
    check("含結束 sentinel", txt.rstrip().endswith("<!-- LUMOS-SLIM:END -->"), txt[-80:])
    check("含 FULL-BACKUP:NONE 佔位符(install.sh 靠字面替換)",
          "<!-- LUMOS-SLIM:FULL-BACKUP:NONE -->" in txt, "")


def _slim_copy_install_files(pkg_dir):
    """複製 `install.sh`(薄殼)+ `install.py`(★真正邏輯所在★,取代舊版把全部
    行為寫在 install.sh 裡的做法)+ `claude-block.md`(安裝器讀的外部範本)到
    `pkg_dir`——★三者缺一不可★:`install.sh` 現在只做兩件事(定位套件目錄、
    挑一支可用的 python 直譯器),真正動作全轉發給同目錄下的 `install.py`,
    少了它 `install.sh` 會 rc2(找不到 install.py)或直接失敗。"""
    from pathlib import Path as _P
    import shutil as _sh
    pkg_dir = _P(pkg_dir)
    repo = _P(GRAPHCTL).parent.parent
    pkg_dir.mkdir(parents=True, exist_ok=True)
    for name in ("install.sh", "install.py"):
        _sh.copy2(repo / "slim" / name, pkg_dir / name)
    (pkg_dir / "install.sh").chmod(0o755)
    _sh.copy2(repo / "slim" / "claude-block.md", pkg_dir / "claude-block.md")


def _slim_copy_uninstall_files(pkg_dir):
    """複製 `uninstall.sh`(薄殼)+ `uninstall.py`(真正邏輯)到 `pkg_dir`——
    與 `_slim_copy_install_files` 對稱,同款理由。"""
    _need_src("slim")
    from pathlib import Path as _P
    import shutil as _sh
    pkg_dir = _P(pkg_dir)
    repo = _P(GRAPHCTL).parent.parent
    pkg_dir.mkdir(parents=True, exist_ok=True)
    for name in ("uninstall.sh", "uninstall.py"):
        _sh.copy2(repo / "slim" / name, pkg_dir / name)
    (pkg_dir / "uninstall.sh").chmod(0o755)


def _slim_make_pkg_at(pkg_dir):
    """建一個「長得像本包」的假交付包(scripts/lumos + install.sh/.py + skill)
    在指定路徑——供 get.sh/uninstall.py 測試共用。★不寫死內容★:lumos 腳本
    內容隨呼叫端傳入,好讓 uninstall 的 sha256 比對測試能控制「符合」與
    「不符合」兩種情境。"""
    _need_src("slim")
    from pathlib import Path as _P
    pkg_dir = _P(pkg_dir)
    (pkg_dir / "scripts").mkdir(parents=True, exist_ok=True)
    (pkg_dir / "skills" / "lumos-project-notes").mkdir(parents=True, exist_ok=True)
    (pkg_dir / "scripts" / "lumos").write_text(
        "#!/usr/bin/env python3\nprint('slim')\n", encoding="utf-8")
    (pkg_dir / "scripts" / "lumos").chmod(0o755)
    (pkg_dir / "skills" / "lumos-project-notes" / "SKILL.md").write_text(
        "# skill\n", encoding="utf-8")
    _slim_copy_install_files(pkg_dir)
    return pkg_dir


def t_slim_uninstall_backs_up_and_preserves_custom_files():
    """★反誤傷①(卸載)★:先裝、再往 skill 目錄塞使用者自訂檔 → 跑 uninstall →
    斷言備份存在且自訂檔在備份裡、~/.claude/settings.json 與 hooks/ 未被建立
    或刪除(卸載腳本壓根不該碰這兩個路徑)。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimuninst-"))
    (root / ".git").mkdir()   # ★install.sh 注入目標守衛第一層要求★:root 本身就是
                               # install.sh 的目標 cwd,標記一下讓它看起來像專案根
    repo = _P(GRAPHCTL).parent.parent

    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")   # ★固定落點★,uninstall.sh 硬編此路徑
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    r = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(root),
                       capture_output=True, text=True, env=env)
    check("uninstall 測試前置:install.sh rc0", r.returncode == 0, r.stdout + r.stderr)

    # 使用者在 skill 目錄裡塞了自己的檔
    custom = fake_home / ".claude" / "skills" / "lumos-project-notes" / "my-own-notes.txt"
    custom.write_text("使用者自訂內容,不該被吃掉\n", encoding="utf-8")

    check("卸載前 settings.json 不存在(前置條件)",
          not (fake_home / ".claude" / "settings.json").exists(), "")
    check("卸載前 hooks/ 不存在(前置條件)",
          not (fake_home / ".claude" / "hooks").exists(), "")

    uninstall_sh = str(repo / "slim" / "uninstall.sh")
    r2 = subprocess.run(["bash", uninstall_sh], cwd=str(root),
                        capture_output=True, text=True, env=env)
    check("uninstall.sh rc0", r2.returncode == 0, r2.stdout + r2.stderr)

    skills_dir = fake_home / ".claude" / "skills"
    # ★2026-08-03 行為變更(真機驗證 MINOR⑤)★:備份不再留在 ~/.claude/skills/
    # ——那是 Claude Code 掃描 skill 的目錄,留在那裡會被當成一個新 skill 載入。
    _bak_root = fake_home / ".local" / "share" / "lumos-slim" / "backups"
    baks = sorted(_bak_root.glob("lumos-project-notes.bak.*")) if _bak_root.is_dir() else []
    check("★備份★不得★留在 ~/.claude/skills/(會被當成新 skill 載入)★",
          not list(skills_dir.glob("lumos-project-notes.bak.*")),
          str(sorted(x.name for x in skills_dir.iterdir())) if skills_dir.is_dir() else "(無)")
    check("★備份存在★ skill 目錄被備份成 .bak.<timestamp>而非直接刪除",
          len(baks) == 1, str(list(skills_dir.iterdir())))
    check("原 skill 路徑已不存在(被 mv 走,不是複製殘留)",
          not (skills_dir / "lumos-project-notes").exists(), "")
    if baks:
        check("★自訂檔在備份裡★", (baks[0] / "my-own-notes.txt").is_file(), str(list(baks[0].iterdir())))
        check("★自訂檔內容未被動★",
              (baks[0] / "my-own-notes.txt").read_text(encoding="utf-8") == "使用者自訂內容,不該被吃掉\n", "")

    check("★絕不碰★ settings.json 卸載後仍不存在(未被建立)",
          not (fake_home / ".claude" / "settings.json").exists(), "")
    check("★絕不碰★ hooks/ 卸載後仍不存在(未被建立或刪除)",
          not (fake_home / ".claude" / "hooks").exists(), "")
    check("全域指令已移除", not (fake_home / ".local" / "bin" / "lumos").exists(), "")


def t_slim_uninstall_refuses_foreign_bin():
    """★反誤傷②(卸載)★:把 ~/.local/bin/lumos 換成使用者自己的一般檔 → 跑
    uninstall → 斷言 rc=1(★2026-07-31 改版:安全性跳過,不是硬錯誤,見 rc
    語意三段式★)且該檔內容未被動。★2026-07-31 步驟獨立化改版★:bin 判定不符
    不再用 `exit` 中止整支腳本——skill 目錄這一步與 bin 的比對結果無關,應該
    照常執行(備份/移除)。獨立性的正面回歸測試見
    `t_slim_uninstall_bin_refusal_does_not_block_claude_md_restore`(驗
    CLAUDE.md 那一步)。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimuninstfp-"))
    (root / ".git").mkdir()   # ★install.sh 注入目標守衛第一層要求★(見上一測試同款註解)
    repo = _P(GRAPHCTL).parent.parent

    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    r = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(root),
                       capture_output=True, text=True, env=env)
    check("uninstall 拒絕測試前置:install.sh rc0", r.returncode == 0, r.stdout + r.stderr)

    bin_path = fake_home / ".local" / "bin" / "lumos"
    bin_path.unlink()
    bin_path.write_text("#!/bin/sh\necho USER OWN BINARY\n", encoding="utf-8")

    uninstall_sh = str(repo / "slim" / "uninstall.sh")
    r2 = subprocess.run(["bash", uninstall_sh], cwd=str(root),
                        capture_output=True, text=True, env=env)
    check("★內容不符 → rc1(安全性跳過,非硬錯誤)★", r2.returncode == 1, r2.stdout + r2.stderr)
    check("★該檔內容未被動★",
          bin_path.read_text(encoding="utf-8") == "#!/bin/sh\necho USER OWN BINARY\n", "")
    check("★步驟互不阻擋★ bin 判定不符後,skill 目錄仍照常被備份(不再『判定失敗即中止』)",
          not (fake_home / ".claude" / "skills" / "lumos-project-notes").exists()
          and any((fake_home / ".local" / "share" / "lumos-slim" / "backups").glob("lumos-project-notes.bak.*")),
          str(list((fake_home / ".claude" / "skills").iterdir())))

    # --force 是唯一合法的繞過方式,且要明確帶
    r3 = subprocess.run(["bash", uninstall_sh, "--force"], cwd=str(root),
                        capture_output=True, text=True, env=env)
    check("★帶 --force 才允許移除★", r3.returncode == 0, r3.stdout + r3.stderr)
    check("--force 後檔案確實被移除", not bin_path.exists(), "")


def t_slim_uninstall_idempotent_second_run():
    """★minor-2(2026-07-31 代碼審第二輪)★:接手者「保險起見再跑一次確認乾淨」是
    很自然的行為,但原本只測過跑一次。裝好 → 塞使用者自訂檔 → 跑 uninstall → 再
    跑一次 uninstall → 斷言:
    ①第二次不炸(rc=0)——讀腳本後判定:三步(BIN/SKILL/PKG)第二次跑時全部落入
      「東西已經不在」的分支(`else` 印 `(未安裝: ...)`,純 echo,不觸發任何
      exit),語意上與「這台機器本來就沒裝過」完全等價,而那個情境本就是 rc0;
      idempotent 工具(`rm -f`/`apt remove` 之類)的慣例是「不需要做事=成功」,
      不是「報錯」,故第二次也判定 rc0 才合理,非 0 反而是腳本壞了。
    ②第二次不產生多餘的空備份目錄——SKILL 路徑在第一次跑完後已被 mv 走,第二次
      `[ -d "$SKILL" ]` 為假,進不了備份分支,不會多出一個 `.bak.*`。
    ③第一次備份出來的使用者自訂檔,第二次跑完後仍完好未被動。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimuninst2x-"))
    (root / ".git").mkdir()   # ★install.sh 注入目標守衛第一層要求★(見前述同款註解)
    repo = _P(GRAPHCTL).parent.parent

    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    r = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(root),
                       capture_output=True, text=True, env=env)
    check("冪等回歸測試前置:install.sh rc0", r.returncode == 0, r.stdout + r.stderr)

    custom = fake_home / ".claude" / "skills" / "lumos-project-notes" / "my-own-notes.txt"
    custom.write_text("使用者自訂內容,不該被吃掉\n", encoding="utf-8")

    uninstall_sh = str(repo / "slim" / "uninstall.sh")
    r1 = subprocess.run(["bash", uninstall_sh], cwd=str(root),
                        capture_output=True, text=True, env=env)
    check("第一次 uninstall rc0", r1.returncode == 0, r1.stdout + r1.stderr)

    skills_dir = fake_home / ".claude" / "skills"
    baks_after_1 = sorted((fake_home / ".local" / "share" / "lumos-slim" / "backups").glob("lumos-project-notes.bak.*"))
    check("第一次跑完備份存在(前置條件)", len(baks_after_1) == 1, str(list(skills_dir.iterdir())))
    content_after_1 = ((baks_after_1[0] / "my-own-notes.txt").read_text(encoding="utf-8")
                        if baks_after_1 else None)

    # ★保險起見再跑一次★
    r2 = subprocess.run(["bash", uninstall_sh], cwd=str(root),
                        capture_output=True, text=True, env=env)
    check("★minor-2★ 第二次 uninstall 不炸,rc=0(冪等——語意等同「本來就沒裝」)",
          r2.returncode == 0, r2.stdout + r2.stderr)

    baks_after_2 = sorted((fake_home / ".local" / "share" / "lumos-slim" / "backups").glob("lumos-project-notes.bak.*"))
    check("★minor-2★ 第二次不產生多餘的空備份目錄(數量不變,仍是 1)",
          len(baks_after_2) == len(baks_after_1) == 1, str(list(skills_dir.iterdir())))
    check("★minor-2★ 第一次備份出來的自訂檔,第二次跑完後仍完好",
          bool(baks_after_2)
          and (baks_after_2[0] / "my-own-notes.txt").read_text(encoding="utf-8") == content_after_1,
          str(list(baks_after_2[0].iterdir())) if baks_after_2 else "無備份目錄")
    check("PKG 目錄第二次跑完後仍不存在(沒有詭異重建)",
          not (fake_home / ".lumos-slim").exists(), "")
    check("BIN 第二次跑完後仍不存在",
          not (fake_home / ".local" / "bin" / "lumos").exists(), "")


def t_slim_uninstall_direct_install_restores_claude_md():
    """★端到端實測抓到的真 bug,回歸測試(2026-07-31)★:接手者若不走 get.sh
    (一行安裝,固定落點 `~/.lumos-slim`),而是照 README 也在教的另一條路——
    直接把交付包 clone 到任意路徑、跑包內 `install.sh`——`~/.lumos-slim` 從
    頭到尾不會存在。舊版 uninstall.sh 拿 `~/.lumos-slim/scripts/lumos` 當 bin
    比對的**唯一**基準,基準缺失就直接 `exit 2` 中止整支腳本,CLAUDE.md 的完整
    版還原(步驟④)完全沒機會執行——接手者從此卸載不掉,且舊訊息說「這可能是
    你自己的東西」在這個情境下是**誤導**(其實就是本包裝的,只是找不到比對
    基準)。這個測試★不經過 get.sh、確保 ~/.lumos-slim 不存在★:交付包 clone
    到一個跟 `~/.lumos-slim` 無關的任意路徑,直接跑該路徑下的 install.sh,再
    跑 uninstall.sh,斷言卸載後 CLAUDE.md 與安裝前完全 byte-equal(完整版區塊
    原文一字不差還原、精簡版區塊清掉)。"""
    import tempfile as _tf, os as _os, shutil as _sh
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-directbug-"))
    repo = _P(GRAPHCTL).parent.parent

    # ★交付包 clone 到任意路徑(不是 ~/.lumos-slim)★——模擬「兩行版」使用者
    # 自己選的落點,例如 `git clone ... ~/dev/Citrus_Lumos`。
    pkg = _slim_make_pkg_at(root / "wherever-i-cloned-it")
    _slim_copy_uninstall_files(pkg)

    # 假專案:CLAUDE.md 帶完整版 LUMOS:GRAPH-DISCIPLINE 區塊(模擬 Landmark)。
    proj = root / "proj"
    proj.mkdir()
    original = (
        "# Landmark\n\n"
        "<!-- LUMOS:GRAPH-DISCIPLINE:START v1.0 — 自動注入/更新,勿手改本區塊 -->\n"
        "## 完整版紀律\n\n離職交接用的完整版內容,卸載後要一字不差還原。\n"
        "<!-- LUMOS:GRAPH-DISCIPLINE:END -->\n\n"
        "## 專案自訂章節\n\n這段在完整版區塊之後,卸載後要一字不差還原。\n"
    )
    (proj / "CLAUDE.md").write_text(original, encoding="utf-8")

    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★前置★ 直接跑包內 install.sh(不經 get.sh)rc0", ri.returncode == 0,
          ri.stdout + ri.stderr)
    check("★前置★ ~/.lumos-slim 確實不存在(模擬 README 兩行版的另一條安裝路徑)",
          not (fake_home / ".lumos-slim").exists(), "")
    after_install = (proj / "CLAUDE.md").read_text(encoding="utf-8")
    check("★前置★ 完整版區塊已被換成精簡版",
          "LUMOS:GRAPH-DISCIPLINE" not in after_install
          and "<!-- LUMOS-SLIM:START -->" in after_install, after_install)

    ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★核心回歸★ uninstall.sh 不因 bin 比對基準缺失而整支中止(rc0,乾淨卸載)",
          ru.returncode == 0, ru.stdout + ru.stderr)
    check("★核心回歸★ CLAUDE.md 與安裝前完全 byte-equal(完整版區塊已還原)",
          (proj / "CLAUDE.md").read_text(encoding="utf-8") == original,
          (proj / "CLAUDE.md").read_text(encoding="utf-8"))
    check("★連帶★ bin 也確實被移除(manifest 基準比對成功,不是靠 --force)",
          not (fake_home / ".local" / "bin" / "lumos").exists(), "")
    check("★連帶★ skill 目錄也確實被備份移除",
          not (fake_home / ".claude" / "skills" / "lumos-project-notes").exists(), "")


def t_slim_uninstall_bin_refusal_does_not_block_claude_md_restore():
    """★設計缺陷回歸測試(②各步獨立,不是一票否決)★:bin 的安全檢查失敗
    (內容跟比對基準不符,可能是使用者自己的東西)不該擋住 CLAUDE.md 的完整版
    還原——這是兩件獨立的事。裝好之後把 `~/.local/bin/lumos` 換成使用者自己的
    檔(manifest 比對一定不符),不帶 `--force` 跑 uninstall.sh:斷言①bin 因為
    安全考量拒絕移除、內容未被動②即便①拒絕,CLAUDE.md 依然完整版位元組級還原
    (步驟互不阻擋)③rc 反映的是「安全性跳過」而非硬錯誤(rc 語意三段式)。"""
    import tempfile as _tf, os as _os, shutil as _sh
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-indep-"))
    repo = _P(GRAPHCTL).parent.parent

    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")   # 固定落點,manifest+PKG 備援都拿得到基準
    _slim_copy_uninstall_files(pkg)
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    proj = root / "proj"
    proj.mkdir()
    original = (
        "# 專案標題\n\n"
        "<!-- LUMOS:GRAPH-DISCIPLINE:START v1.0 -->\n完整版內容,獨立性測試。\n"
        "<!-- LUMOS:GRAPH-DISCIPLINE:END -->\n"
    )
    (proj / "CLAUDE.md").write_text(original, encoding="utf-8")

    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★前置★ install.sh rc0", ri.returncode == 0, ri.stdout + ri.stderr)

    bin_path = fake_home / ".local" / "bin" / "lumos"
    bin_path.unlink()
    bin_path.write_text("#!/bin/sh\necho USER OWN BINARY\n", encoding="utf-8")

    ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★①bin 因安全考量拒絕移除,內容未被動★",
          bin_path.read_text(encoding="utf-8") == "#!/bin/sh\necho USER OWN BINARY\n", "")
    check("★②即便①拒絕,CLAUDE.md 仍完整還原(步驟互不阻擋,本次修的核心)★",
          (proj / "CLAUDE.md").read_text(encoding="utf-8") == original,
          (proj / "CLAUDE.md").read_text(encoding="utf-8"))
    check("★③rc 反映安全性跳過,非硬錯誤★ rc==1", ru.returncode == 1,
          ru.stdout + ru.stderr)


def t_slim_uninstall_removes_manifest_when_bin_cleared():
    """★真跑冒煙抓到的殘留(2026-08-01)★:整套測試全綠、卸載彙總印「✓ 全部
    完成」,實際跑完卻在 `~/.local/share/lumos-slim/` 底下留著 manifest.json
    ——沒有任何一條測試斷言過它該消失(不是斷言寫錯,是根本沒去驗)。

    ★驗的是行為不是寫法★:真的跑一次安裝再跑一次卸載,然後對檔案系統做
    存在性斷言(`.exists()`),不看原始碼有沒有出現 `manifest_path.unlink()`
    這種字面。把 ⑤ 整段刪掉、或把 `unlink()` 換成 no-op,這條都會翻紅。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimmanifest-"))

    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    _slim_copy_uninstall_files(pkg)
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    proj = root / "proj"
    proj.mkdir()
    (proj / "CLAUDE.md").write_text("# 專案標題\n\n原有內容\n", encoding="utf-8")

    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★前置★ install.sh rc0", ri.returncode == 0, ri.stdout + ri.stderr)

    manifest = fake_home / ".local" / "share" / "lumos-slim" / "manifest.json"
    check("★前置★ 安裝後 manifest 存在", manifest.is_file(), str(manifest))

    ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★卸載後 manifest 檔案真的不存在★(存在性斷言,不是掃原始碼)",
          not manifest.exists(), ru.stdout + ru.stderr)
    # ★2026-08-03 行為變更★:skill 備份現在落在 lumos-slim/backups/(不再留在
    # ~/.claude/skills/,那會被當成新 skill 載入)。於是 lumos-slim/ 不再是空的,
    # 「清空目錄」那步★正確地★不會觸發——但★刻意保留 ≠ 可以不講★,
    # 彙總必須明說留了什麼、留在哪(否則就是原本 manifest 殘留那條缺陷的同一形狀)。
    _bak = manifest.parent / "backups"
    check("★前置★ 現場成立:這次卸載真的產生了 skill 備份(否則下面在測不成立的現場)",
          _bak.is_dir() and any(_bak.iterdir()), ru.stdout + ru.stderr)
    check("★有備份時 lumos-slim/ 正確地保留(它不是空的)★",
          manifest.parent.exists(), ru.stdout + ru.stderr)
    check("★但彙總必須明講留了什麼、留在哪(刻意保留不等於可以靜默)★",
          "刻意保留" in ru.stdout and "backups" in ru.stdout, ru.stdout)
    check("★但 ~/.local/share 本身絕不能被動★(那是眾多工具共用的地方)",
          (fake_home / ".local" / "share").is_dir(), ru.stdout + ru.stderr)
    check("★乾淨卸載 rc0★", ru.returncode == 0, ru.stdout + ru.stderr)


def t_slim_uninstall_keeps_manifest_when_shim_remains():
    """★代碼審 r4 抓到的漏分支★:「bin 沒清乾淨就別刪 manifest」原本是靠在①/①b
    每一條「沒移除」分支手動設 `bin_cleared = False` 來簿記,①b 的 `OSError`
    分支★漏設了一條★——Windows 上 `lumos.cmd` 讀不到(權限/被別的程序鎖住)時
    shim 明明還在,manifest 卻照樣被刪,把使用者重試時唯一的比對基準銷毀。

    ★修法不是補那一條分支,是換掉整個機制★:改成事後直接查檔案系統實況
    (`dst_script.exists() or dst_shim.exists()`)——分支簿記天生會漏(這次就
    漏了),查實況對每一條現有與未來新增的分支都自動成立。

    ★驗行為★:布置「`lumos` 已清掉、但有一個內容不符本包樣板的 `lumos.cmd`
    孤兒還在」的現場(不帶 --force 時卸載器會拒絕移除它),斷言 manifest ★仍在★。
    把修法還原成 `bin_cleared = True` 的旗標簿記,這條會翻紅。"""
    import tempfile as _tf, os as _os, json as _json
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimmanifest-shim-"))

    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    _slim_copy_uninstall_files(pkg)
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home), LUMOS_SLIM_SIMULATE_WINDOWS="1")

    proj = root / "proj"
    proj.mkdir()
    (proj / "CLAUDE.md").write_text("# 專案標題\n\n原有內容\n", encoding="utf-8")

    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★前置★ Windows 模擬安裝 rc0", ri.returncode == 0, ri.stdout + ri.stderr)

    manifest = fake_home / ".local" / "share" / "lumos-slim" / "manifest.json"
    shim = fake_home / ".local" / "bin" / "lumos.cmd"
    check("★前置★ 安裝後 manifest 與 shim 都在", manifest.is_file() and shim.is_file(), "")

    # 把 shim 換成「使用者自己的東西」——卸載器會拒絕移除它(不帶 --force)
    shim.write_bytes("@echo off\r\nrem 使用者自己的東西\r\n".encode("utf-8"))

    ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    out = ru.stdout + ru.stderr
    check("★前置★ 現場成立:shim 確實沒被移除(仍在原地)", shim.is_file(), out)
    check("★shim 還在 → manifest 必須留著(它是重試時唯一的比對基準)★",
          manifest.is_file(), out)
    kept = _json.loads(manifest.read_text(encoding="utf-8")).get("bin_sha256", "")
    check("★留下來的 manifest 仍可用作基準★", bool(kept), repr(kept))


def t_slim_uninstall_manifest_ignores_stray_cmd_on_posix():
    """★代碼審 r5 抓到,r4 修法自己引入的邊界(a)★:`bin_cleared` 原本無條件檢查
    `dst_shim.exists()`,但①b 整段包在 `if IS_WIN:` 底下——非 Windows 機器
    根本不會去看、去動 `~/.local/bin/lumos.cmd`。於是 macOS/Linux 上只要那個
    路徑上剛好有別的東西(`~/.local/bin` 是很多工具共用的地方,也可能是先前
    用 LUMOS_SLIM_SIMULATE_WINDOWS=1 測試留下的殘留),manifest 就永遠刪不掉,
    訊息還誤導成「上面 bin 有項目未移除」——但①b 從沒嘗試移除它。★而且⑤沒有
    `--force` 分支(①/①b 才有)★,使用者照著彙總訊息重跑 --force 也解不開。

    ★驗行為★:非 Windows(不設 SIMULATE_WINDOWS)、`lumos.cmd` 路徑上放一個
    不相干的檔案,斷言①manifest 仍被正常清掉 ②那個不相干的檔案原封不動。
    把 `IS_WIN and` 拿掉,這條翻紅。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimmanifest-stray-"))

    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    _slim_copy_uninstall_files(pkg)
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))
    env.pop("LUMOS_SLIM_SIMULATE_WINDOWS", None)

    proj = root / "proj"
    proj.mkdir()
    (proj / "CLAUDE.md").write_text("# 專案標題\n\n原有內容\n", encoding="utf-8")

    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★前置★ 非 Windows 安裝 rc0", ri.returncode == 0, ri.stdout + ri.stderr)

    manifest = fake_home / ".local" / "share" / "lumos-slim" / "manifest.json"
    stray = fake_home / ".local" / "bin" / "lumos.cmd"
    stray_bytes = "別的東西,跟本包無關\n".encode("utf-8")
    stray.write_bytes(stray_bytes)

    ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    out = ru.stdout + ru.stderr
    check("★非 Windows 上不相干的 lumos.cmd 不得卡住 manifest 清理★",
          not manifest.exists(), out)
    check("★那個不相干的檔案原封不動(非 Windows 下①b 本來就不該碰它)★",
          stray.is_file() and stray.read_bytes() == stray_bytes, out)


def t_slim_uninstall_keeps_manifest_when_shim_is_broken_symlink():
    """★代碼審 r5 抓到,r4 修法自己引入的邊界(b)★:判斷式左右兩半不對稱——
    `dst_script` 那半寫了 `exists() or is_symlink()`,`dst_shim` 那半只有
    `exists()`。`Path.exists()` 對「目標已被刪掉的斷鏈 symlink」回傳 False,
    但那個 symlink 本身仍佔著 `~/.local/bin/lumos.cmd` 這個路徑、①b 也確實
    沒把它移除(讀內容會拋 OSError,走「無法安全比對→跳過移除」那條)。
    於是 shim 還在,manifest 卻被判成「可以清了」而刪掉——正是 r4 要修的那條
    資料相依被繞過。

    ★驗行為★:Windows 模擬下把 lumos.cmd 做成指向不存在目標的斷鏈 symlink,
    斷言 manifest ★仍在★。把 `or dst_shim.is_symlink()` 拿掉,這條翻紅。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimmanifest-brokenlink-"))

    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    _slim_copy_uninstall_files(pkg)
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home), LUMOS_SLIM_SIMULATE_WINDOWS="1")

    proj = root / "proj"
    proj.mkdir()
    (proj / "CLAUDE.md").write_text("# 專案標題\n\n原有內容\n", encoding="utf-8")

    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★前置★ Windows 模擬安裝 rc0", ri.returncode == 0, ri.stdout + ri.stderr)

    manifest = fake_home / ".local" / "share" / "lumos-slim" / "manifest.json"
    shim = fake_home / ".local" / "bin" / "lumos.cmd"
    shim.unlink()
    shim.symlink_to(root / "這個目標不存在")
    check("★前置★ 現場成立:斷鏈 symlink(exists() 為假但 is_symlink() 為真)",
          (not shim.exists()) and shim.is_symlink(), "")

    ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    out = ru.stdout + ru.stderr
    check("★前置★ 斷鏈 shim 確實沒被移除(仍佔著那個路徑)", shim.is_symlink(), out)
    check("★shim 還佔著路徑 → manifest 必須留著★", manifest.is_file(), out)


def t_slim_uninstall_manifest_parent_cleanup_is_best_effort():
    """★代碼審 r3 抓到的錯誤歸因★:manifest 刪掉之後「順帶清掉空的 lumos-slim/
    父目錄」是選配收尾,原本跟 `unlink()` 共用同一個 try/except——父目錄清不掉時
    會印成「⚠ 移除 manifest 失敗」並把 rc 升到 2(真正的錯誤),但 manifest 其實
    已經刪成功、`✓ 已移除` 都印出來了。使用者會同時看到 ✓ 和 ⚠,以為要手動處理。

    ★這條測試的第一版是錯的,記在這裡當教訓★:第一版用「父目錄裡塞一個別的
    檔案讓它非空」當現場——但那樣 `if ... and not any(parent.iterdir())` 直接
    判假,`rmdir()` ★根本不會被執行★,例外路徑一次都沒跑到,把修法還原成共用
    try 的突變照樣全綠。這正是本專案已撞十一次的「測試存在但沒在驗它宣稱要驗
    的」——**要驗例外處理,現場就必須真的讓那個呼叫拋例外**。

    ★真正的現場★:把 `~/.local/share` 設成唯讀(r-x)。`unlink()` 需要的是
    `lumos-slim/` 的寫權限(仍有)故會成功;`rmdir("lumos-slim")` 需要的是
    父目錄 `share/` 的寫權限(已拿掉)故必定拋 PermissionError(OSError 子類)。
    斷言:①manifest 真的被刪 ②rc 仍是 0 ③輸出沒有誤導的「移除 manifest 失敗」。"""
    import tempfile as _tf, os as _os, stat as _st
    from pathlib import Path as _P
    if hasattr(_os, "geteuid") and _os.geteuid() == 0:
        check("★skip★ root 身分下權限不生效,此測試無意義", True, "running as root")
        return
    root = _P(_tf.mkdtemp(prefix="gctl-slimmanifest-parent-"))

    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    _slim_copy_uninstall_files(pkg)
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    proj = root / "proj"
    proj.mkdir()
    (proj / "CLAUDE.md").write_text("# 專案標題\n\n原有內容\n", encoding="utf-8")

    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★前置★ install.sh rc0", ri.returncode == 0, ri.stdout + ri.stderr)

    manifest = fake_home / ".local" / "share" / "lumos-slim" / "manifest.json"
    # ★2026-08-03:先把 skill 拿掉,讓卸載★不會★產生備份★——備份會落在
    # lumos-slim/backups/,那樣 lumos-slim/ 就不是空的、`rmdir` 這一步根本不會被
    # 呼叫到,現場就不成立了(第④型)。這條測的是「rmdir 失敗時只印一句、不升級 rc」,
    # 前提是 rmdir 真的會被嘗試。
    import shutil as _sh
    _skill = fake_home / ".claude" / "skills" / "lumos-project-notes"
    if _skill.is_dir():
        _sh.rmtree(_skill)
    share = manifest.parent.parent
    orig_mode = share.stat().st_mode
    _os.chmod(share, 0o500)          # r-x:lumos-slim/ 仍可寫(unlink 過),但不能被 rmdir
    try:
        ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                            capture_output=True, text=True, env=env)
        out = ru.stdout + ru.stderr
        check("★前置★ 現場成立:rmdir 這一步真的拋了例外(輸出有順帶清理沒成功的字樣)",
              "順帶清理空目錄" in out, out)
        check("★manifest 仍被刪掉(父目錄清不掉不該擋住它)★", not manifest.exists(), out)
        check("★rc 仍是 0(選配收尾失敗不得升級成『真正的錯誤』)★", ru.returncode == 0, out)
        check("★輸出不得出現誤導的『移除 <manifest> 失敗』★",
              f"移除 {manifest} 失敗" not in out, out)
    finally:
        _os.chmod(share, orig_mode)


def t_slim_uninstall_claude_md_write_failure_does_not_abort_remaining_steps():
    """★2026-08-02 對照實驗抓到的合約違反(不是 reviewer 抓到的——四席裡三席
    明確宣稱「各步互不阻擋、沒有任何一步會中止其他步驟」,而且講反了)★。

    本檔 docstring 與圖譜宣告的 ★INVARIANT★ 是「五個步驟各自獨立、互不阻擋」。
    但 `_restore_claude_md()`(步驟④)裡的 `unlink()`/`write_text()` 是裸呼叫,
    `main()` 呼叫它時也沒有 try——CLAUDE.md 唯讀/磁碟滿/檔案被鎖住時直接拋
    `PermissionError` 炸穿 `main()`,★排在它後面的步驟⑤(manifest)完全不會執行★,
    使用者只看到一段 traceback。合約在 code 裡根本沒被兌現。

    ★現場必須真的拋例外,不能只是讓它不被執行★(第④型假綠的教訓):把
    `CLAUDE.md` 本身 chmod 成 `r--r--r--`——區塊移除算出來的新內容非空,走的是
    `target.write_text(new)` 那一支,對唯讀檔開 'w' 必定 PermissionError。
    父目錄權限不動,所以步驟⑤要動的 `~/.local/share/` 完全不受影響,⑤沒跑成
    只可能是被④炸斷。

    ★翻紅釘★:把 `_restore_claude_md()` 的 try/except 拿掉還原成裸呼叫,
    「manifest 仍被移除」與「rc 是 2 不是 1」兩條斷言會翻紅(未捕捉例外的
    exit code 正好是 1——所以 rc 那條刻意釘死 2,不收 `in (1, 2)`,否則就掉進
    第②型「斷言太鬆」)。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    if hasattr(_os, "geteuid") and _os.geteuid() == 0:
        check("★skip★ root 身分下權限不生效,此測試無意義", True, "running as root")
        return
    root = _P(_tf.mkdtemp(prefix="gctl-slimclaudemd-blocked-"))

    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    _slim_copy_uninstall_files(pkg)
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    proj = root / "proj"
    proj.mkdir()
    claude_md = proj / "CLAUDE.md"
    claude_md.write_text("# 專案標題\n\n原有內容\n", encoding="utf-8")

    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★前置★ install.sh rc0", ri.returncode == 0, ri.stdout + ri.stderr)

    manifest = fake_home / ".local" / "share" / "lumos-slim" / "manifest.json"
    check("★前置★ 安裝後 manifest 存在(否則⑤本來就沒事可做,測不到東西)",
          manifest.is_file(), str(manifest))
    before = claude_md.read_text(encoding="utf-8")
    check("★前置★ 安裝後 CLAUDE.md 真的有 LUMOS-SLIM 區塊(④才有事可做)",
          "LUMOS-SLIM:START" in before, before[:200])

    orig_mode = claude_md.stat().st_mode
    _os.chmod(claude_md, 0o444)
    try:
        ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                            capture_output=True, text=True, env=env)
        out = ru.stdout + ru.stderr
        check("★前置★ 現場成立:④ 真的踩到檔案系統錯誤(不是被跳過)",
              "區塊移除/還原失敗" in out, out)
        check("★前置★ 沒有未捕捉例外炸出 traceback",
              "Traceback (most recent call last)" not in out, out)
        check("★合約:④ 失敗不得阻擋⑤——manifest 仍被移除★",
              not manifest.exists(), out)
        check("★rc 必須是 2(彙總出來的錯誤),不是 1(未捕捉例外的 exit code)★",
              ru.returncode == 2, f"rc={ru.returncode}\n{out}")
        check("★④ 失敗時 CLAUDE.md 必須原封不動(不得半殘)★",
              claude_md.read_text(encoding="utf-8") == before, out)
    finally:
        _os.chmod(claude_md, orig_mode)


def t_slim_install_filesystem_error_reports_cleanly_without_traceback():
    """★install 的例外處理跟 uninstall 是相反的語意,這條測試守的是這個差別★。

    uninstall 宣告「各步互不阻擋」,所以它逐步吞 OSError 再彙總;install 的
    `main()` 是★遇錯早退★(每一步依賴前一步,裝到一半就該停,而不是把 skill
    裝進一個沒有 CLI 的環境)。所以 install 這邊★不能★學 uninstall 逐處包
    try/except 讓它繼續跑——那會改掉它的順序語意。

    install 真正該修的只有一件:例外別以 traceback 的形式丟給使用者。
    `PermissionError` 的堆疊對使用者毫無用處,「權限不足,請確認 X 可寫」才有。

    ★現場★:把 `~/.local/bin` chmod 成 `r-x`,`shutil.copyfile()` 寫不進去,
    必定 PermissionError。★翻紅釘★:把 `_main_guarded()` 的 except 拿掉、
    入口改回 `main()`,「沒有 traceback」與「rc==2」兩條會翻紅(未捕捉例外的
    exit code 是 1)。

    ★這條刻意不斷言「已完成的步驟被回滾」★——精簡版明確不做交易式回滾
    (回滾自己也會失敗,而且刪使用者的東西風險更高),半成品狀態是已知且
    刻意保留的,重跑 `--force` 收斂。斷言不存在的行為會變成假需求。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    if hasattr(_os, "geteuid") and _os.geteuid() == 0:
        check("★skip★ root 身分下權限不生效,此測試無意義", True, "running as root")
        return
    root = _P(_tf.mkdtemp(prefix="gctl-sliminstall-perm-"))

    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    bin_dir = fake_home / ".local" / "bin"
    bin_dir.mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    proj = root / "proj"
    proj.mkdir()
    (proj / "CLAUDE.md").write_text("# 專案標題\n\n原有內容\n", encoding="utf-8")

    orig_mode = bin_dir.stat().st_mode
    _os.chmod(bin_dir, 0o500)
    try:
        ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                            capture_output=True, text=True, env=env)
        out = ri.stdout + ri.stderr
        check("★前置★ 現場成立:安裝真的踩到檔案系統錯誤(不是悄悄成功了)",
              "檔案系統錯誤" in out, out)
        check("★不得把 traceback 丟給使用者★",
              "Traceback (most recent call last)" not in out, out)
        check("★rc 必須是 2(可辨識的錯誤),不是 1(未捕捉例外的 exit code)★",
              ri.returncode == 2, f"rc={ri.returncode}\n{out}")
        check("★訊息必須可行動(講得出常見原因與下一步)★",
              "權限" in out and "重跑" in out, out)
        check("★CLAUDE.md 不得被動過(③ 排在失敗的① 之後,早退代表它沒跑到)★",
              "LUMOS-SLIM" not in (proj / "CLAUDE.md").read_text(encoding="utf-8"), out)
    finally:
        _os.chmod(bin_dir, orig_mode)


def t_slim_uninstall_claude_md_read_failure_does_not_abort_remaining_steps():
    """★同一條合約的第二個破口,單 reviewer 抓到(2026-08-02)★:第一版修法只把
    `_restore_claude_md()` 裡的 `unlink()`/`write_text()` 包進 try,★`read_text()`
    留在 try 外面★——「檔案系統寫入」這個字眼讓我只掃了「寫」。

    兩種真實觸發:①CLAUDE.md 讀不到(`chmod 000`)→ `PermissionError`(OSError
    子類)②CLAUDE.md 內容不是合法 utf-8(中文專案裡別的編輯器存成 Big5、貼進
    壞位元組都很真實)→ ★`UnicodeDecodeError` 不是 OSError 子類★(繼承
    `ValueError`),連寫入那邊的 `except OSError` 都攔不到。兩者都炸穿 `main()`、
    步驟⑤永遠不執行——★跟修之前的症狀一模一樣★,只是入口從寫換成讀。

    ★翻紅釘★:把 `read_text()` 的 try/except 拿掉還原成裸呼叫,兩個場景的
    「無 traceback」「manifest 仍被移除」「rc==2」都會翻紅。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    if hasattr(_os, "geteuid") and _os.geteuid() == 0:
        check("★skip★ root 身分下權限不生效,此測試無意義", True, "running as root")
        return

    def _one(label, corrupt, expect_kw):
        root = _P(_tf.mkdtemp(prefix="gctl-slimread-"))
        fake_home = root / "home"
        pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
        _slim_copy_uninstall_files(pkg)
        (fake_home / ".local" / "bin").mkdir(parents=True)
        env = dict(_os.environ, HOME=str(fake_home))
        proj = root / "proj"
        proj.mkdir()
        claude_md = proj / "CLAUDE.md"
        claude_md.write_text("# 專案標題\n\n原有內容\n", encoding="utf-8")

        ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                            capture_output=True, text=True, env=env)
        check(f"★前置★[{label}] install.sh rc0", ri.returncode == 0, ri.stdout + ri.stderr)
        manifest = fake_home / ".local" / "share" / "lumos-slim" / "manifest.json"
        check(f"★前置★[{label}] 安裝後 manifest 存在(⑤才有事可做)",
              manifest.is_file(), str(manifest))

        corrupt(claude_md)
        ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                            capture_output=True, text=True, env=env)
        out = ru.stdout + ru.stderr
        check(f"★前置★[{label}] 現場成立:④ 真的踩到讀取失敗",
              expect_kw in out, out)
        check(f"[{label}] ★不得炸出 traceback★",
              "Traceback (most recent call last)" not in out, out)
        check(f"[{label}] ★合約:④ 讀失敗不得阻擋⑤——manifest 仍被移除★",
              not manifest.exists(), out)
        check(f"[{label}] ★rc 必須是 2,不是 1(未捕捉例外的 exit code)★",
              ru.returncode == 2, f"rc={ru.returncode}\n{out}")
        _os.chmod(claude_md, 0o644)

    _one("讀不到", lambda f: _os.chmod(f, 0o000), "讀不到")
    _one("非 utf-8",
         lambda f: f.open("ab").write(b"\xff\xfe not utf-8\n"),
         "不是合法 utf-8")


def t_slim_install_non_utf8_claude_md_reports_cleanly():
    """★install 側的姊妹漏洞(同一次 review 抓到)★:`_main_guarded()` 第一版
    只接 `OSError`,但 `_merge_claude_md_text()` 讀的是★使用者既有的★
    CLAUDE.md——那份檔案不是我們寫的、編碼不歸我們管。不是合法 utf-8 時拋的是
    `UnicodeDecodeError`(繼承 `ValueError`,★不是 OSError★),攔不到,照樣
    traceback + rc1,違反這次修法自己承諾的「例外別以 traceback 丟給使用者」。

    ★同時守一條更重要的行為★:看不懂內容時★不得改寫使用者的 CLAUDE.md★
    ——斷言那個位元組序列原封不動還在。

    ★翻紅釘★:拿掉 `_main_guarded` 的 `except UnicodeDecodeError` 分支,
    「無 traceback」與「rc==2」翻紅。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminstall-enc-"))
    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))
    proj = root / "proj"
    proj.mkdir()
    claude_md = proj / "CLAUDE.md"
    raw = b"# Title\n\n\xff\xfe invalid utf8 content\n"
    claude_md.write_bytes(raw)

    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    out = ri.stdout + ri.stderr
    check("★前置★ 現場成立:安裝真的踩到編碼問題(不是悄悄成功了)",
          "不是合法 utf-8" in out, out)
    check("★不得炸出 traceback★",
          "Traceback (most recent call last)" not in out, out)
    check("★rc 必須是 2,不是 1(未捕捉例外的 exit code)★",
          ri.returncode == 2, f"rc={ri.returncode}\n{out}")
    check("★看不懂內容就不准改寫使用者的 CLAUDE.md(位元組原封不動)★",
          claude_md.read_bytes() == raw, repr(claude_md.read_bytes()[:60]))
    # ★2026-08-02 對交付包端到端真跑時發現的不對稱★:OSError 分支有講「已完成的
    # 步驟不會被回滾」,這條沒講——但這時 ①CLI 與 ②skill 其實已經裝好了,不講
    # 使用者會以為整件事失敗、跑去手動清理。訊息不對稱本身就是缺陷。
    check("★必須講明半成品狀態(①②已裝好、只有③沒動),否則使用者會誤以為全失敗★",
          "不會被回滾" in out and "冪等" in out, out)
    check("★前置★ 現場成立:①②這時真的已經裝好了(否則上一條在講一件沒發生的事)",
          (fake_home / ".local" / "bin" / "lumos").exists()
          and (fake_home / ".claude" / "skills" / "lumos-project-notes").is_dir(),
          str(sorted(_os.listdir(fake_home / ".local" / "bin"))))


def t_slim_uninstall_readonly_pkg_files_still_removed():
    """★2026-08-03 中文 Windows 真機驗證的 MAJOR★:卸載 `~/.lumos-slim` 時撞上
    git 設成唯讀的 pack 檔(.idx/.pack)——`shutil.rmtree` 預設 `PermissionError`。

    ★真正的傷害不是「刪不掉」,是「刪到一半」★:訊息只說「移除失敗」,聽起來像
    什麼都沒動;實測 `.git` 目錄還在但 HEAD/config/index 已被刪掉,留下一個
    「看起來像 repo、實際已損壞」的目錄。而 `get.ps1` 用 `Test-Path "$Dest\\.git"`
    判斷「是不是我們的 clone」→ True → 跑 `git pull` → rc=128 → 使用者看到
    「可能有本地改動,或不是 fast-forward」——★完全指錯方向,把人鎖死★。

    ★本測試驗真行為(不是掃長相)★:真的建一個含唯讀檔的 pkg,真的跑卸載,
    斷言目錄★完全消失★。macOS 上的唯讀語意足以觸發同一條 rmtree 例外路徑。

    ★翻紅釘★:把 `onerror`/`onexc` 拿掉 → 「完全移除」翻紅。"""
    import tempfile as _tf, os as _os, stat as _st, shutil as _sh
    from pathlib import Path as _P
    if hasattr(_os, "geteuid") and _os.geteuid() == 0:
        check("★skip★ root 身分下權限不生效", True, "running as root")
        return
    root = _P(_tf.mkdtemp(prefix="gctl-rdonly-"))
    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    _slim_copy_uninstall_files(pkg)
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))
    proj = root / "proj"; proj.mkdir()
    (proj / "CLAUDE.md").write_text("# 專案\n\n內容\n", encoding="utf-8")
    subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                   capture_output=True, text=True, env=env)

    # ★模擬 Windows 上 git 對 pack 檔設的唯讀屬性★
    packdir = fake_home / ".lumos-slim" / ".git" / "objects" / "pack"
    packdir.mkdir(parents=True, exist_ok=True)
    idx = packdir / "p.idx"
    idx.write_text("packdata\n", encoding="utf-8")
    _os.chmod(idx, 0o444)
    # ★這段第一版是假綠(第 15 次),記為教訓★:原本只 `chmod 444` 那個★檔案★,
    # 以為就重現了 Windows 的情境——但 ★POSIX 與 Windows 的擋法根本不同★:
    #   Windows:檔案的「唯讀屬性」本身就擋刪除
    #   POSIX  :刪檔只看★父目錄★的寫入權,檔案自己 444 照刪不誤
    # 於是 macOS 上 rmtree 兩種寫法都成功,把 onerror 拿掉的翻紅釘★照樣全綠★。
    # 修法:改成讓★父目錄★不可寫(POSIX 上真的會擋),這是同一條 rmtree 例外路徑的
    # 可及類比。★誠實邊界:這不是與 Windows 相同的機制,只是同樣會逼出 PermissionError
    # 並讓 _on_rm_error 有機會補權限;真機 Windows 的唯讀屬性路徑仍未驗過。★
    _os.chmod(packdir, 0o555)
    check("★前置★ 現場成立:pack 目錄不可寫(POSIX 上這才擋得住 rmtree)",
          not (packdir.stat().st_mode & _st.S_IWUSR), oct(packdir.stat().st_mode))
    check("★前置★ 現場成立:pkg 內容像本包(否則 rmtree 那條分支根本不會走到)",
          (fake_home / ".lumos-slim" / "scripts" / "lumos").is_file()
          and (fake_home / ".lumos-slim" / "install.sh").is_file(), "pkg 結構不對")

    ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    out = ru.stdout + ru.stderr
    check("★唯讀檔不得擋住移除——~/.lumos-slim 必須完全消失★",
          not (fake_home / ".lumos-slim").exists(), out)
    check("★不得留下半殘的目錄(那會讓 get.ps1 誤判成『可用的 clone』把人鎖死)★",
          not (fake_home / ".lumos-slim" / ".git").exists(), out)
    _sh.rmtree(root, ignore_errors=True)


def t_slim_uninstall_skill_backup_leaves_skills_dir_clean():
    """★2026-08-03 真機驗證的 MINOR⑤★:卸載後 `~/.claude/skills/` 底下留下
    `lumos-project-notes.bak.<timestamp>`,而那個目錄含 `SKILL.md`——
    ★下一個 Claude Code session 把它當成一個有效 skill 載入★,實測 skill 清單
    真的多出一條。也就是★卸載沒有讓這個 skill 停止作用,只是換了個怪名字繼續生效★,
    而訊息還印「已備份並移除」——它根本沒離開那個目錄。

    設計意圖(怕誤刪使用者塞的東西)是對的,★落點錯了★:`~/.claude/skills/` 正是
    Claude Code 掃描 skill 的目錄。改落 `~/.local/share/lumos-slim/backups/`
    ——那裡已經是安裝器放 manifest 的地方,語意一致且不在任何掃描範圍。

    ★同時釘住「刻意保留 ≠ 可以靜默」★:備份會讓 lumos-slim/ 不再是空的,
    「清空目錄」那步正確地不觸發,但彙總必須明講留了什麼、留在哪——
    否則就是原本 manifest 殘留那條缺陷的同一形狀。

    ★翻紅釘★:落點改回 `_unique_backup_path(skill)` → 前兩條翻紅。"""
    import tempfile as _tf, os as _os, shutil as _sh
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-bakloc-"))
    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    _slim_copy_uninstall_files(pkg)
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))
    proj = root / "proj"; proj.mkdir()
    (proj / "CLAUDE.md").write_text("# 專案\n\n內容\n", encoding="utf-8")
    subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                   capture_output=True, text=True, env=env)

    skills_dir = fake_home / ".claude" / "skills"
    skill = skills_dir / "lumos-project-notes"
    check("★前置★ 現場成立:skill 真的裝好了(否則備份分支不會走到)", skill.is_dir(), str(skill))
    (skill / "MY_NOTE.md").write_text("使用者自己塞的筆記\n", encoding="utf-8")

    ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    out = ru.stdout + ru.stderr
    leftovers = sorted(x.name for x in skills_dir.iterdir()) if skills_dir.is_dir() else []
    check("★~/.claude/skills/ 底下不得留下任何東西(留了會被當成新 skill 載入)★",
          leftovers == [], str(leftovers))
    bak_root = fake_home / ".local" / "share" / "lumos-slim" / "backups"
    baks = sorted(bak_root.glob("lumos-project-notes.bak.*")) if bak_root.is_dir() else []
    check("★備份必須真的存在於新落點(不是被直接刪掉)★", len(baks) == 1, str(baks))
    check("★使用者自己塞的檔必須完好跟著搬過去★",
          bool(baks) and (baks[0] / "MY_NOTE.md").is_file(), str(baks))
    check("★彙總必須明講留了什麼、留在哪(刻意保留不等於可以靜默)★",
          "刻意保留" in out and "backups" in out, out)
    _sh.rmtree(root, ignore_errors=True)


def t_slim_install_skill_backup_also_leaves_skills_dir_clean():
    """★2026-08-03 Windows 真機回歸測試:⑤ 只修了卸載端,★安裝端漏了★★。

    `install.py` 的 `_install_skill` 仍把既有 skill 備份到 `~/.claude/skills/` 底下
    改名——那正是 Claude Code 掃描 skill 的目錄,實測清單真的出現
    `lumos-project-notes.bak.<ts>`。

    ★而且安裝端留下的比卸載端更糟★:**卸載器不會清它**(卸載只認
    `lumos-project-notes` 這個名字),於是那份備份會★永遠留在 skills 目錄裡持續生效★。

    修法:兩邊共用同一個落點 `~/.local/share/lumos-slim/backups/`。
    ★不同落點就等於又製造一次「同一件事兩份實作」★——那是本專案今天已經
    收編過三次的形狀。

    ★翻紅釘★:把 `_skill_backup_path` 換回 `_unique_backup_path` → 前兩條翻紅。"""
    import tempfile as _tf, os as _os, shutil as _sh
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-instbak-"))
    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    _slim_copy_uninstall_files(pkg)
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))
    proj = root / "proj"; proj.mkdir()
    (proj / "CLAUDE.md").write_text("# 專案\n\n內容\n", encoding="utf-8")

    subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                   capture_output=True, text=True, env=env)
    skills_dir = fake_home / ".claude" / "skills"
    skill = skills_dir / "lumos-project-notes"
    check("★前置★ 現場成立:第一次安裝真的裝好了 skill", skill.is_dir(), str(skill))
    (skill / "MY_NOTE.md").write_text("使用者自己塞的\n", encoding="utf-8")

    # ★重裝★才會觸發「備份既有 skill」那條分支
    r2 = subprocess.run(["bash", str(pkg / "install.sh"), "--force"], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    out = r2.stdout + r2.stderr
    check("★前置★ 現場成立:重裝真的走到了「備份既有 skill」那條分支",
          "已備份既有 skill" in out, out)

    leftovers = sorted(x.name for x in skills_dir.iterdir())
    check("★安裝端的備份也不得留在 ~/.claude/skills/(會被當新 skill 載入,"
          "而且★卸載器不會清它★)★",
          leftovers == ["lumos-project-notes"], str(leftovers))
    bak_root = fake_home / ".local" / "share" / "lumos-slim" / "backups"
    baks = sorted(bak_root.glob("lumos-project-notes.bak.*")) if bak_root.is_dir() else []
    check("★備份必須落在與卸載端相同的位置(不同落點=又一次兩份實作)★",
          len(baks) == 1, str(baks))
    check("★使用者塞的檔必須完好跟著搬過去★",
          bool(baks) and (baks[0] / "MY_NOTE.md").is_file(), str(baks))
    _sh.rmtree(root, ignore_errors=True)


def t_slim_ps1_real_parser_accepts_both_execution_paths():
    """★2026-08-03:推翻本專案長期掛著的「這台機器沒有 PowerShell,驗不了」★。

    那句誠實邊界被當成免驗證通行證寫進多個節點,而它★對其中兩個機制是錯的★:
      ・`$Args` 自動變數遮蔽 → PowerShell ★語言層★行為,跨平台一致
      ・BOM 讓 `iex` 炸第 1 行 → 同上(`irm` 回字串、BOM 不被剝)
    只有「Windows 磁碟執行時用系統 ANSI codepage 讀檔」才是真正 Windows-only。
    PowerShell 7 Core 可 `brew install powershell`,前兩者在 macOS 上就驗得到。

    ★通則(值得記進圖譜)★:遇到「跨平台語言層行為」不要直接套用「沒有那個執行環境」
    這個免驗證通行證——★先問它到底是不是該平台獨有的行為★。

    本測試在有 `pwsh` 時做兩件真事:
      ① 用真 parser 解析三支 .ps1(磁碟路徑)
      ② 讀成字串再 ParseInput(模擬 `irm | iex`,★不剝 BOM★)
    沒有 pwsh 時明確 skip(不假裝驗過)。"""
    import shutil as _sh, subprocess as _sp
    from pathlib import Path as _P
    pwsh = _sh.which("pwsh")
    if not pwsh:
        check("★skip★ 本機無 pwsh——★這是環境限制,不是「驗過了」★"
              "(pwsh 可 brew install;有裝就會真的跑 parser)", True, "no pwsh")
        return
    repo = _P(GRAPHCTL).parent.parent
    script = (
        '$bad = 0\n'
        'foreach ($f in @("slim/get.ps1","slim/install.ps1","slim/uninstall.ps1")) {\n'
        '  $p = Join-Path $env:LUMOS_REPO $f\n'
        '  $e1 = $null; $t1 = $null\n'
        '  [void][System.Management.Automation.Language.Parser]::ParseFile($p, [ref]$t1, [ref]$e1)\n'
        '  if ($e1.Count -ne 0) { "FILE-FAIL $f " + $e1[0].Message; $bad = 1 }\n'
        '  $raw = [System.Text.Encoding]::UTF8.GetString([System.IO.File]::ReadAllBytes($p))\n'
        '  $first = $raw.Split([char]10)[0]\n'
        # ★不可用 $first.StartsWith("#")★:.NET 的 String.StartsWith(string) 預設是
        # ★文化相關比對,會忽略 U+FEFF 這類零寬字元★——第一個字元明明是 BOM 也回 True,
        # 這條檢查就永遠不會翻紅(自測踩到,第 16 次假綠的第二層)。改直接比對字元。
        '  if ($first.Length -eq 0 -or $first[0] -ne [char]0x23) { "IEX-FAIL $f U+" + ("{0:X4}" -f [int][char]$first[0]); $bad = 1 }\n'
        '}\n'
        '$snippet = "# entry (Windows/PowerShell)" + [Environment]::NewLine + "Write-Output SNIP"\n'
        '$plain  = try { Invoke-Expression $snippet | Out-Null; "OK" } catch { "FAIL" }\n'
        '$bommed = try { Invoke-Expression ([char]0xFEFF + $snippet) | Out-Null; "OK" } catch { "FAIL" }\n'
        '"MECH plain=$plain bommed=$bommed"\n'
        'if ($bad -eq 0) { "ALL-OK" }\n')
    import os as _os
    r = _sp.run([pwsh, "-NoProfile", "-Command", script],
                capture_output=True, text=True,
                env=dict(_os.environ, LUMOS_REPO=str(repo)))
    check("★前置★ 現場成立:pwsh 真的跑起來並回了結果(不是靜默失敗)",
          r.returncode == 0 and r.stdout.strip() != "", f"rc={r.returncode}\n{r.stdout}\n{r.stderr}")
    check("★真 parser:三支 .ps1 從★磁碟★解析必須零錯誤★",
          "FILE-FAIL" not in r.stdout, r.stdout + r.stderr)
    # ★這段第一版是假綠(第 16 次)★:原本用 `ReadAllText` 讀檔再 `ParseInput`,兩處都錯——
    #   ①`ReadAllText` ★會自動剝掉 BOM★,根本沒模擬到 irm 的行為
    #   ②`ParseInput`／`ScriptBlock::Create` 都★容忍★開頭的 U+FEFF;
    #     ★只有實際執行(`Invoke-Expression`)才失敗★——回報者的錯誤本來就是執行期的
    #     command-not-found(他也寫了「非終止型、後續照跑」),不是 parse error。
    # 於是把 BOM 加回去的翻紅釘★照樣全綠★。修法兩件:①改用保留 BOM 的讀法,檢查
    # 第 1 行的第一個字元是不是 `#`(BOM 在前面時它就不再是註解)②另用合成片段
    # ★真的執行★,自證這個機制存在。
    check("★保留 BOM 的讀法下,每支 .ps1 的第 1 行仍必須是註解(BOM 會讓它不是)★",
          "IEX-FAIL" not in r.stdout, r.stdout + r.stderr)
    check("★前置★ 機制自證:無 BOM 的合成片段執行得起來",
          "plain=OK" in r.stdout, r.stdout)
    check("★機制自證:同一片段加上 BOM 就★執行失敗★——這正是 ASCII-only 勝過 BOM 的地方★",
          "bommed=FAIL" in r.stdout, r.stdout)
    check("★整體:磁碟與 irm 兩條路徑都過★", "ALL-OK" in r.stdout, r.stdout + r.stderr)


def t_ps1_args_shadowing_is_real_language_behavior():
    """★用真 PowerShell 證明 `$Args` 遮蔽不是傳說★——本專案先前只能掃原始碼長相,
    現在可以直接跑(見 t_slim_ps1_real_parser_accepts_both_execution_paths 的說明)。

    這條★不是在測本專案的碼★,是在測「合約背後的那個語言事實」還成不成立。
    ★為什麼值得留★:合約 `param() 不得用 $Args` 的正當性完全建立在這個事實上;
    哪天 PowerShell 改掉這個行為,這條會翻紅,提醒我們重新檢視合約是否還需要。"""
    import shutil as _sh, subprocess as _sp
    pwsh = _sh.which("pwsh")
    if not pwsh:
        check("★skip★ 本機無 pwsh——環境限制,不是「驗過了」", True, "no pwsh")
        return
    script = (
        'function Bad  { param($Pkg, $Args)       ; "BAD="  + $Args.Count }\n'
        'function Good { param($Pkg, $ScriptArgs) ; "GOOD=" + $ScriptArgs.Count }\n'
        'Bad  -Pkg x -Args       @("--force","--here")\n'
        'Good -Pkg x -ScriptArgs @("--force","--here")\n')
    r = _sp.run([pwsh, "-NoProfile", "-Command", script], capture_output=True, text=True)
    check("★前置★ 現場成立:pwsh 真的跑了兩個函式", "BAD=" in r.stdout and "GOOD=" in r.stdout,
          r.stdout + r.stderr)
    check("★語言事實:param 叫 $Args 時,傳進來的值★被自動變數蓋掉、count 為 0★",
          "BAD=0" in r.stdout, r.stdout)
    check("★對照:改名 $ScriptArgs 後 count 正確為 2(證明差異來自名字不是別的)★",
          "GOOD=2" in r.stdout, r.stdout)


def t_slim_ps1_ascii_only_no_bom():
    """★2026-08-03 Windows 真機回歸測試:BOM 只是把問題搬家,不是解法★。

    v1.4 給三支 `.ps1` 加了 BOM 修好「磁碟執行」,卻弄壞了 README 唯一教的
    `irm ... | iex`——`irm` 回傳的是★普通字串★,PowerShell 不會替它剝 BOM,
    於是 `U+FEFF` 成了第 1 行的內容,那行註解被當成指令執行:

        Windows/PowerShell : The term 'Windows/PowerShell' is not recognized...
        + ﻿# get.ps1 — ...一行安裝入口(Windows/PowerShell)

    ★兩難★:無 BOM → 磁碟執行被 cp950 誤解碼;有 BOM → `irm | iex` 炸第 1 行。

    ★正解是消滅問題不是搬家:ASCII-only + 無 BOM★,兩條路徑都不再需要 BOM。
    中文說明搬到 `slim/WINDOWS-NOTES.md`(知識不丟,但不進 .ps1)。

    ★這條紀律組織內部早就有★:LandmarkMember 的 CLAUDE.md〈Deploy 腳本踩雷規則〉
    第 1 條「ASCII-only 規則」,理由一字不差,而且是踩了三輪 prod deploy 失敗才立的。
    ★我設計這幾支檔案時沒有去查過——那正是 CLAUDE.md 第一條「圖譜先行」要防的。★

    ★本測試是機械完備的★:斷言「零個非 ASCII 位元組」直接消滅整個問題類別
    (不需要再模擬 DBCS 規則、也不需要判斷哪些字元危險)。"""
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).parent.parent
    # ★2026-09-07 #7 起把 repo 根的 get.ps1 也納入★:它一直帶著中文,只是沒被這條蓋到。
    # 理由跟精簡版那三支一字不差(磁碟執行用系統 ANSI codepage 解碼、CJK 前導位元組吃掉
    # 下一個位元組),而「沒人回報」不等於沒問題——這個節點自己就寫過「沒人用過的路徑
    # 不會有人回報」。中文說明搬到圖譜節點,不進 .ps1。
    targets = [repo / "slim" / n for n in ("get.ps1", "install.ps1", "uninstall.ps1")]
    targets.append(repo / "get.ps1")
    for path in targets:
        name = ("slim/" if path.parent.name == "slim" else "") + path.name
        raw = path.read_bytes()
        check(f"★{name} 不得有 BOM(有 BOM 會讓 `irm | iex` 在第 1 行就炸)★",
              raw[:3] != b"\xef\xbb\xbf", repr(raw[:8]))
        bad = [(i, b) for i, b in enumerate(raw) if b > 127]
        check(f"★{name} 必須是 ASCII-only(非 ASCII 位元組會在 cp950 下撞壞引號配對)★",
              not bad,
              f"發現 {len(bad)} 個非 ASCII 位元組,前幾個位移: {[i for i, _ in bad[:8]]}\n"
              + (raw.decode("utf-8", "replace")[max(0, bad[0][0] - 60):bad[0][0] + 60] if bad else ""))

    notes = repo / "slim" / "WINDOWS-NOTES.md"
    check("★中文設計說明必須有落點(不是刪掉,是搬家)★",
          notes.is_file() and len(notes.read_text(encoding="utf-8")) > 500,
          str(notes))


def t_slim_ps1_args_param_not_shadowed_by_automatic_variable():
    """★2026-08-03 Windows 真機回歸測試的 MAJOR★:`param($Pkg, $Args)` 讓
    ★所有命令列參數靜默失效★——`--force` / `--here` / `-y` 全部收不到。

    現象:明明加了 `--force`,卻仍印「已存在,加 --force 覆寫」。
    根因:`$Args` 是 PowerShell ★自動變數★(該函式自己「未綁定的參數」),
    會蓋掉呼叫端傳進來的值;於是 `@Args` splatting 展開成★空★。
    最小重現(回報者提供,已納入 WINDOWS-NOTES.md):

        function Invoke-Test { param($Pkg, $Args); ... }
        Invoke-Test -Pkg "x" -Args @("--force")
        → 函式內 $Args = []  count=0

    ★這不是 v1.4 引入的★——前一版把邏輯包進函式時就在了,前一份回報沒抓到是
    因為當時沒傳過任何參數。★「沒人用過的路徑不會有人回報」是真的盲區★。

    ★誠實邊界★:這條是原始碼長相檢查(假綠第③型),★刻意如此★——開發機沒有
    PowerShell 跑不了。它買的是「不會退回到已知會壞的寫法」。"""
    import re as _re
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).parent.parent
    for name in ("get.ps1", "install.ps1", "uninstall.ps1"):
        text = (repo / "slim" / name).read_text(encoding="utf-8")
        code = [ln for ln in text.splitlines() if not ln.strip().startswith("#")]
        code_text = "\n".join(code)
        check(f"★前置★ {name} 真的有 param(...) 與 splatting(否則本測試空轉)",
              "param(" in code_text and "@" in code_text, code_text[:300])
        check(f"★{name} 的 param 不得使用保留名 $Args(會被自動變數蓋掉)★",
              not _re.search(r"param\([^)]*\$Args\b", code_text), code_text)
        check(f"★{name} 不得對 $Args 做 splatting(@Args 會展開成空)★",
              "@Args" not in code_text, code_text)
        check(f"★{name} 入口必須把 $args 傳給非保留名的參數★",
              _re.search(r"-ScriptArgs\s+\$args", code_text) is not None, code_text)


def t_slim_ps1_subprocess_output_does_not_pollute_return():
    """★2026-08-03 真機驗證的 MAJOR★:安裝★成功★那次的收尾爆:

        Cannot convert argument "exitCode", with value: "System.Object[]",
        for "SetShouldExit" to type "System.Int32"

    根因:PowerShell 函式的 `return` 會帶出函式內★所有未被消費的輸出★。
    `& $Py.Source ...` 的 stdout 沒被指派給任何變數就進了輸出流,
    `return $LASTEXITCODE` 再追加一個數字 → 呼叫端收到 ★Object[]★ 不是數字。

    ★`$code = $LASTEXITCODE; return $code` 解決不了★——問題出在 `&` 的 stdout
    進了輸出流,不是 return 的寫法。正解是 `| Out-Host`(直接進主機,不進 pipeline)。

    ★誠實邊界★:這條是第③型(驗寫法不驗行為),★而且刻意如此★——開發機沒有
    PowerShell,一行 .ps1 都跑不了。它買的是「每個 `&` 呼叫外部程式的地方都接了
    `| Out-Host`」這個對稱性,不是「Windows 上真的回數字」。"""
    import re as _re
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).parent.parent
    for name in ("get.ps1", "install.ps1", "uninstall.ps1"):
        txt = (repo / "slim" / name).read_text(encoding="utf-8-sig")
        lines = [l for l in txt.splitlines() if not l.strip().startswith("#")]
        calls = [l for l in lines if _re.match(r"\s*&\s+\$", l)]
        check(f"★前置★ {name} 真的有 `&` 呼叫外部程式(找不到代表正則失效、測試空轉)",
              len(calls) >= 1, "\n".join(lines[:40]))
        for c in calls:
            check(f"★{name} 的 `&` 呼叫必須接 | Out-Host(否則 return 帶出整包輸出變 Object[])★",
                  "Out-Host" in c, c)


def t_slim_get_ps1_every_git_call_checks_lastexitcode():
    """★2026-08-02 對照實驗抓到的不對稱★:`get.ps1` 的 `git pull` 那一支有檢
    `$LASTEXITCODE`、`git clone` 那一支沒有——同一個函式裡一個有一個沒有,是
    漏寫不是設計。漏掉時 clone 失敗(沒網路/沒權限/磁碟滿)會照樣往下走,
    使用者拿到的錯誤訊息是「交付包內容可能不完整」,查錯方向整個被帶偏。

    ★為什麼不能靠 `$ErrorActionPreference = "Stop"` 兜★:它只管 PowerShell
    cmdlet,原生執行檔(git.exe)回非零 exit code 不會觸發終止;PS 7.3 起的
    `$PSNativeCommandUseErrorActionPreference` 才改這行為,而本包要支援
    Windows PowerShell 5.1。

    ★這條測試驗得到什麼、驗不到什麼(誠實邊界)★——它是本專案假綠清單第③型
    「驗寫法不驗行為」,★而且是刻意的★:這台機器沒有 PowerShell(開發環境是
    macOS),無法執行任何一行 ps1。
    - 驗得到:每一個呼叫 `git` 的行,後面幾行內出現 `$LASTEXITCODE` 檢查
      ——也就是「新增 git 呼叫時不會忘了配一道檢查」這個★對稱性★。
    - 驗不到:`$LASTEXITCODE` 在真實 PowerShell 裡對這些呼叫路徑是否確實
      被設定、`return 2` 是否真的傳得回呼叫端。那需要真機,見
      `t_slim_ps1_write_error_noterminating_under_stop_preference` 的同款聲明。
      ★不得因為這條綠了就宣稱 get.ps1 在 Windows 上正確★。"""
    import re as _re
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).parent.parent
    text = (repo / "slim" / "get.ps1").read_text(encoding="utf-8")
    code_lines = [ln for ln in text.splitlines() if not ln.strip().startswith("#")]

    # ★只認「行首(可帶變數指派)的 git 呼叫」★——第一版用 `(?<![\w-])git\s`
    # 掃全行,把錯誤訊息字串裡的「找不到 git 指令」「不是本包的 git clone」也
    # 算成呼叫,三條斷言裡有一條當場翻紅。字串裡的 git 不是呼叫。
    # 已知限制:管線中段的 git(`... | git ...`)抓不到——目前這支沒有,真要
    # 新增那種寫法時這條會靜默漏掉,不是萬用偵測器。
    git_lines = [i for i, ln in enumerate(code_lines)
                 if _re.match(r'\s*(\$\w+\s*=\s*)?git\s', ln)]
    check("★前置★ 真的找得到 git 呼叫行(找不到代表這條正則已經失效、測試在空轉)",
          len(git_lines) >= 2, "\n".join(code_lines[i] for i in git_lines))

    for i in git_lines:
        window = "\n".join(code_lines[i + 1:i + 6])
        check(f"★git 呼叫(行內容: {code_lines[i].strip()[:48]!r})後必須檢 $LASTEXITCODE★",
              "$LASTEXITCODE" in window, window)


def t_slim_uninstall_keeps_manifest_when_bin_refused():
    """★manifest 的清除有一個資料相依,不能無腦刪★:①bin 基於安全考量沒被
    移除時,manifest 必須留著——它是使用者之後加 `--force` 或手動確認時唯一的
    比對基準,先刪掉等於銷毀判斷依據,下次重跑只會落到「基準缺失」而不是
    「內容不符」,使用者反而更難判斷。

    ★驗行為★:製造「bin 被換成使用者自己的檔」現場、跑不帶 --force 的卸載,
    斷言 manifest 檔案★仍然存在★,而且它仍然能當基準用(內容可解析出
    bin_sha256)。把 ⑤ 的 `if bin_cleared:` 拿掉改成無條件刪,這條翻紅。"""
    import tempfile as _tf, os as _os, json as _json
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimmanifest-keep-"))

    fake_home = root / "home"
    pkg = _slim_make_pkg_at(fake_home / ".lumos-slim")
    _slim_copy_uninstall_files(pkg)
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    proj = root / "proj"
    proj.mkdir()
    (proj / "CLAUDE.md").write_text("# 專案標題\n\n原有內容\n", encoding="utf-8")

    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★前置★ install.sh rc0", ri.returncode == 0, ri.stdout + ri.stderr)

    manifest = fake_home / ".local" / "share" / "lumos-slim" / "manifest.json"
    bin_path = fake_home / ".local" / "bin" / "lumos"
    bin_path.unlink()
    bin_path.write_text("#!/bin/sh\necho USER OWN BINARY\n", encoding="utf-8")

    # 先把卸載器複製到 pkg 外面(第一次卸載的步驟③會把 `~/.lumos-slim` 整包移除,
    # 那是它該做的;第二次重跑必須從別的地方叫,模擬 README 明列的「從自己 clone
    # 的目錄跑」那條支援路徑)。
    import shutil as _sh2
    outside = root / "pkg-copy"
    outside.mkdir()
    for fn in ("uninstall.sh", "uninstall.py"):
        _sh2.copy2(pkg / fn, outside / fn)

    ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★bin 拒絕移除時 manifest 必須留著(它是重試的比對基準)★",
          manifest.is_file(), ru.stdout + ru.stderr)
    kept = _json.loads(manifest.read_text(encoding="utf-8")).get("bin_sha256", "")
    check("★留下來的 manifest 仍可用作基準(bin_sha256 解析得出)★",
          bool(kept), repr(kept))
    check("★rc 仍是安全性跳過 rc1★", ru.returncode == 1, ru.stdout + ru.stderr)

    # ★同一份現場加 --force 重跑:bin 清掉了,manifest 這次就該一起消失★
    # ——證明「留著」不是永久豁免,而是等使用者裁定後照樣收乾淨。
    # ⚠ 第一次卸載的步驟③已經把 `~/.lumos-slim` 整包移除(那是它該做的),所以
    # 第二次不能再從 pkg 路徑叫——先把兩支檔案複製到 pkg 外面,模擬使用者
    # 「從自己 clone 的目錄再跑一次」那條路(README 明列的支援用法)。
    rf = subprocess.run(["bash", str(outside / "uninstall.sh"), "--force"], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★--force 重跑後 bin 清掉,manifest 也跟著消失★",
          not bin_path.exists() and not manifest.exists(), rf.stdout + rf.stderr)


def t_slim_get_idempotent():
    """★get.sh 冪等★:~/.lumos-slim 已存在時再跑一次不得產生 git clone 對非空
    目錄的『爆炸』式錯誤,而是 git pull 或直接沿用。用本地 git repo 當 clone
    來源(`LUMOS_SLIM_REPO_URL` 覆蓋預設 GitHub URL),不打真網路。"""
    import tempfile as _tf, os as _os, shutil as _sh
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimget-"))
    (root / ".git").mkdir()   # ★install.sh 注入目標守衛第一層要求★:get.sh 不 cd,
                               # install.sh 的目標 cwd 就是呼叫 get.sh 時的 root
    repo = _P(GRAPHCTL).parent.parent

    src_repo = root / "src_repo"
    src_repo.mkdir()
    subprocess.run(["git", "init", "-q", str(src_repo)], check=True)
    _slim_make_pkg_at(src_repo)
    _sh.copy2(repo / "slim" / "get.sh", src_repo / "get.sh")
    _slim_copy_uninstall_files(src_repo)
    subprocess.run(["git", "-C", str(src_repo), "add", "-A"], check=True)
    subprocess.run(["git", "-C", str(src_repo), "-c", "user.email=t@t", "-c", "user.name=t",
                    "commit", "-qm", "init"], check=True)

    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home), LUMOS_SLIM_REPO_URL=str(src_repo))
    get_sh = str(repo / "slim" / "get.sh")

    r1 = subprocess.run(["bash", get_sh], cwd=str(root), capture_output=True, text=True, env=env)
    check("get.sh 首次執行 rc0", r1.returncode == 0, r1.stdout + r1.stderr)
    check("~/.lumos-slim 已建立(git clone)",
          (fake_home / ".lumos-slim" / ".git").is_dir(), "")
    check("全域指令已裝(經由 get.sh → install.sh)",
          (fake_home / ".local" / "bin" / "lumos").exists(), "")

    r2 = subprocess.run(["bash", get_sh], cwd=str(root), capture_output=True, text=True, env=env)
    check("★冪等★ 第二次執行不出現 git clone 式爆炸訊息",
          "already exists and is not an empty directory" not in (r2.stdout + r2.stderr),
          r2.stdout + r2.stderr)
    check("★冪等★ 第二次執行 stderr 無 Python/bash 未捕例外 traceback",
          "Traceback" not in r2.stderr, r2.stderr)
    check("~/.lumos-slim 二次執行後仍是合法 git repo(未被破壞)",
          (fake_home / ".lumos-slim" / ".git").is_dir(), "")

    # 帶 --force 轉發給 install.sh,驗證冪等更新 + 強制重裝可以完整跑到底
    r3 = subprocess.run(["bash", get_sh, "--force"], cwd=str(root),
                        capture_output=True, text=True, env=env)
    check("get.sh --force 轉發給 install.sh,第二次仍可完整跑完 rc0",
          r3.returncode == 0, r3.stdout + r3.stderr)


def t_slim_get_no_git():
    """git 不存在時 get.sh 要給清楚錯誤訊息、rc2,不是 traceback。用限縮 PATH
    (不含 git 所在目錄)模擬 git 缺失。"""
    import tempfile as _tf
    import shutil as _sh2
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-slimget-nogit-"))
    repo = _P(GRAPHCTL).parent.parent
    fake_home = root / "home"
    fake_home.mkdir()
    empty_bin = root / "empty-bin"
    empty_bin.mkdir()

    bash_bin = _sh2.which("bash") or "/bin/bash"
    env = {"HOME": str(fake_home), "PATH": str(empty_bin)}
    get_sh = str(repo / "slim" / "get.sh")
    r = subprocess.run([bash_bin, get_sh], capture_output=True, text=True, env=env)
    check("git 缺失時 get.sh rc2(非 0)", r.returncode == 2, r.stdout + r.stderr)
    check("git 缺失時給清楚錯誤訊息(非 traceback)",
          "git" in r.stderr and "Traceback" not in r.stderr, r.stderr)
    check("~/.lumos-slim 未被建立(失敗於 git 檢查,未走到 clone)",
          not (fake_home / ".lumos-slim").exists(), "")


def t_slim_readme_assertions():
    """README 必要章節與關鍵句的內容斷言(spec [S5])。"""
    from pathlib import Path as _P
    p = _P(GRAPHCTL).parent.parent / "slim" / "README.md"
    txt = p.read_text(encoding="utf-8")
    for key, name in (
        ("lumos search", "進場三步"),
        ("lumos context", "進場三步-context"),
        ("lumos contracts", "進場三步-contracts"),
        ("鐵則", "frontmatter 四條鐵則"),
        ("移除的是入口不是全部程式碼", "功能子集聲明(★後半句才是 helper 澄清★)"),
        ("lumos update", "〈更新方式〉章(2026-08-19 取代凍結聲明)"),
        ("install-hooks.sh", "明講不要跑哪些"),
        ("doctor", "合約鏈與 doctor 解法"),
    ):
        check(f"README 含「{name}」", key in txt, f"缺 {key!r}")
    # ★交付文字掃描器也要掃 README★
    # ★C1 例外(2026-07-31 終審後已人工審查,故意保留;2026-07-31 接手者演練複審追加
    # 第 4 支)★:README 的「doctor 有些建議指向本包沒給的指令」揭露段故意寫出
    # `lumos init`/`lumos update`/`lumos self-audit`/`lumos signoff` 告訴讀者
    # 「這些指令不存在,看到請忽略」——這是自我指涉的誠實揭露,不是意外的懸空引用
    # (不會誤導讀者以為指令存在)。`signoff` 是複審查出的第 4 支:`scripts/lumos`
    # 的 check_regen_provenance()(lint 與 doctor 共用)在 regen 節點缺證據指針時
    # 會建議「走 signoff 升級」,同型未交付指令,同一段揭露一併白名單。掃描器仍要
    # 跑、仍要對其餘內容零容忍,只白名單這四個已審查過的候選——★不寫死數量★:
    # 這份列舉不保證窮盡(該 spec 已被「我列了 N 種/N 支」打臉四次)。
    scanner = str(_P(GRAPHCTL).parent / "slim-scan.py")
    r = subprocess.run([sys.executable, scanner, str(p), "--json"],
                       capture_output=True, text=True)
    import json as _j3
    cands = _j3.loads(r.stdout)["candidates"] if r.stdout.strip() else []
    reviewed_exception = {("init", "prefixed"),   # ("update","prefixed") 2026-08-19 刪:update 已存在,舊「本包沒有」豁免語意反轉
                          ("self-audit", "prefixed"), ("signoff", "prefixed")}
    # ★2026-08-01 新增的「程式碼註解裡也會提到本包沒交付的檔案」揭露段★——同樣是
    # 自我指涉的誠實揭露(告訴讀者這些字串在註解裡看到是正常的)。★但這裡不放行
    # 整個 (token, form)★:上面那組 (token, form) 白名單天生偏寬,同 token/form 的
    # 候選出現在 README 任何一行都會被靜默吃掉(skill 那支守衛就是因此改用四元組)。
    # 這兩條改綁「該段獨有的特徵字串」——換句話說,只有出現在這段揭露裡才放行,
    # 同一個 token 若在別處新長出來仍會炸開。
    reviewed_in_context = (
        ("design-loop", "skill-name", "這些檔案本包都沒交付"),
        ("code-loop", "prose", "這些檔案本包都沒交付"),
    )
    unexpected = [
        c for c in cands
        if (c["token"], c["form"]) not in reviewed_exception
        and not any(c["token"] == t and c["form"] == f and sub in c["text"]
                    for t, f, sub in reviewed_in_context)
    ]
    check("README 無非預期的懸空引用(排除 C1 已審查揭露段例外)",
          not unexpected, str(unexpected))


def t_slim_skill_reference_scan_assertions():
    """★minor-2(2026-07-31 代碼審)★:交付 skill 的 `SKILL.md`/`reference.md` 從來
    沒被任何測試餵進 `slim-scan.py`——`t_slim_readme_assertions` 只掃 README.md。
    這是既有缺口:reference.md 裡確實有一批已人工審過的自我揭露句(告訴讀者「這些
    指令沒交付,看到請忽略」),但沒有任何機械測試守住它們不會被之後的編輯不小心
    改壞、或悄悄多長出新的懸空引用。

    ★白名單求精確,不求寬鬆★:比照 README 用 (token, form) 的作法還不夠精確——
    (token, form) 允許同一 token/form 出現在任何一行都被放行,新增的懸空引用只要
    湊巧撞上已核准的 (token, form) 組合就會被靜默吃掉。這裡改用 (檔名, 行號,
    token, form) 四元組——每一條白名單項目對應唯一一行,新增/搬動都會被判成
    「非預期」而炸開。"""
    from pathlib import Path as _P
    skill_dir = _P(GRAPHCTL).parent.parent / "slim" / "skills" / "lumos-project-notes"
    skill_md = skill_dir / "SKILL.md"
    ref_md = skill_dir / "reference.md"
    scanner = str(_P(GRAPHCTL).parent / "slim-scan.py")
    r = subprocess.run([sys.executable, scanner, str(skill_md), str(ref_md), "--json"],
                       capture_output=True, text=True)
    import json as _j4
    cands = _j4.loads(r.stdout)["candidates"] if r.stdout.strip() else []

    # 已人工審過的自我揭露句(reference.md)—— 每條都是「明講這條指令本精簡版沒
    # 交付」的誠實揭露,不是意外的懸空引用。行號釘死,任何搬動/新增都會落到白
    # 名單外而被下面的斷言抓到。
    reviewed = {
        ("reference.md", 18, "install", "prefixed"),
        ("reference.md", 18, "init", "bare-token"),
        ("reference.md", 59, "install", "bare-token"),
        ("reference.md", 59, "uninstall", "bare-token"),
        ("reference.md", 59, "bootstrap", "bare-token"),
        ("reference.md", 59, "init", "bare-token"),
        ("reference.md", 59, "deinit", "bare-token"),
        ("reference.md", 59, "teardown", "bare-token"),
        ("reference.md", 61, "init", "prefixed"),
        ("reference.md", 61, "self-audit", "prefixed"),
        ("reference.md", 61, "signoff", "prefixed"),
        ("reference.md", 61, "init", "bare-token"),
        ("reference.md", 246, "gov", "bare-token"),
        ("reference.md", 497, "spec-trace", "bare-token"),
        ("reference.md", 653, "self-audit", "prefixed"),
        ("reference.md", 699, "signoff", "bare-token"),
        ("reference.md", 768, "signoff", "bare-token"),
        # ★已審查的假陽性★:這行講的是 `npx playwright install` 裝瀏覽器,跟
        # 「lumos install」無關——prose 形態的已知代價(裸 token 無法分辨語境)。
        ("reference.md", 343, "install", "prose"),
        # ★已審查的假陽性★(2026-09-02):「enforcement 只管『鏈的存在與一致』」這句的
        # enforcement 是英文常用詞(強制力),不是指令引用;2026-09-02 新增 lumos enforcement
        # 指令後才與指令名撞號。prose 形態、語境無關,同 playwright 那條。
        ("reference.md", 484, "enforcement", "prose"),
    }
    unexpected = [c for c in cands
                  if (_P(c["file"]).name, c["line"], c["token"], c["form"]) not in reviewed]
    check("skill 交付文字(SKILL.md+reference.md)無非預期的懸空引用",
          not unexpected, str(unexpected))
    # ★反鎖死★:白名單本身不能偷偷變成「反正全部放行」——候選數要等於白名單數,
    # 否則代表掃描器行為變了(候選變少)卻沒人發現、白名單裡有死條目。
    check("skill 候選總數與白名單一一對應(無死條目、無漏網)",
          len(cands) == len(reviewed), f"候選 {len(cands)} / 白名單 {len(reviewed)}")


def t_slim_gate():
    """交付前四道機械驗證(spec [S6])。★四道都不可跳★"""
    import tempfile as _tf, re as _re, json as _j, os as _os, shutil as _sh
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).parent.parent
    root = _P(_tf.mkdtemp(prefix="gctl-slimgate-"))
    dist = root / "dist"
    r = subprocess.run([sys.executable, str(repo / "scripts" / "slim-gen.py"),
                        "--outfile", str(dist / "scripts" / "lumos")],
                       capture_output=True, text=True)
    check("gate: 生成 rc0", r.returncode == 0, r.stdout + r.stderr)
    cli = dist / "scripts" / "lumos"

    # 第 1 道 負向:--help choices 不得出現任何移除指令(逐支列名)
    keep = set("""append archive backlinks context contracts decision-add decision-reindex
decision-supersede decisions delguard doctor export guard links lint map new query recent
rel-cascade search set show stale stats sync-verified-by""".split())
    full = subprocess.run([sys.executable, GRAPHCTL, "--help"],
                          capture_output=True, text=True).stdout
    allc = set(_re.search(r"\{([a-z0-9,\-]+)\}", full).group(1).split(","))
    removed = allc - keep
    h = subprocess.run([sys.executable, str(cli), "--help"],
                       capture_output=True, text=True).stdout
    got = set(_re.search(r"\{([a-z0-9,\-]+)\}", h).group(1).split(","))
    check("★第1道 負向★ choices 不含任何移除指令", not (got & removed),
          str(sorted(got & removed)))
    check("★全覆蓋★ 保留∪移除 == --help 全集且零交集",
          (keep | removed) == allc and not (keep & removed), "")

    # 第 2 道 正向:子模式 —— ★驗 spec S6-3 的三來源判準,對真 parser 斷言★
    def _help(*a):
        return subprocess.run([sys.executable, str(cli), *a, "--help"],
                              capture_output=True, text=True).stdout
    # 來源③ 旗標帶 choices → 機械枚舉那類
    check("S6-3: export --format 有 choices(→機械枚舉)",
          "{mermaid,dot,html}" in _help("export").replace(" ", ""), _help("export")[:300])
    # 來源② positional 帶 choices
    check("S6-3: rel-cascade verb 有 choices(→機械枚舉)",
          "{confirm,prune,list,resume,visited}" in _help("rel-cascade").replace(" ", ""),
          _help("rel-cascade")[:300])
    # 來源① subparsers
    g = _help("guard")
    # ★釘的是「子指令能被機械枚舉」,不是「剛好幾支」★:加子指令時照實更新這一行,
    # 不要為了讓它綠而不加子指令。2026-09-22 加了 plan/settle/abandon/required 四支。
    check("S6-3: guard 的子指令能被機械枚舉(→有 choices 清單)",
          "{list,scaffold,plan,settle,abandon,required,bind,audit,trace,kill-add,kill}" in g.replace(" ", ""), g[:300])
    # 純旗標型:整份 help 不得出現任何 choices 的 {..} 形式
    for cmd in ("search", "archive"):
        check(f"S6-3: {cmd} 無任何 choices(→純旗標型)", "{" not in _help(cmd), _help(cmd)[:300])
    vault = mkvault()
    d = subprocess.run([sys.executable, str(cli), "--vault", str(vault), "doctor"],
                       capture_output=True, text=True)
    # ★C3(2026-07-31 終審)★:純 rc in (0,1) 收不住「未捕捉例外」——Python 未捕例外
    # 就是 exit 1,跟正常「發現 issue」的 rc=1 撞號;審查員注入
    # `_totally_undefined_helper()` 進 run_doctor,rc=1 + 完整 traceback 照樣被這條
    # 斷言收下。加兩道:①stderr 不得含 Traceback ②stdout 必須真的跑到收尾摘要行
    # (「─────」分隔線後的「圖譜健康」或「發現 N 個 issue」)——這行只有 run_doctor
    # 正常跑完全部檢查才會印,NameError 會在印到這裡前就整支炸掉,stdout 提早截斷。
    check("★正向 doctor 實跑★(不只 --help)",
          d.returncode in (0, 1) and "Traceback" not in d.stderr,
          d.stderr[:300])
    check("★正向 doctor 實跑★ stdout 真的跑到收尾摘要(未被例外提早截斷)",
          ("圖譜健康" in d.stdout or "個 issue" in d.stdout) and "篇)" in d.stdout,
          d.stdout[-300:] + "|STDERR|" + d.stderr[:300])

    # 第 3 道 等價:goldset search 30 條,完整版 vs 精簡版結果一致
    # ★C2(2026-07-31 終審)★:原本跑在 mkvault() 的空 vault 上——四個空資料夾 + 一篇
    # MOC,兩邊 search 都回空字串,這道閘等於在比 '' == ''、把 cmd_search 掏空也
    # 10/10 PASS。改跑在本 repo 自己的 docs/lumos-toolchain-knowledge(唯讀 search,
    # 不寫入;spec:243 要求「須先定死跑哪個 vault」——goldset 的 snapshot_commit
    # 就是這份 vault 某個舊版本,用同一份 vault 最貼近原意)。先驗證完整版在這個
    # vault 上 30 條全部非空,否則等於只是換了個空 vault、沒解掉真問題。
    real_vault = repo / "docs" / "lumos-toolchain-knowledge"
    gs = _j.loads((repo / "governance" / "eval" / "retrieval-goldset.json")
                  .read_text(encoding="utf-8"))
    all_qs = [q["query"] for q in gs["search"]]
    nonempty = 0
    for q in all_qs:
        a0 = subprocess.run([sys.executable, GRAPHCTL, "--vault", str(real_vault),
                             "search", q, "--files-only"], capture_output=True, text=True)
        if a0.stdout.strip():
            nonempty += 1
    check("★C2★ 完整版在真 vault 上 30 條 goldset 查詢皆非空(防退化成空 vault假守衛)",
          nonempty == len(all_qs), f"{nonempty}/{len(all_qs)} 非空")

    qs = [q["query"] for q in gs["search"][:10]]      # 取前 10 條做冒煙,全量在 Step 4
    same = 0
    for q in qs:
        a = subprocess.run([sys.executable, GRAPHCTL, "--vault", str(real_vault),
                            "search", q, "--files-only"], capture_output=True, text=True)
        b = subprocess.run([sys.executable, str(cli), "--vault", str(real_vault),
                            "search", q, "--files-only"], capture_output=True, text=True)
        if a.stdout == b.stdout:
            same += 1
    check("★第3道 等價★ search 前10條兩版一致(真 vault)", same == len(qs), f"{same}/{len(qs)}")

    # 第 4 道 真機預演在 Step 4 手動跑(需乾淨 HOME)


def t_slim_gate_search_equivalence_counterfactual():
    """★C2 反事實(spec:268)★:第 3 道等價驗證的價值全在「壞掉時會不會擋」。
    故意在精簡版產物副本裡竄改排序(reverse 掉 `_rank_score_candidates` 的回傳
    順序,模擬「行級手術動到排序參數」這種真會發生的壞法),重跑與 t_slim_gate
    完全同款的比對邏輯,斷言 same != 10——這道閘必須翻紅,不能永遠 PASS。"""
    import tempfile as _tf, json as _j
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).parent.parent
    root = _P(_tf.mkdtemp(prefix="gctl-slimgate-cf3-"))
    dist_cli = root / "lumos"
    r = subprocess.run([sys.executable, str(repo / "scripts" / "slim-gen.py"),
                        "--outfile", str(dist_cli)],
                       capture_output=True, text=True)
    check("★C2 反事實★ fixture: 生成 rc0", r.returncode == 0, r.stdout + r.stderr)

    text = dist_cli.read_text(encoding="utf-8")
    marker = "        scored = _rank_score_candidates(env, term, list(_cand_hits))"
    check("★C2 反事實★ 產物含預期的排序呼叫(竄改點存在,前提沒漂移)",
          marker in text, "")
    tampered = text.replace(marker, marker + "\n        scored = list(reversed(scored))", 1)
    check("★C2 反事實★ 竄改確實改到檔案內容", tampered != text, "")
    dist_cli.write_text(tampered, encoding="utf-8")
    dist_cli.chmod(0o755)

    real_vault = repo / "docs" / "lumos-toolchain-knowledge"
    gs = _j.loads((repo / "governance" / "eval" / "retrieval-goldset.json")
                  .read_text(encoding="utf-8"))
    qs = [q["query"] for q in gs["search"][:10]]
    same = 0
    diverged = []
    for q in qs:
        a = subprocess.run([sys.executable, GRAPHCTL, "--vault", str(real_vault),
                            "search", q, "--files-only"], capture_output=True, text=True)
        b = subprocess.run([sys.executable, str(dist_cli), "--vault", str(real_vault),
                            "search", q, "--files-only"], capture_output=True, text=True)
        if a.stdout == b.stdout:
            same += 1
        else:
            diverged.append(q)
    check("★C2 反事實★ 竄改排序後,等價閘必翻紅(same 不再是 10/10)",
          same != len(qs), f"same={same}/{len(qs)}, 有差異的查詢={diverged}")


def t_slim_gate_doctor_nameerror_counterfactual():
    """★C3 反事實★:第 2 道「doctor 實跑」的斷言(★正向 doctor 實跑★)存在的理由
    正是「精簡版 doctor 會壞要抓得到」——行級手術最典型的故障就是砍到還被引用的
    函式,執行期 NameError。故意在精簡版產物副本裡的 `run_doctor` 開頭塞一顆地雷
    (`_totally_undefined_helper()`),斷言 t_slim_gate 現在用的斷言邏輯
    (`Traceback not in stderr` 且 stdout 有收尾摘要)會抓到它翻紅。"""
    import tempfile as _tf
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).parent.parent
    root = _P(_tf.mkdtemp(prefix="gctl-slimgate-cf2-"))
    dist_cli = root / "lumos"
    r = subprocess.run([sys.executable, str(repo / "scripts" / "slim-gen.py"),
                        "--outfile", str(dist_cli)],
                       capture_output=True, text=True)
    check("★C3 反事實★ fixture: 生成 rc0", r.returncode == 0, r.stdout + r.stderr)

    text = dist_cli.read_text(encoding="utf-8")
    marker = "def run_doctor(env: Env, strict: bool, color: bool, suggest=False, ci=False, verbose=False, touched=None):"  # 2026-08-21 +verbose(體檢 #10);2026-09-22 +touched(本機只擋碰到的)
    check("★C3 反事實★ 產物含預期的 run_doctor 簽名(竄改點存在,前提沒漂移)",
          marker in text, "")
    tampered = text.replace(
        marker, marker + "\n    _totally_undefined_helper()  # ★注入的 NameError★", 1)
    check("★C3 反事實★ 竄改確實改到檔案內容", tampered != text, "")
    dist_cli.write_text(tampered, encoding="utf-8")
    dist_cli.chmod(0o755)

    vault = mkvault()
    d = subprocess.run([sys.executable, str(dist_cli), "--vault", str(vault), "doctor"],
                       capture_output=True, text=True)
    check("★C3 反事實★ 注入 NameError 後確實 rc=1(前提成立)", d.returncode == 1,
          f"rc={d.returncode} stderr={d.stderr[:200]}")
    gate_ok = (d.returncode in (0, 1) and "Traceback" not in d.stderr
               and (("圖譜健康" in d.stdout or "個 issue" in d.stdout) and "篇)" in d.stdout))
    check("★C3 反事實★ 注入 NameError 後,doctor 實跑閘必翻紅(不是被 rc in (0,1) 放行)",
          not gate_ok, f"stderr含Traceback={'Traceback' in d.stderr}, stdout尾={d.stdout[-200:]!r}")


def t_slim_gen_dist_ships_entrypoints():
    """★交付包完整性★:slim-gen 組交付包時只複製了 install.sh/README.md/skills,
    漏了 get.sh(curl|bash 入口)與 uninstall.sh——接手者拿到的包裡沒有一行安裝
    入口、也沒有卸載腳本,等於那些功能不存在。★2026-08 Task 13 擴充★:安裝/卸載
    邏輯搬進 Python 後,`install.py`/`uninstall.py` 才是真正的邏輯所在,`.sh`
    只是薄殼——漏了任一個都會讓 `.sh` 呼叫失敗;`.ps1` 三支(install/uninstall/
    get)是 Windows 入口,同樣不可漏。斷言生成後 dist/ 內含全部入口,且 `.sh`
    三支保留可執行位元(組包用 shutil.copy2 保留 mode,但仍要機械鎖住,防止改用
    別的複製方式時悄悄退化成 0o644)——`.py`/`.ps1` 的可執行性不靠 Unix mode
    bit(前者一律經薄殼 `python <path>` 呼叫,後者靠 Windows PowerShell 執行
    原則),不檢查可執行位元。"""
    import tempfile as _tf
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).parent.parent
    root = _P(_tf.mkdtemp(prefix="gctl-slimdist-"))
    dist = root / "dist"
    r = subprocess.run([sys.executable, str(repo / "scripts" / "slim-gen.py"),
                        "--outfile", str(dist / "scripts" / "lumos")],
                       capture_output=True, text=True)
    check("slim-gen rc0", r.returncode == 0, r.stdout + r.stderr)

    expected = ["get.sh", "get.ps1",
                "uninstall.sh", "uninstall.py", "uninstall.ps1",
                "install.sh", "install.py", "install.ps1",
                "README.md", "claude-block.md",
                "scripts/lumos", "skills/lumos-project-notes/SKILL.md"]
    for rel in expected:
        p = dist / rel
        check(f"dist/{rel} 存在", p.is_file(), f"{p} 不存在")

    for rel in ("get.sh", "uninstall.sh", "install.sh"):
        p = dist / rel
        if p.is_file():
            mode = p.stat().st_mode & 0o111
            check(f"dist/{rel} 有可執行位元", mode != 0, oct(p.stat().st_mode))


def t_slim_install_guard_rejects_empty_dir():
    """★注入目標守衛,第一層★:空目錄(無 `.git`/無 `docs/*-knowledge/`/無既有
    `CLAUDE.md`)——這裡看起來不是專案根,拒絕 rc=2,且 `CLAUDE.md` 不得被建立。
    ★誠實邊界★:這層擋的是「在 `~` 或隨便一個目錄下誤跑」,不是那兩次真實事故
    (事故發生的目錄本身就有 .git/CLAUDE.md/docs/*-knowledge,像不像專案根這層
    完全擋不住——那是第二層的事,見 `t_slim_install_guard_rejects_source_repo`)。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-guard-empty-"))
    repo = _P(GRAPHCTL).parent.parent

    pkg = _slim_make_pkg_at(root / "pkg")
    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)
    env = dict(_os.environ, HOME=str(fake_home))

    empty = root / "empty"
    empty.mkdir()

    r = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(empty),
                       capture_output=True, text=True, env=env)
    check("★第一層★ 空目錄 → rc=2", r.returncode == 2, r.stdout + r.stderr)
    check("★第一層★ CLAUDE.md 未被建立", not (empty / "CLAUDE.md").exists(), "")
    check("★第三層★ 輸出含目標絕對路徑(即使被拒絕也要印)",
          str(empty) in r.stdout, r.stdout)
    check("拒絕訊息講清楚檢查了什麼",
          ".git" in (r.stdout + r.stderr) and "docs" in (r.stdout + r.stderr), r.stdout + r.stderr)


