def t_slim_install_symlink_cwd_audit_path_matches_write_path():
    """★MINOR(2026-08-01 代碼審第四輪,bash 版本的原始缺陷/回歸情境)★:第三層
    守衛與 CLAUDE.md 寫入路徑計算必須用同一套「已解 symlink 的實體路徑」,不能
    一個用 `pwd -P`、另一個用素樸 `$(pwd)`——否則透過 symlink 進入專案目錄時,
    守衛稽核印出的「將修改: …」路徑會跟真正寫入完成後回報的路徑字串不一致。

    ★2026-08 Task 13 搬成 Python 後,這整類 bug 已被結構性消滅★:邏輯全部搬進
    `install.py`,`目標專案`/`將修改` 兩行印出的路徑與實際寫入用的路徑都來自
    同一個 `target_dir = Path.cwd().resolve()`(`Path.cwd()` 底層呼叫
    `os.getcwd()`,這一律回傳實體路徑,不像 bash 的 `pwd` 內建指令有「邏輯路徑
    ($PWD 追蹤)」與「實體路徑(`-P`)」兩種形式可能被混用)——沒有第二種路徑
    表示法可以拿來跟它打架,也就不存在「一個用 -P、另一個沒用」這種可以犯的
    錯誤。本測試因此從「回歸測試」變成「結構不可能重現的反事實確認」:即使刻意
    透過 symlink cwd + 模擬互動 shell 已 `cd` 進 symlink 的情境(`env
    PWD=<symlink 路徑>`,原 bash 版本用來逼出分歧的手法,這裡沿用只是為了不
    削弱涵蓋面),斷言仍然必須成立——如果將來有人回頭在 install.sh 薄殼裡加
    了什麼繞過 install.py、自己算路徑的邏輯,這條測試才擋得住。"""
    import tempfile as _tf, os as _os, re as _re
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-symlink-"))

    pkg = _slim_make_pkg_at(root / "pkg")
    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)

    real_proj = root / "real-proj"
    real_proj.mkdir()
    subprocess.run(["git", "init", "-q", str(real_proj)], check=True)

    link_proj = root / "link-proj"
    link_proj.symlink_to(real_proj, target_is_directory=True)

    # ★關鍵★:顯式把 $PWD 設成 symlink 路徑,模擬互動 shell 已 cd 進 symlink
    # 後再呼叫本腳本的情境——沒有這行,子行程的 bash 起手 PWD 會直接落回
    # getcwd() 的實體路徑,測不出 `pwd` 與 `pwd -P` 的分歧。
    env = dict(_os.environ, HOME=str(fake_home), PWD=str(link_proj))

    r = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(link_proj),
                       capture_output=True, text=True, env=env)
    check("symlink cwd 安裝 rc0", r.returncode == 0, r.stdout + r.stderr)

    m_target = _re.search(r"^將修改: (.+)$", r.stdout, _re.MULTILINE)
    m_done = _re.search(r"^✓ CLAUDE\.md 精簡版紀律區塊已安裝/更新: (.+)$", r.stdout, _re.MULTILINE)
    check("輸出含「將修改:」稽核行", m_target is not None, r.stdout)
    check("輸出含「✓ …已安裝/更新:」收尾行", m_done is not None, r.stdout)

    if m_target and m_done:
        audit_path = m_target.group(1).strip()
        written_path = m_done.group(1).strip()
        check("★稽核路徑與實際寫入路徑字串一致★ (改回素樸 $(pwd) 會在這裡翻紅)",
              audit_path == written_path,
              f"稽核: {audit_path!r}  實際寫入: {written_path!r}")
        check("★兩者皆已解 symlink(實體路徑,非 symlink 邏輯路徑)★",
              str(link_proj) not in audit_path and str(link_proj) not in written_path,
              f"稽核: {audit_path!r}  實際寫入: {written_path!r}  symlink路徑: {link_proj}")

    real_claude_md = real_proj / "CLAUDE.md"
    check("CLAUDE.md 確實寫在實體路徑底下", real_claude_md.exists(), "")


def _slim_min_path_env():
    """組一個「足夠跑 bash/python3/git,但不含任何 ~/.local/bin」的最小 PATH
    字串——供 Windows PATH 提示測試模擬「使用者 PATH 沒加這個路徑」的情境,
    同時不因為限縮過頭連 python3/bash/git 本身都找不到而讓 fixture 先炸掉。"""
    import shutil as _sh2
    from pathlib import Path as _P
    dirs = []
    for exe in (sys.executable, _sh2.which("bash"), _sh2.which("git")):
        if exe:
            d = str(_P(exe).parent)
            if d not in dirs:
                dirs.append(d)
    dirs += ["/usr/bin", "/bin"]
    return ":".join(dirs)


def t_slim_install_sh_forwards_args():
    """★薄殼轉發參數(2026-08 Task 13 新增)★:`install.sh` 現在只是薄殼,真正
    邏輯全在同目錄的 `install.py`——這條測試只驗「轉發」這一件事本身,不牽涉
    `install.py` 的任何業務邏輯:用一支*假* `install.py`(只把收到的 `sys.argv`
    原樣印成 JSON)取代真正的實作,跑 `install.sh --force --here extra-arg`,
    斷言 `install.sh` 轉發給它的參數逐一、逐序與命令列輸入相同。★不用真正的
    install.py★是刻意的——這樣才是對「轉發」這個行為的獨立單元測試,不會被
    `install.py` 內部邏輯(例如三層守衛提前 rc2)污染,那些已經有專屬測試蓋。"""
    import tempfile as _tf, json as _j
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-fwd-"))
    repo = _P(GRAPHCTL).parent.parent

    pkg = root / "pkg"
    pkg.mkdir()
    import shutil as _sh
    _sh.copy2(repo / "slim" / "install.sh", pkg / "install.sh")
    (pkg / "install.sh").chmod(0o755)
    (pkg / "install.py").write_text(
        "#!/usr/bin/env python3\n"
        "import json, sys\n"
        "print(json.dumps(sys.argv[1:]))\n",
        encoding="utf-8")

    r = subprocess.run(["bash", str(pkg / "install.sh"), "--force", "--here", "extra-arg"],
                       cwd=str(root), capture_output=True, text=True)
    check("薄殼轉發:rc0(假 install.py 直接印完就結束)", r.returncode == 0, r.stdout + r.stderr)
    got = _j.loads(r.stdout.strip())
    check("★薄殼原樣轉發參數,逐一逐序相同★",
          got == ["--force", "--here", "extra-arg"], f"轉發到: {got}")


def t_slim_uninstall_sh_forwards_args():
    """★薄殼轉發參數★:與 `t_slim_install_sh_forwards_args` 對稱,驗
    `uninstall.sh` → `uninstall.py` 的參數轉發。"""
    import tempfile as _tf, json as _j
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-fwd2-"))
    repo = _P(GRAPHCTL).parent.parent

    pkg = root / "pkg"
    pkg.mkdir()
    import shutil as _sh
    _sh.copy2(repo / "slim" / "uninstall.sh", pkg / "uninstall.sh")
    (pkg / "uninstall.sh").chmod(0o755)
    (pkg / "uninstall.py").write_text(
        "#!/usr/bin/env python3\n"
        "import json, sys\n"
        "print(json.dumps(sys.argv[1:]))\n",
        encoding="utf-8")

    r = subprocess.run(["bash", str(pkg / "uninstall.sh"), "--force"],
                       cwd=str(root), capture_output=True, text=True)
    check("薄殼轉發:rc0(假 uninstall.py 直接印完就結束)", r.returncode == 0, r.stdout + r.stderr)
    got = _j.loads(r.stdout.strip())
    check("★薄殼原樣轉發參數★", got == ["--force"], f"轉發到: {got}")


def t_slim_install_windows_creates_cmd_shim():
    """★Windows 分支邏輯測試,非真機驗證★(2026-08 Task 13)——這台機器沒有
    Windows,無法驗證真實 `.cmd` 檔案系統/PATH 行為;用
    `LUMOS_SLIM_SIMULATE_WINDOWS=1` 環境變數(見 `install.py` 的 `IS_WIN`
    定義)逼同一份 Python 程式碼走 Windows 分支,驗證的是★程式邏輯本身★:
    ①產生 `lumos.cmd` shim,內容用 `%~dp0`(批次檔自己所在目錄)相對定位、
    不寫死 PKG 絕對路徑(維持「複製後與交付包解耦」,`~/.lumos-slim` 事後被
    砍掉也不影響已裝好的東西——這是 Unix 版 `cp` 就自帶的特性,Windows shim
    若寫死 PKG 路徑就會喪失這個特性)②同時複製一份 `lumos`(shim 實際呼叫的
    目標,內容與 `scripts/lumos` 逐位元組相同)③★不★對 `lumos` 執行
    chmod +x(Windows 不需要;驗證「真的沒呼叫 chmod」最直接的方式就是看
    可執行位元有沒有被設起來——Unix 分支跑同一支 fixture 一定會設起來)
    ④manifest 記錄的 `bin_sha256` 是 `lumos`(內容副本)的雜湊,直接可以拿
    `scripts/lumos` 來源比對,語意跟 Unix 版一致(shim 本身內容固定、跟安裝
    位置無關,拿它當比對基準沒有鑑別力,故不採用它)。
    ★測不到什麼★:mklink、真實 cmd.exe/PowerShell 執行 `.cmd` 的行為、
    Windows PATH 環境變數的真實生效方式——這些只有真機才驗得到,見
    `slim/README.md`〈支援平台〉的誠實聲明,不要把這條測試的綠燈誤讀成
    「Windows 已完整驗證」。"""
    import tempfile as _tf, os as _os, hashlib as _hl, json as _j
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-win-"))

    pkg = _slim_make_pkg_at(root / "pkg")
    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)

    proj = root / "proj"
    proj.mkdir()
    subprocess.run(["git", "init", "-q", str(proj)], check=True)

    env = dict(_os.environ, HOME=str(fake_home), LUMOS_SLIM_SIMULATE_WINDOWS="1")
    r = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                       capture_output=True, text=True, env=env)
    check("Windows 模擬安裝 rc0", r.returncode == 0, r.stdout + r.stderr)

    dst_shim = fake_home / ".local" / "bin" / "lumos.cmd"
    dst_script = fake_home / ".local" / "bin" / "lumos"
    check("★產生 .cmd shim★", dst_shim.is_file(), "")
    shim_text = dst_shim.read_text(encoding="utf-8") if dst_shim.is_file() else ""
    check("★shim 用 %~dp0 相對定位★", "%~dp0" in shim_text, shim_text)
    check("★shim 不寫死 PKG 絕對路徑(維持與交付包解耦)★", str(pkg) not in shim_text, shim_text)
    check("★同時複製 lumos 內容副本(shim 呼叫的目標)★", dst_script.is_file(), "")
    if dst_script.is_file():
        check("★不 chmod +x(Windows 分支跳過,證明走的是那個分支而非誤判)★",
              dst_script.stat().st_mode & 0o111 == 0, oct(dst_script.stat().st_mode))
        check("★lumos 內容副本與 PKG 來源逐位元組相同★",
              dst_script.read_bytes() == (pkg / "scripts" / "lumos").read_bytes(), "")

    manifest_path = fake_home / ".local" / "share" / "lumos-slim" / "manifest.json"
    check("manifest 已寫", manifest_path.is_file(), "")
    if manifest_path.is_file() and dst_script.is_file():
        data = _j.loads(manifest_path.read_text(encoding="utf-8"))
        expect_sha = _hl.sha256(dst_script.read_bytes()).hexdigest()
        check("★manifest bin_sha256 對應 lumos 內容副本,與 Unix 版語意一致★",
              data.get("bin_sha256") == expect_sha, str(data))


def t_slim_install_windows_path_hint_message():
    """★Windows 分支邏輯測試,非真機驗證★:PATH 缺 `~/.local/bin` 時,提示
    文字要分平台——Windows 講「系統環境變數」,Unix 講 shell 設定檔(見
    `install.py` main() 結尾的分支)。用同一個假交付包分別跑兩次安裝(一次
    一般環境、一次 `LUMOS_SLIM_SIMULATE_WINDOWS=1`),兩次都把 PATH 限縮成
    不含 `~/.local/bin`(但仍含 python3/bash/git,見 `_slim_min_path_env`,
    否則薄殼自己會先因為找不到 python 而 rc2,測不到真正要測的分支),斷言
    兩次印出的提示文字確實不同、且各自命中各自平台的關鍵字。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-winpath-"))
    pkg = _slim_make_pkg_at(root / "pkg")
    min_path = _slim_min_path_env()

    def _run(simulate_win):
        tag = "win" if simulate_win else "unix"
        fake_home = root / f"home-{tag}"
        (fake_home / ".local" / "bin").mkdir(parents=True)
        proj = root / f"proj-{tag}"
        proj.mkdir()
        subprocess.run(["git", "init", "-q", str(proj)], check=True)
        env = dict(_os.environ, HOME=str(fake_home), PATH=min_path)
        if simulate_win:
            env["LUMOS_SLIM_SIMULATE_WINDOWS"] = "1"
        else:
            env.pop("LUMOS_SLIM_SIMULATE_WINDOWS", None)
        return subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                              capture_output=True, text=True, env=env)

    r_unix = _run(False)
    r_win = _run(True)
    check("Unix 模擬安裝 rc0", r_unix.returncode == 0, r_unix.stdout + r_unix.stderr)
    check("Windows 模擬安裝 rc0", r_win.returncode == 0, r_win.stdout + r_win.stderr)
    check("★Unix 提示含「shell 設定檔」字樣★", "shell 設定檔" in r_unix.stderr, r_unix.stderr)
    check("★Windows 提示含「系統環境變數」字樣★", "系統環境變數" in r_win.stderr, r_win.stderr)
    check("★兩平台提示文字確實不同★", r_unix.stderr != r_win.stderr, "")


def t_slim_uninstall_windows_removes_paired_files():
    """★Windows 分支邏輯測試,非真機驗證★:卸載時 `lumos.cmd` shim 與 `lumos`
    內容副本要成對移除(不是只清掉其中一個留下孤兒檔)。用
    `LUMOS_SLIM_SIMULATE_WINDOWS=1` 裝一次、卸載一次(--force,聚焦驗證『配
    對』這件事本身,不糾結 sha256 比對邏輯——那條已有 Unix 版的等價測試蓋過,
    Windows 分支共用同一段比對程式碼)。斷言卸載後兩個檔案都不見了。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-winrm-"))

    pkg = _slim_make_pkg_at(root / "pkg")
    _slim_copy_uninstall_files(pkg)
    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)

    proj = root / "proj"
    proj.mkdir()
    subprocess.run(["git", "init", "-q", str(proj)], check=True)

    env = dict(_os.environ, HOME=str(fake_home), LUMOS_SLIM_SIMULATE_WINDOWS="1")
    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★前置★ Windows 模擬安裝 rc0", ri.returncode == 0, ri.stdout + ri.stderr)

    dst_shim = fake_home / ".local" / "bin" / "lumos.cmd"
    dst_script = fake_home / ".local" / "bin" / "lumos"
    check("★前置★ .cmd shim 與內容副本都已裝上", dst_shim.is_file() and dst_script.is_file(), "")

    ru = subprocess.run(["bash", str(pkg / "uninstall.sh"), "--force"], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("Windows 模擬卸載 rc0", ru.returncode == 0, ru.stdout + ru.stderr)
    check("★lumos.cmd shim 已移除★", not dst_shim.exists(), "")
    check("★lumos 內容副本已移除(成對清除,無孤兒檔)★", not dst_script.exists(), "")


def t_slim_uninstall_windows_orphan_cmd_shim_removed():
    """★Windows 分支邏輯測試,非真機驗證★(2026-08 Task 16,②MAJOR,紅→綠鎖
    行為):修復前 `uninstall.py` 的 `if dst_script.exists() or
    dst_script.is_symlink():` 把整個 `lumos.cmd`(`dst_shim`)移除邏輯都巢狀在
    底下——`lumos` 不存在但 `lumos.cmd` 還在(使用者手滑只刪了 `lumos`,忘了
    刪 `.cmd`)時,外層 `if` 直接判假,整段(含 `--force` 分支)都跳過,孤兒
    `lumos.cmd` 永遠清不掉、`--force` 也救不了——牴觸 `uninstall.py` 自己
    docstring 講的「兩者總是成對安裝/移除」,也是 install.py 那邊 Task 14②
    已經修過的「碰撞偵測要同時看兩個檔案」的鏡像缺口。

    先用 `LUMOS_SLIM_SIMULATE_WINDOWS=1` 做一次真實安裝(產生真正的
    `lumos`+`lumos.cmd` 配對,shim 內容是 install.py 實際偵測出的直譯器,不是
    自己憑空編的假字串),接著只刪 `lumos`(模擬使用者手滑),留下孤兒
    `lumos.cmd`;跑一次不帶 `--force` 的模擬 Windows 卸載,斷言:①rc 仍是
    0(乾淨卸載,因為孤兒 shim 內容比對得上 install.py 產生的固定樣板,不需要
    `--force` 這條保護)②孤兒 `lumos.cmd` 確實被清掉,不是永遠殘留。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-orphancmd-"))

    pkg = _slim_make_pkg_at(root / "pkg")
    _slim_copy_uninstall_files(pkg)
    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)

    proj = root / "proj"
    proj.mkdir()
    subprocess.run(["git", "init", "-q", str(proj)], check=True)

    env = dict(_os.environ, HOME=str(fake_home), LUMOS_SLIM_SIMULATE_WINDOWS="1")
    ri = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★前置★ Windows 模擬安裝 rc0", ri.returncode == 0, ri.stdout + ri.stderr)

    dst_shim = fake_home / ".local" / "bin" / "lumos.cmd"
    dst_script = fake_home / ".local" / "bin" / "lumos"
    check("★前置★ .cmd shim 與內容副本都已裝上", dst_shim.is_file() and dst_script.is_file(), "")

    # ★模擬使用者手滑只刪了 lumos,忘了刪 lumos.cmd★——不透過 uninstall,直接
    # 手動製造孤兒現場。
    dst_script.unlink()
    check("★前置★ lumos 已不存在、lumos.cmd 仍孤兒殘留(現場已布置)",
          not dst_script.exists() and dst_shim.is_file(), "")

    ru = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★孤兒現場下卸載仍 rc0(乾淨卸載,shim 內容比對得上,不需要 --force)★",
          ru.returncode == 0, ru.stdout + ru.stderr)
    check("★孤兒 lumos.cmd 確實被清掉(不是永遠殘留)★", not dst_shim.exists(), "")


def t_slim_uninstall_windows_orphan_cmd_shim_foreign_content_needs_force():
    """★反誤傷 + Windows 分支邏輯測試,非真機驗證★(2026-08 Task 16,②MAJOR,
    對稱驗證):驗證 `t_slim_uninstall_windows_orphan_cmd_shim_removed` 的修法
    不是矯枉過正變成「lumos 不存在時無腦刪掉任何 lumos.cmd」——內容比對規則
    要真的有鑑別力。孤兒 `lumos.cmd` 若內容不符合 install.py 產生的固定樣板
    (可能是使用者自己的東西),不帶 `--force` 應該拒絕移除(rc=1,安全性
    跳過,不是硬錯誤);帶 `--force` 才能覆蓋這條保護。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-orphancmdfg-"))

    pkg = _slim_make_pkg_at(root / "pkg")
    _slim_copy_uninstall_files(pkg)
    fake_home = root / "home"
    bin_dir = fake_home / ".local" / "bin"
    bin_dir.mkdir(parents=True)
    foreign_shim = bin_dir / "lumos.cmd"
    foreign_bytes = "@echo off\r\nrem 使用者自己的東西,不是本包產生的 shim\r\n".encode("utf-8")
    foreign_shim.write_bytes(foreign_bytes)

    proj = root / "proj"
    proj.mkdir()
    subprocess.run(["git", "init", "-q", str(proj)], check=True)

    env = dict(_os.environ, HOME=str(fake_home), LUMOS_SLIM_SIMULATE_WINDOWS="1")
    r = subprocess.run(["bash", str(pkg / "uninstall.sh")], cwd=str(proj),
                       capture_output=True, text=True, env=env)
    check("★內容不符本包樣板 → rc1(安全性跳過,非硬錯誤)★", r.returncode == 1, r.stdout + r.stderr)
    check("★該檔內容未被動(位元組級比對)★",
          foreign_shim.read_bytes() == foreign_bytes, repr(foreign_shim.read_bytes()))

    rf = subprocess.run(["bash", str(pkg / "uninstall.sh"), "--force"], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★帶 --force 才允許移除★", rf.returncode == 0, rf.stdout + rf.stderr)
    check("--force 後檔案確實被移除", not foreign_shim.exists(), "")


def _slim_python3_only_path_env(root):
    """建一個「PATH 上保證只有 `python3`、沒有 `python`」的環境字串——供
    `t_slim_install_windows_shim_does_not_hardcode_python_*` 用,★不依賴宿主
    機器剛好沒裝 `python` 這個巧合★(即使巧合成立,也不該讓測試的紅/綠取決於
    跑測試那台機器裝了什麼):在 `root` 下自建一個 stub bin 目錄,裡面放一支
    只轉呼叫真正直譯器(`sys.executable`)的 `python3` shell script,PATH 只
    含這個 stub 目錄 + `bash`/`git` 所在目錄(薄殼與 git 操作需要),刻意不
    帶系統其他可能藏著 `python` 這個名字的目錄。回傳組好的 PATH 字串。"""
    import shutil as _sh2
    stub_dir = root / "stubbin"
    stub_dir.mkdir(parents=True, exist_ok=True)
    py3 = stub_dir / "python3"
    py3.write_text(f'#!/bin/sh\nexec "{sys.executable}" "$@"\n', encoding="utf-8")
    py3.chmod(0o755)
    dirs = [str(stub_dir)]
    for exe in (_sh2.which("bash"), _sh2.which("git")):
        if exe:
            d = str(Path(exe).parent)
            if d not in dirs:
                dirs.append(d)
    return ":".join(dirs)


def t_slim_install_windows_shim_does_not_hardcode_python_when_only_python3_available():
    """★Windows 分支邏輯測試,非真機驗證★(2026-08 Task 14,①★必修★,紅→
    綠鎖行為):修復前 `.cmd` shim 寫死呼叫字面 `python`(`install.py` 舊版
    `_install_cli()` 的 `shim_text = '@echo off\\r\\npython "%~dp0lumos"
    %*\\r\\n'`),但同專案 `install.sh`/`install.ps1` 兩支薄殼都承認 `python`
    可能不存在(先試 `python3`,找不到才退 `python`)——只有 `python3.exe`、
    沒有 `python.exe` 的 Windows 機器上,`install.ps1` 用 `python3` 把安裝
    跑完、印出「裝好了」,但產生的 shim 卻寫死呼叫 `python`,之後每次打
    `lumos` 都得到 `'python' is not recognized`,裝完即壞。

    用 `_slim_python3_only_path_env()` 組一個 PATH 上保證只有 `python3`(自製
    stub,`exec` 真正的直譯器,不依賴宿主機器巧合沒裝 `python`)的環境,跑一次
    模擬 Windows 安裝,斷言產生的 shim 裡呼叫 lumos 腳本前的那個指令詞恰好是
    `python3`——★精確比對,不是子字串比對★(`"python3" in shim_text` 這種
    寫法測不出寫死 bug,因為 `python3` 這個字串本身就包含 `python` 這個子
    字串,子字串比對永遠是真)。"""
    import tempfile as _tf, os as _os, re as _re
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-wshimpy-"))

    pkg = _slim_make_pkg_at(root / "pkg")
    fake_home = root / "home"
    (fake_home / ".local" / "bin").mkdir(parents=True)

    proj = root / "proj"
    proj.mkdir()
    subprocess.run(["git", "init", "-q", str(proj)], check=True)

    only_python3_path = _slim_python3_only_path_env(root)
    env = dict(_os.environ, HOME=str(fake_home), PATH=only_python3_path,
               LUMOS_SLIM_SIMULATE_WINDOWS="1")
    r = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                       capture_output=True, text=True, env=env)
    check("模擬 Windows 安裝(PATH 只有 python3)rc0", r.returncode == 0, r.stdout + r.stderr)

    dst_shim = fake_home / ".local" / "bin" / "lumos.cmd"
    shim_text = dst_shim.read_text(encoding="utf-8") if dst_shim.is_file() else ""
    m = _re.search(r'^(\S+)\s+"%~dp0lumos"', shim_text, _re.MULTILINE)
    interpreter = m.group(1) if m else None
    check("★shim 有記錄呼叫用的直譯器★", interpreter is not None, shim_text)
    check("★不是寫死字面 python(精確比對,非子字串)★", interpreter != "python", shim_text)
    check("★確實記錄成偵測到的 python3★", interpreter == "python3", shim_text)


def t_slim_install_windows_collision_detects_orphan_cmd_shim():
    """★Windows 分支邏輯測試,非真機驗證★(2026-08 Task 14,②,紅→綠鎖行為):
    修復前碰撞偵測 `collided = dst_script.exists() or dst_script.is_symlink()`
    只看 `lumos`(dst_script)不看 `lumos.cmd`(dst_shim)——使用者若手動刪了
    `lumos` 忘了刪 `lumos.cmd`(單獨殘留),非 `--force` 重裝時 `collided` 判
    成假,會直接跳過碰撞保護、無聲覆寫殘留的 `lumos.cmd`,繞過「碰撞需要
    --force」這條保護的存在意義。

    這裡的 fake bin 目錄只放一個殘留的 `lumos.cmd`(內容是可辨識的假字串),
    刻意不放 `lumos`,模擬「使用者砍過 lumos、忘了砍 .cmd」的現場,跑一次不帶
    --force 的模擬 Windows 安裝,斷言:①rc 非 0(視為碰撞,不是靜默成功)
    ②殘留的 `lumos.cmd` 內容原封不動(沒被蓋掉)③沒有產生 `lumos`(證明真的
    在碰撞保護那一步就退出,沒有往下跑完安裝)。"""
    import tempfile as _tf, os as _os
    from pathlib import Path as _P
    root = _P(_tf.mkdtemp(prefix="gctl-sliminst-cmdcollide-"))

    pkg = _slim_make_pkg_at(root / "pkg")
    fake_home = root / "home"
    bin_dir = fake_home / ".local" / "bin"
    bin_dir.mkdir(parents=True)
    orphan_shim = bin_dir / "lumos.cmd"
    # ★用 write_bytes/read_bytes 比對,不用 write_text/read_text★——後者預設
    # universal-newline 轉譯,讀回時會把 \r\n 正規化成 \n,拿它跟原始字串比較
    # 即使檔案位元組完全沒被動過也會誤判成「內容變了」(假紅),掩蓋掉真正要
    # 驗的事:檔案位元組有沒有被 install.py 動過。
    orphan_bytes = "@echo off\r\nrem 使用者手動殘留的舊 shim,lumos 本體已被刪除\r\n".encode("utf-8")
    orphan_shim.write_bytes(orphan_bytes)

    proj = root / "proj"
    proj.mkdir()
    subprocess.run(["git", "init", "-q", str(proj)], check=True)

    env = dict(_os.environ, HOME=str(fake_home), LUMOS_SLIM_SIMULATE_WINDOWS="1")
    r = subprocess.run(["bash", str(pkg / "install.sh")], cwd=str(proj),
                       capture_output=True, text=True, env=env)
    check("★孤兒 lumos.cmd 視為碰撞,非 0 退出(不是靜默成功)★",
          r.returncode != 0, r.stdout + r.stderr)
    check("★孤兒 lumos.cmd 內容未被覆寫(位元組級比對)★",
          orphan_shim.read_bytes() == orphan_bytes,
          repr(orphan_shim.read_bytes()))
    check("★仍未產生 lumos(dst_script),證明真的沒往下跑完安裝步驟★",
          not (bin_dir / "lumos").exists(), "")

    # ★對稱驗證★:同一份殘留現場,帶 --force 應該能正常覆寫成功(不是从此
    # 卡死),避免這條修復矯枉過正變成「Windows 上 --force 也救不了」。
    rf = subprocess.run(["bash", str(pkg / "install.sh"), "--force"], cwd=str(proj),
                        capture_output=True, text=True, env=env)
    check("★帶 --force 能正常覆寫孤兒殘留,重新裝成功★", rf.returncode == 0, rf.stdout + rf.stderr)
    check("★--force 之後 lumos.cmd 內容已更新(不再是孤兒殘留文字,位元組級比對)★",
          orphan_shim.read_bytes() != orphan_bytes,
          repr(orphan_shim.read_bytes()))
    check("★--force 之後 lumos 也已產生★", (bin_dir / "lumos").exists(), "")


def t_slim_ps1_scripts_avoid_session_killing_trailing_exit():
    """★靜態結構檢查,非真機驗證★(2026-08 Task 14,③保險性修法;★Task 15
    擴大範圍★——Task 14 只改了三支檔案「結尾」那個 `exit $LASTEXITCODE`,
    早期錯誤分支(找不到 python3/python、找不到 git、clone/pull 失敗、交付包
    不完整)留下的 6 處 `exit 2` 沒有一併修,反而更該修:它們全在錯誤路徑上,
    使用者最需要看到錯誤訊息的時候,視窗反而被關掉、連錯在哪都來不及讀)。
    PowerShell 的 `exit` 在 `irm ... | iex` 或 `& "路徑\\install.ps1"` 這種
    呼叫鏈裡會終止整個呼叫端 session(不像 bash 子行程只結束自己),而 README
    教的兩種呼叫方式(`irm ... | iex` 一行版、`& "$HOME\\.lumos-slim\\install.ps1"`
    兩行版)都會踩到。

    ★這台機器沒有 PowerShell,無法真機驗證這段語意★——只能做靜態結構檢查:
    斷言三支 `.ps1` 的**程式碼行完全不含裸 `exit`**(不只結尾的
    `exit $LASTEXITCODE`,也涵蓋早期分支的 `exit 2`;排除註解行,避免被修復
    說明自己的文字誤觸發),同時仍把 rc 寫回 `$LASTEXITCODE`(供呼叫端在同一
    個 session 內讀到)、且都留著「這段修法未經真機驗證」的誠實聲明,不能
    包裝成已解決。★反向斷言(驗『沒有把守衛拆成不擋』)另見
    `t_slim_ps1_error_branches_still_halt_via_return`。"""
    import re as _re
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).parent.parent
    slim = repo / "slim"

    for name in ("install.ps1", "uninstall.ps1", "get.ps1"):
        text = (slim / name).read_text(encoding="utf-8")
        # ★只看真正的程式碼行,不看註解★——修復說明的註解文字裡本來就會提到
        # 舊寫法的字面 `exit $LASTEXITCODE`/`exit 2`(拿來解釋改了什麼),對
        # 整份檔案做無腦字串比對會被自己的說明文字誤觸發成「還有裸 exit」假紅。
        code_lines = [ln for ln in text.splitlines() if not ln.strip().startswith("#")]
        code_text = "\n".join(code_lines)
        check(f"★{name} 程式碼行完全不含裸 exit(涵蓋早期錯誤分支的 exit 2,不只結尾)★",
              not _re.search(r'(?im)^\s*exit(?![\w-])', code_text),
              code_text)
        check(f"★{name} 仍把 rc 寫回 $LASTEXITCODE 供呼叫端讀取★",
              "$LASTEXITCODE = $LASTEXITCODE" in text or "$global:LASTEXITCODE" in text,
              text)
        # ★2026-08-03 改判準★:三支 .ps1 已改為 ASCII-only(見下方 BOM/DBCS 那條測試),
        # 中文說明搬到 slim/WINDOWS-NOTES.md。誠實聲明因此也必須是英文,且改為
        # ★指向那份筆記★——把「為什麼這樣寫」留在檔案裡是重點,語言是次要。
        check(f"★{name} 必須指向 WINDOWS-NOTES.md(中文設計說明的落點)★",
              "WINDOWS-NOTES.md" in text, text)


def t_slim_ps1_error_branches_still_halt_via_return():
    """★反向斷言,防止「拔掉 exit 但守衛被拆成不擋」★(2026-08 Task 15,
    接續 Task 14 殘留缺陷):把 `exit 2` 改成別的寫法,很容易一不小心寫成
    「印完錯誤訊息但沒有真的中止」,導致守衛形同虛設(例如找不到 python 卻
    繼續往下跑 install.py)。這裡做的是**靜態結構檢查**,驗的是:每一處
    `Write-Error`(程式碼行,排除註解)緊接著的下一行程式碼必須是
    `return <整數>`——在 PowerShell 裡,函式本體內的 `return` 會直接結束
    整個函式(不只是結束當下的 if/elseif 區塊),只要這個 `return` 是函式
    本體內、沒有巢狀在別的迴圈/scriptblock 裡面,後面真正的安裝/卸載動作
    就不會被跑到;另外檢查函式回傳值真的有被外層收進變數、寫回
    `$global:LASTEXITCODE`,不是函式內部對了但外層沒接住。

    ★這條驗得到什麼、驗不到什麼(誠實邊界)★:
    - 驗得到:原始碼結構上「錯誤訊息後面緊接著就是 `return <int>`,不是繼續
      往下的其他陳述式」;3 支檔案裡 6 個 `Write-Error` 一一對應 6 個
      `return`;邏輯確實包進 `function`;函式回傳值確實被外層變數接住並寫回
      `$global:LASTEXITCODE`。
    - 驗不到:PowerShell 真實執行語意——這個 `return` 在實際執行時是否真的
      結束整個函式(而非某個巢狀 scriptblock/迴圈,本檔案的函式本身沒有這種
      巢狀,但這條測試不是靠追蹤大括號配對驗證這件事,是靠人工確認結構後
      寫死的正則);函式呼叫鏈、`$LASTEXITCODE`/`$global:LASTEXITCODE` 在
      PowerShell 各種呼叫路徑(`&`/`iex`/dot-source)下是否真的对呼叫端可見,
      都需要真機驗證,這台機器沒有 PowerShell 做不到。

    ★2026-08 Task 16 事後補述(這條測試實際踩到的邊界)★:這條測試連續撐過
    Task 14/15 兩輪(含 mutant 驗證),但完全沒抓到 ①的 `$ErrorActionPreference
    = "Stop"` 讓 `Write-Error` 本身變終止型例外的問題——因為它驗的是「原始碼
    長相」(Write-Error 後面那一行寫的是不是 `return <int>`),不是「執行到
    那一行時,`Write-Error` 這個陳述式本身會不會先拋例外讓 `return` 永遠執行
    不到」。這是本專案第十次撞到「測試存在但沒在驗它宣稱要驗的」——mutant
    驗證只證明「抓得到我想到的失敗模式」,不證明「抓得到真正的失敗模式」,
    不能當作「測試夠格」的證據。真正涵蓋這個語意規則的是
    `t_slim_ps1_write_error_noterminating_under_stop_preference`(見該測試
    docstring 對自己驗得到/驗不到的誠實邊界)。"""
    import re as _re
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).parent.parent
    slim = repo / "slim"

    expected_write_error_count = {
        "install.ps1": 1,
        "uninstall.ps1": 1,
        "get.ps1": 5,
    }

    for name, expected_count in expected_write_error_count.items():
        text = (slim / name).read_text(encoding="utf-8")
        code_lines = [ln for ln in text.splitlines() if not ln.strip().startswith("#")]

        write_error_count = 0
        for i, ln in enumerate(code_lines):
            if not _re.search(r'\bWrite-Error\b', ln):
                continue
            write_error_count += 1
            j = i + 1
            while j < len(code_lines) and code_lines[j].strip() == "":
                j += 1
            next_line = code_lines[j].strip() if j < len(code_lines) else ""
            check(f"★{name} 第{write_error_count}處 Write-Error 後緊接著 return <int>(不是繼續往下跑)★",
                  bool(_re.match(r'^return\s+\d+$', next_line)),
                  f"下一行程式碼是: {next_line!r}\n完整檔案:\n{text}")

        check(f"★{name} 錯誤分支(Write-Error)數量符合預期({expected_count}),沒有分支被漏改或多算★",
              write_error_count == expected_count,
              f"實際找到 {write_error_count} 處\n{text}")

        check(f"★{name} 邏輯已包進函式(function),不是留在裸的頂層★",
              bool(_re.search(r'(?im)^\s*function\s+\S+', text)),
              text)

        m_call = _re.search(r'\$(\w+)\s*=\s*Invoke-\w+', text)
        check(f"★{name} 函式回傳值有被外層變數接住★", bool(m_call), text)
        if m_call:
            varname = m_call.group(1)
            check(f"★{name} 接住的變數有寫回 $global:LASTEXITCODE(呼叫端讀得到 rc)★",
                  bool(_re.search(rf'\$global:LASTEXITCODE\s*=\s*\${varname}\b', text)),
                  text)


def t_slim_ps1_write_error_noterminating_under_stop_preference():
    """★靜態結構檢查,非真機驗證★(2026-08 Task 16,①BLOCKER,補 Task 15
    真正的漏洞):三支 `.ps1` 頂部都設 `$ErrorActionPreference = "Stop"`——
    PowerShell 語意:`Stop` 會把 `Write-Error` 這種非終止型錯誤升級成終止型
    例外(等同 `throw`)。後果:①`Write-Error` 那行直接拋例外,它後面的
    `return <int>`(`t_slim_ps1_error_branches_still_halt_via_return` 驗的
    正是這一行的長相)是死碼,永遠執行不到 ②例外炸穿 `Invoke-Install`/
    `Invoke-Uninstall`/`Invoke-Get`,連 `$rc = Invoke-* ...` 的賦值都完成不了
    ③檔尾 `$global:LASTEXITCODE = $rc` 永遠不執行,呼叫端讀到的是殘留舊值
    (很可能是 0)——把失敗誤判成成功;使用者看到的也不是設計中的乾淨 ERROR
    訊息,而是未捕捉例外的堆疊。★這正好打掉 Task 14/15 整段修法的目的,而且
    發生在它最該保護的錯誤路徑上★——這是本專案第十次撞到「測試存在但沒在驗
    它宣稱要驗的」,細節見 `t_slim_ps1_error_branches_still_halt_via_return`
    docstring 的事後補述。

    修法:每一處 `Write-Error` 呼叫都明確加 `-ErrorAction Continue`——這是
    PowerShell 官方支援的逐次呼叫覆寫機制,對單一 cmdlet 呼叫的 `-ErrorAction`
    參數會蓋過 `$ErrorActionPreference` 這個全域偏好設定(其餘沒有明確覆寫的
    cmdlet 仍然照 `Stop` 該終止就終止,這是刻意保留的行為,只放行 Write-Error
    這條刻意設計成非終止的分支)。

    ★這條驗得到什麼、驗不到什麼(誠實邊界,不能再犯同一種「驗長相不驗語意」
    的錯)★:
    - 驗得到:①三支檔案的 `$ErrorActionPreference = "Stop"` 賦值仍在(沒有
      順手拔掉,拔掉會弱化其他未加 -ErrorAction 覆寫的 cmdlet 該終止卻不終止
      的保護)②每一處 `Write-Error` 呼叫「那一行本身」帶有
      `-ErrorAction Continue`/`SilentlyContinue`/`Ignore` 這種明確覆寫寫法
      (不是靠猜隔壁行、不是子字串比對整份檔案)③`Write-Error` 出現次數符合
      預期(7 處:install.ps1=1、uninstall.ps1=1、get.ps1=5),沒有分支被漏改
      或多算 ④結構順序上,`$ErrorActionPreference = "Stop"` 賦值出現在所有
      `Write-Error` 呼叫「之前」(粗略對應函式內由上而下的執行順序;三支檔案
      邏輯本身是線性、沒有前置分支會跳過賦值,行號順序在這裡足以近似執行
      順序,但這不是控制流分析)。
    - 驗不到(這才是核心誠實聲明):`-ErrorAction Continue` 這個參數在真實
      PowerShell 執行時是否確實蓋過 `$ErrorActionPreference`(這是 PowerShell
      官方文件記載的行為,但這台機器沒有 PowerShell,沒有辦法實際執行一行
      `$ErrorActionPreference = "Stop"; Write-Error "x" -ErrorAction Continue;
      Write-Host "still alive"` 去驗證「still alive」真的印得出來);函式
      scope 内對 `$ErrorActionPreference` 的區域賦值(Task 16③也順手把它從
      頂層搬進函式,見 `slim/install.ps1`/`slim/uninstall.ps1`/`slim/get.ps1`
      同一段修復註解)在函式呼叫當下是否真的先於函式內任何 cmdlet 生效,是
      PowerShell scope 解析規則,同樣沒有真機可以驗;`$LASTEXITCODE`/
      `$global:LASTEXITCODE` 在 `irm | iex`/`&`/dot-source 各種呼叫路徑下
      是否真的對呼叫端可見,一樣需要真機驗證。★不把 mutant 驗證(把
      `-ErrorAction Continue` 拿掉確認這條測試會翻紅)當作「測試夠格」的
      證據★——mutant 只證明「抓得到我想到的這一種失敗模式」,不證明「抓
      得到 PowerShell 真實執行時所有可能讓 Write-Error 變終止型的失敗模式」
      (例如:若之後有人在 `-ErrorAction Continue` 後面誤加了會覆寫回 `Stop`
      的參數、或把整行搬進一個自己又設了 `$ErrorActionPreference = "Stop"`
      的巢狀 scriptblock,這條正則不保證抓得到)。"""
    import re as _re
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).parent.parent
    slim = repo / "slim"

    expected_write_error_count = {
        "install.ps1": 1,
        "uninstall.ps1": 1,
        "get.ps1": 5,
    }

    for name, expected_count in expected_write_error_count.items():
        text = (slim / name).read_text(encoding="utf-8")
        code_lines = [ln for ln in text.splitlines() if not ln.strip().startswith("#")]

        stop_idx = None
        for i, ln in enumerate(code_lines):
            if _re.search(r'\$ErrorActionPreference\s*=\s*"Stop"', ln):
                stop_idx = i
                break
        check(f"★{name} 仍設 $ErrorActionPreference = \"Stop\"(沒有為了閃避這個 bug 順手拔掉,"
              "弱化其他 cmdlet 該終止卻不終止的保護)★",
              stop_idx is not None, text)

        write_error_count = 0
        for i, ln in enumerate(code_lines):
            if not _re.search(r'\bWrite-Error\b', ln):
                continue
            write_error_count += 1
            check(f"★{name} 第{write_error_count}處 Write-Error 本行有明確非終止 -ErrorAction 覆寫"
                  "(不依賴猜測隔壁行、不是整份檔案子字串比對)★",
                  bool(_re.search(r'-ErrorAction\s+(Continue|SilentlyContinue|Ignore)\b', ln)),
                  ln)
            if stop_idx is not None:
                check(f"★{name} 第{write_error_count}處 Write-Error 出現在 $ErrorActionPreference = \"Stop\" "
                      "賦值之後(結構順序近似執行順序,不是控制流分析)★",
                      i > stop_idx, f"Write-Error 在第 {i} 行,Stop 賦值在第 {stop_idx} 行\n{text}")

        check(f"★{name} Write-Error 出現次數符合預期({expected_count}),沒有分支被漏改或多算★",
              write_error_count == expected_count,
              f"實際找到 {write_error_count} 處\n{text}")


def t_suite_strips_git_env_from_hook_invocation():
    """★pre-push 假紅回歸釘(2026-08-01)★:`git push` 會把 `GIT_DIR` export 給
    hook,hook 再把整個 env 傳給測試進程。大量測試會自己 `git init` 臨時 repo
    再對它下 git 指令——`GIT_DIR` 一旦存在就★覆蓋 cwd 推斷★,那些指令全部打到
    本 repo 而不是臨時 repo。症狀是同一個 commit 人手跑全綠、由 pre-push 跑就
    紅個三五條,而且每次紅的條數還不一樣;把 `GIT_DIR` 指向本 repo 實測,紅的
    條數暴增到 65。

    ★驗行為不是驗寫法★:真的用被污染的 env 去 spawn 一個子進程跑一條 git 重的
    測試,斷言它 rc0。把 `main()` 開頭那段 `environ.pop` 拿掉,這條會翻紅
    (已驗證:拿掉後同一條在污染 env 下確實失敗)。"""
    import os as _os5
    env = dict(_os5.environ)
    env["GIT_DIR"] = str(Path(GRAPHCTL).resolve().parent.parent / ".git")
    r = subprocess.run([sys.executable, str(Path(__file__).resolve()),
                        "-k", "codeloop_guard_prepush"],
                       capture_output=True, text=True, env=env)
    check("★GIT_DIR 被污染時,建臨時 repo 的測試仍該全綠(env 已在進入點清掉)★",
          r.returncode == 0, (r.stdout + r.stderr)[-1500:])


