# ══ query 結構化查詢(WHERE over 標籤家族;[[Projects/圖譜結構化查詢_計劃]]) ══

def _mk_query_vault():
    """query 測試共用小庫:標籤家族×狀態×合約×連結 交叉樣本。"""
    v = mkvault()
    write(v, "Systems/Pay.md",
          "type: system\nstatus: done\ntags:\n  - type/system\n  - status/done\n  - risk/金流\n"
          "summary: |-\n  KEY:★INVARIANT★ 金流恆等一條 [test:t_dummy]\n",
          body="# Pay\n[[Systems/Hub]]\n")
    write(v, "Systems/Prose.md",
          "type: system\nstatus: done\ntags:\n  - type/system\n  - status/done\n  - risk/金流\n",
          body="# Prose\n散文裡提到 ★INVARIANT★ 三個字但不是合約行\n")
    write(v, "Issues/OpenPay.md",
          "type: issue\nstatus: open\ntags:\n  - type/issue\n  - status/open\n  - risk/金流\n  - priority/P1\n",
          body="# OpenPay\n[[Systems/Hub]]\n")
    write(v, "Issues/DonePay.md",
          "type: issue\nstatus: done\ntags:\n  - type/issue\n  - status/done\n  - risk/金流\n",
          body="# DonePay\n")
    write(v, "Systems/Hub.md",
          "type: system\nstatus: doing\ntags:\n  - type/system\n  - status/doing\n",
          body="# Hub\n[[Issues/Free]]\n")
    write(v, "Issues/Free.md",
          "type: issue\nstatus: open\ntags:\n  - type/issue\n  - status/open\n",
          body="# Free\n")
    write(v, "Systems/DeadPay.md",
          "type: system\nstatus: superseded\ntags:\n  - type/system\n  - status/superseded\n  - risk/金流\n",
          body="# DeadPay\n")
    return v


def t_query_tag_and():
    """--tag 可重複=AND;命中列出 rel [status]。"""
    v = _mk_query_vault()
    r = run(v, "query", "--tag", "risk/金流", expect_rc=0)
    for rel in ("Systems/Pay.md", "Systems/Prose.md", "Issues/OpenPay.md", "Issues/DonePay.md"):
        check(f"單 tag 命中 {rel}", rel in r.stdout, r.stdout)
    check("單 tag 不含無標節點 Hub", "Systems/Hub.md" not in r.stdout, r.stdout)
    check("輸出帶狀態欄", "[open]" in r.stdout and "[done]" in r.stdout, r.stdout)
    r2 = run(v, "query", "--tag", "risk/金流", "--tag", "priority/P1", expect_rc=0)
    check("雙 tag=AND 只剩 OpenPay", "Issues/OpenPay.md" in r2.stdout, r2.stdout)
    check("雙 tag=AND 排除單命中 Pay", "Systems/Pay.md" not in r2.stdout, r2.stdout)


def t_query_no_tag_and_active():
    """--no-tag 排除;--active=狀態不在收案態。"""
    v = _mk_query_vault()
    r = run(v, "query", "--tag", "risk/金流", "--no-tag", "type/issue", expect_rc=0)
    check("--no-tag 排除 issue 型", "Issues/OpenPay.md" not in r.stdout and "Issues/DonePay.md" not in r.stdout, r.stdout)
    check("--no-tag 保留 system 型", "Systems/Pay.md" in r.stdout, r.stdout)
    r2 = run(v, "query", "--tag", "risk/金流", "--active", expect_rc=0)
    check("--active 保留 open", "Issues/OpenPay.md" in r2.stdout, r2.stdout)
    check("--active 排除 done", "Issues/DonePay.md" not in r2.stdout and "Systems/Pay.md" not in r2.stdout, r2.stdout)


def t_query_contract_uses_real_parser():
    """--contract 沿用 extract_contracts:只認 KEY 行標準格式,散文提及不算。"""
    v = _mk_query_vault()
    r = run(v, "query", "--tag", "risk/金流", "--contract", expect_rc=0)
    check("真合約節點 Pay 命中", "Systems/Pay.md" in r.stdout, r.stdout)
    check("★散文提及 Prose 不命中(真解析器)★", "Systems/Prose.md" not in r.stdout, r.stdout)
    check("無合約 issue 不命中", "Issues/OpenPay.md" not in r.stdout, r.stdout)


def t_query_linked_scope():
    """--linked <節點>:範圍縮到連入+連出 1-hop 鄰居(不含錨點自己)。"""
    v = _mk_query_vault()
    # Hub 的鄰居:連入 Pay/OpenPay,連出 Free。DonePay/Prose 無連結不在鄰域。
    r = run(v, "query", "--linked", "Hub", "--tag", "status/open", expect_rc=0)
    check("鄰域內 open 命中 OpenPay", "Issues/OpenPay.md" in r.stdout, r.stdout)
    check("鄰域內連出方向也算(Free)", "Issues/Free.md" in r.stdout, r.stdout)
    check("鄰域外不入列(DonePay)", "Issues/DonePay.md" not in r.stdout, r.stdout)
    check("錨點自己不入列", "Systems/Hub.md" not in r.stdout, r.stdout)
    rbad = run(v, "query", "--linked", "沒這個節點", "--tag", "risk/金流")
    check("--linked 查無節點 rc2", rbad.returncode == 2, f"rc={rbad.returncode}")


def t_query_forget_superseded():
    """預設排除 superseded(對齊 search 真遺忘鐵則);--include-superseded 逃生;隱藏數走 stderr。"""
    v = _mk_query_vault()
    r = run(v, "query", "--tag", "risk/金流", expect_rc=0)
    check("預設排除 superseded(DeadPay 不出)", "Systems/DeadPay.md" not in r.stdout, r.stdout)
    check("隱藏提示走 stderr 且計數=1", "已隱藏 1" in r.stderr, r.stderr)
    check("隱藏提示不污染 stdout", "已隱藏" not in r.stdout, r.stdout)
    r2 = run(v, "query", "--tag", "risk/金流", "--include-superseded", expect_rc=0)
    check("--include-superseded 召回 DeadPay", "Systems/DeadPay.md" in r2.stdout, r2.stdout)
    check("逃生模式不印隱藏提示", "已隱藏" not in r2.stderr, r2.stderr)


def t_query_bare_rc2():
    """無任何篩選旗標=rc2 拒絕(對齊 stale --candidate 慣例,不列全庫)。"""
    v = _mk_query_vault()
    r = run(v, "query")
    check("bare query rc2", r.returncode == 2, f"rc={r.returncode}\n{r.stderr}")
    check("錯誤訊息說明要帶條件", "--tag" in r.stderr, r.stderr)


def t_query_json():
    """--json:stdout 純 JSON,含 results(node/status/tags)與 hidden_superseded。"""
    import json as _json
    v = _mk_query_vault()
    r = run(v, "query", "--tag", "risk/金流", "--json", expect_rc=0)
    parsed = None
    try:
        parsed = _json.loads(r.stdout)
    except Exception:
        pass
    check("--json stdout 合法 JSON", parsed is not None, r.stdout)
    check("--json hidden_superseded=1", bool(parsed) and parsed.get("hidden_superseded") == 1, r.stdout)
    nodes = [x.get("node") for x in (parsed or {}).get("results", [])]
    check("--json results 含 Pay", "Systems/Pay.md" in nodes, r.stdout)
    check("--json results 不含 DeadPay", "Systems/DeadPay.md" not in nodes, r.stdout)
    st = next((x.get("status") for x in (parsed or {}).get("results", []) if x.get("node") == "Issues/OpenPay.md"), None)
    check("--json 帶 status 欄", st == "open", r.stdout)


def t_vendored_consumer_srconly_skip_regression():
    """★消費端假紅回歸釘([[Issues/vendored自測3紅_來源repo專用測試漏標skip]] 2026-08-17)★:
    Landmark 跑 lumos update 後 vendored 自測 3 紅,全是引用來源 repo 資產的測試
    漏掛(或掛太粗)「來源 repo 專用」skip 守衛:
    - t_precommit_whitelist_drift_guard 直讀 docs/lumos-toolchain-knowledge/Systems/
      pitfalls-code-loop.md,無守衛 → 消費端 FileNotFoundError;
    - t_s2_snr_synthetic 守衛掛在 `governance/eval`(目錄),但 Landmark **自己有**
      governance/eval(檢索考卷),只是沒有 canary_snr.py → 守衛放行後炸兩條
      (「snr 腳本 rc0」+ json 解析 EXCEPTION)。判準粒度必須到「真正要用的檔」。
      (歷史敘述;snr 測試 2026-08-26 已隨機制退場,樣本換 t_difficulty_panel_width
      ——同款精確檔守衛 governance/autonomous_loop/difficulty.py,陷阱形狀與牙齒不變)

    ★驗行為不是驗寫法★:真的搭一個消費端模擬環境(scripts/ 有、docs/ 無、
    governance/eval 目錄在但腳本不在——復刻 Landmark 的陷阱形狀),spawn 子進程
    跑這兩支,斷言 rc0 + 記成 skip + 零 ✗。把守衛拿掉/改回目錄粒度,這條會紅。"""
    import shutil as _sh
    root = Path(tempfile.mkdtemp(prefix="gctl-consumer-sim-"))
    (root / "scripts").mkdir()
    src_scripts = Path(GRAPHCTL).resolve().parent
    for f in ("lumos", "test_lumos.py"):
        _sh.copy(src_scripts / f, root / "scripts" / f)
    if (src_scripts / "hooks").is_dir():
        _sh.copytree(src_scripts / "hooks", root / "scripts" / "hooks")
    # 陷阱形狀:governance/eval 與 autonomous_loop 目錄存在(消費端有自己的考卷/腳本)
    # 但精確檔不存在(原樣本 canary_snr.py 已隨機制退場,2026-08-26 換 difficulty.py——
    # 同款「精確檔守衛」,釘的牙齒不變:守衛改回目錄粒度這條就紅)
    (root / "governance" / "eval").mkdir(parents=True)
    (root / "governance" / "autonomous_loop").mkdir(parents=True)
    # docs/ 整個不存在(消費端 vault 是自己專案的,不叫 lumos-toolchain-knowledge)
    for kw, tname in (("precommit_whitelist_drift_guard", "t_precommit_whitelist_drift_guard"),
                      ("difficulty_panel_width", "t_difficulty_panel_width"),
                      ("vendored_file_list_matches_what_install_ships", "t_vendored_file_list_matches_what_install_ships")):
        r = subprocess.run([sys.executable, str(root / "scripts" / "test_lumos.py"), "-k", kw],
                           capture_output=True, text=True)
        check(f"★消費端模擬:{tname} rc0(不紅)★", r.returncode == 0,
              (r.stdout + r.stderr)[-800:])
        check(f"消費端模擬:{tname} 記成 skip(不是靜默綠)", f"skip {tname}" in r.stdout,
              r.stdout[-800:])
        check(f"消費端模擬:{tname} 零 ✗", "✗" not in r.stdout, r.stdout[-800:])


# ── per-test 超時(2026-08-22 立;症狀真實發生)────────────────────────────
# 症狀:全套跑到某支會卡死——CPU 只走 3 秒、牆鐘走了 7 分鐘,得人工 kill 整輪,
# 而且看不出是卡在哪一支。一輪 10 分鐘的套件卡住一次就等於整輪報廢。
#
# ★超時判紅,不判 skip★:沒跑完就是沒驗過。判 skip 會讓消費 rc 的一方(pre-push /
# CI)把「沒驗」當「驗過」——這個 repo 已經為同型假綠付過代價(-k 選中 0 個也判紅)。
#
# 用 SIGALRM:單進程、零依賴、不影響既有測試。沒有 SIGALRM 的平台(Windows)自動
# 退回「不設限」,行為與加這條之前完全一致。
import os as _os_timeout
import time as _time_slow

TEST_TIMEOUT_SEC = int(_os_timeout.environ.get("LUMOS_TEST_TIMEOUT", "180"))
# 每支耗時,收尾印最慢五支。★這不是效能監控,是超時上限的校準依據★:
# 上限要對「現在最慢那支」有足夠餘裕,否則慢一點的機器(CI)會假紅,
# 然後下一步就是有人把 LUMOS_TEST_TIMEOUT 設 0 繞過——閘變裝飾。
SLOWEST = []
SKIPPED_NAMES = []   # r1 代碼審折入:跳過只記總數的話,「換掉哪一支」看不出來;把名字也留著
# 天生就慢的測試(輪詢 CI 這種)給自己的上限。
# ★不要為了遷就最慢那支把全域上限拉高★——那會讓真的卡死也要等到那個上限才被打斷,
# 等於把偵測能力送掉。實測(2026-08-22 本機):t_ci_wait 132.3s、次慢 25.8s,
# 所以全域 180s 對「一般測試」有 7x 餘裕,只有 t_ci_wait 需要單獨放寬。
TIMEOUT_OVERRIDE = {"t_ci_wait": 450}          # 132.3s → 餘裕 3.4x


class TestTimeout(Exception):
    pass


def run_with_timeout(fn, seconds):
    """跑 fn,超過 seconds 秒拋 TestTimeout。seconds<=0 或平台無 SIGALRM = 不設限。"""
    import signal
    if seconds <= 0 or not hasattr(signal, "SIGALRM"):
        return fn()

    def _boom(signum, frame):
        raise TestTimeout(f"超過 {seconds}s 未結束")

    old = signal.signal(signal.SIGALRM, _boom)
    signal.alarm(seconds)
    try:
        return fn()
    finally:
        signal.alarm(0)
        signal.signal(signal.SIGALRM, old)


def _enforcement_fixture(all_active=True, with_hook_events=True):
    """建一個臨時 repo+home,可選全裝好或全缺,回 (root, home)。

    ★with_hook_events 是 2026-09-08 #19 S4 加的★:判準從「有註冊就算生效」
    升格成「現在有註冊 ∧ 現在的檔案指紋對得上 ∧ 最近有一筆成功完成的事件」,
    所以「全裝好」的現場必須連事件也造出來,否則五支 hook 會是 stale/unknown。
    ★這個開關本身就是那條判準的反向對照★:關掉它,那五列必須從 active 掉下來。
    """
    import json as _j
    root = Path(tempfile.mkdtemp(prefix="gctl-enf-repo-"))
    home = Path(tempfile.mkdtemp(prefix="gctl-enf-home-"))
    subprocess.run(["git", "-C", str(root), "init"], capture_output=True, text=True)
    if all_active:
        # hooks 目錄 + core.hooksPath
        (root / "scripts" / "hooks").mkdir(parents=True)
        for h in ("pre-commit", "pre-push"):
            p = root / "scripts" / "hooks" / h
            p.write_text("#!/bin/sh\nexit 0\n"); p.chmod(0o755)
        subprocess.run(["git", "-C", str(root), "config", "core.hooksPath", "scripts/hooks"], capture_output=True)
        (root / ".github" / "workflows").mkdir(parents=True)
        (root / ".github" / "workflows" / "ci.yml").write_text("name: CI\n")
        # 全域 settings 四 hook 註冊 + ★真的建出目標 .py 檔★(r1 審:註冊≠檔在,active 要兩者都成立)
        chd = home / ".claude"; (chd / "hooks").mkdir(parents=True)
        hooks = {"SessionStart": ["lumos-entry-hook.py", "ci-status-hook.py"],
                 "PreToolUse": ["impact-hook.py"], "Stop": ["check-graph-sync.py"]}
        cfg = {}
        _hook_layer = {"lumos-entry-hook.py": "session-entry-hook",
                       "ci-status-hook.py": "sessionstart-ci-status-hook",
                       "impact-hook.py": "pretooluse-impact-hook",
                       "check-graph-sync.py": "stop-graph-sync-hook",
                       "dispatch-lens-hook.py": "pretooluse-dispatch-lens-hook"}
        for ev, files in hooks.items():
            grp = {"hooks": [{"command": "python3 " + str(chd / "hooks" / f)} for f in files]}
            if ev == "PreToolUse":
                grp["matcher"] = "Edit|Write"
            cfg[ev] = [grp]
            for f in files:
                (chd / "hooks" / f).write_text("# stub\n")   # 目標檔真的存在
        (chd / "settings.json").write_text(_j.dumps({"hooks": cfg}), encoding="utf-8")
    if all_active and with_hook_events:
        # ★三條件裡的第②③條★:同 repo、同版本、近期成功完成的事件。
        # 指紋要對得上實際的 hook 檔——換版之後沒跑過就不該算生效。
        import hashlib as _h, json as _hj, datetime as _hd
        rt = root / "governance" / "runtime"; rt.mkdir(parents=True, exist_ok=True)
        _now = _hd.datetime.now().astimezone().isoformat()
        _lines = []
        for _f, _layer in _hook_layer.items():
            _fp_path = home / ".claude" / "hooks" / _f
            if not _fp_path.exists():
                continue
            _fp = _h.sha256(_fp_path.read_bytes()).hexdigest()[:16]
            _lines.append(_hj.dumps({"ts": _now, "hook": _layer, "kind": "ok",
                                     "repo": str(root.resolve()), "fp": _fp},
                                    ensure_ascii=False))
        (rt / "hook-events.jsonl").write_text("\n".join(_lines) + ("\n" if _lines else ""),
                                              encoding="utf-8")
    return root, home


def t_enforcement_all_active():
    m = _load_lumos_inproc()
    root, home = _enforcement_fixture(all_active=True)
    rows = m.enforcement_status(root=root, home=home)
    by = {r["layer"]: r["status"] for r in rows}
    check("enforcement: 入口 hook active", by.get("session-entry-hook") == "active", str(by))
    check("enforcement: impact hook active", by.get("pretooluse-impact-hook") == "active", str(by))
    check("enforcement: 圖譜同步 hook active", by.get("stop-graph-sync-hook") == "active", str(by))
    check("enforcement: ci-status hook active(r1:第 4 支不漏檢)", by.get("sessionstart-ci-status-hook") == "active", str(by))
    check("enforcement: pre-commit active", by.get("git-pre-commit") == "active", str(by))
    check("enforcement: pre-push active", by.get("git-pre-push") == "active", str(by))
    check("enforcement: python active", by.get("python") == "active", str(by))
    check("enforcement: CI workflow active", by.get("ci-workflow") == "active", str(by))
    check("enforcement: 遠端檢查恆 unknown", by.get("required-status-check") == "unknown", str(by))

    # ★反向對照:判準從「有註冊」升格成「最近真的跑過」★(2026-09-08 #19 S4)。
    # r1 外家否決席判 blocker:只用「有註冊」判不出「現在」有沒有效——
    # hook 今天上午跑過、下午被移除,舊判準照樣顯示 active。
    # 這一段把「最近成功跑過」的證據拿掉,那五列必須從 active 掉下來;
    # ★而且不准掉成 inactive★——那可能只是七天內沒被觸發,講成「沒裝」是另一種假訊號。
    root2, home2 = _enforcement_fixture(all_active=True, with_hook_events=False)
    by2 = {r["layer"]: r["status"] for r in m.enforcement_status(root=root2, home=home2)}
    for _layer in ("session-entry-hook", "pretooluse-impact-hook",
                   "stop-graph-sync-hook", "sessionstart-ci-status-hook"):
        check("★沒有近期成功紀錄 → %s 不准是 active★" % _layer,
              by2.get(_layer) != "active", str(by2))
        check("★而且不准掉成 inactive(那是「沒裝」的意思)★",
              by2.get(_layer) in ("stale", "unknown"), "%s=%s" % (_layer, by2.get(_layer)))
    check("★同一份現場裡,git 那兩道不受 hook 事件影響★(免得改判準時誤傷別列)",
          by2.get("git-pre-push") == "active" and by2.get("git-pre-commit") == "active", str(by2))


