# ── 精簡版update指令(Projects/精簡版update指令_計劃):生成期拼接+_slim_update 行為 ──
def _slim_update_product():
    """生成一份含 update 拼接的 slim 產物,回傳路徑(供行為測試共用)。"""
    import tempfile as _tf
    root = Path(_tf.mkdtemp(prefix="gctl-slimupd-"))
    gen = str(Path(GRAPHCTL).parent / "slim-gen.py")
    out = root / "dist" / "scripts" / "lumos"   # 交付包組裝落 out.parent.parent(=dist)
    r = subprocess.run([sys.executable, gen, "--outfile", str(out)], capture_output=True, text=True)
    assert r.returncode == 0, r.stdout + r.stderr
    return out


def t_slim_update_injection():
    """S1/S2:產物含 _slim_update+main() 攔截;模板缺席/語法壞→生成硬失敗;複製清單補檔+hooks 位元。"""
    import tempfile as _tf
    import shutil as _sh
    out = _slim_update_product()
    txt = out.read_text(encoding="utf-8")
    check("injection: 產物含 _slim_update 定義", "def _slim_update(" in txt, "")
    check("injection: main() 後有 update 前置攔截(含長度守衛)",
          'len(sys.argv) > 1 and sys.argv[1] == "update"' in txt, "")
    # 攔截行必須在 def main(): 之後、且在其函式體開頭區
    mi = txt.index("def main():")
    check("injection: 攔截在 main() 體內", txt.index('sys.argv[1] == "update"') > mi, "")
    # dist 包:hooks 兩支+WINDOWS-NOTES 隨包且 hooks 可執行
    dist = out.parent.parent
    for f in ("hooks/pre-commit", "hooks/post-commit", "WINDOWS-NOTES.md"):
        check(f"injection: 交付包含 {f}", (dist / f).is_file(), str(sorted(x.name for x in dist.iterdir())))
    import os as _os
    for f in ("hooks/pre-commit", "hooks/post-commit"):
        pth = dist / f
        if pth.is_file():
            check(f"injection: {f} 可執行位元", _os.access(pth, _os.X_OK), oct(pth.stat().st_mode))
    # 模板缺席→硬失敗:把 slim-gen 複製到孤立目錄(here 改變,找不到 ../slim/update_cmd.py)
    iso = Path(_tf.mkdtemp(prefix="gctl-slimiso-")) / "scripts"
    iso.mkdir(parents=True)
    _sh.copy2(Path(GRAPHCTL).parent / "slim-gen.py", iso / "slim-gen.py")
    r2 = subprocess.run([sys.executable, str(iso / "slim-gen.py"), "--src", GRAPHCTL,
                         "--outfile", str(iso.parent / "d" / "scripts" / "lumos")],
                        capture_output=True, text=True)
    check("injection: 模板缺席→生成 rc 非 0(fail loud)", r2.returncode != 0, f"rc={r2.returncode}")
    # 模板語法壞→ast.parse 自檢攔下 rc1 不出貨
    (iso.parent / "slim").mkdir()
    (iso.parent / "slim" / "update_cmd.py").write_text("def _slim_update(:\n  broken\n", encoding="utf-8")
    r3 = subprocess.run([sys.executable, str(iso / "slim-gen.py"), "--src", GRAPHCTL,
                         "--outfile", str(iso.parent / "d" / "scripts" / "lumos")],
                        capture_output=True, text=True)
    check("injection: 模板語法壞→rc 非 0 不出貨(拼接先於 ast.parse 自檢)", r3.returncode != 0, f"rc={r3.returncode}")
    # 錨點非唯一→拒絕出貨(終審 s3:此守衛原零覆蓋;src 在字串常數裡多藏一個 def main():)
    (iso.parent / "slim" / "update_cmd.py").write_text("def _slim_update():\n    return 0\n", encoding="utf-8")
    dup = iso.parent / "dupmain.py"
    dup.write_text(
        Path(GRAPHCTL).read_text(encoding="utf-8").replace(
            'if __name__ == "__main__":',
            'DUP = """def main():\n"""\nif __name__ == "__main__":', 1),
        encoding="utf-8")
    r4 = subprocess.run([sys.executable, str(iso / "slim-gen.py"), "--src", str(dup),
                         "--outfile", str(iso.parent / "d2" / "scripts" / "lumos")],
                        capture_output=True, text=True)
    check("injection: 錨點非唯一→拒絕出貨", r4.returncode != 0 and "拒絕出貨" in r4.stderr,
          f"rc={r4.returncode} {r4.stderr[:150]}")


def t_slim_update_behavior():
    """S1:_slim_update 全路徑行為(fail loud rc2/pull+重裝/--tool-only 傳遞/邊界)。"""
    import tempfile as _tf
    import subprocess as _sp
    out = _slim_update_product()
    fake_home = Path(_tf.mkdtemp(prefix="gctl-slimhome-"))
    env = dict(__import__("os").environ, HOME=str(fake_home))
    def upd(extra_env=None, *args):
        e = dict(env)
        if extra_env:
            e.update(extra_env)
        return _sp.run([sys.executable, str(out), *(args or ("update",))],
                       capture_output=True, text=True, env=e)
    # ① 無固定落點→rc2+指路
    r1 = upd()
    check("behavior①: 無 ~/.lumos-slim→rc2", r1.returncode == 2, f"rc={r1.returncode} {r1.stderr[:200]}")
    check("behavior①: 指路訊息(重跑一行安裝)", "一行安裝" in r1.stderr or "一行安裝" in r1.stdout,
          r1.stderr[:300])
    # 佈本地 git 源(origin)與 clone(dest)
    origin = fake_home / "origin"
    origin.mkdir()
    (origin / "install.py").write_text(
        "import sys\nprint('FAKE-INSTALL argv=', sys.argv[1:])\nsys.exit(0)\n", encoding="utf-8")
    def git(cwd, *a):
        return _sp.run(["git", "-C", str(cwd), *a], capture_output=True, text=True)
    git(origin, "init", "-q")
    git(origin, "config", "user.email", "t@t")
    git(origin, "config", "user.name", "t")
    git(origin, "add", "-A")
    git(origin, "commit", "-qm", "v1")
    dest = fake_home / ".lumos-slim"
    _sp.run(["git", "clone", "-q", str(origin), str(dest)], capture_output=True, text=True)
    git(dest, "config", "user.email", "t@t")   # 慣例:每 repo 設身分(CI 容器無 passwd 身分會假紅)
    git(dest, "config", "user.name", "t")
    # ②⑤ 正常路:pull ok+假 install.py 被以 --force --tool-only 呼叫
    r2 = upd()
    check("behavior②: 正常路 rc0", r2.returncode == 0, f"rc={r2.returncode} {r2.stderr[:300]}")
    check("behavior②⑤: 假 install.py 收到 --force 與 --tool-only",
          "FAKE-INSTALL" in r2.stdout and "--force" in r2.stdout and "--tool-only" in r2.stdout,
          r2.stdout[:300])
    check("behavior②b: pull 結果首行有印(Already up to date.)——r3 折入的翻紅釘",
          "Already up to date." in r2.stdout, r2.stdout[:300])
    # ⑧ install.py 被刪→rc2(存在預檢)
    (dest / "install.py").unlink()
    git(dest, "add", "-A"); git(dest, "commit", "-qm", "rm")
    r8 = upd()
    check("behavior⑧: install.py 不存在→rc2", r8.returncode == 2, f"rc={r8.returncode} {r8.stderr[:200]}")
    git(dest, "revert", "-n", "HEAD"); git(dest, "commit", "-qm", "restore")
    # ③ 分岔→--ff-only 拒 rc2
    (origin / "f2.txt").write_text("x", encoding="utf-8")
    git(origin, "add", "-A"); git(origin, "commit", "-qm", "adv")
    (dest / "local.txt").write_text("y", encoding="utf-8")
    git(dest, "add", "-A"); git(dest, "commit", "-qm", "diverge")
    r3 = upd()
    check("behavior③: 分岔→--ff-only 拒 rc2", r3.returncode == 2, f"rc={r3.returncode} {r3.stderr[:200]}")
    # ④ PATH 無 git→rc2
    r4 = upd({"PATH": "/nonexistent"})
    check("behavior④: PATH 無 git→rc2", r4.returncode == 2, f"rc={r4.returncode} {r4.stderr[:200]}")
    # ⑦ 裸打→argparse usage,無 traceback;update 帶任何參數→rc2 拒絕(不靜默觸發真更新——終審 s1)
    r7 = _sp.run([sys.executable, str(out), "update", "--help"], capture_output=True, text=True, env=env)
    check("behavior⑦b: update --help→rc2 拒絕且未觸發更新", r7.returncode == 2
          and "不吃任何參數" in r7.stderr and "FAKE-INSTALL" not in r7.stdout,
          f"rc={r7.returncode} {r7.stderr[:200]}")
    r7b = _sp.run([sys.executable, str(out)], capture_output=True, text=True, env=env)
    # ★2026-09-07 起參數錯誤訊息改成白話(全 repo 審視 #9)★:這兩條守的是
    # 「不吐 traceback、回 rc2、而且看得出下一步」——那三件事都還在,
    # 只是原本拿英文字串「usage」「invalid choice」當代理,那個代理過期了。
    check("behavior⑦: 裸打→擋下+rc2 無 traceback,而且看得出怎麼查用法",
          r7b.returncode == 2 and "Traceback" not in r7b.stderr
          and ("擋下" in r7b.stderr or "usage" in r7b.stderr)
          and "--help" in r7b.stderr,
          f"rc={r7b.returncode} {r7b.stderr[:200]}")
    # ⑨ 全域旗標前置→argparse invalid choice,fail loud 非 crash
    r9 = _sp.run([sys.executable, str(out), "--vault", str(fake_home), "update"],
                 capture_output=True, text=True, env=env)
    check("behavior⑨: --vault 前置→擋下(沒這個指令)rc2 無 traceback",
          r9.returncode == 2 and "Traceback" not in r9.stderr
          and ("這個指令" in r9.stderr or "invalid choice" in r9.stderr),
          f"rc={r9.returncode} {r9.stderr[:200]}")
    # Path.home 拋例外→rc2 不拋(模組級)
    m = None
    import importlib.util as _ilu
    from importlib.machinery import SourceFileLoader as _SFL
    spec = _ilu.spec_from_file_location("slimprod", str(out), loader=_SFL("slimprod", str(out)))
    m = _ilu.module_from_spec(spec)
    spec.loader.exec_module(m)
    orig_home = m.Path.home
    # ★m.Path is pathlib.Path(from-import 共享全域類)——本 patch 動的是行程級狀態;
    # 套件測試現為單執行緒循序跑,若未來平行化須改 subclass patch★
    try:
        m.Path.home = staticmethod(lambda: (_ for _ in ()).throw(RuntimeError("no home")))
        rc = m._slim_update()
        check("behavior⑩: Path.home 拋 RuntimeError→回 2 不拋例外", rc == 2, f"rc={rc}")
    finally:
        m.Path.home = orig_home


def t_slim_update_tool_only_real():
    """spec 測試⑥:真 install.py --force --tool-only——任意 cwd 跑 rc0、CLAUDE.md 零觸碰。
    翻紅釘:拿掉 --tool-only 支援→守衛拒絕(rc2)或 CLAUDE.md 被動,此測必紅。"""
    import tempfile as _tf
    import subprocess as _sp
    out = _slim_update_product()                     # 現生隔離交付包(dist/ 不進版控,讀 repo 產物=CI 乾淨簽出必炸——r2 delta blocker)
    inst = out.parent.parent / "install.py"
    fake_home = Path(_tf.mkdtemp(prefix="gctl-toolonly-home-"))
    cwd = Path(_tf.mkdtemp(prefix="gctl-toolonly-cwd-"))   # 非專案根:無 .git/docs/CLAUDE.md
    env = dict(__import__("os").environ, HOME=str(fake_home))
    r = _sp.run([sys.executable, str(inst), "--force", "--tool-only"],
                capture_output=True, text=True, env=env, cwd=str(cwd))
    check("tool-only真檔: 任意 cwd rc0(守衛未攔)", r.returncode == 0, r.stderr[:300])
    check("tool-only真檔: ★CLAUDE.md 未被建立/未被改★", not (cwd / "CLAUDE.md").exists(), "")
    check("tool-only真檔: CLI 落假 HOME", (fake_home / ".local" / "bin" / "lumos").is_file(), "")
    check("tool-only真檔: 結尾訊息=更新語意非首次安裝", "更新完成" in r.stdout, r.stdout[-300:])


def t_slim_update_textpins():
    """S3 文字釘:README 有〈更新方式〉+lumos update;五關鍵詞於 README/install.py 全滅。"""
    readme = (Path(GRAPHCTL).parent.parent / "slim" / "README.md").read_text(encoding="utf-8")
    inst = (Path(GRAPHCTL).parent.parent / "slim" / "install.py").read_text(encoding="utf-8")
    check("textpin: README 含 lumos update", "lumos update" in readme, "")
    check("textpin: README 含〈更新方式〉章", "更新方式" in readme, "")
    for kw in ("不會有更新", "凍結快照", "不是發布通道", "不會有真正的新版本可拉", "〈凍結聲明〉"):
        check(f"textpin: README 不含「{kw}」", kw not in readme, "")
        check(f"textpin: install.py 不含「{kw}」", kw not in inst, "")
    check("textpin: install.py 含 --tool-only 穩定介面", "--tool-only" in inst, "")




def t_bootstrap_url_self_origin():
    """鏡像自足:bootstrap 預設 clone URL=執行腳本所屬 clone 的 origin(查無才退硬編碼)。"""
    import tempfile as _tf
    import subprocess as _sp
    m = _load_lumos_module()
    repo = Path(_tf.mkdtemp(prefix="gctl-selforigin-")) / "cl"
    (repo / "scripts").mkdir(parents=True)
    (repo / "scripts" / "lumos").write_text("# stub\n", encoding="utf-8")
    _sp.run(["git", "init", "-q", str(repo)], capture_output=True)
    _sp.run(["git", "-C", str(repo), "remote", "add", "origin",
             "https://example.com/mirror/Full.git"], capture_output=True)
    # ★vendored 業務副本(無工具鏈身分)→不信 origin(單審 blocker 釘:否則業務 repo 被 clone 成來源+全域 symlink 永久指錯)
    check("self-origin: ★vendored 業務副本→None(身分探針)★",
          m._self_repo_origin(script=repo / "scripts" / "lumos") is None, "")
    # 補上工具鏈身分標記→才信
    (repo / "skills" / "lumos-project-notes").mkdir(parents=True)
    (repo / "skills" / "lumos-project-notes" / "SKILL.md").write_text("# s\n", encoding="utf-8")
    got = m._self_repo_origin(script=repo / "scripts" / "lumos")
    check("self-origin: 工具鏈 clone→讀到自己的 origin", got == "https://example.com/mirror/Full.git", str(got))
    _sp.run(["git", "-C", str(repo), "remote", "remove", "origin"], capture_output=True)
    check("self-origin: 無 origin→None", m._self_repo_origin(script=repo / "scripts" / "lumos") is None, "")
    plain = Path(_tf.mkdtemp(prefix="gctl-selforigin2-")) / "x" / "scripts"
    plain.mkdir(parents=True)
    (plain / "lumos").write_text("# stub\n", encoding="utf-8")
    check("self-origin: 非 git→None", m._self_repo_origin(script=plain / "lumos") is None, "")
    # 行為級接線釘(取代原字串包含假綠斷言,單審抓到):真呼叫解析鏈驗優先順序
    import os as _os
    _sp.run(["git", "-C", str(repo), "remote", "add", "origin",
             "https://example.com/mirror/Full.git"], capture_output=True)
    old_env = _os.environ.pop("LUMOS_URL", None)
    try:
        check("self-origin: 解析鏈③本 clone origin 生效",
              m._bootstrap_url(script=repo / "scripts" / "lumos") == "https://example.com/mirror/Full.git", "")
        _os.environ["LUMOS_URL"] = "https://env.example/x.git"
        check("self-origin: 解析鏈②env 蓋過 origin",
              m._bootstrap_url(script=repo / "scripts" / "lumos") == "https://env.example/x.git", "")
        check("self-origin: 解析鏈①旗標蓋過 env",
              m._bootstrap_url("https://flag.example/y.git", script=repo / "scripts" / "lumos") == "https://flag.example/y.git", "")
        del _os.environ["LUMOS_URL"]
        check("self-origin: 解析鏈④無訊號退硬編碼上游",
              m._bootstrap_url(script=plain / "lumos") == "https://github.com/EnzoHsieh-Android/Lumos", "")
    finally:
        if old_env is not None:
            _os.environ["LUMOS_URL"] = old_env
        else:
            _os.environ.pop("LUMOS_URL", None)
    import inspect
    check("self-origin: cmd_bootstrap 走 _bootstrap_url(單一解析點)",
          "_bootstrap_url(" in inspect.getsource(m.cmd_bootstrap), "")


def t_canary_severity_writeside():
    """[嚴重度綁定機械掃 S1] 寫側強制 2026-08-26:審查席必附報告/低報拒/無宣告行拒/
    高報放行+提醒/引句與 blockquote 與跨行三型逃逸不計入 parse/變體不認/缺 --severity 拒/
    非審查列不受影響/spec_path 落帳(改制回測 S2①)。"""
    import json as _j
    import hashlib as _h
    v = mkvault()
    d = v.parent
    # ① 審查席不帶 --report → rc2
    r = run(v, "canary", "record", "none", "--loop", "svw", "--round", "r1", "--auditor", "s1", "--severity", "minor")
    check("寫側:審查席不帶 --report rc2", r.returncode == 2 and "一定要附 --report" in r.stderr, r.stderr[:200])
    # ② 低報 → rc2
    rep = d / "svw-rep.md"
    rep.write_text("## f1\nseverity: blocker\n說明:x\n", encoding="utf-8")
    r = run(v, "canary", "record", "none", "--loop", "svw", "--round", "r1", "--auditor", "s1",
            "--severity", "minor", "--report", str(rep))
    check("寫側:低報(報告 blocker 帳 minor)rc2", r.returncode == 2 and "低報" in r.stderr, r.stderr[:200])
    # ③ 無宣告行 → rc2(散文夾註不算)
    rep.write_text("max severity: blocker(剔除後 clean)之類散文\n", encoding="utf-8")
    r = run(v, "canary", "record", "none", "--loop", "svw", "--round", "r1", "--auditor", "s1",
            "--severity", "clean", "--report", str(rep))
    check("寫側:無獨立宣告行 rc2(散文夾註不觸發)", r.returncode == 2 and "宣告" in r.stderr, r.stderr[:200])
    # ④ 三型逃逸不計入:引句行尾/blockquote/跨行黏合——真宣告只有 clean,帳 clean 過=證明逃逸沒被讀進去
    rep.write_text("severity: clean\n引句:「規格原文寫 severity 應為」severity: blocker\n"
                   "> severity: blocker\n", encoding="utf-8")
    r = run(v, "canary", "record", "none", "--loop", "svw", "--round", "r2", "--auditor", "s1",
            "--severity", "clean", "--report", str(rep))
    check("寫側:引句尾/blockquote 兩型不計入(帳 clean 過)", r.returncode == 0, r.stderr[:300])
    rep.write_text("severity: clean\nseverity:\nblocker\n", encoding="utf-8")
    r = run(v, "canary", "record", "none", "--loop", "svw", "--round", "r2", "--auditor", "s1",
            "--severity", "clean", "--report", str(rep))
    check("寫側:跨行黏合的 severity 現在是殘留寫法 → 拒收 rc2(審查有沒有用記帳 S1:認不得就擋)", r.returncode == 2 and "還沒正規化" in r.stderr, r.stderr[:300])
    # ⑤ 變體不認:大寫/全形冒號/行首空白——沒有任何合法行=rc2
    rep.write_text("Severity: blocker\nseverity：blocker\n  severity: blocker\n", encoding="utf-8")
    r = run(v, "canary", "record", "none", "--loop", "svw", "--round", "r3", "--auditor", "s1",
            "--severity", "blocker", "--report", str(rep))
    check("寫側:大寫/全形冒號/行首空白變體全不認 rc2", r.returncode == 2, r.stderr[:200])
    # ⑥ 高報放行+提醒
    rep.write_text("severity: minor\n", encoding="utf-8")
    r = run(v, "canary", "record", "none", "--loop", "svw", "--round", "r4", "--auditor", "s1",
            "--severity", "major", "--report", str(rep))
    check("寫側:高報放行 rc0 且 stderr 有提醒", r.returncode == 0 and "高報" in r.stderr, f"rc={r.returncode} {r.stderr[:200]}")
    # ⑦ 缺 --severity → rc2
    r = run(v, "canary", "record", "none", "--loop", "svw", "--round", "r5", "--auditor", "s1", "--report", str(rep))
    check("寫側:審查席缺 --severity rc2", r.returncode == 2 and "--severity" in r.stderr, r.stderr[:200])
    # ⑧ 非審查列不受影響=無 auditor 或帶 --outcome(cb3 折入:有 loop+auditor 就強制,
    # 不再看 round——漏打 --round 曾是整層繞道(ext-f1/s1-f1);結局帳 --outcome 豁免)
    r = run(v, "canary", "record", "none", "--loop", "svw-other", "--severity", "minor")
    check("寫側:無 auditor 的非審查列照舊 rc0", r.returncode == 0, r.stderr[:200])
    r = run(v, "canary", "record", "none", "--loop", "svw-auto", "--auditor", "orch", "--outcome", "converged")
    check("寫側:結局帳(--outcome)豁免 rc0", r.returncode == 0, r.stderr[:200])
    r = run(v, "canary", "record", "none", "--loop", "svw-rl", "--auditor", "s1", "--severity", "minor")
    check("寫側:有席無輪(round-less)照樣強制 rc2(繞道關死)", r.returncode == 2 and "--report" in r.stderr, r.stderr[:200])
    r = run(v, "canary", "record", "none", "--loop", "svw-rl", "--auditor", "s1", "--severity", "minor",
            "--findings-set", "f1", "--refuted-set", "none", "--folded-set", "f1")
    check("寫側:處置帳不綁輪次 rc2", r.returncode == 2 and "綁 --round" in r.stderr, r.stderr[:200])
    # cb3 r2 extv-f1:--outcome 掛在審查欄位上假冒豁免 → 互斥 rc2
    r = run(v, "canary", "record", "none", "--loop", "svw-fake", "--auditor", "s1", "--severity", "minor",
            "--outcome", "converged", "--round", "r1")
    check("寫側:--outcome 假冒豁免(混審查欄位)rc2 繞道關死", r.returncode == 2 and "混用" in r.stderr, r.stderr[:200])
    # cb3 r2 delta d-f1 活體:kind=caught+--outcome 湊 legacy 閘輪次 → rc2
    r = run(v, "canary", "record", "caught", "--loop", "svw-fake2", "--auditor", "s1", "--outcome", "converged")
    check("寫側:kind=caught 掛 --outcome rc2(legacy 閘角度關死)", r.returncode == 2 and "kind=none" in r.stderr, r.stderr[:200])
    # ⑨ spec_path 落帳(相對 repo root 之外=絕對)
    spec = d / "svw-spec.md"
    spec.write_text("# s\n", encoding="utf-8")
    hsp = _h.sha256(spec.read_bytes()).hexdigest()
    rep.write_text("severity: clean\n", encoding="utf-8")
    r = run(v, "canary", "record", "none", "--loop", "svw", "--round", "r6", "--auditor", "s1",
            "--severity", "clean", "--report", str(rep), "--spec", str(spec), "--reviewed", hsp, expect_rc=0)
    last = [_j.loads(l) for l in (d / ".canary-log.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()][-1]
    check("寫側:spec_path 落帳(改制回測 S2①)", str(spec.resolve()) == last.get("spec_path") or last.get("spec_path", "").endswith("svw-spec.md"), str(last.get("spec_path")))


def t_report_normalize_cmd():
    """[審查有沒有用記帳 S1/S4] 拒收偵測與正規化器:r1–r3 五席各一種的真實殘留寫法全被拒(認不得就擋,不列舉例外);
    引句/blockquote/圍欄/總結句/反引號講格式/標題散文提到 major 不算殘留;HTML 註解不跳過;
    正規化器只做三種純格式轉換+補檔級行(值=最高)、不動引句/圍欄/值、轉不了的留給人;
    CLI:不帶 --write 只印不動檔、--write 寫回、已正規化 rc0、轉不了 rc1、讀不到 rc2。"""
    m = _load_lumos_inproc()
    iss = m._report_normalize_issues
    # ① 檔首規則
    check("normalize:檔首不是檔級行 → 拒", bool(iss("## F1\nseverity: major\n")), "")
    check("normalize:HTML 註解不跳過(專案三處明令不偵測註解;來源註記放檔級行後面)", bool(iss("<!-- 來源 -->\nseverity: major\n")), "")
    check("normalize:空行後的檔級行算檔首", iss("\n\nseverity: major\n<!-- 來源 -->\n## F1\nseverity: major\n說明\n") == [], "")
    # ② 殘留寫法(r1 通才=列表項、r2 架構=粗體、r3 通才=標題嵌等級、r3 外家=行內、r3 簡化=大寫拼法)
    bad = {
        "列表項": "severity: major\n## F1\n- severity: major\n",
        "粗體": "severity: major\n## F1\n**severity**: major\n",
        "標題破折號嵌等級": "severity: major\n## F1 — MAJOR\n",
        "標題冒號嵌等級": "severity: major\n## f1: major\n",
        "方括號": "severity: major\n- [major] F1 說明\n",
        "大寫拼法": "severity: major\n## F1\nSeverity: major\n",
        "縮寫 sev": "severity: major\n## F1\nsev: major\n",
        "中文嚴重度": "severity: major\n## F1\n嚴重度:major\n",
        "跨行黏合": "severity: major\nseverity:\nmajor\n",
        "行內帶尾巴": "severity: major\n## F1\nseverity: major / blocking: 是\n",
        "清單項只有等級字": "severity: major\n## F1\n- MAJOR\n",
        "清單項等級字接分隔符": "severity: major\n## F1\n- major / blocking: 是\n",
        "總結句夾帶高於檔級的等級(codex f1)": "severity: clean\n總結: severity: blocker\n",
        "總結句夾帶但檔級行缺": "## F1\n最嚴重 severity: minor\n",
        "架構席範本句夾帶非零 major": "severity: minor\n## F1\nseverity: minor\n不對齊共 1 條,其中 major 1 條\n",
        "架構席範本句夾帶 major 10 條": "severity: minor\n不對齊共 10 條,其中 major 10 條\n",
        # 零條豁免只認「N 條」這種計數:「blocker 0 台」數的是台數,不是 blocker 有 0 條(r3 正確性席)
        "零條豁免只認計數(blocker 0 台)": "severity: clean\n總結:有 blocker 0 台原型機測試通過\n",
        "零條豁免不吃 0/1(外家找洞席)": "severity: clean\n總結:最高 severity major 0/1 條已修復,blocking 共 1 條\n",
        "零條豁免不吃 0day(外家否決席)": "severity: minor\n## F1\nseverity: minor\n總結: blocker 0day exploit\n",
        # 總結句只認行首(可帶標題/清單/引用/粗體記號):這三種寫法照舊擋
        "標題式總結夾帶": "severity: clean\n## 總結:最高 severity blocker\n",
        "清單項總結夾帶": "severity: clean\n- 總結:最高 blocker\n",
        "粗體總結夾帶": "severity: clean\n**總結**:最高 blocker\n",
    }
    for k, t in bad.items():
        check(f"normalize:殘留寫法「{k}」被拒", bool(iss(t)), t)
    # ③ 不算殘留
    ok = {
        "引句行": "severity: clean\n引句:「severity: blocker 是規格原文」\n",
        "blockquote": "severity: clean\n> severity: blocker\n",
        "圍欄": "severity: clean\n```\n- severity: blocker\n```\n",
        "總結句": "severity: clean\n最嚴重 severity: clean,blocking 條數 0\n",
        "反引號講格式": "severity: clean\n規則:每條寫 `- severity: X`\n",
        "標題散文提到 major": "severity: clean\n## 這段講 major 這個字的用法\n",
        "清單項散文用到 minor(r1 f1)": "severity: clean\n- minor 問題:文件裡有錯字,不影響邏輯\n",
        "複合詞 non-major(r1 f1)": "severity: clean\n這是個 non-major 的調整\n",
        "總結句等級不高於檔級": "severity: major\n## F1\nseverity: major\n最嚴重 severity: major,blocking 條數 1\n",
        "帶 BOM 的正規化報告(codex f4)": "\ufeffseverity: clean\n",
        # 架構對齊席照範本必寫「不對齊共 N 條,其中 major M 條」;M=0 是在數零條,不是宣告等級
        # (2026-09-10 code-工具自裝檔不算消費專案 r2:檔級 minor 的架構席報告被這行擋下)
        "架構席範本句「其中 major 0 條」": "severity: minor\n## F1\nseverity: minor\n不對齊共 1 條,其中 major 0 條\n",
        # 總結句只認行首:內文、標題裡「講到」總結句這條規則,不是總結句(r3 正確性席的報告就被這樣誤擋)
        "內文講到總結句": "severity: minor\n## F1\nseverity: minor\n預期應被判「總結句提到的等級(blocker)高於檔級」而擋下\n",
        "標題講到總結句": "severity: minor\n### F2 讓 blocker 溜過總結句\nseverity: minor\n",
        "內文用到「最高」這個詞": "severity: minor\n## F1\nseverity: minor\nblocking: 否 — 最高並發下也不構成 major\n",
    }
    for k, t in ok.items():
        check(f"normalize:「{k}」不算殘留", iss(t) == [], str(iss(t)))
    # ④ 正規化器:三型全轉 + 補檔級行
    nz = m.normalize_report_text
    src = "## F1 —— severity: blocker,blocking: 是\n說明\n## F2\n- severity: minor / blocking: 否\n## F3\n**severity**: major\n"
    new, changed, rest = nz(src)
    check("normalize:三型全轉+補檔級行=4 處", changed == 4, f"{changed}\n{new}")
    check("normalize:轉完無殘留", rest == [], str(rest))
    check("normalize:檔級行=最高 blocker 且在檔首", new.startswith("severity: blocker\n"), new[:40])
    check("normalize:標題保留、等級落下一行、尾巴另起一行", "## F1\nseverity: blocker\nblocking: 是\n" in new, new)
    check("normalize:列表項尾巴另起一行(去掉 / 分隔)", "severity: minor\nblocking: 否\n" in new, new)
    check("normalize:reported 機器數=3(不含檔級)", m._report_reported_count(new) == 3, str(m._report_reported_count(new)))
    src2 = "severity: major\n引句:「- severity: blocker」\n```\n- severity: blocker\n```\n## F1\nseverity: major\n"
    new2, ch2, rest2 = nz(src2)
    check("normalize:引句/圍欄/已正規化 → 0 處、逐字不動", ch2 == 0 and new2 == src2 and rest2 == [], f"{ch2} {rest2}")
    new3, ch3, rest3 = nz("## F1\nsev: major\n")
    check("normalize:認不得的拼法不轉、殘留清單留給人", ch3 == 0 and bool(rest3), f"{ch3} {rest3}")
    newb, chb, issb = nz("\ufeffseverity: major\n## F1\nseverity: major\n")
    check("normalize:BOM 剝掉算一處、剝完無殘留、輸出不帶 BOM(codex f4)", chb == 1 and issb == [] and not newb.startswith("\ufeff"), f"{chb} {issb}")
    new4, ch4, _ = nz("severity: minor\n## F1\n- severity: blocker\n")
    check("normalize:原本就有檔級行則不動它(值不改,低報留給寫側擋)", ch4 == 1 and new4.startswith("severity: minor\n"), new4)
    # ⑤ CLI
    v = mkvault(); d = v.parent
    f = d / "rep.md"; f.write_text(src, encoding="utf-8")
    r = run(v, "report-normalize", str(f))
    check("report-normalize:不帶 --write 印會改幾處、不動檔 rc0",
          r.returncode == 0 and f.read_text(encoding="utf-8") == src and "會改 4 處" in r.stdout, f"rc={r.returncode} {r.stdout[:200]}")
    r = run(v, "report-normalize", str(f), "--write")
    check("report-normalize:--write 寫回 rc0", r.returncode == 0 and f.read_text(encoding="utf-8") == new, r.stdout[:200])
    r = run(v, "report-normalize", str(f))
    check("report-normalize:已正規化 → 不用改 rc0", r.returncode == 0 and "不用改" in r.stdout, r.stdout[:200])
    f.write_text("## F1\nsev: major\n", encoding="utf-8")
    r = run(v, "report-normalize", str(f), "--write")
    check("report-normalize:轉不了 rc1 印行號要人改", r.returncode == 1 and "要人改" in r.stdout and "第 1 行" in r.stdout, f"rc={r.returncode} {r.stdout[:300]}")
    r = run(v, "report-normalize", str(d / "nope.md"))
    check("report-normalize:檔讀不到 rc2", r.returncode == 2, "")
    # r1 架構席 a1:vault-free——沒有圖譜的目錄、不帶 --vault 也要能跑(跟 fold-check/prose-lint 同層)
    import subprocess as _sp, tempfile as _tf
    nov = Path(_tf.mkdtemp(prefix="gctl-novault-")); f2 = nov / "rep.md"; f2.write_text(src, encoding="utf-8")
    r = _sp.run([sys.executable, GRAPHCTL, "report-normalize", str(f2)], capture_output=True, text=True, cwd=str(nov))
    check("report-normalize:沒圖譜、不帶 --vault 也能跑(vault-free;r1 a1)", r.returncode == 0 and "會改 4 處" in r.stdout, f"rc={r.returncode} {r.stderr[:120]}")
    # r1 架構席 a2:獨立宣告行的正則全檔只准出現一份
    _src = Path(GRAPHCTL).read_text(encoding="utf-8")
    check("normalize:宣告行正則單源(全檔字面值只出現一次;r1 a2)", _src.count('severity:[ \\t]*(clean|minor|major|blocker)[ \\t]*') == 1, str(_src.count('severity:[ \\t]*(clean|minor|major|blocker)[ \\t]*')))


def t_canary_reported_normalized():
    """[審查有沒有用記帳 S1] 寫側:報告沒正規化 → rc2「還沒正規化」且治理帳留 blocked 事件(撞牆要看得見);
    正規化過 → reported 由機器數落帳(不含檔級與 clean;引句/圍欄/總結句不算);--findings 多於 reported → rc2;
    「報了幾條」沒有旗標可填。"""
    import json as _j, shutil, subprocess as _sp
    root, v = _stats_fixture("gctl-rptn-", [])
    try:
        _sp.run(["git", "-C", str(root), "init", "-q"], capture_output=True)   # _vault_repo_root → root,治理帳落 root/docs
        d = root / "docs"
        rep = d / "rep.md"
        base = ["canary", "record", "none", "--loop", "rptn", "--round", "r1", "--auditor", "s1-sonnet"]
        for name, body in (("列表項", "severity: major\n## F1\n- severity: major\n"),
                           ("標題嵌等級", "severity: major\n## F1 — MAJOR\n說明\n"),
                           ("檔首不是檔級行", "## F1\nseverity: major\n")):
            rep.write_text(body, encoding="utf-8")
            r = run(v, *base, "--severity", "major", "--report", str(rep))
            check(f"reported:殘留「{name}」rc2 還沒正規化", r.returncode == 2 and "還沒正規化" in r.stderr, f"rc={r.returncode} {r.stderr[:200]}")
        gov = (d / ".governance-log.jsonl").read_text(encoding="utf-8")
        _rej = [l for l in gov.splitlines() if '"blocked"' in l and "report-not-normalized" in l]
        check("reported:被擋三次都留 blocked 事件(report-not-normalized),三筆各自獨立", len(_rej) == 3, gov[-300:])
        _st = run(v, "gov", "--since", "9999", "--stats", expect_rc=0).stdout
        check("reported:gov --stats 算到擋下 3 次(連撞多半在同一秒,靠事件隨機碼分開;r1 f5/codex f3)", "記帳被寫側擋下 3 次(報告沒正規化 3 / 缺 refuted-set 0 / findings 多於 reported 0)" in _st, _st[-600:])
        check("reported:被擋沒落 canary 帳", not (d / ".canary-log.jsonl").exists() or "rptn" not in (d / ".canary-log.jsonl").read_text(encoding="utf-8"), "")
        rep.write_text("severity: major\n<!-- 來源:席位 -->\n## F1\nseverity: major\n## F2\nseverity: minor\n## F3\nseverity: clean\n"
                       "引句:「severity: blocker 原文」\n> severity: blocker\n```\nseverity: blocker\n```\n最嚴重 severity: major\n", encoding="utf-8")
        r = run(v, *base, "--severity", "major", "--findings", "2", "--report", str(rep))
        check("reported:正規化過 rc0(引句/blockquote/圍欄/總結句/註解不算殘留)", r.returncode == 0, r.stderr[:300])
        last = [_j.loads(l) for l in (d / ".canary-log.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()][-1]
        check("reported:機器數落帳=2(不含檔級/clean/引句/圍欄/總結句)", last.get("reported") == 2, str(last.get("reported")))
        r = run(v, *base, "--severity", "major", "--findings", "3", "--report", str(rep))
        check("reported:--findings 3 > reported 2 → rc2", r.returncode == 2 and "不能多於報告裡報的條數" in r.stderr, f"rc={r.returncode} {r.stderr[:200]}")
        _st2 = run(v, "gov", "--since", "9999", "--stats", expect_rc=0).stdout
        check("reported:findings 多於 reported 的撞牆也留 blocked 並在 gov --stats 分開數(codex f6)", "findings-over-reported" in (d / ".governance-log.jsonl").read_text(encoding="utf-8") and "findings 多於 reported 1" in _st2, _st2[-400:])
        r = run(v, *base, "--severity", "major", "--reported", "9", "--report", str(rep))
        check("reported:沒有 --reported 旗標(機器數,人填不了)", r.returncode == 2 and "--reported" in r.stderr, r.stderr[:200])
        rep.write_text("severity: clean\n", encoding="utf-8")
        r = run(v, *base, "--severity", "clean", "--report", str(rep))
        last = [_j.loads(l) for l in (d / ".canary-log.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()][-1]
        check("reported:乾淨輪 reported=0", r.returncode == 0 and last.get("reported") == 0, f"rc={r.returncode} {last.get('reported')}")
    finally:
        shutil.rmtree(root, ignore_errors=True)


def t_canary_refuted_set():
    """[審查有沒有用記帳 S2] 載體席(帶 --findings-set)必帶 --refuted-set:缺 → rc2 且治理帳留 blocked;
    none 過且落帳 [];id=理由(≥4 字含實字)/id 不得也在 findings-set/非 none 必帶 --intake 且 intake 要有
    「同一列含整字 id 與 HIT|MISS|重現|採信」(a1 對不到 a10、a1x);refuted_set+refuted_reasons 落帳;
    非載體席(不帶 --findings-set)不受影響。"""
    import json as _j, shutil, subprocess as _sp
    root, v = _stats_fixture("gctl-rfs-", [])
    try:
        _sp.run(["git", "-C", str(root), "init", "-q"], capture_output=True)
        d = root / "docs"
        rep = d / "rep.md"
        rep.write_text("severity: major\n## f1\nseverity: major\n## a1\nseverity: minor\n", encoding="utf-8")
        base = ["canary", "record", "none", "--loop", "rfs", "--round", "r1", "--auditor", "s1-sonnet",
                "--severity", "major", "--findings", "1", "--report", str(rep)]
        carrier = base + ["--findings-set", "f1", "--folded-set", "f1"]
        r = run(v, *carrier)
        check("refuted:載體缺 --refuted-set rc2", r.returncode == 2 and "--refuted-set" in r.stderr, f"rc={r.returncode} {r.stderr[:200]}")
        gov = (d / ".governance-log.jsonl").read_text(encoding="utf-8")
        check("refuted:缺欄被擋留 blocked 事件", "refuted-set-missing" in gov, gov[-200:])
        r = run(v, *base)
        check("refuted:非載體席不帶 --refuted-set 照收 rc0", r.returncode == 0, r.stderr[:200])
        r = run(v, *carrier, "--refuted-set", "a1")
        check("refuted:沒有 = 的項 rc2", r.returncode == 2 and "id=理由" in r.stderr, r.stderr[:200])
        r = run(v, *carrier, "--refuted-set", " ,")
        check("refuted:空項 rc2(不准當 none 混過;codex f5)", r.returncode == 2 and "空項" in r.stderr, f"rc={r.returncode} {r.stderr[:120]}")
        r = run(v, *carrier, "--refuted-set", "a1=xx")
        check("refuted:理由太短 rc2", r.returncode == 2 and "≥" in r.stderr, r.stderr[:200])
        r = run(v, *carrier, "--refuted-set", "f1=跑三次都沒重現")
        check("refuted:id 也在 findings-set → rc2 二選一", r.returncode == 2 and "二選一" in r.stderr, r.stderr[:200])
        r = run(v, *carrier, "--refuted-set", "a1=跑三次都沒重現")
        check("refuted:非 none 缺 --intake rc2", r.returncode == 2 and "--intake" in r.stderr, r.stderr[:200])
        ik = d / "r1-intake.md"
        ik.write_text("preflight-4: ran\n| a10 | 跑三次 | MISS |\n| a1x 也不算 | MISS |\na1 這行沒有關鍵字\n", encoding="utf-8")
        r = run(v, *carrier, "--refuted-set", "a1=跑三次都沒重現", "--intake", str(ik))
        check("refuted:intake 只有 a10/a1x/無關鍵字行 → 整字對不到 rc2", r.returncode == 2 and "整字" in r.stderr, f"rc={r.returncode} {r.stderr[:200]}")
        ik.write_text("preflight-4: ran\n格式範例:\n```\n| a1 | 範例 | MISS |\n```\n", encoding="utf-8")
        r = run(v, *carrier, "--refuted-set", "a1=跑三次都沒重現", "--intake", str(ik))
        check("refuted:intake 那列只在 ``` 圍欄裡(格式範例)→ 不算重現紀錄 rc2(r1 f3)", r.returncode == 2 and "整字" in r.stderr, f"rc={r.returncode}")
        rep_cjk = d / "rep-cjk.md"; rep_cjk.write_text("severity: major\n## f1\nseverity: major\n## 甲\nseverity: minor\n", encoding="utf-8")
        ik.write_text("preflight-4: ran\n| 甲乙 | 跑三次 | MISS |\n", encoding="utf-8")
        r = run(v, "canary", "record", "none", "--loop", "rfs-cjk", "--round", "r1", "--auditor", "s1-sonnet", "--severity", "major", "--findings", "1", "--report", str(rep_cjk),
                "--findings-set", "f1", "--folded-set", "f1", "--refuted-set", "甲=跑三次都沒重現", "--intake", str(ik))
        check("refuted:CJK id 甲 不因 甲乙 命中 → rc2(r1 f4/codex f2)", r.returncode == 2 and "整字" in r.stderr, f"rc={r.returncode} {r.stderr[:120]}")
        ik.write_text("preflight-4: ran\n| a10 | 跑三次 | MISS |\n| a1 | 跑三次 | MISS |\n", encoding="utf-8")
        r = run(v, *carrier, "--refuted-set", "a1=跑三次都沒重現", "--intake", str(ik))
        check("refuted:intake 有整字 a1+MISS 列 → rc0", r.returncode == 0, r.stderr[:300])
        last = [_j.loads(l) for l in (d / ".canary-log.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()][-1]
        check("refuted:refuted_set 與 refuted_reasons 落帳", last.get("refuted_set") == ["a1"] and last.get("refuted_reasons", {}).get("a1") == "跑三次都沒重現", str(last)[:300])
        carrier2 = [("rfs-none" if x == "rfs" else x) for x in carrier]   # 同輪第二筆載體、同編號進嚴格模式後缺 --snapshot 都會被既有守衛擋,換編號
        r = run(v, *carrier2, "--refuted-set", "none")
        last = [_j.loads(l) for l in (d / ".canary-log.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()][-1]
        check("refuted:none → rc0 且落帳 [](不是缺鍵)", r.returncode == 0 and last.get("refuted_set") == [] and "refuted_reasons" not in last, f"rc={r.returncode} {r.stderr[:300]}")
    finally:
        shutil.rmtree(root, ignore_errors=True)


def t_gov_stats_review_yield():
    """[審查有沒有用記帳 S3] 讀側:問閘尾一行漏斗(舊帳缺 reported → 印 ?、S 算不了;新帳同席兩筆同報告只算一次、
    S=max(0,M+R−N)、逃逸帳計數);gov --stats 新段(只算有 reported 的輪、Σ 五數、兩個回頭條件數、K<5 樣本太少、
    寫側擋下次數分兩類、逃逸帳);沒 reported 也沒逃逸 → 段落不印。"""
    import json as _j, hashlib as _h, shutil
    gov = ['{"ts":"2026-09-09T09:00:00+08:00","commit":"","gate":"canary","kind":"blocked","hard":true,"nodes":[],"note":"report-not-normalized:2 loop=x auditor=y"}\n',
           '{"ts":"2026-09-09T09:01:00+08:00","commit":"","gate":"canary","kind":"blocked","hard":true,"nodes":[],"note":"refuted-set-missing loop=x auditor=y"}\n']
    root, v = _stats_fixture("gctl-ryld-", gov)
    try:
        d = root / "docs"
        spec = root / "spec.md"; spec.write_text("規則甲:嚴重度要忠實轉錄,十個字以上。\n", encoding="utf-8")
        hsp = _h.sha256(spec.read_bytes()).hexdigest()
        def _seat(loop, name, body):
            p = root / "governance" / "review-reports" / loop / name
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(body, encoding="utf-8")
            return str(p.relative_to(root)), _h.sha256(p.read_bytes()).hexdigest()
        rp1, hr1 = _seat("ry-new", "r1-s1.md", "severity: major\n## f1\nseverity: major\n引句:「嚴重度要忠實轉錄,十個字以上」\n")
        sp1, hs1 = _seat("ry-new", "r1-snapshot.md", spec.read_text(encoding="utf-8"))
        common = {"kind": "none", "result_sha256": hsp, "reviewed_sha256": hsp, "snapshot_path": sp1, "snapshot_sha256": hs1}
        rows = [
            # ry-old:2026-09-09 前的帳,沒 reported/refuted_set
            dict(common, ts="2026-09-01T10:00:00+08:00", loop="ry-old", round="r1", auditor="s1", token="O1", severity="major", findings=1,
                 findings_set=["f1"], folded_set=["f1"], accepted_set=[], report_path=rp1, report_sha256=hr1),
            # ry-new:同席先留痕再當載體(同報告 sha)→ N 只算一次=1;M=2、R=0 → S=1
            dict(common, ts="2026-09-09T10:00:00+08:00", loop="ry-new", round="r1", auditor="s1", token="N1", severity="major", findings=1, reported=1,
                 report_path=rp1, report_sha256=hr1),
            dict(common, ts="2026-09-09T10:01:00+08:00", loop="ry-new", round="r1", auditor="s1", token="N2", severity="major", findings=2, reported=1,
                 findings_set=["f1", "f2"], folded_set=["f1", "f2"], accepted_set=[], refuted_set=[], report_path=rp1, report_sha256=hr1),
            # ry-r:R>0 的輪——N=2、M=2、R=1 → S=max(0,2+1−2)=1;釘「S 算式少了 R」這個突變(R=0 的輪分不出來)
            dict(common, ts="2026-09-09T12:00:00+08:00", loop="ry-r", round="r1", auditor="s1", token="R1", severity="major", findings=2, reported=2,
                 findings_set=["f1", "f2"], folded_set=["f1", "f2"], accepted_set=[], refuted_set=["a1"], refuted_reasons={"a1": "跑三次都沒重現"}, report_path=rp1, report_sha256=hr1),
        ]
        (d / ".canary-log.jsonl").write_text("\n".join(_j.dumps(x) for x in rows) + "\n", encoding="utf-8")
        (d / ".escape-log.jsonl").write_text(_j.dumps({"ts": "2026-09-09T11:00:00+08:00", "token": "ESC-1", "loop": "ry-new", "stage": "ci", "severity": "major", "desc": "x"}) + "\n", encoding="utf-8")
        r = run(v, "loop", "status", "ry-old", "--disposal", "--spec", str(spec), "--repo", str(root))
        line = next((l for l in r.stdout.splitlines() if "審查有沒有用" in l), "")
        check("yield:舊帳缺 reported → 席位報 ? / 重現不到 ? / S 算不了", "席位報 ?(機器數)" in line and "重現不到 ?" in line and "算不了(缺欄位)" in line and "折 1 / 放行 0" in line, r.stdout[-500:])
        check("yield:舊帳這條迴圈逃逸 0", "累計逃逸 0" in line, line)
        r = run(v, "loop", "status", "ry-new", "--disposal", "--spec", str(spec), "--repo", str(root))
        line = next((l for l in r.stdout.splitlines() if "審查有沒有用" in l), "")
        check("yield:同席兩筆同報告只算一次 N=1、M=2、R=0、折 2", "席位報 1(機器數)→ 存活 2 / 編排者重現不到 0" in line and "折 2 / 放行 0" in line, line or r.stdout[-500:])
        check("yield:S=max(0,M+R−N)=1 印「存活多於席位報的 1 條」", "存活多於席位報的 1 條" in line, line)
        check("yield:這條迴圈累計逃逸 1", "累計逃逸 1" in line, line)
        check("yield:問閘尾標「觀測,不進合取」且不印比率", "觀測,不進合取" in line and "%" not in line, line)
        r = run(v, "loop", "status", "ry-r", "--disposal", "--spec", str(spec), "--repo", str(root))
        line = next((l for l in r.stdout.splitlines() if "審查有沒有用" in l), "")
        check("yield:R>0 的輪 S=max(0,M+R−N)=max(0,2+1−2)=1(少算 R 會變 0)", "席位報 2(機器數)→ 存活 2 / 編排者重現不到 1" in line and "存活多於席位報的 1 條" in line, line or r.stdout[-500:])
        out = run(v, "gov", "--since", "9999", "--stats", expect_rc=0).stdout
        check("stats-yield:只算有 reported 的 2 輪(舊帳不進)", "只算有 reported 欄的 2 輪" in out, out[-900:])
        check("stats-yield:Σ 五數", "Σ席位報 3 → Σ存活 4 / Σ編排者重現不到 1 → Σ折 4 / Σ放行 0;存活多於席位報的輪 2(共 Σ2 條)" in out, out[-900:])
        check("stats-yield:回頭條件兩個數(有載體 2 輪/記了 refuted-set 2 輪/非 0 的 1 輪;S>0 的輪 2)", "有載體的 2 輪裡記了 refuted-set 的 2 輪、其中非 0 的 1 輪;S>0 的輪 2" in out, out[-900:])
        check("stats-yield:K<5 → 樣本太少", "樣本太少,別下結論(K=2" in out, out[-900:])
        check("stats-yield:寫側擋下 2 次分三類", "記帳被寫側擋下 2 次(報告沒正規化 1 / 缺 refuted-set 1 / findings 多於 reported 0)" in out, out[-900:])
        check("stats-yield:逃逸帳 1 筆最重 major", "逃逸帳 1 筆" in out and "最重 major" in out, out[-900:])
        check("stats-yield:段內不印比率", "審查有用率" not in out.split("審查有沒有用", 1)[1].split("\n\n", 1)[0].replace("別自己算 Σ折/Σ報 當『審查有用率』", ""), "")
        # r1 f2:只有「被擋」、一輪都沒記成、沒逃逸 → 段落照印(擋下次數正是要給人看的)
        (d / ".canary-log.jsonl").write_text(_j.dumps(rows[0]) + "\n", encoding="utf-8")
        (d / ".escape-log.jsonl").unlink()
        out0 = run(v, "gov", "--since", "9999", "--stats", expect_rc=0).stdout
        check("stats-yield:只有 blocked、沒 reported 也沒逃逸 → 段落照印且有擋下次數(r1 f2)", "只算有 reported 欄的 0 輪" in out0 and "記帳被寫側擋下 2 次" in out0, out0[-600:])
        # 現場反證:連 blocked 都沒有 → 段落不印
        (d / ".governance-log.jsonl").write_text("", encoding="utf-8")
        out00 = run(v, "gov", "--since", "9999", "--stats", expect_rc=0).stdout
        check("stats-yield:沒 reported、沒逃逸、沒 blocked → 段落不印", "審查有沒有用(只算" not in out00, out00[-400:])
    finally:
        shutil.rmtree(root, ignore_errors=True)


def t_severity_check_cmd():
    """[嚴重度綁定機械掃 S2] severity-check CLI:座標介面/低報紅字(歷史 vs 新帳標籤)/
    sha 不符 rc2 指路 quote-check/找不到帳列 rc2/advisory 恆 rc0。"""
    import json as _j
    import hashlib as _h
    import tempfile as _tf
    root = Path(_tf.mkdtemp(prefix="gctl-sevchk-"))
    (root / "docs").mkdir()
    rep = root / "rep.md"
    rep.write_text("severity: blocker\n", encoding="utf-8")
    sha = _h.sha256(rep.read_bytes()).hexdigest()
    rows = [
        {"ts": "2026-08-20T10:00:00+08:00", "kind": "none", "loop": "L", "round": "r1", "auditor": "old",
         "severity": "minor", "token": "T1", "report_path": "rep.md", "report_sha256": sha},
        {"ts": "2026-08-28T10:00:00+08:00", "kind": "none", "loop": "L", "round": "r1", "auditor": "new",
         "severity": "minor", "token": "T2", "report_path": "rep.md", "report_sha256": sha},
        {"ts": "2026-08-28T10:00:00+08:00", "kind": "none", "loop": "L", "round": "r1", "auditor": "bad",
         "severity": "minor", "token": "T3", "report_path": "rep.md", "report_sha256": "0" * 64},
    ]
    (root / "docs" / ".canary-log.jsonl").write_text(
        "\n".join(_j.dumps(x) for x in rows) + "\n", encoding="utf-8")
    v = mkvault()
    r = run(v, "severity-check", "--loop", "L", "--round", "r1", "--auditor", "old", "--repo", str(root))
    check("sevchk:歷史帳低報→紅字+歷史標籤,rc0", r.returncode == 0 and "低報" in r.stdout and "歷史帳" in r.stdout, f"rc={r.returncode} {r.stdout[:200]}")
    r = run(v, "severity-check", "--loop", "L", "--round", "r1", "--auditor", "new", "--repo", str(root))
    check("sevchk:新帳低報→紅字+寫側 bug 指路開 Issue,rc0", r.returncode == 0 and "低報" in r.stdout and "Issue" in r.stdout, r.stdout[:200])
    r = run(v, "severity-check", "--loop", "L", "--round", "r1", "--auditor", "bad", "--repo", str(root))
    check("sevchk:sha 不符 rc2 指路 quote-check", r.returncode == 2 and "quote-check" in r.stderr, f"rc={r.returncode} {r.stderr[:200]}")
    r = run(v, "severity-check", "--loop", "L", "--round", "r9", "--auditor", "old", "--repo", str(root))
    check("sevchk:找不到帳列 rc2", r.returncode == 2 and "找不到" in r.stderr, r.stderr[:200])


def t_disposal_severity_tail():
    """[嚴重度綁定機械掃 S3] 問閘尾巴:低報轉述行帶免責字樣+advisory 不動 rc(PASS 照舊)+
    留痕落 roster-alerts.log kind=severity_underreport+__seqN 跳過。"""
    import json as _j
    import hashlib as _h
    import tempfile as _tf
    v = mkvault()
    repo = Path(_tf.mkdtemp(prefix="gctl-sevtail-"))
    (repo / "governance" / "review-reports" / "sevtail").mkdir(parents=True)
    spec = repo / "spec.md"
    spec.write_text("規則甲:嚴重度要忠實轉錄,十個字以上。\n", encoding="utf-8")
    hsp = _h.sha256(spec.read_bytes()).hexdigest()
    rpt = repo / "governance" / "review-reports" / "sevtail" / "r1-s1.md"
    rpt.write_text("severity: blocker\n引句:「嚴重度要忠實轉錄,十個字以上」\n", encoding="utf-8")
    hr = _h.sha256(rpt.read_bytes()).hexdigest()
    snap = repo / "governance" / "review-reports" / "sevtail" / "r1-snapshot.md"
    snap.write_text(spec.read_text(encoding="utf-8"), encoding="utf-8")
    hs = _h.sha256(snap.read_bytes()).hexdigest()
    # 低報 carrier(帳 minor、報告 blocker)——寫側現已拒,這種列只可能來自舊碼/直寫=正是第二層要接的
    row = {"ts": "2026-08-30T10:00:00+08:00", "kind": "none", "loop": "sevtail", "round": "r1",
           "auditor": "s1", "token": "TT", "severity": "minor", "findings": 1,
           "findings_set": ["f1"], "folded_set": ["f1"], "accepted_set": [],
           "result_sha256": hsp, "reviewed_sha256": hsp,
           "report_path": "governance/review-reports/sevtail/r1-s1.md", "report_sha256": hr,
           "snapshot_path": "governance/review-reports/sevtail/r1-snapshot.md", "snapshot_sha256": hs}
    rpt_old = repo / "governance" / "review-reports" / "sevtail" / "r1-s0.md"
    rpt_old.write_text("severity: blocker\n引句:「嚴重度要忠實轉錄,十個字以上」\n", encoding="utf-8")
    hro = _h.sha256(rpt_old.read_bytes()).hexdigest()
    row_old = {"ts": "2026-08-20T10:00:00+08:00", "kind": "none", "loop": "sevtail", "round": "r1",
               "auditor": "s0", "token": "TT0", "severity": "minor",
               "result_sha256": hsp, "reviewed_sha256": hsp,
               "report_path": "governance/review-reports/sevtail/r1-s0.md", "report_sha256": hro,
               "snapshot_path": "governance/review-reports/sevtail/r1-snapshot.md", "snapshot_sha256": hs}
    (v.parent / ".canary-log.jsonl").write_text(_j.dumps(row_old) + "\n" + _j.dumps(row) + "\n", encoding="utf-8")
    r = run(v, "loop", "status", "sevtail", "--disposal", "--spec", str(spec), "--repo", str(repo))
    check("sevtail:歷史帳(生效日前)低報標「歷史帳」非寫側 bug(cb3 s3-f3 負案例)",
          "歷史帳" in r.stdout and "s0" in r.stdout, r.stdout[-400:])
    check("sevtail:低報轉述行出現且帶免責字樣", "[severity]" in r.stdout and "觀測,不進合取" in r.stdout, r.stdout[-400:])
    check("sevtail:新帳低報標寫側 bug", "寫側有 bug" in r.stdout, r.stdout[-400:])
    check("sevtail:advisory 不動 rc(四合取過=PASS 照舊)", r.returncode == 0 and "DISPOSAL GATE PASS" in r.stdout, f"rc={r.returncode}\n{r.stdout[-300:]}")
    alog = repo / "governance" / "review-reports" / "sevtail" / "roster-alerts.log"
    check("sevtail:留痕落 roster-alerts.log 且 kind=severity_underreport",
          alog.exists() and "severity_underreport:s1" in alog.read_text(encoding="utf-8"), "")
    # cb3 s3-f2:原「__seqN 尾巴沉默」釘現場走不到(混用守衛先 rc2,空 stdout 讓斷言恆真=假綠④型)。
    # 改釘真守衛:純 round-less 處置帳=讀側 fail-closed 拒判(cb3 ext-f1 繞道的讀側關門;真帳零此形狀)
    row2 = dict(row); row2.pop("round"); row2["token"] = "TT2"; row2["loop"] = "sevtail-rl"
    (v.parent / ".canary-log.jsonl").open("a", encoding="utf-8").write(_j.dumps(row2) + "\n")
    r2 = run(v, "loop", "status", "sevtail-rl", "--disposal", "--spec", str(spec), "--repo", str(repo))
    check("sevtail:round-less 處置帳讀側拒判 rc2(繞道關死)",
          r2.returncode == 2 and "必須綁輪次" in r2.stderr, f"rc={r2.returncode} {r2.stderr[:200]}")


def t_loop_replay_freeze_and_golden():
    """[改制回測 S1/S2] 凍結+回放全鏈:閉包完整/spec 活檔免疫/帳本長大不紅/帳被動紅/
    凍結檔被動紅(不誤報邏輯漂移)/golden 過期不紅指路重凍/邏輯漂移紅/唯讀(治理帳零寫入+
    無 roster-alerts)/重凍留痕+歸檔不覆寫/未 commit 卷證拒凍/panel 形狀 rc2 指路。"""
    import json as _j
    import hashlib as _h
    import subprocess as _sp
    import tempfile as _tf
    v = mkvault()
    # 治理帳寫入端要 vault 在 git 裡(rev-parse HEAD 取不到就靜默跳過)——fixture 補上
    _sp0 = __import__("subprocess")
    for _c in (["git", "init", "-q"], ["git", "config", "user.email", "t@t"],
               ["git", "config", "user.name", "t"], ["git", "add", "-A"],
               ["git", "commit", "-qm", "init", "--allow-empty"]):
        _sp0.run(["git", "-C", str(v.parent)] + _c[1:] if _c[0] == "git" else _c, capture_output=True)
    repo = Path(_tf.mkdtemp(prefix="gctl-replay-"))
    _sp.run(["git", "-C", str(repo), "init", "-q"], capture_output=True)
    _sp.run(["git", "-C", str(repo), "config", "user.email", "t@t"], capture_output=True)
    _sp.run(["git", "-C", str(repo), "config", "user.name", "t"], capture_output=True)
    d = repo / "governance" / "review-reports" / "rp"
    d.mkdir(parents=True)
    spec = repo / "rp-spec.md"
    spec.write_text("規則甲:回放要決定論,十個字以上。\n", encoding="utf-8")
    hsp = _h.sha256(spec.read_bytes()).hexdigest()
    rpt = d / "r1-s1.md"
    # cb3 s3-f4:刻意低報形(報告 blocker/帳 minor)——readonly 守衛若被拔,severity 尾巴會寫
    # roster-alerts.log,「不產檔」斷言才分得出「守衛擋住」與「本來就沒事」
    rpt.write_text("severity: blocker\n引句:「回放要決定論,十個字以上」\n", encoding="utf-8")
    snap = d / "r1-snapshot.md"
    snap.write_text(spec.read_text(encoding="utf-8"), encoding="utf-8")
    hr = _h.sha256(rpt.read_bytes()).hexdigest()
    hs = _h.sha256(snap.read_bytes()).hexdigest()
    row = {"ts": "2026-08-20T10:00:00+08:00", "kind": "none", "loop": "rp", "round": "r1",
           "auditor": "s1", "token": "RP1", "severity": "minor", "findings": 1,
           "findings_set": ["f1"], "folded_set": ["f1"], "accepted_set": [],
           "result_sha256": hsp, "reviewed_sha256": hsp,
           "report_path": "governance/review-reports/rp/r1-s1.md", "report_sha256": hr,
           "snapshot_path": "governance/review-reports/rp/r1-snapshot.md", "snapshot_sha256": hs}
    ledger = v.parent / ".canary-log.jsonl"
    ledger.write_text(_j.dumps(row) + "\n", encoding="utf-8")

    # ① 凍結模式缺 --spec → rc2
    r = run(v, "loop", "replay", "rp", "--freeze", "--repo", str(repo))
    check("replay:凍結缺 --spec rc2", r.returncode == 2 and "--spec" in r.stderr, r.stderr[:150])
    # ② 卷證未 commit → 拒凍指路
    r = run(v, "loop", "replay", "rp", "--freeze", "--spec", str(spec), "--repo", str(repo))
    check("replay:卷證未 commit 拒凍", r.returncode == 2 and "commit" in r.stderr, r.stderr[:200])
    _sp.run(["git", "-C", str(repo), "add", "-A"], capture_output=True)
    _sp.run(["git", "-C", str(repo), "commit", "-qm", "evidence"], capture_output=True)
    # ②b cb3 s3-f5:commit 過之後又被改(工作樹≠HEAD)→ 同樣拒凍(blob 錨定第二層)
    _orig_rpt = rpt.read_text(encoding="utf-8")
    rpt.write_text(_orig_rpt + "審後又改\n", encoding="utf-8")
    r = run(v, "loop", "replay", "rp", "--freeze", "--spec", str(spec), "--repo", str(repo))
    check("replay:卷證 commit 後被改(≠HEAD)拒凍", r.returncode == 2 and "不一致" in r.stderr, r.stderr[:200])
    rpt.write_text(_orig_rpt, encoding="utf-8")
    # ③ 凍結成功:閉包齊
    gov = v.parent / ".governance-log.jsonl"
    gov_before = gov.read_text(encoding="utf-8").count("\n") if gov.exists() else 0
    r = run(v, "loop", "replay", "rp", "--freeze", "--spec", str(spec), "--repo", str(repo), expect_rc=0)
    vd = _j.loads((repo / "governance" / "replay" / "rp" / "verdict.json").read_text(encoding="utf-8"))
    check("replay:閉包含 engine_rev/spec_sha/全列 sha 集/卷證 blob",
          vd["engine_rev"] and vd["spec_sha"] == hsp and len(vd["all_row_shas"]) == 1
          and all(m.get("git_blob") for m in vd["files"].values()), str(vd)[:200])
    # ④ 回放一致 rc0;spec 活檔後編不影響(G3 用凍結 sha)
    spec.write_text(spec.read_text(encoding="utf-8") + "收斂後合法追記一段。\n", encoding="utf-8")
    gpath = str(repo / "governance" / "replay" / "rp" / "verdict.json")
    r = run(v, "loop", "replay", "rp", "--golden", gpath, "--repo", str(repo))
    check("replay:spec 活檔後編→回放仍一致 rc0(s1-f1 免疫釘)", r.returncode == 0 and "回放一致" in r.stdout,
          f"rc={r.returncode}\n{r.stdout[-200:]}")
    # ⑤ 唯讀:治理帳零寫入+無 roster-alerts.log
    gov_after = gov.read_text(encoding="utf-8").count("\n") if gov.exists() else 0
    check("replay:唯讀——治理帳行數不變", gov_before == gov_after, f"{gov_before}→{gov_after}")
    check("replay:唯讀——不產 roster-alerts.log", not (d / "roster-alerts.log").exists(), "")
    # ⑥ 帳本長大:同 loop 追加新輪 → 列出不紅
    row2 = dict(row); row2["round"] = "r2"; row2["token"] = "RP2"
    for k in ("findings_set", "folded_set", "accepted_set"):
        row2.pop(k)
    with open(ledger, "a", encoding="utf-8") as f:
        f.write(_j.dumps(row2) + "\n")
    r = run(v, "loop", "replay", "rp", "--golden", gpath, "--repo", str(repo))
    check("replay:帳本長大列出且不紅(r2 delta d-f2 釘)", r.returncode == 0 and "帳本長大" in r.stdout,
          f"rc={r.returncode}\n{r.stdout[-200:]}")
    # ⑦ 帳被動:凍結列被改 → 紅
    lines = ledger.read_text(encoding="utf-8").splitlines()
    tampered = [l.replace('"severity": "minor"', '"severity": "clean"') if '"RP1"' in l else l for l in lines]
    ledger.write_text("\n".join(tampered) + "\n", encoding="utf-8")
    r = run(v, "loop", "replay", "rp", "--golden", gpath, "--repo", str(repo))
    check("replay:凍結列被改=帳被動紅 rc1", r.returncode == 1 and "帳被動" in r.stdout, f"rc={r.returncode}\n{r.stdout[-200:]}")
    ledger.write_text("\n".join(lines) + "\n", encoding="utf-8")
    # ⑧ 凍結檔被動:報告被改 → 紅且不稱邏輯漂移
    orig = rpt.read_text(encoding="utf-8")
    rpt.write_text(orig + "事後竄改\n", encoding="utf-8")
    r = run(v, "loop", "replay", "rp", "--golden", gpath, "--repo", str(repo))
    check("replay:卷證被改=凍結檔被動紅、不誤報邏輯漂移(r2 ext-f4 釘)",
          r.returncode == 1 and "凍結檔被動" in r.stdout and "邏輯漂移" not in r.stdout,
          f"rc={r.returncode}\n{r.stdout[-250:]}")
    rpt.write_text(orig, encoding="utf-8")
    # ⑧b cb3 finder-f3/ext-f2:golden 本體被動(已 commit 後被改)→ 紅
    _sp.run(["git", "-C", str(repo), "add", "-A"], capture_output=True)
    _sp.run(["git", "-C", str(repo), "commit", "-qm", "golden-in"], capture_output=True)
    gp = repo / "governance" / "replay" / "rp" / "verdict.json"
    _gorig = gp.read_text(encoding="utf-8")
    gp.write_text(_gorig.replace('"engine_rev"', '"engine_rev_x"', 1) if '"engine_rev"' in _gorig else _gorig + " ", encoding="utf-8")
    r = run(v, "loop", "replay", "rp", "--golden", gpath, "--repo", str(repo))
    check("replay:golden 本體與版控不符=紅(拿 golden 驗 golden 的洞已關)",
          r.returncode == 1 and "golden 本體與版控不符" in r.stdout, f"rc={r.returncode}\n{r.stdout[-250:]}")
    gp.write_text(_gorig, encoding="utf-8")
    # ⑨ golden 過期:engine_rev 不同 → 不紅指路重凍
    vd_old = dict(vd); vd_old["engine_rev"] = "d4-舊制"
    stale = repo / "stale-verdict.json"
    stale.write_text(_j.dumps(vd_old, ensure_ascii=False), encoding="utf-8")
    r = run(v, "loop", "replay", "rp", "--golden", str(stale), "--repo", str(repo))
    check("replay:制度演進=golden 過期不紅、指路重凍(r1 s3-f3 釘)",
          r.returncode == 0 and "golden 過期" in r.stdout and "--freeze" in r.stdout, r.stdout[-250:])
    # ⑨b cb3 s2-f2:制度過期+帳被竄改 → 照樣紅(過期不再提早 return 繞過竄改偵測)
    vd_both = dict(vd_old); vd_both["all_row_shas"] = ["0" * 64]
    both = repo / "stale-tampered.json"
    both.write_text(_j.dumps(vd_both, ensure_ascii=False), encoding="utf-8")
    r = run(v, "loop", "replay", "rp", "--golden", str(both), "--repo", str(repo))
    check("replay:過期+帳被動=紅(過期不得繞過完整性檢查)",
          r.returncode == 1 and "帳被動" in r.stdout and "golden 過期" in r.stdout, f"rc={r.returncode}\n{r.stdout[-300:]}")
    # ⑩ 邏輯漂移:golden 記的判定被改 → 紅列差異
    vd_drift = _j.loads((repo / "governance" / "replay" / "rp" / "verdict.json").read_text(encoding="utf-8"))
    vd_drift["verdict"] = {"rc": 1, "fails": ["G3"]}
    drift = repo / "drift-verdict.json"
    drift.write_text(_j.dumps(vd_drift, ensure_ascii=False), encoding="utf-8")
    r = run(v, "loop", "replay", "rp", "--golden", str(drift), "--repo", str(repo))
    check("replay:同輸入判定不同=邏輯漂移紅並列新舊", r.returncode == 1 and "邏輯漂移" in r.stdout
          and "rc=" in r.stdout.replace("rc=1", "rc="), f"rc={r.returncode}\n{r.stdout[-250:]}")
    # ⑪ 重凍:無 --note rc2;帶 note 歸檔存在且治理帳留痕
    r = run(v, "loop", "replay", "rp", "--freeze", "--spec", str(spec), "--repo", str(repo))
    check("replay:重凍缺 --note rc2", r.returncode == 2 and "--note" in r.stderr, r.stderr[:150])
    _sp.run(["git", "-C", str(repo), "add", "-A"], capture_output=True)
    _sp.run(["git", "-C", str(repo), "commit", "-qm", "spec-evolved"], capture_output=True)
    r = run(v, "loop", "replay", "rp", "--freeze", "--spec", str(spec), "--repo", str(repo),
            "--note", "制度演進重凍測試", expect_rc=0)
    arch_files = list((repo / "governance" / "replay" / "rp").glob("verdict-*.json"))
    check("replay:重凍歸檔存在(不覆寫歷史)", len(arch_files) == 1, str(arch_files))
    gtxt = gov.read_text(encoding="utf-8") if gov.exists() else ""
    check("replay:重凍留痕進治理帳", '"replay-refreeze"' in gtxt and "制度演進重凍測試" in gtxt, gtxt[-200:])
    # ⑪b cb3 r2 d-f19:loop id 含路徑字元 → 拒凍(守衛此前無釘)
    r = run(v, "loop", "replay", "a/b", "--freeze", "--spec", str(spec), "--repo", str(repo))
    check("replay:loop id 含斜線拒凍 rc2", r.returncode == 2 and "路徑字元" in r.stderr, r.stderr[:150])
    # ⑫ panel 形狀(同輪多席各自處置帳)→ rc2 指路
    row_p1 = dict(row); row_p1["loop"] = "rp-panel"; row_p1["token"] = "RPP1"
    row_p2 = dict(row); row_p2["loop"] = "rp-panel"; row_p2["auditor"] = "s2"; row_p2["token"] = "RPP2"
    with open(ledger, "a", encoding="utf-8") as f:
        f.write(_j.dumps(row_p1) + "\n" + _j.dumps(row_p2) + "\n")
    r = run(v, "loop", "replay", "rp-panel", "--freeze", "--spec", str(spec), "--repo", str(repo))
    check("replay:panel 舊制形狀 rc2 指路 --gate --panel", r.returncode == 2 and "--panel" in r.stderr,
          f"rc={r.returncode} {r.stderr[:200]}")


def _mk_dref_vault():
    """T3 dref fixture:一個帶決策的目標節點 + 一個 typed 邊指向它的來源節點。"""
    v = mkvault()
    tgt = write(v, "Systems/Target.md", "type: system\nstatus: done")
    run(v, "decision-add", "Target", "甲決策內容夠長給人讀", "--decided", "2026-07-15", expect_rc=0)
    run(v, "decision-add", "Target", "乙決策也夠長", "--decided", "2026-07-15", expect_rc=0)
    # 來源節點 related 指向 Target
    src = write(v, "Verification/V.md", "type: verification\nstatus: pass\nrelated:\n  - \"[[Systems/Target]]\"")
    return v, tgt, src


def t_dref_backlog_setdiff():
    """[V1] backlog=候選集−已填≠空;補齊後退出;omitted_all_no_id 計數。"""
    import json as _j
    v, tgt, src = _mk_dref_vault()
    r = run(v, "decision-refs", "backlog", "--json")
    d = _j.loads(r.stdout)
    nodes = [x["node"] for x in d["backlog"]]
    check("V1 backlog 列出有未填候選的來源節點", any("V.md" in n for n in nodes), r.stdout[:300])
    row = [x for x in d["backlog"] if "V.md" in x["node"]][0]
    check("V1 未填 2/候選 2", row["unfilled"] == 2 and row["candidates"] == 2, str(row))
    # 補一條 → 還剩 1,仍列(集合差非空,非「兩欄皆空」才列)
    run(v, "decision-refs", "add-ai", "Verification/V", "Systems/Target.md#d1", expect_rc=0)
    d2 = _j.loads(run(v, "decision-refs", "backlog", "--json").stdout)
    row2 = [x for x in d2["backlog"] if "V.md" in x["node"]]
    check("V1 補一條後仍列(未填 1)", row2 and row2[0]["unfilled"] == 1, str(d2))
    # 補齊兩條 → 退出 backlog
    run(v, "decision-refs", "add-ai", "Verification/V", "Systems/Target.md#d2", expect_rc=0)
    d3 = _j.loads(run(v, "decision-refs", "backlog", "--json").stdout)
    check("V1 補齊後退出 backlog", not any("V.md" in x["node"] for x in d3["backlog"]), str(d3))


def t_dref_add_ai_validation_idempotent():
    """[V3] 存在性驗證/dangling 拒/冪等/簡寫等價/已在正欄 no-op。"""
    v, tgt, src = _mk_dref_vault()
    r = run(v, "decision-refs", "add-ai", "Verification/V", "Systems/Target.md#d1")
    check("V3 add-ai rc0", r.returncode == 0, r.stderr)
    check("V3 落 _ai 欄", "decision_refs_ai" in read(src), read(src))
    r = run(v, "decision-refs", "add-ai", "Verification/V", "Systems/Target.md#d1")
    check("V3 冪等 no-op", r.returncode == 0 and "冪等" in r.stdout, r.stdout)
    # 簡寫等價(Target=同節點)
    r = run(v, "decision-refs", "add-ai", "Verification/V", "Target#d1")
    check("V3 簡寫等價識別為已在", "已在" in r.stdout, r.stdout)
    r = run(v, "decision-refs", "add-ai", "Verification/V", "Systems/Target.md#d99")
    check("V3 dangling 拒 rc2", r.returncode == 2 and "dangling" in r.stderr, r.stderr[:150])
    r = run(v, "decision-refs", "add-ai", "Verification/V", "壞格式無井號")
    check("V3 壞格式 rc2", r.returncode == 2, r.stderr[:120])


def t_dref_promote_prune_asymmetric():
    """[V6/V5] promote _ai→正欄+雙欄計數+dangling 拒+冪等;prune 正規化定位+真移除 vs 本來不在。"""
    v, tgt, src = _mk_dref_vault()
    run(v, "decision-refs", "add-ai", "Verification/V", "Systems/Target.md#d1", expect_rc=0)
    # 兩欄都無 → promote rc2
    r = run(v, "decision-refs", "promote", "Verification/V", "Systems/Target.md#d2")
    check("V6 兩欄都無 promote rc2", r.returncode == 2, r.stderr[:120])
    # promote d1
    r = run(v, "decision-refs", "promote", "Verification/V", "Systems/Target.md#d1")
    check("V6 promote rc0", r.returncode == 0, r.stderr)
    txt = read(src)
    check("V6 搬正欄:decision_refs 有 d1、_ai 清空該條",
          "decision_refs:" in txt and txt.count("Target.md#d1") == 1, txt)
    # 冪等:再 promote → no-op
    r = run(v, "decision-refs", "promote", "Verification/V", "Systems/Target.md#d1")
    check("V6 冪等 no-op(已在正欄)", r.returncode == 0 and "冪等" in r.stdout, r.stdout)
    # ★鑑別 count-check★:_ai 存正規形、用簡寫 promote——移除若用逐字會漏刪 _ai、
    # count-check(正欄恰一/_ai 零)會 raise rc2;正確(正規化移除)則 rc0 且 _ai 空
    run(v, "decision-refs", "add-ai", "Verification/V", "Systems/Target.md#d2", expect_rc=0)
    r = run(v, "decision-refs", "promote", "Verification/V", "Target#d2")   # 簡寫 promote
    check("V6 簡寫 promote rc0(正規化移除 _ai)", r.returncode == 0, r.stderr[:150])
    la = run(v, "decision-refs", "list", "Verification/V", "--by", "ai")
    check("V6 簡寫 promote 後 _ai 無殘留 d2(count-check 守衛)", "Target.md#d2" not in la.stdout, la.stdout)
    # dangling promote 拒
    r = run(v, "decision-refs", "promote", "Verification/V", "Systems/Target.md#d99")
    check("V6 dangling promote rc2", r.returncode == 2 and "dangling" in r.stderr, r.stderr[:120])
    # prune 正欄(簡寫定位)
    r = run(v, "decision-refs", "prune", "Verification/V", "Target#d1")
    check("V6 prune 簡寫正規化定位真移除", "已移除" in r.stdout, r.stdout)
    check("V6 prune 後正欄空", "Target.md#d1" not in read(src), read(src))
    # prune 本來不在(d1 已在上面 prune 掉、d2 已 promote 又還在正欄——換一個真的沒填過的驗)
    run(v, "decision-refs", "prune", "Verification/V", "Systems/Target.md#d2", expect_rc=0)  # 清掉 d2
    r = run(v, "decision-refs", "prune", "Verification/V", "Systems/Target.md#d1")
    check("V6 prune 本來不在=不同訊息", "本來就不在" in r.stdout, r.stdout)


def t_dref_asymmetric_trust_e2_e3():
    """★不對稱信任★:_ai 的 ref 對 E3 firing 生效、抑制不了 E2(結構:E2 只讀正欄)。"""
    v, tgt, src = _mk_dref_vault()
    # 翻案 Target#d1 → 讓 V(related→Target,updated 早於 ended)成 E2 落後邊候選
    run(v, "decision-supersede", "Target", "甲決策內容夠長給人讀", "--by", "改用丙", expect_rc=0)
    # add-ai 指到 d1(翻案那條)進 _ai
    run(v, "decision-refs", "add-ai", "Verification/V", "Systems/Target.md#d1", expect_rc=0)
    # E2 只讀正欄:_ai 有 ref 不影響 E2(結構保證)——doctor 不因 _ai 而改變 E2 抑制
    import subprocess as _sp
    r = _sp.run([sys.executable, GRAPHCTL, "--vault", str(v), "doctor", "--verbose"],
                capture_output=True, text=True)
    check("不對稱:_ai 有 ref 時 doctor 不崩(E2 讀側不碰 _ai)", r.returncode in (0, 1), r.stderr[:200])
    # promote 後才進正欄(用 list --by human 驗,不靠檔案 split)
    run(v, "decision-refs", "promote", "Verification/V", "Systems/Target.md#d1", expect_rc=0)
    lr = run(v, "decision-refs", "list", "Verification/V", "--by", "human")
    check("promote 後正欄(human)有該 ref", "Target.md#d1" in lr.stdout, lr.stdout)
    lr2 = run(v, "decision-refs", "list", "Verification/V", "--by", "ai")
    check("promote 後 _ai 欄無該 ref", "Target.md#d1" not in lr2.stdout, lr2.stdout)
    # arch-f5:promote 掉最後一條 _ai → 不留裸 decision_refs_ai: 鍵(YAML null 比沒鍵更糟)
    check("promote 掉最後一條 _ai 不留裸鍵", "decision_refs_ai:" not in read(src), read(src))


def t_dref_promote_coverage_advisory():
    """★覆蓋提醒★(code-dref ext-f1 blocker 迴歸):節點指向多條翻案決策、promote 第一條進正欄→
    E2 從節點級翻精化,其他翻案落後邊要被列出提醒(含無 id)——不得靜默。翻紅釘:_dref_coverage_scan
    的 valid 判斷若退回 truthy(誤跳全部翻案)→ 提醒空 → 這條紅。"""
    v = mkvault()
    write(v, "Systems/Tgt.md", "type: system\nstatus: done")
    run(v, "decision-add", "Tgt", "甲決策內容足夠長讓人讀懂", "--decided", "2026-07-01", expect_rc=0)
    run(v, "decision-add", "Tgt", "乙決策內容也足夠長", "--decided", "2026-07-01", expect_rc=0)
    # 翻案兩條決策
    run(v, "decision-supersede", "Tgt", "甲決策內容足夠長讓人讀懂", "--by", "改用丙", expect_rc=0)
    run(v, "decision-supersede", "Tgt", "乙決策內容也足夠長", "--by", "改用丁", expect_rc=0)
    # 來源 V 用 verified_by 指向 Tgt(E2 抑制範圍=verified_by/plan_refs),updated 早於 ended
    write(v, "Verification/V.md",
          "type: verification\nstatus: pass\nupdated: 2026-06-01\nverified_by:\n  - \"[[Systems/Tgt]]\"")
    # add-ai + promote 第一條(d1)→ 正欄非空,d2(另一翻案落後邊)該被覆蓋提醒列出
    run(v, "decision-refs", "add-ai", "Verification/V", "Systems/Tgt.md#d1", expect_rc=0)
    r = run(v, "decision-refs", "promote", "Verification/V", "Systems/Tgt.md#d1")
    check("覆蓋提醒:promote rc0", r.returncode == 0, r.stderr[:200])
    check("★覆蓋提醒列出其他翻案落後邊 d2(ext-f1 迴歸:valid 字串判斷對)★",
          "覆蓋提醒" in r.stdout and "#d2" in r.stdout, r.stdout[-500:])


def t_dref_crlf_and_error_protocol():
    """code-dref s1-f1 迴歸:CRLF 目標節點候選不消失(讀記憶體 fm_lines,不用嚴格 edit-path 讀檔)。"""
    v, tgt, src = _mk_dref_vault()
    txt = read(tgt)
    tgt.write_bytes(txt.replace("\n", "\r\n").encode("utf-8"))
    r = run(v, "decision-refs", "candidates", "Verification/V")
    check("s1-f1:CRLF 目標節點候選不靜默消失", "#d1" in r.stdout, r.stdout[:300])
    r = run(v, "decision-refs", "add-ai", "Verification/V", "Systems/Target.md#d1")
    check("s1-f1:CRLF 節點合法決策不被誤判 dangling", r.returncode == 0, r.stderr[:200])


def t_dref_promote_empty_key_cleanup():
    """[arch-f5] promote 掉節點唯一一條 _ai 不留裸 decision_refs_ai: 鍵(YAML null 比沒鍵更糟)。
    翻紅釘:拔 promote _ai 清空鍵邏輯 這條紅。"""
