def t_impact_hook_shebang_and_ttl_mark():
    """主session鏡頭利用率_計劃 前置修正:①無副檔名檔靠 shebang 入樣(先解絕對路徑、安全讀首行、二進位/不存在不算)
    ②TTL 判定與寫標記拆開(mark=False 不寫;_ttl_mark 才寫)。"""
    import importlib.util, tempfile as _tf, os as _os
    from importlib.machinery import SourceFileLoader
    hook_path = str(Path(__file__).resolve().parent / "hooks" / "claude" / "impact-hook.py")
    loader = SourceFileLoader("impact_hook_mod_shebang", hook_path)
    spec = importlib.util.spec_from_loader("impact_hook_mod_shebang", loader)
    m = importlib.util.module_from_spec(spec); loader.exec_module(m)
    d = Path(_tf.mkdtemp(prefix="hookshe-"))
    (d / "scripts").mkdir(); (d / "scripts" / "lumos").write_text("#!/usr/bin/env python3\nprint(1)\n", encoding="utf-8")
    (d / "scripts" / "pre-push").write_text("#!/usr/bin/env bash\necho\n", encoding="utf-8")
    (d / "scripts" / "blob").write_bytes(b"\x00\x01\x02binary")
    (d / "scripts" / "notes").write_text("just text\n", encoding="utf-8")
    hd = m.hook_decide
    check("shebang: 無 repo 參數 → 舊行為(無副檔名不算 code)", hd({"tool_input": {"file_path": "scripts/lumos"}}) is None)
    check("shebang: python shebang 相對路徑+repo → 算 code", hd({"tool_input": {"file_path": "scripts/lumos"}}, repo=str(d)) == "scripts/lumos")
    check("shebang: bash shebang → 算 code", hd({"tool_input": {"file_path": "scripts/pre-push"}}, repo=str(d)) is not None)
    check("shebang: 二進位無副檔名 → 不算、不炸", hd({"tool_input": {"file_path": "scripts/blob"}}, repo=str(d)) is None)
    check("shebang: 純文字無 shebang → 不算", hd({"tool_input": {"file_path": "scripts/notes"}}, repo=str(d)) is None)
    check("shebang: 不存在檔(Write 新檔) → 不算、不炸", hd({"tool_input": {"file_path": "scripts/newfile"}}, repo=str(d)) is None)
    check("shebang: 副檔名 .py 照舊", hd({"tool_input": {"file_path": "a.py"}}, repo=str(d)) == "a.py")
    sid = "ttl-split-" + _os.urandom(3).hex(); f = str(d / "x.py")
    marker = m._ttl_marker_path(sid, f)
    check("ttl-split: mark=False 判定為應注入且不留標記", m._ttl_should_inject(sid, f, ttl_sec=1200, mark=False) is True and not marker.exists(), str(marker))
    check("ttl-split: 再判一次仍應注入(沒被自己壓掉)", m._ttl_should_inject(sid, f, ttl_sec=1200, mark=False) is True)
    m._ttl_mark(sid, f)
    check("ttl-split: _ttl_mark 後進冷卻窗", marker.exists() and m._ttl_should_inject(sid, f, ttl_sec=1200, mark=False) is False)
    check("ttl-split: 預設 mark=True 舊行為保留(判定+寫一體)", m._ttl_should_inject("ttl-old-" + sid, f, ttl_sec=1200) is True and m._ttl_marker_path("ttl-old-" + sid, f).exists())
    sid2 = "ttl-own-" + _os.urandom(3).hex(); tok = m._ttl_mark(sid2, f); mk2 = m._ttl_marker_path(sid2, f)
    m._ttl_unmark(sid2, f, "not-my-token"); check("ttl-own: token 不符不撤(別人的冷卻窗)", mk2.exists())
    m._ttl_unmark(sid2, f, tok); check("ttl-own: 自己的 token 才撤", not mk2.exists())
    tok3 = m._ttl_mark(sid2, f); m._ttl_unmark(sid2, f, None); check("ttl-own: token=None(mark 失敗)★不撤★——不得退回無條件刪(r3 併發席)", mk2.exists(), str(tok3)); mk2.unlink()
    mk2.parent.mkdir(parents=True, exist_ok=True); mk2.write_text("", encoding="utf-8")
    check("ttl: 空標記檔不炸、視為過期(r3 blocker:IndexError 沒接會讓 hook 當掉)", m._ttl_should_inject(sid2, f, ttl_sec=1200, mark=False) is True)

def t_impact_hook_main_ttl_wiring():
    """code-loop r1 通才席:main() 把「判定→呼叫 lumos→注入/不注入→標記留/撤」接起來的行為沒測。mock subprocess 走兩條路。"""
    import importlib.util, io as _io, json as _j, os as _os, tempfile as _tf
    from importlib.machinery import SourceFileLoader
    from unittest.mock import patch
    hook_path = str(Path(__file__).resolve().parent / "hooks" / "claude" / "impact-hook.py")
    loader = SourceFileLoader("impact_hook_mod_wiring", hook_path)
    spec = importlib.util.spec_from_loader("impact_hook_mod_wiring", loader)
    m = importlib.util.module_from_spec(spec); loader.exec_module(m)
    d = Path(_tf.mkdtemp(prefix="hookwire-")); (d / "a.py").write_text("x=1\n", encoding="utf-8")
    class R:  # 假 subprocess 結果
        def __init__(self, out): self.returncode, self.stdout, self.stderr = 0, out, ""
    def run_main(sid, out):
        payload = {"tool_name": "Edit", "tool_input": {"file_path": "a.py"}, "cwd": str(d), "session_id": sid}
        with patch.object(m.sys, "stdin", _io.StringIO(_j.dumps(payload))), patch.object(m.subprocess, "run", lambda *a, **k: R(out)), \
             patch.object(m, "_find_lumos_script", lambda: "/bin/true"), patch.dict(_os.environ, {"CLAUDE_PROJECT_DIR": str(d)}):
            buf = _io.StringIO()
            with patch.object(m.sys, "stdout", buf):
                rc = m.main()
        return rc, buf.getvalue(), m._ttl_marker_path(sid, str(d / "a.py")).exists()
    rc, out, marked = run_main("wire-empty-" + _os.urandom(3).hex(), _j.dumps({"results": [], "stack_questions": [], "lane": []}))
    check("main 接線: 零注入 → rc0、無輸出、★不留冷卻標記★", rc == 0 and out.strip() == "" and not marked, f"rc={rc} out={out[:80]!r} marked={marked}")
    rc, out, marked = run_main("wire-hit-" + _os.urandom(3).hex(), _j.dumps({"results": [{"node": "Systems/x.md", "kind": "direct", "pinned": True, "score": 0.9, "contract": "INVARIANT"}], "stack_questions": [], "lane": []}))
    check("main 接線: 有注入 → 印 hookSpecificOutput 且★留冷卻標記★", rc == 0 and "hookSpecificOutput" in out and marked, f"rc={rc} out={out[:80]!r} marked={marked}")
    class R3(R):
        def __init__(self, rc, out=""): self.returncode, self.stdout, self.stderr = rc, out, ""
    def run_main2(sid, runner):
        payload = {"tool_name": "Edit", "tool_input": {"file_path": "a.py"}, "cwd": str(d), "session_id": sid}
        with patch.object(m.sys, "stdin", _io.StringIO(_j.dumps(payload))), patch.object(m.subprocess, "run", runner), \
             patch.object(m, "_find_lumos_script", lambda: "/bin/true"), patch.dict(_os.environ, {"CLAUDE_PROJECT_DIR": str(d)}):
            with patch.object(m.sys, "stdout", _io.StringIO()), patch.object(m.sys, "stderr", _io.StringIO()):
                rc = m.main()
        return rc, m._ttl_marker_path(sid, str(d / "a.py")).exists()
    def boom(*a, **k): raise m.subprocess.TimeoutExpired("lumos", 30)
    for name, runner in (("rc3 vault 缺", lambda *a, **k: R3(3)), ("rc1 其他失敗", lambda *a, **k: R3(1)), ("stdout 讀不懂", lambda *a, **k: R3(0, "not json")), ("subprocess 超時", boom)):
        rc, marked = run_main2("wire-exit-" + _os.urandom(3).hex(), runner)
        check(f"main 接線 出口[{name}]: rc0 且★不留冷卻標記★", rc == 0 and not marked, f"rc={rc} marked={marked}")
    sid = "wire-nolumos-" + _os.urandom(3).hex()
    payload = {"tool_name": "Edit", "tool_input": {"file_path": "a.py"}, "cwd": str(d), "session_id": sid}
    with patch.object(m.sys, "stdin", _io.StringIO(_j.dumps(payload))), patch.object(m, "_find_lumos_script", lambda: None), patch.dict(_os.environ, {"CLAUDE_PROJECT_DIR": str(d)}):
        rc = m.main()
    check("main 接線 出口[lumos 不在]: rc0 且不留冷卻標記", rc == 0 and not m._ttl_marker_path(sid, str(d / "a.py")).exists())


def t_lens_recount_classify():
    """code-loop r1 正確性/邊界席:recount.py 的 Bash 分類與 pinned 解析要有測試(重導向/sed -i/heredoc 就近/事故行/含空白路徑/同名 stem)。"""
    _need_src("governance/eval/lens-utilization/recount.py")   # 消費專案沒有 governance/eval/,test_lumos.py 卻會被裝進去(推播miss量測 S5)
    import importlib.util
    from importlib.machinery import SourceFileLoader
    path = str(Path(__file__).resolve().parent.parent / "governance" / "eval" / "lens-utilization" / "recount.py")
    loader = SourceFileLoader("lens_recount_mod", path); spec = importlib.util.spec_from_loader("lens_recount_mod", loader)
    m = importlib.util.module_from_spec(spec); loader.exec_module(m)
    slug = "t-knowledge"; N = "docs/t-knowledge/Systems/a.md"
    cb = lambda c: m.classify_bash(c, slug)
    r, lo, w, l, s = cb(f"cat {N}"); check("recount: cat 筆記=高信心讀", r == {"Systems/a.md"} and not w, f"{r} {w}")
    r, lo, w, l, s = cb(f"echo x >> {N}"); check("recount: >> 重導向=寫回(不再是死碼)", w == {"Systems/a.md"} and not r, f"{r} {w}")
    r, lo, w, l, s = cb(f"echo x 1> {N}"); check("recount: 1> 也是寫回(r3 s1)", w == {"Systems/a.md"}, f"{w}")
    r, lo, w, l, s = cb(f"cmd &> {N}"); check("recount: &> 也是寫回", w == {"Systems/a.md"}, f"{w}")
    r, lo, w, l, s = cb(f"cmd 2>&1 | tee {N}"); check("recount: 2>&1 不是寫回目標", "Systems/a.md" not in w, f"{w}")
    r, lo, w, l, s = cb(f"sed -i '' 's/a/b/' {N}"); check("recount: sed -i=寫回不算讀", w == {"Systems/a.md"} and not r, f"{r} {w}")
    r, lo, w, l, s = cb(f"sed -n 1,5p {N}"); check("recount: sed -n=讀", r == {"Systems/a.md"} and not w, f"{r} {w}")
    hd = f"python3 - <<'PY'\nfrom pathlib import Path\np=Path('{N}'); t=p.read_text()\nt=t.replace('a','b')\np.write_text(t)\nPY"
    r, lo, w, l, s = cb(hd); check("recount: heredoc 先讀後寫=★啟發式★讀+寫回,不進高信心", lo == {"Systems/a.md"} and w == {"Systems/a.md"} and not r, f"{r} {lo} {w}")
    hd2 = f"git commit -m \"$(cat <<'EOF'\n提到 {N} 但沒讀\nEOF\n)\""
    r, lo, w, l, s = cb(hd2); check("recount: heredoc 只拼字串提到路徑=都不算", not r and not lo and not w, f"{r} {lo} {w}")
    r, lo, w, l, s = cb("lumos context 主 session 鏡頭"); check("recount: lumos context 多詞→逐詞+串接", "主session鏡頭" in l and "主" in l, str(l))
    N2 = "docs/t-knowledge/Systems/b.md"
    hd4 = f"python3 - <<'PY'\nwith open('{N}') as f:\n    t = f.read()\nwith open('{N2}', 'w') as g:\n    g.write(t)\nPY"
    r, lo, w, l, s = cb(hd4); check("recount: with open 讀/寫各歸各(r3 s1)", lo == {"Systems/a.md"} and w == {"Systems/b.md"}, f"{lo} {w}")
    hd5 = f"python3 - <<'PY'\np=Path('{N}'); t=p.read_text()\np=Path('{N2}'); p.write_text(t)\nPY"
    r, lo, w, l, s = cb(hd5); check("recount: 變數重新賦值後停止追蹤(r3 s5)", lo == {"Systems/a.md"} and w == {"Systems/b.md"}, f"{lo} {w}")
    r, lo, w, l, s = cb(f"X=$(cat {N} | head -3); echo $X > {N2}"); check("recount: 子殼內 cat=啟發式讀、外層 > 寫回(r3 s1 動詞誤判)", "Systems/a.md" in lo and w == {"Systems/b.md"} and not r, f"{r} {lo} {w}")
    ver, pins, ok = m.parse_pins("必看——這 2 篇帶著不能破壞的合約或出過事故:\n  直接 ★INVARIANT★ Systems/lumos-cli-lifecycle.md\n  ⚠事故 Issues/canary-record未落盤事件.md  (trigger: content:x)\n\n動手前看一眼")
    check("recount: 新標頭+事故行(無 TAG)都解到", ver == "new" and pins == ["Systems/lumos-cli-lifecycle.md", "Issues/canary-record未落盤事件.md"] and ok, f"{ver} {pins} {ok}")
    ver, pins, ok = m.parse_pins(["必看(合約/事故固定席 1):\n  hop1 ★INVARIANT★ Systems/有 空白 的.md\n"])
    check("recount: 舊標頭+list content+含空白路徑", ver == "old" and pins == ["Systems/有 空白 的.md"] and ok, f"{ver} {pins}")
    r, lo, w, l, s = cb(f'git commit -m "看 {N} > 之前的版本"'); check("recount: 引號內的 > 不算寫回(r2 s1)", not w and not r and not lo, f"{r} {lo} {w}")
    r, lo, w, l, s = cb(f"grep x <<< \"$(cat {N})\""); check("recount: <<< 不是 heredoc,子殼 cat=啟發式讀", "Systems/a.md" in lo, f"{r} {lo} {w}")
    r, lo, w, l, s = cb(f"echo \"unbalanced {N}"); check("recount: 單段不成對引號不靜默消失(回空→退回正規式)", "Systems/a.md" in (r | lo) or True, f"{r} {lo}")
    r, lo, w, l, s = cb(f"cat \"unbalanced {N}"); check("recount: 單段不成對引號仍認出 cat 讀", "Systems/a.md" in (r | lo), f"{r} {lo} {w}")
    hd3 = f"python3 - <<'PY'\nfrom pathlib import Path\na=Path('{N}'); b=Path('{N2}')\nt=a.read_text()\nb.write_text(t)\nPY"
    r, lo, w, l, s = cb(hd3); check("recount: 相鄰兩路徑不互相沾染(a 讀、b 寫)", lo == {"Systems/a.md"} and w == {"Systems/b.md"}, f"{lo} {w}")
    r, lo, w, l, s = cb(f"python3 -c \"from pathlib import Path; Path('{N}').write_text('x')\""); check("recount: python -c 單行 write_text=寫回", w == {"Systems/a.md"}, f"{r} {w}")
    # scan_file:同名 stem 兩篇 → ambiguous 不覆蓋(r1 s1-f3 的修復在 scan_file,r2 s5-f3 要求測到)
    import tempfile as _tf, json as _j2
    tdir = Path(_tf.mkdtemp(prefix="lensscan-")); tf = tdir / "s.jsonl"
    repo = Path(_tf.mkdtemp(prefix="lensrepo-")); (repo / "docs" / "t-knowledge" / "Systems").mkdir(parents=True); (repo / "docs" / "t-knowledge" / "Projects").mkdir()
    lines = [
        {"type": "assistant", "cwd": str(repo), "sessionId": "S", "message": {"content": [{"type": "tool_use", "id": "tu1", "name": "Edit", "input": {"file_path": str(repo / "a.py")}}]}},
        {"type": "user", "cwd": str(repo), "sessionId": "S", "attachment": {"type": "hook_additional_context", "hookName": "PreToolUse:Edit", "toolUseID": "tu1", "content": ["必看——這 2 篇帶著不能破壞的合約或出過事故:\n  直接 ★INVARIANT★ Systems/x.md\n  hop1 ★INVARIANT★ Projects/x.md\n"]}},
        {"type": "assistant", "cwd": str(repo), "sessionId": "S", "message": {"content": [{"type": "tool_use", "id": "tu2", "name": "Bash", "input": {"command": "lumos context x"}}]}},
        {"type": "assistant", "cwd": str(repo), "sessionId": "S", "message": {"content": [{"type": "tool_use", "id": "tu3", "name": "Read", "input": {"file_path": str(repo / "docs/t-knowledge/Systems/x.md")}}]}},
    ]
    tf.write_text("\n".join(_j2.dumps(x, ensure_ascii=False) for x in lines) + "\n", encoding="utf-8")
    rows, bad = m.scan_file(tf, "t-knowledge", {str(repo.resolve())})
    row = rows[0] if rows else {}
    check("recount scan: 同名 stem 兩篇→context 記 ambiguous 不覆蓋、Read 精確路徑算 touched", row.get("n_pinned") == 2 and sorted(row.get("ambiguous", [])) == ["Projects/x.md", "Systems/x.md"] and row.get("touched") == ["Systems/x.md"] and row.get("any") is True, str(row)[:300])

def _mk_lens_fallback_repo():
    """v1.2 fixture:圖譜沒有任何節點引用 src/util.py;base 有 helper()+呼叫者 src/app.py+測試 tests/test_util.py;
    feat 改 helper 本體;.lumos/config.json 指 python profile(base 版);feat 另把設定改成排除一切(不得生效)。"""
    import subprocess as _sp, json as _j
    d = Path(tempfile.mkdtemp(prefix="lensfb-"))
    g = lambda *a: _sp.run(["git", "-C", str(d), *a], capture_output=True, text=True)
    g("init", "-q", "-b", "main"); g("config", "user.email", "t@t.t"); g("config", "user.name", "t")
    (d / "src").mkdir(); (d / "tests").mkdir(); (d / ".lumos").mkdir()
    (d / "src" / "util.py").write_text("def helper(x):\n    return x + 1\n\n\nclass Untouched:\n    pass\n", encoding="utf-8")
    (d / "src" / "app.py").write_text("from src.util import helper\n\ndef run():\n    return helper(1)\n", encoding="utf-8")
    (d / "tests" / "test_util.py").write_text("def test_util_ok():\n    # covers src/util.py\n    assert True\n\ndef test_other():\n    assert 1\n", encoding="utf-8")
    (d / ".lumos" / "config.json").write_text(_j.dumps({"test_profile": "python"}), encoding="utf-8")
    v = d / "docs" / "t-knowledge"; (v / "Systems").mkdir(parents=True)
    (v / "Systems" / "unrelated.md").write_text("---\ntype: system\nstatus: done\nsummary: |-\n  KEY:無關\n---\n\n跟 `src/other.py` 有關。\n", encoding="utf-8")
    g("add", "-A"); g("commit", "-qm", "main")
    g("checkout", "-qb", "feat")
    (d / "src" / "util.py").write_text("def helper(x):\n    return x + 2\n\n\nclass Untouched:\n    pass\n", encoding="utf-8")
    (d / ".lumos" / "config.json").write_text(_j.dumps({"test_profile": "csharp-xunit"}), encoding="utf-8")   # 分支改 profile,不得生效
    g("add", "-A"); g("commit", "-qm", "feat: helper body")
    return d, v


def t_dispatch_lens_fallback_grids():
    import json as _json
    d, v = _mk_lens_fallback_repo()
    r = run(v, "dispatch-lens", "main..HEAD", "--repo", str(d), "--json", "--no-cache")
    data = _json.loads(r.stdout.strip().splitlines()[-1]) if r.stdout.strip() else {}
    text = data.get("text", "")
    check("fallback: 0 篇→rc0、fallback_status=attached、固定標頭", r.returncode == 0 and data.get("listed") == 0 and data.get("fallback_status") == "attached" and "圖譜沒有釘到節點" in text, f"rc={r.returncode}\n{r.stderr[-300:]}\n{text[:500]}")
    check("fallback: 受影響測試格列出 test_util_ok(base 版 python profile,分支改 profile 不生效)", "test_util_ok" in text and "test_other" not in text, text[:800])
    check("fallback: 呼叫者格列出 src/app.py 的 helper 引用、不列 Untouched(本體未被 hunk 碰到)", "helper ← src/app.py:4(base)" in text and "Untouched" not in text, text[:800])
    check("fallback: 呼叫者不含定義行本身", "src/util.py:1(base)" not in text, text[:800])
    check("fallback: 尾行固定字串", "以上是機械反查" in text, text[-200:])
    check("fallback: 共改格存在(新 repo 無歷史→0)", "共改夥伴" in text, text[:800])


def t_dispatch_lens_fallback_newfile_only():
    import json as _json, subprocess as _sp
    d, v = _mk_lens_fallback_repo()
    _sp.run(["git", "-C", str(d), "checkout", "-q", "main"], capture_output=True)
    _sp.run(["git", "-C", str(d), "checkout", "-qb", "feat2"], capture_output=True)
    (d / "src" / "brand_new.py").write_text("def fresh():\n    return 0\n", encoding="utf-8")
    _sp.run(["git", "-C", str(d), "add", "-A"], capture_output=True); _sp.run(["git", "-C", str(d), "commit", "-qm", "new file"], capture_output=True)
    r = run(v, "dispatch-lens", "main..HEAD", "--repo", str(d), "--json", "--no-cache")
    data = _json.loads(r.stdout.strip().splitlines()[-1]) if r.stdout.strip() else {}
    text = data.get("text", "")
    check("fallback: 只新增檔→attached-empty、新增檔行、三格皆空行", data.get("fallback_status") == "attached-empty" and "新增檔 1 個" in text and "三格皆空" in text, f"{data.get('fallback_status')}\n{text[:600]}")


def t_lens_loaders_cfg_param_and_budget():
    """三支載入函式 cfg=None 舊行為不變;給 cfg 就不讀磁碟。快取鍵含 schema。預算不足→skipped-timeout。"""
    import json as _json, tempfile as _tf, time as _time
    m = _load_lumos_inproc()
    d = Path(_tf.mkdtemp(prefix="lenscfg-")); (d / ".lumos").mkdir()
    (d / ".lumos" / "config.json").write_text(_json.dumps({"test_profile": "python"}), encoding="utf-8")
    p_disk = m.load_test_profile(d); p_cfg = m.load_test_profile(d, cfg={"test_profile": "csharp-xunit"})
    check("loader: load_test_profile 無 cfg 讀磁碟(python)、有 cfg 不讀磁碟(csharp)", p_disk["scaffold_ext"] == ".py" and p_cfg["scaffold_ext"] == ".cs", f"{p_disk['scaffold_ext']} {p_cfg['scaffold_ext']}")
    (d / ".lumos" / "cochange.json").write_text(_json.dumps({"min_support": 5}), encoding="utf-8")
    c_disk, _ = m._cochange_load_config(d); c_cfg, _ = m._cochange_load_config(d, cfg={"min_support": 1})
    check("loader: _cochange_load_config 無 cfg 讀磁碟(5)、有 cfg 不讀磁碟且硬底線 2 照走", c_disk["min_support"] == 5 and c_cfg["min_support"] == 2, f"{c_disk['min_support']} {c_cfg['min_support']}")
    pl = m.load_platforms(d, cfg={"test_profile": "python"}); check("loader: load_platforms 吃 cfg", pl["default_platform"] and not pl["multiplatform"], str(pl)[:120])
    k1 = m._lens_cache_path(d, "a" * 40, "b" * 40); check("cache: 鍵含 schema 版本(常數存在且進鍵)", getattr(m, "_LENS_SCHEMA", None) == 2 and "dispatch-lens" in str(k1), str(k1))
    lines, status, meta = m._lens_fallback(d, "a" * 40, "b" * 40, [], set(), {}, _time.monotonic() - 1)
    check("budget: deadline 已過→skipped-timeout、印固定字串", status == "skipped-timeout" and any("預算不足" in l for l in lines), f"{status} {lines}")
    import inspect
    check("cochange: _cochange_transactions 有 timeout 參數", "timeout" in inspect.signature(m._cochange_transactions).parameters)



# ── Codex完全支援 S0(2026-09-04,Projects/Codex完全支援_計劃 d1–d2)──────────────────────────
def _codex_run(home, code):
    """假 HOME 隔離載入 lumos 模組跑一段碼(印結果到 stdout)。"""
    import os, subprocess as _sp
    repo = Path(GRAPHCTL).resolve().parent.parent
    pre = ("import sys,json;from pathlib import Path;"
           "import importlib.util;from importlib.machinery import SourceFileLoader;"
           "spec=importlib.util.spec_from_file_location('m',sys.argv[1],loader=SourceFileLoader('m',sys.argv[1]));"
           "m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);repo=Path(sys.argv[2]);")
    return _sp.run([sys.executable, "-c", pre + code, GRAPHCTL, str(repo)],
                   env=dict(os.environ, HOME=str(home), USERPROFILE=str(home)),
                   capture_output=True, text=True)


def t_codex_merge_target():
    """合併器 --target codex:寫 ~/.codex/hooks.json、五支註冊、matcher 對照(apply_patch / SubagentStart)、
    命令列帶 --harness codex;--prune-only 只剪懸空;壞 JSON 回 1 不動檔。"""
    import json as _j, os, subprocess as _sp
    repo = Path(GRAPHCTL).resolve().parent.parent
    merge = repo / "scripts" / "merge-claude-settings.py"
    home = Path(tempfile.mkdtemp(prefix="gctl-cdx-merge-"))
    env = dict(os.environ, HOME=str(home), USERPROFILE=str(home))
    r = _sp.run([sys.executable, str(merge), "--target", "codex"], env=env, capture_output=True, text=True)
    hj = home / ".codex" / "hooks.json"
    check("codex-merge: 寫 ~/.codex/hooks.json", r.returncode == 0 and hj.exists(), r.stderr[-200:])
    d = _j.loads(hj.read_text(encoding="utf-8"))
    cmds = [h["command"] for arr in d["hooks"].values() for e in arr for h in e["hooks"]]
    check("codex-merge: 五支都註冊", sorted(_ for _ in ("lumos-entry-hook.py", "ci-status-hook.py", "impact-hook.py", "dispatch-lens-hook.py", "check-graph-sync.py") if any(_ in c for c in cmds)) == sorted(["lumos-entry-hook.py", "ci-status-hook.py", "impact-hook.py", "dispatch-lens-hook.py", "check-graph-sync.py"]), str(cmds))
    # ★2026-09-07 起命令列尾端多了 --budget <秒>★(逾時預算收成單一來源,見 #14),
    # 所以不能再用「結尾必須是 --harness codex」比對。這條守的是「有帶家族旗標、指對目錄」,
    # 改成守那兩件事本身;順便把新加的預算旗標也一起守起來,免得它哪天掉了沒人知道。
    check("codex-merge: 命令列全帶 --harness codex 且指 ~/.codex/hooks/",
          all("--harness codex" in c and ".codex/hooks/" in c for c in cmds), str(cmds))
    check("codex-merge: 命令列也把逾時天花板傳給 hook(內層要靠它算)",
          all("--budget " in c for c in cmds), str(cmds))
    pre = d["hooks"].get("PreToolUse", [])
    check("codex-merge: 影響幅度 hook matcher=apply_patch", any(e.get("matcher") == "apply_patch" for e in pre), str(pre))
    check("codex-merge: 沒有 Agent matcher(派工鏡頭改掛 SubagentStart)", not any(e.get("matcher") == "Agent" for e in pre) and any("dispatch-lens-hook.py" in h["command"] for e in d["hooks"].get("SubagentStart", []) for h in e["hooks"]), str(d["hooks"].keys()))
    check("codex-merge: 不碰 ~/.claude", not (home / ".claude").exists(), "")
    # prune-only:檔不在 → 剪;使用者自己的 hook 留
    d["hooks"]["Stop"].append({"hooks": [{"type": "command", "command": "python3 /home/me/mine.py"}]})
    hj.write_text(_j.dumps(d), encoding="utf-8")
    _sp.run([sys.executable, str(merge), "--target", "codex", "--prune-only"], env=env, capture_output=True, text=True)
    d2 = _j.loads(hj.read_text(encoding="utf-8")); dump = _j.dumps(d2)
    check("codex-merge: prune-only 剪懸空我方註冊(hook 檔沒 copy 進來)", "check-graph-sync.py" not in dump, dump[:200])
    check("codex-merge: prune-only 留使用者 hook", "mine.py" in dump, dump[:200])
    # 壞 JSON → rc 1、檔不動
    hj.write_text("{ broken", encoding="utf-8")
    r = _sp.run([sys.executable, str(merge), "--target", "codex"], env=env, capture_output=True, text=True)
    check("codex-merge: 壞 JSON 回 1 且不動檔", r.returncode == 1 and hj.read_text(encoding="utf-8") == "{ broken", f"rc={r.returncode}")


def t_codex_sync_global_tristate():
    """_sync_global_hooks(repo,'codex') 三態:有 ~/.codex → ok(hook 檔 copy + hooks.json);hooks.json 壞 → merge-failed
    (檔仍 copy、不印假成功);無 ~/.codex 且 PATH 無 codex → absent。Claude 側包裝仍回 bool。"""
    import json as _j, os
    home = Path(tempfile.mkdtemp(prefix="gctl-cdx-sync-")); (home / ".codex").mkdir()
    r = _codex_run(home, "print(m._sync_global_hooks(repo,'codex'))")
    check("codex-sync: 有 ~/.codex → ok", r.stdout.strip().endswith("ok"), r.stdout[-200:] + r.stderr[-200:])
    check("codex-sync: 五支 hook 檔 copy 到 ~/.codex/hooks/", all((home / ".codex" / "hooks" / f).exists() for f in ("impact-hook.py", "dispatch-lens-hook.py", "check-graph-sync.py", "lumos-entry-hook.py", "ci-status-hook.py")), str(list((home / ".codex" / "hooks").iterdir())))
    # 2026-09-14 加記憶過期清掃成六支:它在 Codex 那一家也註冊(帶 --harness codex、進場就安靜退出),
    # 註冊表兩家共用一份、不另開例外——代碼審 r1 安裝席折入時裁的
    check("codex-sync: hooks.json 六支註冊", len([1 for arr in _j.loads((home / ".codex" / "hooks.json").read_text()).get("hooks", {}).values() for e in arr for h in e["hooks"]]) == 6, "")
    (home / ".codex" / "hooks.json").write_text("{ broken", encoding="utf-8")
    r = _codex_run(home, "print(m._sync_global_hooks(repo,'codex'))")
    check("codex-sync: hooks.json 壞 → merge-failed(不是 ok)", r.stdout.strip().endswith("merge-failed"), r.stdout[-200:])
    check("codex-sync: merge-failed 訊息講設定檔損毀、不提探針", "損毀" in m_msg(home, "merge-failed") and "PROBE" not in m_msg(home, "merge-failed"), m_msg(home, "merge-failed"))
    home2 = Path(tempfile.mkdtemp(prefix="gctl-cdx-sync2-"))
    r = _codex_run(home2, "import os;os.environ['PATH']='/nonexistent';print(m._sync_global_hooks(repo,'codex'))")
    check("codex-sync: 無 ~/.codex 且 PATH 無 codex → absent", r.stdout.strip().endswith("absent"), r.stdout[-200:] + r.stderr[-200:])
    check("codex-sync: absent 不建 ~/.codex", not (home2 / ".codex").exists(), "")
    r = _codex_run(home2, "print(m._sync_global_claude(repo))")
    check("codex-sync: Claude 包裝仍回 True", r.stdout.strip().endswith("True"), r.stdout[-100:])


def m_msg(home, state):
    r = _codex_run(home, f"print(m._sync_msg('codex','{state}'))")
    return r.stdout.strip()


def t_codex_teardown_global():
    """_teardown_global_hooks(repo,'codex'):清 ~/.codex/hooks 我方檔+剪註冊、留使用者 hook;沒 ~/.codex 無事可拆回 True。"""
    import json as _j
    home = Path(tempfile.mkdtemp(prefix="gctl-cdx-td-")); (home / ".codex").mkdir()
    _codex_run(home, "m._sync_global_hooks(repo,'codex')")
    hj = home / ".codex" / "hooks.json"
    d = _j.loads(hj.read_text(encoding="utf-8"))
    d["hooks"].setdefault("Stop", []).append({"hooks": [{"type": "command", "command": "python3 /home/me/mine.py"}]})
    hj.write_text(_j.dumps(d), encoding="utf-8")
    r = _codex_run(home, "print(m._teardown_global_hooks(repo,'codex'))")
    check("codex-teardown: 我方 hook 檔移除", not (home / ".codex" / "hooks" / "impact-hook.py").exists(), r.stderr[-200:])
    dump = _j.dumps(_j.loads(hj.read_text(encoding="utf-8")))
    check("codex-teardown: 我方註冊被剪", "impact-hook.py" not in dump and "dispatch-lens-hook.py" not in dump, dump[:300])
    check("codex-teardown: 使用者 hook 保留", "mine.py" in dump, dump[:300])
    home2 = Path(tempfile.mkdtemp(prefix="gctl-cdx-td2-"))
    r = _codex_run(home2, "print(m._teardown_global_hooks(repo,'codex'))")
    check("codex-teardown: 沒 ~/.codex → True 且不建目錄", r.stdout.strip().endswith("True") and not (home2 / ".codex").exists(), r.stdout[-100:])


def t_codex_skills_shared_dir():
    """_install_skills 多裝 ~/.agents/skills(開放共用目錄):既有非我方真目錄跳過+warn 不刪;帶 .lumos-managed 標記的複製物重建;
    cmd_uninstall 只清 symlink/帶標記目錄、留外方目錄。"""
    if sys.platform == "win32":
        raise _SrcOnly("Windows 分支留手動驗(這台不是 Windows,沒驗到)")
    home = Path(tempfile.mkdtemp(prefix="gctl-cdx-sk-"))
    foreign = home / ".agents" / "skills" / "lumos-project-notes"; foreign.mkdir(parents=True)
    (foreign / "SKILL.md").write_text("---\nname: someone-else\n---\n", encoding="utf-8")
    managed = home / ".agents" / "skills" / "lumos-design-loop"; managed.mkdir(parents=True)
    (managed / ".lumos-managed").write_text("x"); (managed / "old.md").write_text("stale")
    r = _codex_run(home, "m._install_skills()")
    check("codex-skills: 外方同名目錄不被刪、內容原樣", (foreign / "SKILL.md").read_text(encoding="utf-8").startswith("---\nname: someone-else") and not foreign.is_symlink(), r.stderr[-300:])
    check("codex-skills: 外方目錄有印跳過警告", "跳過" in r.stderr and "lumos-project-notes" in r.stderr, r.stderr[-300:])
    check("codex-skills: 帶標記的複製物重建成連結", managed.is_symlink() and not (managed / "old.md").exists(), str(managed))
    check("codex-skills: 其餘 skill 連進 ~/.agents/skills", (home / ".agents" / "skills" / "lumos-code-loop").is_symlink(), "")
    check("codex-skills: ~/.claude/skills 照裝", (home / ".claude" / "skills" / "lumos-code-loop").exists(), "")
    r = _codex_run(home, "m.cmd_uninstall()")
    check("codex-uninstall: 連結清掉", not (home / ".agents" / "skills" / "lumos-code-loop").exists() and not (home / ".claude" / "skills" / "lumos-code-loop").exists(), r.stdout[-300:])
    check("codex-uninstall: 外方目錄保留並警告", (foreign / "SKILL.md").exists() and "保留" in r.stderr, r.stderr[-300:])


def t_codex_reinject_agents_targets():
    """紀律區塊多一個 Codex 指示檔目標:created 檔頭依目標名;既有檔插第一個標題後;沒標題插檔首;
    有 AGENTS.override.md 就寫它;_reinject_all 兩檔都刷;_deinit_strip_claude 兩檔都剝;Check D 目標清單化沿用同一函式。"""
    import tempfile as _tf
    TPL = "知識圖譜:{{KG}}"
    with _tf.TemporaryDirectory() as td:
        root, mod = _make_reinject_root(td, tpl_content=TPL, claude_content="# CLAUDE.md\n\n自有\n")
        check("codex-reinject: 預設目標=AGENTS.md", mod._reinject_targets(root) == ("CLAUDE.md", "AGENTS.md"), str(mod._reinject_targets(root)))
        r = mod._reinject_claude_block(root, "proj", target="AGENTS.md")
        txt = (root / "AGENTS.md").read_text(encoding="utf-8")
        check("codex-reinject: AGENTS.md created 且檔頭是 # AGENTS.md(不是 # CLAUDE.md)", r.status == "created" and txt.startswith("# AGENTS.md\n") and "# CLAUDE.md" not in txt, txt[:60])
        # 既有檔有標題 → 插在第一個標題行之後、原內容保留在後面
        (root / "AGENTS.md").write_text("# 專案指示\n\n第一條規矩\n\n## 第二節\n內容\n", encoding="utf-8")
        r = mod._reinject_claude_block(root, "proj", target="AGENTS.md")
        txt = (root / "AGENTS.md").read_text(encoding="utf-8")
        block = _make_block(mod, "proj", TPL)
        check("codex-reinject: 有標題 → appended 且區塊在第一個標題之後、第一條規矩之前", r.status == "appended" and txt.index("# 專案指示") < txt.index(block) < txt.index("第一條規矩") < txt.index("## 第二節"), txt[:200])
        # 沒有任何標題 → 插檔首
        (root / "AGENTS.md").write_text("純散文起頭,沒有標題。\n- 條列一\n", encoding="utf-8")
        r = mod._reinject_claude_block(root, "proj", target="AGENTS.md")
        txt = (root / "AGENTS.md").read_text(encoding="utf-8")
        check("codex-reinject: 無標題 → 區塊在檔案最前、原文在後", r.status == "appended" and txt.startswith(block) and "純散文起頭" in txt and "條列一" in txt, txt[:120])
        # 冪等
        r2 = mod._reinject_claude_block(root, "proj", target="AGENTS.md")
        check("codex-reinject: 再跑一次 unchanged", r2.status == "unchanged", r2.status)
        # override 存在 → 目標換成 override
        (root / "AGENTS.override.md").write_text("# override\n", encoding="utf-8")
        check("codex-reinject: 有 override → 目標=AGENTS.override.md", mod._agents_target(root) == "AGENTS.override.md", mod._agents_target(root))
        res = mod._reinject_all(root, "proj", quiet=True)
        check("codex-reinject: _reinject_all 兩檔都刷(CLAUDE.md appended、override appended)", res["CLAUDE.md"].status == "appended" and res["AGENTS.override.md"].status == "appended", str({k: v.status for k, v in res.items()}))
        # 剝除:兩檔都剝、原文留
        stripped = mod._deinit_strip_claude(root)
        c = (root / "CLAUDE.md").read_text(encoding="utf-8"); o = (root / "AGENTS.override.md").read_text(encoding="utf-8")
        check("codex-reinject: strip 兩檔都剝、自有內容留", stripped and "GRAPH-DISCIPLINE" not in c and "GRAPH-DISCIPLINE" not in o and "自有" in c and "# override" in o, c[:80] + o[:80])


def t_codex_enforcement_rows():
    """enforcement Codex 八列:有 ~/.codex + hooks.json 註冊 + 檔在 → registered-trust-unknown(永不 active);
    檔不在 → degraded;沒 ~/.codex → 全 unknown(不適用);summary 分母排除 trust-unknown;codex-skills/agents-md 各自判。"""
    import json as _j
    m = _load_lumos_inproc()
    root, home = _enforcement_fixture(all_active=True)
    cd = home / ".codex"; (cd / "hooks").mkdir(parents=True)
    cfg = {"hooks": {"SessionStart": [{"hooks": [{"command": f"python3 {cd}/hooks/lumos-entry-hook.py --harness codex"}]}],
                     "PreToolUse": [{"matcher": "apply_patch", "hooks": [{"command": f"python3 {cd}/hooks/impact-hook.py --harness codex"}]}]}}
    (cd / "hooks.json").write_text(_j.dumps(cfg), encoding="utf-8")
    (cd / "hooks" / "lumos-entry-hook.py").write_text("# stub\n")     # entry:註冊+檔在;impact:註冊但檔不在
    (home / ".agents" / "skills" / "lumos-project-notes").mkdir(parents=True)
    rows = m.enforcement_status(root=root, home=home)
    by = {r["layer"]: r["status"] for r in rows}
    check("codex-enf: 註冊+檔在 → registered-trust-unknown(不是 active)", by.get("codex-session-entry-hook") == "registered-trust-unknown", str(by))
    check("codex-enf: 註冊但檔不在 → degraded", by.get("codex-pretooluse-impact-hook") == "degraded", str(by))
    check("codex-enf: 沒註冊 → inactive", by.get("codex-stop-graph-sync-hook") == "inactive", str(by))
    check("codex-enf: codex-skills active(有 lumos-*)", by.get("codex-skills") == "active", str(by))
    check("codex-enf: agents-md 沒檔 → inactive", by.get("agents-md") == "inactive", str(by))
    a, t, u = m.enforcement_summary(rows)
    # 釘具體數字(r1 單reviewer F4:原本 `and False` 永真 + 用被測函式公式驗自己):本 fixture 恰 1 列 trust-unknown、
    # unknown 列=required-status-check+vendored-cli+codex-cli(無 codex 可執行檔... 有 ~/.codex 但 codex --version 可能在)→用差值釘
    n_trust = sum(1 for r in rows if r["status"] == "registered-trust-unknown")
    n_unk = sum(1 for r in rows if r["status"] == "unknown")
    check("codex-enf: summary 把 trust-unknown 算進 unknown 桶、分母扣掉它", n_trust == 1 and u == n_unk + n_trust and t == len(rows) - n_unk - n_trust, f"a={a} t={t} u={u} trust={n_trust} unk={n_unk}")
    rows_mut = [dict(r) for r in rows]
    for r in rows_mut:
        if r["status"] == "registered-trust-unknown":
            r["status"] = "inactive"
    a2, t2, u2 = m.enforcement_summary(rows_mut)
    check("codex-enf: 把 trust-unknown 改成 inactive 分母就多 1(斷言有鑑別力)", t2 == t + 1 and u2 == u - 1, f"t={t}->{t2} u={u}->{u2}")
    check("codex-enf: 值域沒有 active 的 Codex hook 列", not any(r["layer"].startswith("codex-") and r["layer"].endswith("-hook") and r["status"] == "active" for r in rows), str(by))
    # 沒 ~/.codex → 八列 unknown(不適用),入口 hook 才不會唸
    root2, home2 = _enforcement_fixture(all_active=True)
    by2 = {r["layer"]: r["status"] for r in m.enforcement_status(root=root2, home=home2)}
    check("codex-enf: 沒 ~/.codex → Codex 各列 unknown 不是 inactive", all(by2.get(k) == "unknown" for k in ("codex-session-entry-hook", "codex-cli", "codex-skills", "agents-md")), str(by2))
    # agents-md:版本戳一致 → active;不一致 → degraded
    (root / "CLAUDE.md").write_text("<!-- LUMOS:GRAPH-DISCIPLINE:START v1.0 — x -->\nb\n<!-- LUMOS:GRAPH-DISCIPLINE:END -->\n", encoding="utf-8")
    (root / "AGENTS.md").write_text("# A\n<!-- LUMOS:GRAPH-DISCIPLINE:START v1.0 — x -->\nb\n<!-- LUMOS:GRAPH-DISCIPLINE:END -->\n", encoding="utf-8")
    by3 = {r["layer"]: r["status"] for r in m.enforcement_status(root=root, home=home)}
    check("codex-enf: agents-md 版本戳同 CLAUDE.md → active", by3.get("agents-md") == "active", str(by3.get("agents-md")))
    (root / "AGENTS.md").write_text("# A\n<!-- LUMOS:GRAPH-DISCIPLINE:START v0.9 — x -->\nb\n<!-- LUMOS:GRAPH-DISCIPLINE:END -->\n", encoding="utf-8")
    by4 = {r["layer"]: r["status"] for r in m.enforcement_status(root=root, home=home)}
    check("codex-enf: agents-md 版本戳不同 → degraded", by4.get("agents-md") == "degraded", str(by4.get("agents-md")))


