    r = _sp.run([sys.executable, str(merge), "--target", "codx"], env=dict(os.environ, HOME=str(home3), USERPROFILE=str(home3)), capture_output=True, text=True)
    after = st3.read_text(encoding="utf-8") if st3.exists() else None
