    (tmp / "scripts").mkdir(); (tmp / "scripts" / "lonely.py").write_text("x = 1\n", encoding="utf-8")
    spec2 = tmp / "p2.md"; spec2.write_text("# 計劃\n會改 scripts/lonely.py 這支。\n", encoding="utf-8")
