def t_delguard_logs_ok_too():
    """第二輪審視六修 d3:delguard 跑完也記一筆 kind=ok——之前只記 degraded,治理帳 63/63 全是超時,看起來像從沒守到(實測一般 commit 0.4 秒就跑完)。"""
    import subprocess as _sp, os, tempfile as _tf, json as _j
    root = Path(_tf.mkdtemp(prefix="gctl-dgok-")); vault = root / "docs" / "x-knowledge"; (vault / "Systems").mkdir(parents=True)
    (vault / "Systems" / "a.md").write_text("---\nname: a\n---\n# a\n呼叫 old_helper 做事。\n", encoding="utf-8")
    (root / "src").mkdir(); (root / "src" / "m.py").write_text("def old_helper():\n    return 1\n", encoding="utf-8")
    g = lambda *a: _sp.run(["git", "-C", str(root), *a], capture_output=True, text=True)
    g("init", "-q"); g("add", "-A"); g("-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "i")
    (root / "src" / "m.py").write_text("def new_helper():\n    return 1\n", encoding="utf-8"); g("add", "-A")
    r = _sp.run([sys.executable, GRAPHCTL, "delguard", "--staged"], cwd=str(root), capture_output=True, text=True, timeout=120)
    log = vault / ".." / ".governance-log.jsonl"
    log = (root / "docs" / ".governance-log.jsonl")
    txt = log.read_text(encoding="utf-8") if log.exists() else ""
    oks = [l for l in txt.splitlines() if '"gate": "delguard"' in l and '"kind": "ok"' in l]
    check("delguard ok 帳: 跑完記一筆 kind=ok(帶 tokens/hits/secs)", r.returncode == 0 and len(oks) == 1 and "tokens=" in oks[0] and "hits=" in oks[0], (r.stdout[-160:], txt[-200:]))
    # 外家 r1 M2 / r2 M:「掃描被截斷回部分結果」這條路 → 帳記 degraded(reason=timeout-partial)、--json degraded=true。
    # 不能用超小 deadline 去逼(那會在 git diff 後的早期檢查點就走舊的 _degraded_json 路,測到的不是這條修法——假綠形態);
    # 改成行程內 monkeypatch:讓 vault_scan 睡過 deadline 再呼叫 deadline_check(),模擬真的被截斷。
    import io as _io2, contextlib as _cl2, time as _tm
    from unittest.mock import patch as _patch
    m = _load_lumos_module(); cwd0 = os.getcwd()
    def fake_scan(tokens, conf, gr, deadline_check=None):
        _tm.sleep(1.2)
        if deadline_check is not None and deadline_check():
            return []
        return []
    try:
        os.chdir(str(root)); buf = _io2.StringIO()
        with _patch.object(m, "_delguard_vault_scan", fake_scan), _patch.dict(os.environ, {"LUMOS_DELGUARD_DEADLINE": "1.0"}), _cl2.redirect_stdout(buf), _cl2.redirect_stderr(_io2.StringIO()):
            rc2 = m.cmd_delguard_check(as_json=True)
    finally:
        os.chdir(cwd0)
    try:
        j2 = _j.loads(buf.getvalue().strip().splitlines()[-1])
    except Exception:
        j2 = {}
    txt2 = log.read_text(encoding="utf-8")
    partial = [l for l in txt2.splitlines() if '"gate": "delguard"' in l and "timeout-partial" in l]
    check("delguard 部分結果: 掃描被 deadline 截斷 → 帳記 degraded reason=timeout-partial 且 --json degraded=true+reason", rc2 == 0 and len(partial) == 1 and j2.get("degraded") is True and j2.get("reason") == "timeout-partial", (str(j2)[:160], txt2[-200:]))
    # 第三輪稽核:gov 呈現層要把同日多筆 delguard 帳折成 ×N(原條件要 detail 為空,永遠折不到)
    r3 = _sp.run([sys.executable, GRAPHCTL, "delguard", "--staged"], cwd=str(root), capture_output=True, text=True, timeout=120)
    g = _sp.run([sys.executable, GRAPHCTL, "gov", "--since", "1"], cwd=str(root), capture_output=True, text=True, timeout=120)
    n_ok_ledger = sum(1 for l in log.read_text(encoding="utf-8").splitlines() if '"gate": "delguard"' in l and '"kind": "ok"' in l)
    ok_rows = [l for l in g.stdout.splitlines() if "delguard/ok" in l]
    check("gov 折疊 delguard: 帳上兩筆同日 ok 在預設視圖只佔一行(折成一行,不洗版)", n_ok_ledger == 2 and len(ok_rows) == 1, (n_ok_ledger, g.stdout[-240:]))


def t_daily_governance_wrapper_is_function_wrapped():
    """第四輪稽核(2026-09-05):bash 邊讀邊執行,長跑的 wrapper 在跑時被改檔會讀到半行炸掉(當天實發生:自主迴圈 3 小時回來後 syntax error,
    後段全沒跑)。守衛三件(代碼審 r1 折入,Codex 外家席抓到首版只比三個字串、把主體搬回頂層也假綠):
    ①main() 之外只准前奏(shebang/註解/空行/set/DIR=/ts()/mkdir logs),任何呼叫子腳本或 python3 scripts/lumos 的行都必須在 main() 體內;
    ②最後一行必須是 main "$@"; exit 同一行(沒 exit → main 跑完 bash 回頭從舊 byte 位置續讀,檔長變了會讀垃圾甚至整支重跑,scratch 實驗實證);
    ③bash -n 過。"""
    import subprocess as _sp, re as _re
    p = Path(GRAPHCTL).resolve().parent.parent / "governance" / "daily-governance.sh"
    lines = p.read_text(encoding="utf-8").splitlines()
    starts = [i for i, l in enumerate(lines) if l.strip() == "main() {"]
    check("daily-governance: 恰有一個 main() {", len(starts) == 1, str(starts))
    if not starts:
        return
    ms = starts[0]
    me = next(i for i in range(ms + 1, len(lines)) if lines[i] == "}")  # 函式體結尾:頂格的 }
    body = "\n".join(lines[ms + 1:me])
    prelude_ok = _re.compile(r'^(#.*|\s*|set .*|DIR=.*|ts\(\) \{.*\}|mkdir -p "\$DIR/logs")$')
    bad_pre = [(i + 1, l) for i, l in enumerate(lines[:ms]) if not prelude_ok.match(l)]
    check("daily-governance: main() 之前只有前奏(shebang/註解/set/DIR/ts/mkdir),沒有可執行主體", not bad_pre, str(bad_pre[:3]))
    after = [(i + 1, l) for i, l in enumerate(lines[me + 1:], me + 1) if l.strip() and not l.lstrip().startswith("#") and l.strip() != 'main "$@"; exit']
    check("daily-governance: } 之後除註解只剩 main \"$@\"; exit 這一行", not after, str(after[:3]))
    check("daily-governance: 最後一行是 main \"$@\"; exit(exit 同一行,防回頭讀檔)", lines[-1].strip() == 'main "$@"; exit', lines[-1])
    calls = [l for l in lines if _re.search(r'"\$DIR/[a-z-]+\.sh"|python3 scripts/lumos', l) and not l.lstrip().startswith("#")]
    check("daily-governance: 所有子腳本/lumos 呼叫都在 main() 體內", calls and all(l in body for l in calls), f"{len(calls)} 個呼叫")
    # 通才席 r1 第二條:整步被刪也曾假綠。五步名冊釘死——要拿掉一步就得連這裡一起改(守衛的意思就是不能默默掉)。
    roster = ['"$DIR/ai-governance-research.sh"', '"$DIR/autonomous-loop.sh" --dry-run', '"$DIR/lint-watch-check.sh"', "python3 scripts/lumos doctor --ci", "python3 scripts/lumos testmap build"]
    missing = [r for r in roster if r not in body]
    check("daily-governance: 五步名冊(日報/自主迴圈/lint-watch/doctor --ci/testmap build)都在 main() 體內", not missing, str(missing))
    check("daily-governance: 收尾 echo 在體內", 'echo "[$(ts)] daily-governance wrapper 完成"' in body, "")
    r = _sp.run(["bash", "-n", str(p)], capture_output=True, text=True)
    check("daily-governance: bash -n 語法過", r.returncode == 0, r.stderr[:160])


def t_license_headers_travel_with_vendored_files():
    """授權標示必須跟著「會被複製進別人專案」的檔案走(2026-09-06 定 MIT)。

    為什麼要機械守:根目錄的 LICENSE ★刻意不在 _VENDORED_TOOLKIT 白名單裡★——deinit 會對白名單
    每一項刪檔,加進去等於在消費專案刪掉使用者自己的 LICENSE。所以合規完全靠檔頭,而檔頭是靠人手
    維持的東西,重構或 slim-gen 改寫時最容易被靜默弄丟。

    ★這支測試被打臉四次才長成現在這樣,每一次的壞例子都留在下面的斷言裡★:
      r1 外家席:白名單裡塞「含右括號的註解」→ 掃原始碼字串的版本假綠;
      r1 通才席:白名單改成「兩個 tuple 相加」→ 換成語法樹解析還是假綠;
      r1 架構對齊席:同檔 t_precommit_whitelist_drift_guard 早有更好寫法——載入模組讀執行期真值;
      合約獨立審計:①在 scripts/hooks/ 頂層(不是 claude/ 底下)新增一支沒標示的檔,會被真的複製
      出去,而手寫的清單掃不到 → 改成跟 _vendor_toolchain 同一套邏輯算;②MIT「全文」原本只比對兩
      句片語,把中段整個換掉照樣綠 → 改成跟根目錄 LICENSE 的 MIT 正文逐行比對。
    (合約 1 的「deinit 不得刪掉使用者的 LICENSE」另有端到端測試 t_deinit_never_deletes_user_license,
     因為只驗白名單內容是必要非充分——繞過白名單直接刪檔這支測試看不到,審計實測過。)"""
    import re as _re
    _spdx = _re.compile(r"^#\s*SPDX-License-Identifier:\s*MIT\s*$", _re.M)
    _who = _re.compile(r"^#\s*SPDX-FileCopyrightText:", _re.M)
    root = Path(GRAPHCTL).resolve().parent.parent
    main = (root / "scripts" / "lumos").read_text(encoding="utf-8")
    head = lambda text, n=45: "\n".join(text.splitlines()[:n])
    m = _load_lumos()

    # [KEY 2 之一] 主程式檔頭:SPDX 註解行 + MIT 正文逐行比對(不是片語比對)
    check("授權/KEY2: 主程式檔頭有 SPDX 標示(必須是註解行)",
          bool(_spdx.search(head(main))) and bool(_who.search(head(main))), head(main, 6))
    lic_path = root / "LICENSE"
    check("授權: 根目錄有 LICENSE 且是 MIT", lic_path.is_file() and "MIT License" in lic_path.read_text(encoding="utf-8"), str(lic_path))
    lic = lic_path.read_text(encoding="utf-8") if lic_path.is_file() else ""
    body = [ln.strip() for ln in lic.split("Permission is hereby granted", 1)[-1].split("---")[0].splitlines() if ln.strip()]
    hdr_txt = "\n".join(ln.lstrip("#").strip() for ln in main.splitlines()[:60])
    missing_lines = [ln for ln in body if ln not in hdr_txt]
    check("授權/KEY2: 主程式檔頭的 MIT 正文與根目錄 LICENSE 逐行相符(不是只比兩句片語)",
          bool(body) and not missing_lines, f"缺 {len(missing_lines)} 行: {missing_lines[:2]}")

    # [KEY 2 之二] 會被複製出去的檔案集合★跟生產邏輯同一套算法★,不是手寫清單
    # 安裝端 2026-09-10 起只複製這份精確清單(第三輪外家否決席:原本整個目錄 rglob,連沒進版控的檔也裝)
    targets = list(getattr(m, "_VENDORED_ALL", []))
    # 紀律模板刻意不加標頭:它會被合併進消費端自己的 CLAUDE.md/AGENTS.md,標頭會落進使用者的檔案
    exempt = {"scripts/templates/graph-discipline.md"}
    targets = sorted(set(targets) - exempt)
    check("授權/KEY2: 會被複製出去的檔案集合算得出來且非空", len(targets) >= 12, f"{len(targets)} 支")
    missing = [f for f in targets if (root / f).is_file() and not _spdx.search(head((root / f).read_text(encoding="utf-8", errors="replace")))]
    check("授權/KEY2: 每支會被複製進消費專案的檔都帶 SPDX 標示", not missing, str(missing))

    # [KEY 1] 授權檔不得進白名單(讀執行期真值,不掃原始碼字串)
    wl = list(getattr(m, "_VENDORED_TOOLKIT", []))
    check("授權/KEY1: _VENDORED_TOOLKIT 讀得到且非空", bool(wl) and all(isinstance(x, str) for x in wl), str(wl)[:160])
    bad = [x for x in wl if Path(x).name in ("LICENSE", "COPYING", "NOTICE")]
    check("授權/KEY1: ★授權檔不得進 _VENDORED_TOOLKIT★(白名單內容面)", not bad, str(bad) or str(wl)[:120])


def t_deinit_never_deletes_user_license():
    """★端到端★:在消費專案跑 deinit,使用者自己的 LICENSE / COPYING / NOTICE 必須原封不動。

    出身(2026-09-06 合約獨立審計):只驗「白名單裡沒有 LICENSE」是必要非充分——審計員完全不碰
    白名單,直接在 _deinit_remove_vendored 開頭加一行刪 LICENSE,原本那支測試 6/6 全綠、什麼都
    沒發現。所以這裡不看白名單長怎樣,直接跑真的移除流程,再確認檔案還在。"""
    from pathlib import Path as _P
    m = _load_lumos()
    src = _mk_f9_src("gctl-lic-src-")
    root = _P(tempfile.mkdtemp(prefix="gctl-lic-deinit-"))
    sc = root / "scripts"
    (sc / "hooks" / "claude").mkdir(parents=True)
    (sc / "templates").mkdir(parents=True)
    (sc / "hooks" / "pre-commit").write_text("#!/bin/sh\n")
    (sc / "hooks" / "claude" / "impact-hook.py").write_text("#x\n")
    (sc / "templates" / "graph-discipline.md").write_text("tpl\n")
    for rel in m._VENDORED_TOOLKIT:
        (root / rel).parent.mkdir(parents=True, exist_ok=True)
        (root / rel).write_text("x\n")
    user_files = {"LICENSE": "MIT License\n\nCopyright (c) 2026 消費專案自己的人\n",
                  "COPYING": "GPL-3.0\n", "NOTICE": "our notice\n"}
    for name, txt in user_files.items():
        (root / name).write_text(txt, encoding="utf-8")

    m._deinit_remove_vendored(root, src)

    for name, txt in user_files.items():
        p = root / name
        check(f"deinit: 使用者自己的 {name} 必須留著且內容未變", p.is_file() and p.read_text(encoding="utf-8") == txt,
              f"exists={p.exists()}")
    check("deinit: 確實有在做事(vendored 主程式已移除),不是空跑", not (sc / "lumos").exists(), "")


def t_delguard_excludes_prose_dirs():
    """delguard 不掃 governance/ 與 docs/,★但那兩夾絕對不能進 pre-commit 的硬閘豁免★
    (2026-09-06 全 repo 審視第二批;代碼審 r1 通才席判 blocker 後重寫)。

    出身:治理帳上 30% 的 delguard 執行是「逾時降級」——守衛在半盲狀態下擋人。原以為跟 token
    數有關,量出來是跟★命中行數★成正比(6 詞/835 命中=9.7 秒、10 詞/1615 命中=14 秒,而預算
    就是 15 秒)。真因是掃進了審查卷證與治理帳:四個常用詞全 repo 命中 75587 行、7.17 秒,
    排除後 7336 行、0.47 秒。

    ★blocker 的教訓:兩份清單語意不同,不可以互抄★——delguard 那份是「哪裡不算活著的程式」,
    pre-commit 的 should_exclude 是「哪些檔改了不必配圖譜」。第一版為了滿足既有的漂移守衛,
    把 governance/ 一起抄進 pre-commit,結果 governance/ 底下 28 支真程式全部從「改 code 沒動
    圖譜就擋」的硬閘掉出去(審查席在乾淨 clone 實測重現)。所以拆成兩個常數,並在這裡釘死
    「散文清單不得出現在硬閘那一行」。

    這支測試★驗行為不只驗常數★:餵一份假 diff 給真正的解析函式,確認治理目錄的改動不會被
    收成 token(r1 通才席實測:只比對常數的版本,把 excl 寫死成 False 也照樣全綠)。"""
    m = _load_lumos()
    ex = list(getattr(m, "_DELGUARD_EXCLUDE_DIRS", []))
    prose = list(getattr(m, "_DELGUARD_PROSE_DIRS", []))
    allx = list(getattr(m, "_DELGUARD_ALL_EXCLUDE_DIRS", []))
    for d in ("governance/", "docs/"):
        check(f"delguard: 散文清單含 {d}", d in prose, str(prose))
    check("delguard: 合併清單 = 建置產物 + 散文", set(allx) == set(ex) | set(prose), str(allx))
    # ★硬閘那一行不得含 governance★(docs/* 是它本來就有的,不是這次加的)
    hooks_dir = Path(GRAPHCTL).resolve().parent / "hooks"
    case_line = [l for l in (hooks_dir / "pre-commit").read_text(encoding="utf-8").splitlines()
                 if "node_modules" in l and "case" not in l][0]
    check("delguard: ★pre-commit 的硬閘豁免不得含 governance★(那底下有真程式,豁免=改 code 不配圖譜也放行)",
          "governance" not in case_line, case_line[:140])
    # 行為面:餵真的 diff 文字給解析器,治理目錄的加號行不得被收成 token
    # delguard 抽的是被★刪掉★的識別字(減號行)。餵一份兩個檔各刪一個符號的假 diff:
    # 治理目錄那個不該被抽出來,一般程式那個要照抽——這樣才驗得到排除真的在起作用。
    diff = ("diff --git a/governance/autonomous_loop/gap_select.py b/governance/autonomous_loop/gap_select.py\n"
            "--- a/governance/autonomous_loop/gap_select.py\n"
            "+++ b/governance/autonomous_loop/gap_select.py\n"
            "@@ -1,3 +1,2 @@\n"
            "-def zzzGovernanceOnlySymbol():\n"
            "diff --git a/scripts/thing.py b/scripts/thing.py\n"
            "--- a/scripts/thing.py\n"
            "+++ b/scripts/thing.py\n"
            "@@ -1,3 +1,2 @@\n"
            "-def zzzRealCodeSymbol():\n")
    toks = m._delguard_parse_diff(diff, "docs/lumos-toolchain-knowledge")["tokens"]
    check("delguard/行為: 治理目錄刪掉的符號沒被抽成 token(排除真的在起作用)",
          "zzzGovernanceOnlySymbol" not in toks, str(toks)[:200])
    check("delguard/行為: 一般程式刪掉的符號照樣抽(不是整個關掉)",
          "zzzRealCodeSymbol" in toks, str(toks)[:200])

def t_doctor_summary_admits_soft_reminders():
    """doctor 收尾行不得比正文樂觀(2026-09-06 全 repo 審視第二批;五個鏡頭各自撞到同一件事)。

    出身:實跑當天上面列了 5 件回訪逾期、5 份驗證引用被翻案的決策、1 張零判定的連鎖單、1 條失效
    路徑、沒接 linter,尾行仍印「✓ 圖譜健康 — 0 issues」,人和 AI 都會停在那一行。而且 9/1 起
    129 次 doctor 全部 issues=0,那幾件一件都沒被清掉。

    ★軟提醒不進 rc 是既有裁定,這裡不動它★——只要求結論行把「還有幾段沒算進來」講出來。
    計數放在 warn 與 warn_soft 的共用層:Check F 那種「沒有逐條、只有一句」的走 warn([]),
    issues 加 0,只數 warn_soft 會漏掉它。"""
    import subprocess as _sp
    root = Path(GRAPHCTL).resolve().parent.parent
    r = _sp.run([sys.executable, GRAPHCTL, "doctor"], capture_output=True, text=True, cwd=str(root))
    out = r.stdout
    check("doctor: 既有結論行 token 沒被動到(四處測試錨著)", "圖譜健康" in out or "個 issue" in out, out[-160:])
    check("doctor: 結論行帶「篇)」", "篇)" in out, out[-160:])
    import re as _re
    # ★只數分隔線之前的★:收尾那句自己也用 ⚠(跟該檔既有慣例一致),整份數會多算一
    body_out = out.split("─────")[0] if "─────" in out else out
    warn_printed = body_out.count("  ⚠ ")     # 硬問題與軟提醒印的是同一種行
    hard = _re.search(r"發現 (\d+) 個 issue", out)
    n_hard = int(hard.group(1)) if hard else 0
    tail_has = "提醒沒算進上面那個數字" in out
    check("doctor: 有軟提醒時,收尾行必須講還有幾段沒算進來",
          (warn_printed == 0) or tail_has, f"印了 {warn_printed} 段 ⚠,收尾行有交代={tail_has}")
    if tail_has:
        m = _re.search(r"另有 (\d+) 段", out)
        n_soft = int(m.group(1)) if m else -1
        # ★不能拿「所有 ⚠ 行」當軟提醒數★(代碼審 r1 通才席實測:repo 一有普通壞連結就會多一段
        # 硬 ⚠,測試會在產品沒壞的情況下翻紅)。硬問題已經算進「N 個 issue」,不該重複計。
        # 這裡只斷言關係:軟段數必須介於 0 與總 ⚠ 段數之間,且「軟 + 硬段」不超過總 ⚠ 段數。
        check("doctor: 收尾行的軟段數落在合理範圍(不重複計硬問題)",
              0 <= n_soft <= warn_printed, f"軟 {n_soft} / 總 ⚠ {warn_printed} / 硬 issue {n_hard}")
        if n_hard == 0:
            check("doctor: 沒有硬問題時,軟段數 = 印出的 ⚠ 段數(數字是算的不是手寫)",
                  n_soft == warn_printed, f"收尾說 {n_soft} / 實印 {warn_printed}")
    # 治理帳也要記得下這個數字。★不能對來源 repo 跑 doctor --ci 來驗★(r1 外家席:那會 append
    # 受版控的 docs/.governance-log.jsonl,每跑一次測試就在工作樹留一筆、帳本持續膨脹)。隔離
    # vault 也寫不出帳(寫者取不到可解析的 git HEAD 就靜默跳過)。所以退一步、★誠實標明證據層級★:
    # 這條只驗「欄位有接上」是原始碼事實,不驗執行期的值——值的正確性由上面那幾條斷言涵蓋,
    # 它們比對的是真的跑出來的畫面。
    main_src = (root / "scripts" / "lumos").read_text(encoding="utf-8")
    note_line = [l for l in main_src.splitlines() if "issues={issues}" in l]
    check("doctor: doctor-run 事件的 note 有接上 soft= 欄位(原始碼層;值的正確性由上面的畫面斷言涵蓋)",
          bool(note_line) and any("soft=" in l for l in note_line), str(note_line)[:160])
def t_autoloop_pause_only_stops_dispatch():
    """暫停派工不得把週期觀測一起關掉(2026-09-06 全 repo 審視 #4)。

    出身:2026-09-05 決定暫停派工時,開關寫在 daily-governance.sh 裡包住整支 autonomous-loop.sh,
    結果檢索考卷、情境探針、空轉提醒與 14 天升級鏈、回放週跑、backlog 每日衰減這五段一起停了
    ——而三處筆記白紙黑字寫著「便宜的日常段照跑」。★監看的東西和被監看的東西同命★:回訪到期
    的升級鏈因此沒有出口,那正是同一次審視裡「五件逾期沒人管」的上游原因。

    修法照世界解(feature toggle 只包真正要停的最小單元):開關搬進 autonomous-loop.sh、放在
    選 gap 之前;wrapper 無條件呼叫。這裡釘死那個相對位置——用位置而不是「跑一次看看」,是因為
    真跑會發 LINE、抽探針、燒配額,不適合放進單元測試。"""
    root = Path(GRAPHCTL).resolve().parent.parent
    loop = (root / "governance" / "autonomous-loop.sh").read_text(encoding="utf-8")
    wrap = (root / "governance" / "daily-governance.sh").read_text(encoding="utf-8")
    lines = loop.splitlines()
    def line_of(pat, start=0):
        return next((k for k, l in enumerate(lines) if k >= start and pat in l and not l.lstrip().startswith("#")), -1)
    # 五段週期觀測的「呼叫點」(不是函式定義):都在檔案後段、彼此相鄰
    calls = {}
    for name in ("run_exam", "run_probe", "run_nags", "run_replay"):
        k = next((i for i, l in enumerate(lines)
                  if l.strip().startswith(name + " ") or l.strip() == name
                  or (name in l and l.strip().startswith("[ -d"))), -1)
        calls[name] = k
        check(f"暫停開關: 找得到 {name} 的呼叫點", k > 0, str(k))
    decay = line_of("backlog 衰減")
    check("暫停開關: 找得到 backlog 每日衰減", decay > 0, str(decay))
    gate = next((i for i, l in enumerate(lines) if "LUMOS_AUTOLOOP_OFF" in l and l.strip().startswith("if ")), -1)
    check("暫停開關: autonomous-loop.sh 自己帶 LUMOS_AUTOLOOP_OFF 判斷", gate > 0, str(gate))
    if gate > 0:
        after = {k: v for k, v in list(calls.items()) + [("backlog衰減", decay)] if v > gate}
        check("暫停開關: ★所有週期觀測都排在開關之前(關掉派工不會連它們一起關)★", not after, str(after))
    # wrapper 那側不得再自己判一次(否則等於又把整支包起來)
    wrap_gate = [l for l in wrap.splitlines() if "LUMOS_AUTOLOOP_OFF" in l and l.strip().startswith("if ")]
    check("暫停開關: ★wrapper 不得再包一層判斷★(那正是 09-05 的錯法)", not wrap_gate, str(wrap_gate)[:120])
    check("暫停開關: wrapper 無條件呼叫 autonomous-loop.sh",
          any('"$DIR/autonomous-loop.sh"' in l and not l.lstrip().startswith("#") for l in wrap.splitlines()), "")
    # ★只釘位置會假綠★(r1 外家席):在第一個觀測之前插一行 exit 0,或把 gate 改成永遠不成立,
    # 位置斷言照樣過。這裡再加兩條:①開關之前不得有任何無條件的 exit;②gate 用的是真的環境
    # 變數判斷而不是寫死的常數。
    before = lines[:gate] if gate > 0 else []
    stray_exit = [(i + 1, l) for i, l in enumerate(before)
                  if l.strip() in ("exit 0", "exit") and not l.lstrip().startswith("#")]
    check("暫停開關: 開關之前沒有無條件的 exit(否則觀測根本走不到)", not stray_exit, str(stray_exit[:3]))
    gate_line = lines[gate] if gate > 0 else ""
    check("暫停開關: 判斷讀的是環境變數 LUMOS_AUTOLOOP_OFF(不是寫死的值)",
          "${LUMOS_AUTOLOOP_OFF" in gate_line, gate_line.strip()[:100])
    # ③ 首次執行不得立刻燒配額抽探針(r1 外家席:wrapper 改無條件之後,沒有歷史的機器會當天就抽 8 題)
    check("暫停開關: 探針對「沒有任何歷史」的機器先不抽(免得裝好當天燒配額)",
          "首次執行" in loop and "-s \"$hist\"" in loop, "")
    # ★④ gate 的身體裡必須真的離開★(r1 通才席實測:把 exit 0 拿掉、只留 if 和 log,
    #   暫停就變成什麼都不做、派工每天照跑,而上面所有位置斷言仍然全綠)
    if gate > 0:
        end = next((k for k in range(gate + 1, len(lines)) if lines[k].strip() == "fi"), -1)
        body = lines[gate + 1:end] if end > gate else []
        check("暫停開關: ★gate 的身體裡真的有離開動作★(不然暫停等於沒暫停)",
              any(l.strip() in ("exit 0", "exit", "return 0") for l in body), str([l.strip()[:40] for l in body]))
    # ★⑤ 行為面:真的跑一次,派工不得啟動★——用假的 gap 選擇器當金絲雀:只要派工段有跑到,
    #   它就會被呼叫並留下痕跡。避免真跑 claude(改 PATH 讓 claude 不可見,探針自然跳過)。
    import os as _os, subprocess as _sp, shutil as _sh, tempfile as _tf
    sand = Path(_tf.mkdtemp(prefix="gctl-autoloop-"))
    _sh.copytree(root / "governance", sand / "governance", dirs_exist_ok=True,
                 ignore=_sh.ignore_patterns("__pycache__", "logs", "review-reports", "replay", "eval", "reports"))
    (sand / "governance" / "logs").mkdir(parents=True, exist_ok=True)
    # 沒有日報的話腳本會在到達 gate 之前就結束,金絲雀會「因為根本沒跑到」而假過——
    # 補一份最小日報,讓它真的走到派工那一步(r1 通才席指出的同一種假綠,自查時撞到)
    (sand / "governance" / "reports").mkdir(parents=True, exist_ok=True)
    (sand / "governance" / "reports" / "governance-2026-01-01.json").write_text(
        '{"items": []}', encoding="utf-8")
    canary = sand / "governance" / ".dispatch-canary"
    sh = sand / "governance" / "autonomous-loop.sh"
    txt = sh.read_text(encoding="utf-8").replace(
        "SKIP_CAP=3; skip_n=0", f'touch "{canary}"\nSKIP_CAP=3; skip_n=0', 1)
    sh.write_text(txt, encoding="utf-8")
    env = dict(_os.environ, HOME=str(sand), PATH="/usr/bin:/bin", LUMOS_AUTOLOOP_OFF="1")
    r = _sp.run(["bash", str(sh), "--dry-run", "6"], cwd=str(root), env=env,
                capture_output=True, text=True, timeout=300)
    out = r.stdout + r.stderr
    # ★先確認它真的走到那一步★(不然金絲雀是「因為根本沒跑到」而過的,零鑑別力)
    check("暫停開關/行為: 腳本真的走到暫停判斷(不是提早結束)", "暫停中" in out, out[-260:])
    check("暫停開關/行為: ★OFF=1 真跑一次,派工段沒有被執行到★", not canary.exists(), out[-200:])
    # 反面:OFF=0 時派工段必須跑得到(證明金絲雀本身有鑑別力)
    env0 = dict(env, LUMOS_AUTOLOOP_OFF="0")
    _sp.run(["bash", str(sh), "--dry-run", "6"], cwd=str(root), env=env0,
            capture_output=True, text=True, timeout=300)
    check("暫停開關/行為: ★OFF=0 時派工段跑得到★(金絲雀有鑑別力,不是恆不存在)",
          canary.exists(), "canary 未出現=這條斷言本身沒有鑑別力")


def t_update_syncs_global_from_fresh_not_stale():
    """`lumos update` 同步全域 hooks 時,來源必須是★更新後★的檔(2026-09-06 全 repo 審視 #5)。

    出身:_vendor_toolchain 裡 _install_hooks_py(它同時做 core.hooksPath 與全域同步)排在
    filecmp 自癒迴圈★之前★,於是 update 會拿「更新前」的 vendored 舊副本去覆蓋整台機器的
    ~/.claude/hooks——實測把收工 hook 從 30912B 換成六月版的 15303B,訊息還印綠燈;舊版的
    settings merger 甚至會把已撤除的 hook 註冊加回去。修法:把那支拆成 _set_hooks_path(留在
    原位)與 _sync_global_from_project(搬到自癒之後)。

    這裡用反事實夾具驗:專案的 vendored hook 是舊的、來源是新的,update 完之後全域那份必須
    等於★來源★。

    ★為什麼開子行程,不用同檔既有的 in-process 路線★(r1 架構對齊席問的):這條要驗的是
    「全域同步發生在自癒之後」,而全域同步會寫 ~/.claude —— 必須靠 env 假造 HOME 隔離,
    in-process 直呼改不了子行程看到的 HOME。既有的 _mk_vendor_src/_run_vendor 是為
    「_vendor_toolchain 自己的行為」寫的,不涵蓋全域那一半。"""
    import os, subprocess as _sp, shutil
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).resolve().parent.parent
    base = _P(tempfile.mkdtemp(prefix="gctl-upd-fresh-"))
    src, proj, home = base / "src", base / "proj", base / "home"
    for d in (src / "scripts" / "hooks" / "claude", src / "docs", proj / "scripts" / "hooks" / "claude",
              proj / "docs" / "p-knowledge" / "Systems", home):
        d.mkdir(parents=True, exist_ok=True)
    for f in ("lumos", "install-graph-toolchain.sh"):
        shutil.copy2(repo / "scripts" / f, src / "scripts" / f)
    hook_rel = "scripts/hooks/claude/check-graph-sync.py"
    shutil.copy2(repo / hook_rel, src / hook_rel)
    _sp.run(["git", "init", "-q", "."], cwd=str(src))
    (proj / hook_rel).write_text("OLD-STALE-COPY\n", encoding="utf-8")
    shutil.copy2(repo / "scripts" / "lumos", proj / "scripts" / "lumos")
    _sp.run(["git", "init", "-q", "."], cwd=str(proj))
    env = dict(os.environ, HOME=str(home), USERPROFILE=str(home))
    env.pop("CODEX_HOME", None)
    r = _sp.run([sys.executable, "scripts/lumos", "update", "--source", str(src), "--no-pull"],
                cwd=str(proj), env=env, capture_output=True, text=True)
    glob_hook = home / ".claude" / "hooks" / "check-graph-sync.py"
    check("update: 全域 hook 有被同步出來", glob_hook.is_file(), r.stdout[-200:] + r.stderr[-200:])
    if glob_hook.is_file():
        got, want, stale = glob_hook.read_bytes(), (src / hook_rel).read_bytes(), b"OLD-STALE-COPY\n"
        check("update: ★全域 hook == 來源的新版★(不是更新前的舊副本)", got == want, f"len={len(got)} want={len(want)}")
        check("update: 全域 hook 不是那份舊副本", got != stale, "")
    check("update: 專案 vendored hook 也被自癒成新版",
          (proj / hook_rel).read_bytes() == (src / hook_rel).read_bytes(), "")


def t_update_unions_bookkeeping_instead_of_blocking():
    """來源 clone 只髒了工具自己寫的 append-only 帳時,update 不該被擋,也不該弄壞帳本。

    出身(2026-09-06 全 repo 審視 #5):唯讀的 `lumos show`/`context` 就會 append
    docs/.usage-log.jsonl,而那本帳是版控的。只要有人在來源 clone 裡查過一次圖譜,之後這台
    機器所有專案的 update 都被 fail-closed 擋住,逃生門寫在錯誤訊息最後一行沒人讀得到。

    ★第一版用 stash/pop,實測會在帳本裡留下 <<<<<<< 衝突標記——比原本擋住更糟★。
    改成聯集合併:本機那份讀進記憶體 → checkout 回 HEAD → pull → 把本機獨有的行補回去。
    這裡驗三件:pull 有成功、兩邊的行都在、檔案裡沒有衝突標記。

    ★為什麼開子行程★:要真的有 origin/clone/第三方推送三個 repo 才造得出「來源落後且本機
    髒」這個情境,既有的 _mk_vendor_src 撐不到(它造的是無 remote 的假來源);而且這條路會
    寫 ~/.claude,同樣要靠 env 假造 HOME 隔離。"""
    import os, subprocess as _sp, shutil
    from pathlib import Path as _P
    repo = _P(GRAPHCTL).resolve().parent.parent
    base = _P(tempfile.mkdtemp(prefix="gctl-upd-union-"))
    origin, seed, home = base / "origin", base / "seed", base / "home"
    ident = ["-c", "user.name=t", "-c", "user.email=t@t"]
    origin.mkdir(parents=True); _sp.run(["git", "init", "-q", "--bare", "."], cwd=str(origin))
    # ★裸倉庫的 HEAD 要指到我們真的會推的分支★(2026-09-06 CI 紅):不同機器的 init.defaultBranch
    # 不一樣(本機 main、CI 預設 master)。HEAD 指到不存在的分支時,clone 出來是空工作樹、
    # 只印一行 warning 就過去了,夾具於是靜默壞掉、測試在別的地方丟 FileNotFoundError。
    _sp.run(["git", "symbolic-ref", "HEAD", "refs/heads/main"], cwd=str(origin))
    (seed / "scripts" / "hooks" / "claude").mkdir(parents=True); (seed / "docs").mkdir(parents=True)
    for f in ("lumos", "install-graph-toolchain.sh"):
        shutil.copy2(repo / "scripts" / f, seed / "scripts" / f)
    hook_rel = "scripts/hooks/claude/check-graph-sync.py"
    shutil.copy2(repo / hook_rel, seed / hook_rel)
    (seed / "docs" / ".usage-log.jsonl").write_text('{"ts":"1"}\n', encoding="utf-8")
    _sp.run(["git", "init", "-q", "-b", "main", "."], cwd=str(seed))
    _sp.run(["git", "add", "-A"], cwd=str(seed))
    _sp.run(["git"] + ident + ["commit", "-qm", "init"], cwd=str(seed))
    _sp.run(["git", "remote", "add", "origin", str(origin)], cwd=str(seed))
    _sp.run(["git", "push", "-q", "-u", "origin", "main"], cwd=str(seed))
    other = base / "other"; _sp.run(["git", "clone", "-q", str(origin), str(other)])
    # ★夾具沒建起來就大聲說★——別讓它在後面用一個 FileNotFoundError 表現(那看起來像產品壞了)
    check("update/來源髒帳: 夾具建得起來(clone 拿得到檔案)", (other / hook_rel).is_file(),
          f"clone 後缺檔:{sorted(q.name for q in other.iterdir()) if other.is_dir() else '目錄不存在'}")
    if not (other / hook_rel).is_file():
        return
    with open(other / hook_rel, "a", encoding="utf-8") as fh: fh.write("v2\n")
    with open(other / "docs" / ".usage-log.jsonl", "a", encoding="utf-8") as fh: fh.write('{"ts":"2"}\n')
    _sp.run(["git"] + ident + ["commit", "-qam", "v2"], cwd=str(other))
    _sp.run(["git", "push", "-q"], cwd=str(other))
    src = base / "src"; _sp.run(["git", "clone", "-q", str(origin), str(src)])
    with open(src / "docs" / ".usage-log.jsonl", "a", encoding="utf-8") as fh: fh.write('{"ts":"LOCAL"}\n')
    proj = base / "proj"; (proj / "scripts").mkdir(parents=True)
    (proj / "docs" / "p-knowledge" / "Systems").mkdir(parents=True)
    shutil.copy2(repo / "scripts" / "lumos", proj / "scripts" / "lumos")
    _sp.run(["git", "init", "-q", "."], cwd=str(proj))
    home.mkdir(parents=True, exist_ok=True)
    env = dict(os.environ, HOME=str(home), USERPROFILE=str(home)); env.pop("CODEX_HOME", None)
    r = _sp.run([sys.executable, "scripts/lumos", "update", "--source", str(src)],
                cwd=str(proj), env=env, capture_output=True, text=True)
    led = (src / "docs" / ".usage-log.jsonl").read_text(encoding="utf-8")
    check("update/來源髒帳: 整條 update 成功收尾(看真的 rc,不是只比字串)",
          r.returncode == 0 and "擋下:工具鏈來源拉不到最新版" not in r.stderr,
          f"rc={r.returncode} {r.stderr[-200:]}")
    check("update/來源髒帳: 本機那行沒丟", '{"ts":"LOCAL"}' in led, led[:200])
    check("update/來源髒帳: 遠端那行也拉進來了", '{"ts":"2"}' in led, led[:200])
    check("update/來源髒帳: ★帳本裡沒有衝突標記★(stash/pop 版會留)", "<<<<<<<" not in led and ">>>>>>>" not in led, led[:200])
    check("update/來源髒帳: 來源的 hook 拿到新版", "v2" in (src / hook_rel).read_text(encoding="utf-8"), "")
    check("update/來源髒帳: 全域 hook 也同步到新版(不是只有專案端)",
          "v2" in (home / ".claude" / "hooks" / "check-graph-sync.py").read_text(encoding="utf-8")
          if (home / ".claude" / "hooks" / "check-graph-sync.py").exists() else False, "")
    # ★重複行不得被吃掉★(r1 外家席):JSONL 是事件序列不是集合。再跑一次,這次本機加兩筆
    # 內容跟遠端已有的完全相同的行——正確行為是補回 2 份(遠端 1 + 本機 2 = 3 份)。
    with open(other / "docs" / ".usage-log.jsonl", "a", encoding="utf-8") as fh: fh.write('{"ts":"DUP"}\n')
    _sp.run(["git"] + ident + ["commit", "-qam", "dup"], cwd=str(other)); _sp.run(["git", "push", "-q"], cwd=str(other))
    with open(src / "docs" / ".usage-log.jsonl", "a", encoding="utf-8") as fh: fh.write('{"ts":"DUP"}\n{"ts":"DUP"}\n')
    r2 = _sp.run([sys.executable, "scripts/lumos", "update", "--source", str(src)],
                 cwd=str(proj), env=env, capture_output=True, text=True)
    led2 = (src / "docs" / ".usage-log.jsonl").read_text(encoding="utf-8")
    check("update/來源髒帳: ★合法的重複帳列沒被去重吃掉★(遠端 1 + 本機 2 = 3 份)",
          led2.count('{"ts":"DUP"}') == 3, f"實際 {led2.count('{\"ts\":\"DUP\"}')} 份;rc={r2.returncode}")



def t_prepush_blocks_uncommitted_anchor_baseline():
    """簽名檔改過沒提交就推 → 推送前的閘要擋(2026-09-06,CI 真的因此紅過一次)。

    出身:折完代碼審要推,推送前的閘擋我「把關檔改過沒簽名」,我簽了名、把改動 commit 了
    ——但只 `git add docs/`,而簽名檔在 `governance/` 底下,沒進去。
    ★推送前的閘拿「工作目錄現在的樣子」驗,所以綠;CI 拿「已經推上去的內容」驗,所以紅。★
    更糟的是 CI 的錯誤訊息叫你「再簽一次名」,再簽也沒用,因為問題是沒提交。

    這支是行為測試不是字串比對:真的搭一個 repo、真的把簽名檔弄髒、真的跑那支 hook。"""
    import subprocess, os, shutil
    if not hasattr(os, "setsid"):
        raise _SrcOnly("非 POSIX(要 os.setsid 跑 hook),這段沒驗到")
    src = Path(GRAPHCTL).resolve()
    hook_src = src.parent / "hooks" / "pre-push"
    if not hook_src.is_file():
        raise _SrcOnly("消費端沒有 pre-push(非來源 repo),這段沒驗到")

    root = Path(tempfile.mkdtemp(prefix="gctl-ppbase-"))
    (root / "scripts").mkdir()
    (root / "governance").mkdir()
    shutil.copy2(src, root / "scripts" / "lumos")
    shutil.copy2(hook_src, root / "pre-push")
    subprocess.run(["git", "-C", str(root), "init", "-q"], capture_output=True)
    subprocess.run(["git", "-C", str(root), "config", "user.email", "t@t"], capture_output=True)
    subprocess.run(["git", "-C", str(root), "config", "user.name", "t"], capture_output=True)
    # 產一份對得上的簽名檔並提交(讓第一道 anchor verify 過得去)
    subprocess.run([sys.executable, str(root / "scripts" / "lumos"), "anchor", "approve",
                    "--note", "fixture"], cwd=str(root), capture_output=True)
    base = root / "governance" / "anchor-baseline.json"
    check("prepush-baseline: fixture 真的產出簽名檔了(沒產出的話下面兩段等於沒驗)",
          base.is_file(), str(base))
    subprocess.run(["git", "-C", str(root), "add", "-A"], capture_output=True)
    subprocess.run(["git", "-C", str(root), "commit", "-qm", "init"], capture_output=True)

    def run_hook():
        return subprocess.run(["bash", str(root / "pre-push")], cwd=str(root),
                              capture_output=True, text=True, stdin=subprocess.DEVNULL)

    # ① 乾淨狀態:不該因為「簽名檔沒提交」被擋
    clean = run_hook()
    check("prepush-baseline/反面: 簽名檔已提交時不報這個錯",
          "簽名檔改過了但沒提交" not in clean.stderr, clean.stderr[-200:])

    # ② 把簽名檔弄成「改過沒提交」(加個尾空白,JSON 照樣讀得動 → 第一道 anchor verify 仍會過)
    base.write_text(base.read_text(encoding="utf-8") + "\n", encoding="utf-8")
    dirty = run_hook()
    check("prepush-baseline: 簽名檔改過沒提交 → 擋下(rc≠0)", dirty.returncode != 0,
          f"rc={dirty.returncode} {dirty.stderr[-200:]}")
    check("prepush-baseline: 訊息講清楚是「沒提交」而不是叫人再簽一次名",
          "簽名檔改過了但沒提交" in dirty.stderr and "git add" in dirty.stderr,
          dirty.stderr[-300:])


def t_prepush_runs_both_test_files():
    """推送前的閘必須把兩支測試檔都跑過(2026-09-06 全 repo 審視;CI 因此紅過一次)。

    出身:我把派工段的暫停開關改成預設開啟,跑了關鍵字子集就推,結果 CI 紅在
    scripts/test_autonomous_loop.py(那 132 支整組驗派工行為,被暫停擋掉)。推送前的閘
    一直以來只跑 test_lumos.py,另一支只有 CI 跑——★紅在別支檔而不是你改的那支,是最難
    查的那種★。那支只要 12 秒,沒有不跑的理由。"""
    hook = (Path(GRAPHCTL).resolve().parent / "hooks" / "pre-push").read_text(encoding="utf-8")
    for f in ("scripts/test_lumos.py", "scripts/test_autonomous_loop.py"):
        name = f.split("/")[-1]
        runs = [l for l in hook.splitlines()
                if name in l and "$PY" in l and not l.lstrip().startswith("#")]
        check(f"pre-push: 有真的執行 {name}", bool(runs), name)
    check("pre-push: 兩支都紅了就擋(各自有 exit 1)", hook.count("exit 1") >= 2, str(hook.count("exit 1")))


def t_no_adhoc_normalizer_in_review_reports():
    """審查卷證目錄裡不得再出現臨場正規化腳本(2026-09-06 收貨線指令化案停案後的根因修法)。

    出身:那支腳本(governance/review-reports/code-daily-wrapper-main/normalize.py)有一個
    ★讀不到任何嚴重度宣告就默默補成 clean★ 的分支——而記帳寫入端 rc2 擋的正是這件事,
    留著它等於留一把繞過閘的鑰匙;它還會把引句裡的「」換成『』,讓合法引句錨不回快照。

    ★根因不是缺工具,是派工詞自創格式★:查證指出席位吐錯格式不是模型天生行為,是派工詞
    要求的,而正確格式早就寫在 lumos-design-loop 的 templates.md 卷證規則裡。派工詞照範本
    寫,收貨正規化這件事就不存在——所以這裡直接禁止那個模式,而不是把它收成指令
    (收成指令的設計走過完整設計審,五席一輪打穿,已停案)。"""
    root = Path(GRAPHCTL).resolve().parent.parent
    # ★掃檔案系統不是只掃版控★(r1 架構對齊席):同檔既有同類守衛(t_metric_criteria_drift_guard)
    # 用 rglob 走真實檔案;改用 git ls-files 會只認已追蹤的檔,一支還沒 add 的臨場腳本要等到
    # 真的入版控才擋得到——而「寫下去當下就該擋」才是這條守衛的意思。
    # ★不靠檔名關鍵字★(r1 外家席:改叫 clean.py / convert.py 就繞過,而 normalize_measurements.py
    # 這種正當名字又被誤傷)。改成「卷證目錄裡不該有任何可執行腳本」——卷證是證據不是程式,
    # 要跑的東西應該在 scripts/ 底下受測試與審查管;這條同時把命名繞法整個關掉。
    rr = root / "governance" / "review-reports"
    exts = (".py", ".sh", ".js", ".rb", ".pl")
    bad = [str(q.relative_to(root)) for q in (rr.rglob("*") if rr.is_dir() else [])
           if q.is_file() and q.suffix.lower() in exts and "__pycache__" not in q.parts]
    check("卷證目錄不得有任何腳本(卷證是證據不是程式;派工詞照範本寫就不需要臨場正規化)", not bad, str(bad))
    # 同時釘住:code-loop skill 必須指向格式的單一來源,不要自己再寫一份
    sk = (root / "skills" / "lumos-code-loop" / "SKILL.md").read_text(encoding="utf-8")
    check("code-loop skill 指向席報告格式的單一來源(templates.md 卷證規則)",
          "templates.md" in sk and "卷證規則" in sk, "")
    check("code-loop skill 明寫引句內不要再包同型括號(巢狀會被收貨截斷)",
          "巢狀" in sk, "")


def t_skill_single_source_not_duplicated():
    """宣稱「單源見某某」的頁面,不得又把那段內容自己抄一份(2026-09-06 全 repo 審視 #15)。

    出身:兩份 SKILL.md 都寫著 Codex 對照單源=templates.md,卻又各抄一整段同樣的版本事實
    (哪個版本選得中自訂席、哪個忽略、別信設定檔的沙盒欄)——說是單源,實際三份,提交記錄
    裡就有一次「三處統一」的同步。★Codex 版本行為一變就要改三處★,正是散文載規則會漂的老問題。

    守衛用「版本號」當代理指標:那幾段的識別特徵就是帶具體版本號。有單源指標的頁面出現
    版本號,幾乎必然是又把單源的內容抄回來了。"""
    import re as _re
    root = Path(GRAPHCTL).resolve().parent.parent
    # ★r1 訂正★:初版寫死 `0\.1\d{2}\.\d+`,只認 Codex 現在的 0.1XX.Y——版本一過 0.199 這條守衛
    # 就靜默失效,而要求單源檔必須命中的反面斷言會同時假紅。放寬成任意 x.y.z 又會誤中別的數字,
    # 所以改成鎖「同一行既有版本號、又在講 Codex」:被抄的那段內容本來就長這樣,不靠版本形狀猜。
    ver = _re.compile(r"\b\d+\.\d+\.\d+\b")
    def _codex_version_lines(txt):
        return [ln.strip()[:80] for ln in txt.splitlines()
                if ver.search(ln) and ("codex" in ln.lower() or "Codex" in ln)]
    src_note = ("單源見", "單源=", "不在此複述", "唯一來源", "單一來源")
    # ★r1 折入(兩家適配)★:原本只掃 skills/**/SKILL.md。skills 兩家共用(裝進
    # ~/.claude/skills 與 ~/.agents/skills 的同一份來源,見 t_codex_skills_shared_dir),
    # 所以那部分兩家都吃得到;但 **Codex 另外讀 repo 根的 AGENTS.md**(有 AGENTS.override.md
    # 就只讀它),Claude 讀 CLAUDE.md——版本事實抄進這兩個入口檔,一樣會漂,而守衛看不到。
    targets = sorted((root / "skills").rglob("SKILL.md"))
    targets += [root / n for n in ("AGENTS.md", "AGENTS.override.md", "CLAUDE.md")]
    offenders = []
    for f in targets:
        if not f.is_file():
            continue
        txt = f.read_text(encoding="utf-8")
        if any(k in txt for k in src_note):
            for ln in _codex_version_lines(txt):
                offenders.append(f"{f.relative_to(root)}: {ln}")
    check("單源紀律: 宣稱單源的頭版不得再抄一份 Codex 版本事實", not offenders, str(offenders))
    # 反面:單源本身當然要留著那段(它就是那一份)
    tpl = root / "skills" / "lumos-design-loop" / "templates.md"
    check("單源紀律/反面: 單源檔本身留著 Codex 版本事實(不是把它也刪了)",
          tpl.is_file() and bool(_codex_version_lines(tpl.read_text(encoding="utf-8"))), str(tpl))
    # 反面②:兩家入口檔要真的在掃描範圍內(不是因為檔名寫錯、掃了個不存在的檔而假綠)
    scanned = [f for f in targets if f.is_file()]
    for _entry in ("AGENTS.md", "CLAUDE.md"):
        check(f"單源紀律/反面: {_entry}(Codex/Claude 的入口檔)有被掃到",
              (root / _entry) in scanned, f"{_entry} 不在掃描清單")
    # 反面③:把一行 Codex 版本事實塞進入口檔的副本,掃描器要抓得到
    _fake = "# X\n本檔只指路、單一來源在別處\ncodex-cli 0.153.2 選得中自訂席\n"
    check("單源紀律/反面: 版本事實抄進入口檔會被抓到",
          bool(_codex_version_lines(_fake)) and any(k in _fake for k in src_note), _fake)



def t_no_zero_assertion_return_paths():
    """測試不准有「一條斷言都沒跑就 return」的分支(2026-09-06 代碼審 r1)。

    出身:同批才加了「跑完零斷言=判紅」的 runner 規則,我當時用人工盤點宣稱「全套零命中,
    既有測試沒有這型」——錯的。那次是在 POSIX 機器上跑,五處 `print("- skip(非 POSIX)"); return`
    根本走不到,於是掃不出來;三席代碼審獨立指出同一件事。真在 Windows 上跑,那五支會被自己
    新加的守衛判紅,而它們本來就是合法跳過。

    ★所以盤點改成機械做★:靜態掃每支 t_ 函式,任何 return 之前一個 check() 都沒有的,一律要求
    改走 raise _SrcOnly(跳過通道會被 runner 記成 skip,零斷言判紅只咬真的忘了斷言的)。"""
    import ast as _ast
    src = Path(__file__).resolve().read_text(encoding="utf-8")

    def _calls_check(node):
        return any(isinstance(x, _ast.Call) and isinstance(x.func, _ast.Name) and x.func.id == "check"
                   for x in _ast.walk(node))

    bad = []
    for fn in _ast.parse(src).body:
        if not (isinstance(fn, _ast.FunctionDef) and fn.name.startswith("t_")):
            continue
        seen = {"v": False}

        def walk(body):
            for st in body:
                if isinstance(st, _ast.Return):
                    if not seen["v"]:
                        bad.append(f"{fn.name}:{st.lineno}")
                    continue
                if isinstance(st, _ast.Raise):
                    continue
                if isinstance(st, (_ast.If, _ast.For, _ast.While, _ast.With, _ast.Try)):
                    for fld in ("test", "iter"):
                        v = getattr(st, fld, None)
                        if v is not None and _calls_check(v):
                            seen["v"] = True
                    for nm in ("body", "orelse", "finalbody"):
                        walk(getattr(st, nm, []) or [])
                    for h in getattr(st, "handlers", []) or []:
                        walk(h.body)
                    continue
                if _calls_check(st):
                    seen["v"] = True

        walk(fn.body)

    check("零斷言分支: 沒有測試會在一條斷言都沒跑的情況下 return(該跳過的請 raise _SrcOnly)",
          not bad, f"{len(bad)} 處:{bad[:8]}")

    # 反面:掃描器本身要抓得到——手搭一支零斷言 return 的假測試,必須被列出來
    fake = "def t_fake_zero():\n    if 1:\n        return\n    check('x', True)\n"
    fake_bad = []
    for fn in _ast.parse(fake).body:
        seen2 = {"v": False}
        for st in fn.body:
            if isinstance(st, _ast.If):
                for sub in st.body:
                    if isinstance(sub, _ast.Return) and not seen2["v"]:
                        fake_bad.append(fn.name)
    check("零斷言分支/反面: 掃描器抓得到刻意搭的零斷言 return", fake_bad == ["t_fake_zero"], str(fake_bad))


def t_lint_warns_unknown_frontmatter_key():
    """開頭欄位鍵打錯要出聲(2026-09-06 全 repo 審視 #16)。

    出身:打成 valid_unde / verifed_by,lint 一句話都不說、doctor 也看不到,那個欄位等於沒寫
    ——而它可能是承載回頭條件或驗證關聯的欄位。★只給軟提醒不升 error★:工具對未知欄位的
    立場是前向相容,升 error 會讓別人的 vault 每次 lint 都被嘮叨;清單可用 .lumos/config.json
    的 extra_frontmatter_keys 擴充。

    ★量錯兩次才對的教訓★:我先用「同行為空」數出 78 篇缺回頭條件,實際那是 YAML 清單寫法、
    值在下一行;正確數字是 0 篇空值、7 篇連鍵都沒有。合成席原本說的 12 篇也不對。
    數 frontmatter 一定要把區塊式寫法算進去。"""
    import json, subprocess as _sp
    from pathlib import Path as _P
    base = _P(tempfile.mkdtemp(prefix="gctl-fmkey-"))
    kg = base / "docs" / "fm-knowledge" / "Systems"
    kg.mkdir(parents=True)
    (kg / "a.md").write_text(
        "---\ntype: system\nstatus: done\ncreated: 2026-09-06\nupdated: 2026-09-06\n"
        "aliases: []\nvalid_unde: 打錯一個字\nverifed_by: 也打錯\n"
        "tags:\n  - type/system\n  - status/done\nsummary: |-\n  KEY:測試用\n---\n# a\n",
        encoding="utf-8")
    def run():
        return _sp.run([sys.executable, GRAPHCTL, "--vault", str(base / "docs" / "fm-knowledge"),
                        "lint", "Systems/a"], capture_output=True, text=True, cwd=str(base)).stdout
    out = run()
    check("未知鍵: 打錯的鍵會被唸出來", "valid_unde" in out and "verifed_by" in out, out[-200:])
    check("未知鍵: 有近名提示(不是只說不認得)", "valid_under" in out and "verified_by" in out, out[-200:])
    check("未知鍵: ★只算 warning 不算 error★(前向相容立場)",
          "2 warning" in out or "warning" in out, out[-120:])
    # 可擴充:設定檔列進去就不再唸
    (base / ".lumos").mkdir(exist_ok=True)
    (base / ".lumos" / "config.json").write_text(
        json.dumps({"extra_frontmatter_keys": ["valid_unde", "verifed_by"]}), encoding="utf-8")
    out2 = run()
    check("未知鍵: ★設定檔可擴充★(別的 vault 有自己的欄位,不該被嘮叨)",
          "valid_unde" not in out2, out2[-200:])
    # 反面:正常節點不得被誤唸
    (kg / "b.md").write_text(
        "---\ntype: system\nstatus: done\ncreated: 2026-09-06\nupdated: 2026-09-06\n"
        "aliases: []\nvalid_under: x\nrevalidate_when: y\n"
        "tags:\n  - type/system\n  - status/done\nsummary: |-\n  KEY:測試用\n---\n# b\n",
        encoding="utf-8")
    out3 = _sp.run([sys.executable, GRAPHCTL, "--vault", str(base / "docs" / "fm-knowledge"),
                    "lint", "Systems/b"], capture_output=True, text=True, cwd=str(base)).stdout
    check("未知鍵/反面: 正常欄位不被誤唸", "沒見過的鍵" not in out3, out3[-160:])

    # ★r1 代碼審折入①★:清單初版是「掃本 vault 出現過的鍵」建的,漏了工具真的會讀、
    # 但本 vault 剛好沒節點寫的兩個(core_refs 跨專案升格參照、regen 重建溯源)。
    # 被誤報的話,提示文字「它不會被任何檢查讀到」本身就是假話。
    (kg / "c.md").write_text(
        "---\ntype: system\nstatus: done\ncreated: 2026-09-06\nupdated: 2026-09-06\n"
        "aliases: []\ncore_refs:\n  - core/x\nregen: scripts/foo.py\n"
        "tags:\n  - type/system\n  - status/done\nsummary: |-\n  KEY:測試用\n---\n# c\n",
        encoding="utf-8")
    out4 = _sp.run([sys.executable, GRAPHCTL, "--vault", str(base / "docs" / "fm-knowledge"),
                    "lint", "Systems/c"], capture_output=True, text=True, cwd=str(base)).stdout
    check("未知鍵/反面: 工具自己會讀的欄位(core_refs/regen)不得被誤報成不認得",
          "core_refs" not in out4 and "regen" not in out4, out4[-200:])

    # ★r1 代碼審折入②★:設定檔路徑原本寫死「vault 往上兩層」,vault 巢得更深(monorepo:
    # repo/subdir/docs/x-knowledge)時算到 repo/subdir/.lumos,擴充口悄悄失效且不報錯。
    deep = _P(tempfile.mkdtemp(prefix="gctl-fmdeep-"))
    dkg = deep / "subdir" / "docs" / "d-knowledge" / "Systems"
    dkg.mkdir(parents=True)
    (dkg / "a.md").write_text(
        "---\ntype: system\nstatus: done\ncreated: 2026-09-06\nupdated: 2026-09-06\n"
        "aliases: []\nmy_own_field: x\n"
        "tags:\n  - type/system\n  - status/done\nsummary: |-\n  KEY:測試用\n---\n# a\n",
        encoding="utf-8")
    (deep / ".lumos").mkdir()
    (deep / ".lumos" / "config.json").write_text(
        json.dumps({"extra_frontmatter_keys": ["my_own_field"]}), encoding="utf-8")
    out5 = _sp.run([sys.executable, GRAPHCTL, "--vault", str(deep / "subdir" / "docs" / "d-knowledge"),
                    "lint", "Systems/a"], capture_output=True, text=True, cwd=str(deep)).stdout
    check("未知鍵: 擴充口在巢得更深的 vault 也要生效(不是寫死往上兩層)",
          "my_own_field" not in out5, out5[-200:])


def t_daily_wrapper_health_and_lock():
    """★每日治理 wrapper:五步各自的結果留得住、鎖會清、健康檔寫得出來★
    (2026-09-07 全 repo 審視 #18)。

    出身:9/5 那次它跑到第二步就死了、後三步全沒跑、整天沒人發現——因為
    ①每一步的結果沒被抓到(那種 `echo "[$(ts)] rc=$?"` 抓到的是指令替換自己的結束碼)
    ②三步共用同一個變數名互相覆蓋 ③函式最後一條是無條件的收尾 echo,所以恆回 0。

    這條用假的子腳本跑真的骨架:第二步故意失敗,驗
    ①整支回非零 ②健康檔記得住是「哪一步」失敗 ③鎖收尾清掉了。
    """
    import json as _j
    import os as _os
    import shutil as _sh
    import subprocess as _sp
    _need_src("governance/daily-governance.sh")
    src = (Path(GRAPHCTL).resolve().parent.parent / "governance" / "daily-governance.sh").read_text(encoding="utf-8")
    root = Path(tempfile.mkdtemp(prefix="gctl-wrapper-"))
    try:
        g = root / "governance"
        g.mkdir()
        (root / "scripts").mkdir()
        (g / "daily-governance.sh").write_text(src, encoding="utf-8")
        for name, rc in (("ai-governance-research.sh", 0), ("autonomous-loop.sh", 7),
                         ("lint-watch-check.sh", 0)):
            f = g / name
            f.write_text("#!/bin/bash\nexit %d\n" % rc, encoding="utf-8")
            _os.chmod(f, 0o755)
        lum = root / "scripts" / "lumos"
        lum.write_text("#!/usr/bin/env python3\nimport sys;sys.exit(0)\n", encoding="utf-8")
        _os.chmod(lum, 0o755)
        r = _sp.run(["bash", str(g / "daily-governance.sh")], capture_output=True, text=True, timeout=120)
        check("★中間某一步失敗,整支要回非零★(原本恆回 0)", r.returncode != 0,
              "rc=%d\n%s" % (r.returncode, r.stdout[-400:]))
        hp = g / ".daily-governance-health.json"
        check("健康狀態檔寫得出來", hp.exists(), str(hp))
        if hp.exists():
            hd = _j.loads(hp.read_text(encoding="utf-8"))
            check("★健康檔記得住是哪一步失敗★(不能只記「跑完了」)",
                  hd.get("steps", {}).get("autonomous") == 7, hd)
            check("★沒失敗的步驟要各自留 0,不能互相覆蓋★",
                  [hd["steps"][k] for k in ("governance", "lint_watch", "doctor", "testmap")] == [0, 0, 0, 0], hd)
            check("加總是邏輯聚合(非零)", hd.get("total") == 1, hd)
        check("★收尾把鎖清掉了★(靠 trap,不是寫在函式結尾)",
              not (g / ".daily-governance.lock").exists(), "鎖殘留")
        # 第二次跑:上一次的鎖已清,應該照常跑得起來
        r2 = _sp.run(["bash", str(g / "daily-governance.sh")], capture_output=True, text=True, timeout=120)
        check("鎖清乾淨之後下一次照常跑", "wrapper 開始" in r2.stdout, r2.stdout[-300:])
        # 有人持鎖 → 要讓行,不能搶。
        # ★持鎖者的身分必須真的對得上★:這條原本拿測試行程自己的 pid 當持鎖者,
        # 而那是一支 python——2026-09-07 代碼審 r1 三席各自實測「pid 會被作業系統回收給無關的
        # 行程,那時 kill -0 說活著,wrapper 就永遠讓行」之後,取鎖多了一道身分驗證,
        # 這條測試當場翻紅。它翻得對:舊寫法把那個 bug 當成正確行為釘住了。
        # ★身分驗證後來又換過一次★(code-batch19 通才席 blocker:比對指令列名字被實跑打穿,
        # 持鎖者換個名字啟動就會被搶鎖)。現在鎖裡除了 pid 還要有「持鎖者的啟動時刻」——
        # 不寫那個檔的話,這條會走「驗不出→鎖齡兜底」一樣讓行、一樣綠,
        # ★但驗到的就不是「認得出活著的持鎖者」這件事了★,那是假綠。
        lock = g / ".daily-governance.lock"
        holder = g / "fake-daily-governance.sh"
        holder.write_text("#!/bin/bash\nsleep 60\n", encoding="utf-8")
        _os.chmod(holder, 0o755)
        hp_proc = _sp.Popen(["bash", str(holder)], stdout=_sp.DEVNULL, stderr=_sp.DEVNULL)
        try:
            lock.mkdir()
            (lock / "pid").write_text(str(hp_proc.pid), encoding="utf-8")
            (lock / "start").write_text(
                _sp.run(["ps", "-p", str(hp_proc.pid), "-o", "lstart="],
                        capture_output=True, text=True).stdout.strip(), encoding="utf-8")
            r3 = _sp.run(["bash", str(g / "daily-governance.sh")], capture_output=True, text=True, timeout=120)
            check("★另一份正在跑(pid 活著、而且真的是這支)→ 讓行不搶★",
                  "正在跑" in r3.stdout and "wrapper 開始" not in r3.stdout, r3.stdout[-300:])
            check("讓行時不刪別人的鎖", lock.exists(), "把別人的鎖刪了")
        finally:
            hp_proc.kill()
            hp_proc.wait(timeout=10)
        # ★pid 活著但不是這支(作業系統回收 pid)→ 要接管,不能永遠讓行★
        _sh.rmtree(lock, ignore_errors=True)
        unrel = _sp.Popen([sys.executable, "-c", "import time;time.sleep(60)"],
                          stdout=_sp.DEVNULL, stderr=_sp.DEVNULL)
        try:
            lock.mkdir()
            (lock / "pid").write_text(str(unrel.pid), encoding="utf-8")
            _os.utime(lock, (0, __import__("time").time() - 7200))
            r4 = _sp.run(["bash", str(g / "daily-governance.sh")], capture_output=True, text=True, timeout=120)
            check("★pid 被無關的活行程佔用 → 要接管,不能永遠讓行★",
                  "wrapper 開始" in r4.stdout, r4.stdout[-300:])
        finally:
            unrel.kill()
            unrel.wait(timeout=10)
        # ★pid 檔內容壞掉(非數字)等同「還沒寫 pid」→ 年輕鎖要讓行,不能搶★
        _sh.rmtree(lock, ignore_errors=True)
        lock.mkdir()
        (lock / "pid").write_text("garbage-not-a-pid", encoding="utf-8")
        r5 = _sp.run(["bash", str(g / "daily-governance.sh")], capture_output=True, text=True, timeout=120)
        check("★pid 檔寫壞 + 鎖很年輕 → 讓行★(第一版兩個分支都不成立,直接搶 0 秒齡的鎖)",
              "讓行" in r5.stdout and "wrapper 開始" not in r5.stdout, r5.stdout[-300:])
        _sh.rmtree(lock, ignore_errors=True)
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_daily_wrapper_health_and_lock")


def _wrapper_sandbox():
    """搭一個能真的跑 daily-governance.sh 的假現場(五支子腳本都是 exit 0)。回 (root, governance 目錄)。"""
    import os as _os
    import tempfile as _tf
    _need_src("governance/daily-governance.sh")
    repo = Path(GRAPHCTL).resolve().parent.parent
    root = Path(_tf.mkdtemp(prefix="gctl-wrap2-"))
    g = root / "governance"
    g.mkdir()
    (root / "scripts").mkdir()
    (g / "daily-governance.sh").write_text(
        (repo / "governance" / "daily-governance.sh").read_text(encoding="utf-8"), encoding="utf-8")
    for name in ("ai-governance-research.sh", "autonomous-loop.sh", "lint-watch-check.sh"):
        f = g / name
        f.write_text("#!/bin/bash\nexit 0\n", encoding="utf-8")
        _os.chmod(f, 0o755)
    lum = root / "scripts" / "lumos"
    lum.write_text("#!/usr/bin/env python3\nimport sys;sys.exit(0)\n", encoding="utf-8")
    _os.chmod(lum, 0o755)
    return root, g


def t_daily_wrapper_takeover_is_atomic():
    """★接管殘鎖不准讓兩份同時跑起來★(2026-09-07 代碼審 r1 併發與資源席,實測重現)。

    第一版接管是「rm 掉舊鎖再 mkdir」,擋不住這個排列:
      A 刪 → A 建(成功)→ B 刪(把 A 剛建好的砍掉)→ B 建(成功)
    兩邊的 mkdir 都回 0,兩邊都以為自己拿到鎖。實測八個行程搶同一把殘鎖,
    30 輪有 19 輪出現多人同時拿到;拿真腳本跑,15 輪有 2 輪整支被跑了兩遍
    ——兩份會同時寫同一批 log、各自寫健康檔互相蓋掉。

    改成用 mv 把舊鎖原子搬走:兩個接管者只有一個的 rename 會成功。
    """
    import os as _os
    import shutil as _sh
    import subprocess as _sp
    import time as _tm
    root, g = _wrapper_sandbox()
    try:
        lock = g / ".daily-governance.lock"
        doubled = 0
        # ★輪數要夠★:修完第一版(改用 mv 搬走)之後量到的殘餘漏網率約 1/12,
        # 8 輪只有一半機率抓得到。20 輪約 5 秒,還在超時上限的三十分之一內。
        rounds = 20
        for _ in range(rounds):
            _sh.rmtree(lock, ignore_errors=True)
            lock.mkdir()
            (lock / "pid").write_text("999999", encoding="utf-8")   # 確定死透
            _os.utime(lock, (0, _tm.time() - 7200))                 # 鎖齡 2 小時
            procs = [_sp.Popen(["bash", str(g / "daily-governance.sh")],
                               stdout=_sp.PIPE, stderr=_sp.DEVNULL, text=True) for _ in range(8)]
            outs = [p.communicate(timeout=120)[0] for p in procs]
            if sum(1 for o in outs if "wrapper 開始" in o) > 1:
                doubled += 1
        check("★八個行程搶同一把殘鎖,不准有任何一輪雙開★",
              doubled == 0, "%d/%d 輪雙開" % (doubled, rounds))
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_daily_wrapper_takeover_is_atomic")


def t_daily_wrapper_health_write_failure_is_a_failure():
    """★健康檔寫不進去 = 這一次算失敗,而且不准留垃圾暫存檔★
    (2026-09-07 代碼審 r1 邊界席 + 外家 finder,兩席各自實測)。

    兩個洞疊在一起:
    ① $HEALTH 這個路徑如果變成一個「目錄」(中斷殘留、備份工具建了同名資料夾),
       `mv` 會把暫存檔**搬進那個目錄**而不是回報失敗——於是 wrapper 天天印成功、
       健檢說「沒事」、看門狗說「從沒跑過」,三層防線同時失明且零訊號。
    ② 就算 write_health 回了非零,第一版也只印一句提醒、不動 total,
       五步全成功時整支照樣回 0——排程端看到的是「成功」。
    """
    import shutil as _sh
    import subprocess as _sp
    root, g = _wrapper_sandbox()
    try:
        (g / ".daily-governance-health.json").mkdir()      # ① 路徑變目錄
        r = _sp.run(["bash", str(g / "daily-governance.sh")],
                    capture_output=True, text=True, timeout=120)
        check("★健康檔寫不進去 → 整支要回非零★(第一版回 0,偽裝成功)",
              r.returncode != 0, "rc=%d\n%s" % (r.returncode, r.stderr[-300:]))
        check("★而且要講出「不是普通檔案」這件事★,不能只說寫不進去",
              "不是一個普通檔案" in r.stderr, r.stderr[-300:])
        leftovers = list((g / ".daily-governance-health.json").iterdir())
        check("★失敗時不准留垃圾暫存檔★", not leftovers, [p.name for p in leftovers])
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_daily_wrapper_health_write_failure_is_a_failure")


def t_wrapper_watchdog_no_health_but_wrapper_ran():
    """★健康檔不在時,不准直接斷言「從來沒跑完過」——先問 wrapper 自己的紀錄檔★(2026-09-08)。

    真的講錯過:健康檔不存在,看門狗每天喊一次「這台機器上的 wrapper 從來沒跑完過」,
    而 wrapper 自己的紀錄檔裡前一天和當天都白紙黑字寫著「完成」。
    成因是「寫健康檔」是後來才加進 wrapper 的,排程當時跑的還是舊版,舊版不寫那個檔。
    ★這支看門狗只有一個來源,而那個來源的沉默被它當成了「沒發生過」。★

    現在:健康檔不在 → 去讀 wrapper 的紀錄檔。最近有跑完就換句話講(仍然要喊,
    因為那代表看門狗是瞎的),完全找不到才說「從來沒跑完過」。
    紀錄檔也不在的話退回原本判斷——第二個來源缺席不能讓警報消失。
    """
    import shutil as _sh, subprocess as _sp, tempfile as _tf, datetime as _dt
    _need_src("governance/wrapper-watchdog.sh")
    repo = Path(GRAPHCTL).resolve().parent.parent
    root = Path(_tf.mkdtemp(prefix="gctl-wdlog-"))
    try:
        g = root / "governance"; (g / "logs").mkdir(parents=True)
        wd = g / "wrapper-watchdog.sh"
        wd.write_text((repo / "governance" / "wrapper-watchdog.sh").read_text(encoding="utf-8"),
                      encoding="utf-8")
        wlog = g / "logs" / "daily-wrapper.log"
        st = g / ".wrapper-watchdog-state"

        def _run():
            st.unlink(missing_ok=True)
            return _sp.run(["bash", str(wd)], capture_output=True, text=True, timeout=120,
                           env=_watchdog_quiet_env(root))   # ★別在使用者桌面彈真通知★

        def _stamp(h):
            return (_dt.datetime.now() - _dt.timedelta(hours=h)).strftime("%Y-%m-%d %H:%M:%S")

        # ① 沒有健康檔、也沒有紀錄檔 → 維持原本那句(第二個來源缺席不改變結論)
        r = _run()
        check("★沒有健康檔又沒有紀錄檔 → 還是要說「從來沒跑完過」★",
              "從來沒跑完過" in r.stdout, r.stdout + r.stderr)

        # ② 沒有健康檔,但紀錄檔說兩小時前才跑完 → 不准說「從來沒跑完過」
        # ★時間戳只算一次★:算兩次的話跨秒就對不上,那是測試自己的時序 bug(踩過)
        fin2 = _stamp(2)
        wlog.write_text("[%s] daily-governance wrapper 開始\n"
                        "[%s] daily-governance wrapper 完成\n" % (_stamp(2.2), fin2),
                        encoding="utf-8")
        r = _run()
        check("★紀錄檔說最近才跑完 → 不准講「從來沒跑完過」★",
              "從來沒跑完過" not in r.stdout, r.stdout + r.stderr)
        check("★要改講「有在跑,但沒留下健康狀態檔」★",
              "有在跑" in r.stdout and "健康狀態檔" in r.stdout, r.stdout + r.stderr)
        check("★而且要把紀錄檔上那個時間講出來(人才查得下去)★",
              fin2 in r.stdout, r.stdout)
        # ★不能只驗 stdout★(code-batch20 外家席 f5):前一條已經要求 stdout 同時含
        # 「有在跑」與「健康狀態檔」,所以「stdout 非空」那條是空的;而且五條全部只看
        # stdout,實作只要 echo 對文案、帳不寫、通知不發,照樣全綠。
        # 改成驗第二條通道:它自己的紀錄檔(那也是健檢 [A1] 段真正在讀的東西)。
        wlogf = g / "logs" / "wrapper-watchdog.log"
        check("★這個狀態要落進它自己的紀錄檔★(桌面通知會被權限擋掉,帳不會)",
              wlogf.exists() and '"kind":"nohealth"' in wlogf.read_text(encoding="utf-8"),
              wlogf.read_text(encoding="utf-8") if wlogf.exists() else "紀錄檔根本沒建")

        # ③ ★兩筆以上時要取最後一筆★(code-batch20 通才席 F3 用 mutant 抓到的覆蓋洞:
        #    它把找到就 break 改成「取第一筆」,我原本的五個場景全綠——因為每個場景
        #    都只放一筆完成紀錄。碼本身是對的(不 break 就是後面覆蓋前面),
        #    但沒有任何斷言在守那個語意,誰改成取第一筆都不會有人發現。)
        old_fin, new_fin = _stamp(80), _stamp(2)
        wlog.write_text("[%s] daily-governance wrapper 完成\n"
                        "[%s] daily-governance wrapper 完成\n" % (old_fin, new_fin), encoding="utf-8")
        r = _run()
        check("★紀錄檔有兩筆完成 → 要取最後那筆,不是第一筆★",
              new_fin in r.stdout and old_fin not in r.stdout, r.stdout + r.stderr)
        check("★而且結論要是「有在跑」★(取到第一筆的話會超過門檻、變成從來沒跑完過)",
              "從來沒跑完過" not in r.stdout, r.stdout)

        # ④ 紀錄檔上最後一次跑完已經很久 → 回到「從來沒跑完過」
        wlog.write_text("[%s] daily-governance wrapper 完成\n" % _stamp(80), encoding="utf-8")
        r = _run()
        check("★紀錄檔上最後一次已經超過門檻 → 照樣說「從來沒跑完過」★",
              "從來沒跑完過" in r.stdout, r.stdout + r.stderr)

        # ⑤ 紀錄檔有內容但沒有任何「完成」→ 不能被誤讀成跑完過
        wlog.write_text("[%s] daily-governance wrapper 開始\n"
                        "[%s] 治理日報 段結束 rc=0\n" % (_stamp(1), _stamp(0.9)), encoding="utf-8")
        r = _run()
        check("★只有「開始」沒有「完成」→ 不算跑完★",
              "從來沒跑完過" in r.stdout, r.stdout + r.stderr)
    finally:
        _sh.rmtree(root, ignore_errors=True)


def _gate_ledger_sandbox():
    """造一個最小 repo:有 git、有 docs/、有一份錨點基準線(故意跟實際檔案對不上)。"""
    import subprocess as _sp, tempfile as _tf, json as _json, os as _os
    root = Path(_tf.mkdtemp(prefix="gctl-gateev-"))
    _sp.run(["git", "init", "-q", str(root)], check=True, capture_output=True)
    (root / "docs").mkdir()
    (root / "docs" / ".governance-log.jsonl").write_text("", encoding="utf-8")
    hooks = root / "scripts" / "hooks"; hooks.mkdir(parents=True)
    victim = root / "scripts" / "runner.py"
    victim.write_text("print('v1')\n", encoding="utf-8")
    (root / "governance").mkdir(exist_ok=True)
    (root / "governance" / "anchor-baseline.json").write_text(_json.dumps(
        {"anchors": {"scripts/runner.py": "0" * 64}}, ensure_ascii=False), encoding="utf-8")
    (root / "x.txt").write_text("x", encoding="utf-8")
    _sp.run(["git", "-C", str(root), "add", "-A"], check=True, capture_output=True)
    _sp.run(["git", "-C", str(root), "-c", "user.email=t@t", "-c", "user.name=t",
             "commit", "-qm", "init"], check=True, capture_output=True)
    return root


def _gate_rows(root):
    import json as _json
    p = Path(root) / "docs" / ".governance-log.jsonl"
    if not p.exists():
        return []
    return [_json.loads(l) for l in p.read_text(encoding="utf-8").splitlines() if l.strip()]


def t_blocked_events_are_never_read_as_markers():
    """★擋下/跳過/放行的事件,絕不能被當成「審過了」的憑證★(2026-09-08 代碼審 r1 之後補的)。

    真的踩到了:我把新落帳器的欄名「對齊」既有那支時順手加了分支欄位,
    結果 `blocked` 事件當場被留痕讀取器讀走——既有測試翻紅才發現。

    ★架構對齊席原本那句話是在講一個保護,不是在講一個不一致★:
    它說「新事件讀不到 marker 讀取器——目前不算功能性錯誤,新事件本來就不該被當成 marker」。
    我把它當成欄名不一致去修,等於把保護拆掉。

    現在兩道:①落帳時不寫分支識別欄 ②讀留痕時只認 passed/skipped 兩種 kind。
    ★別讓「哪些 kind 算留痕」只靠欄位有沒有寫★。
    """
    import json as _j, shutil as _sh, tempfile as _tf, subprocess as _sp
    m = _load_lumos_inproc()
    root = Path(_tf.mkdtemp(prefix="gctl-marker-"))
    try:
        _sp.run(["git", "init", "-q", str(root)], check=True, capture_output=True)
        (root / "docs").mkdir()
        log = root / "docs" / ".governance-log.jsonl"
        rows = [
            {"ts": "2026-09-08T10:00:00+08:00", "gate": "code-loop", "kind": "passed",
             "branch": "main", "head_sha": "aaaa", "detail": "真的審過了"},
            {"ts": "2026-09-08T11:00:00+08:00", "gate": "code-loop", "kind": "blocked",
             "branch": "main", "head_sha": "bbbb", "note": "擋下"},
            {"ts": "2026-09-08T12:00:00+08:00", "gate": "code-loop", "kind": "skipped-env",
             "branch": "main", "head_sha": "cccc", "note": "被跳過"},
            {"ts": "2026-09-08T13:00:00+08:00", "gate": "code-loop", "kind": "fail-open",
             "branch": "main", "head_sha": "dddd", "note": "放行"},
        ]
        log.write_text("".join(_j.dumps(r, ensure_ascii=False) + "\n" for r in rows), encoding="utf-8")
        rec = m._codeloop_read_from_ledger(root, "main")
        check("★前置★ 讀得到東西(不然下面的斷言是空的)", rec is not None, str(rec))
        if rec:
            check("★讀到的必須是那筆 passed,不是後面任何一種新事件★",
                  rec.get("head_sha") == "aaaa" and rec.get("status") == "passed", str(rec))
        # 反向對照:只有新事件、沒有 passed/skipped → 要回 None,不能硬湊一筆
        log.write_text("".join(_j.dumps(r, ensure_ascii=False) + "\n" for r in rows[1:]),
                       encoding="utf-8")
        check("★只有擋下/跳過/放行時,要回「沒有留痕」★",
              m._codeloop_read_from_ledger(root, "main") is None,
              str(m._codeloop_read_from_ledger(root, "main")))
        # 落帳器不准寫分支識別欄(第一道)
        src = Path(GRAPHCTL).read_text(encoding="utf-8")
        i = src.index("def _gate_event(")
        seg = src[i:src.index("def _gate_event_or_warn", i)]
        code = "\n".join(l for l in seg.splitlines() if not l.lstrip().startswith("#"))
        check("★落帳器不准寫 branch 欄★(寫了就會被留痕讀取器撿走)",
              'ev["branch"]' not in code, code)
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_blocked_events_are_never_read_as_markers")


def t_hook_event_timestamp_roundtrips_on_old_python():
    """★寫入端與讀取端的時間格式要在最舊的支援版本上兜得起來★(2026-09-08 r1 通才席 blocker)。

    真的壞過:寫入用 `time.strftime("%Y-%m-%dT%H:%M:%S%z")`,吐出來的偏移量**沒有冒號**
    (`+0800`);而讀取用 `datetime.fromisoformat`,★那在 Python 3.11 之前不吃無冒號格式★。
    實測 3.9 直接 ValueError——而 3.9 是這個 repo 的下限、3.10 是 Ubuntu 22.04 內建版本。
    後果是「兩秒前才成功記的一筆」被判成沒跑過,儀表板在那些機器上永久 stale,
    ★正好打臉這批的核心賣點★。

    ★而我的測試原本測不到它★:消費端測試自己造事件時用的是
    `datetime.now().astimezone().isoformat()`(帶冒號),**從沒真的呼叫過寫入器**
    ——消費端與生產端用了不同的資料產生方式,兩邊格式從沒被放在一起驗過。
    這一支就是把它們接起來:用寫入器真的寫、用讀取端真的讀。
    """
    import shutil as _sh, tempfile as _tf, subprocess as _sp, os as _os
    _need_src("scripts/hooks/claude/_hookevent.py")
    hookdir = Path(GRAPHCTL).resolve().parent / "hooks" / "claude"
    cands = [sys.executable]
    for alt in ("/usr/bin/python3", "/usr/local/bin/python3"):
        if _os.path.exists(alt) and alt not in cands:
            cands.append(alt)
    checked_old = False
    for py in cands:
        ver = _sp.run([py, "-c", "import sys;print('%d.%d' % sys.version_info[:2])"],
                      capture_output=True, text=True).stdout.strip()
        root = Path(_tf.mkdtemp(prefix="gctl-tsrt-"))
        try:
            _sp.run(["git", "init", "-q", str(root)], check=True, capture_output=True)
            probe = root / "p.py"
            probe.write_text(
                "import sys\n"
                "sys.path.insert(0, %r)\n" % str(hookdir) +
                "from _hookevent import record\n"
                "print(record(%r, 'H', 'ok', hook_file=__file__))\n" % str(root),
                encoding="utf-8")
            w = _sp.run([py, str(probe)], cwd=str(root), capture_output=True, text=True, timeout=60)
            check("★%s 寫得出事件★" % ver, "True" in w.stdout, w.stdout + w.stderr[-200:])
            verdict = _sp.run(
                [py, "-c",
                 "import importlib.machinery as m, importlib.util as u, sys\n"
                 "l = m.SourceFileLoader('lm', %r)\n" % str(Path(GRAPHCTL).resolve()) +
                 "sp = u.spec_from_loader('lm', l); mod = u.module_from_spec(sp)\n"
                 "sys.argv=['lumos']\n"
                 "try:\n    l.exec_module(mod)\nexcept SystemExit:\n    pass\n"
                 "print(mod._hook_recent_ok(%r, 'H', %r)[0])" % (str(root), str(probe))],
                capture_output=True, text=True, timeout=120).stdout.strip()
            check("★%s:剛寫的那筆要讀得回來(不能判成 stale)★" % ver,
                  verdict == "ok", "verdict=%r" % verdict)
            if ver and tuple(int(x) for x in ver.split(".")) < (3, 11):
                checked_old = True
        finally:
            _sh.rmtree(root, ignore_errors=True)
    check("★前置★ 這台機器上有沒有 3.11 以前的 python 可以驗(沒有就只驗到當前版本)",
          True, "checked_old=%s" % checked_old)
    src = (hookdir / "_hookevent.py").read_text(encoding="utf-8")
    check("★不准用 time.strftime 的 %z 寫時間戳★(它吐無冒號偏移,3.11 前讀不動)",
          '"%Y-%m-%dT%H:%M:%S%z"' not in src, "碼裡還有那個格式")
    print("  ✓ t_hook_event_timestamp_roundtrips_on_old_python")


def t_enforcement_stale_is_not_counted_as_down():
    """★新增的 stale 狀態要一起排出分母、而且要有圖示★(2026-09-08 r1 架構席 major)。

    `stale` 的設計意圖是「不確定,別冤枉」——可能只是七天內沒被觸發。
    但摘要行的分母排除清單只寫了 unknown 與 registered-trust-unknown,
    ★漏排它就等於把「沒被觸發」算成「沒生效」★,摘要永遠偏悲觀;
    圖示字典也沒有這個鍵,會落到問號分支。
    這正是「這批想解決假訊號,卻在另一個角落製造一個新的假訊號」。
    """
    m = _load_lumos_inproc()
    rows = [{"layer": "a", "status": "active"}, {"layer": "b", "status": "stale"},
            {"layer": "c", "status": "unknown"}, {"layer": "d", "status": "inactive"}]
    # ★回的是 (active, 非 unknown 總數, unknown 數) 三元組,不是字串★
    # (第一版拿字串比對,對著一個 tuple 找 "1/2",當然找不到——那是我的斷言型別看錯,
    #  不是實作壞掉。同一天不只一次:斷言之前先確認被測的東西是什麼型別。)
    act, total, unk = m.enforcement_summary(rows)
    check("★stale 不准被算進分母★(4 列裡 stale+unknown 兩列要排掉,分母剩 2)",
          (act, total, unk) == (1, 2, 2), str((act, total, unk)))
    src = Path(GRAPHCTL).read_text(encoding="utf-8")
    # ★要咬的是「圖示字典裡有 stale」,不是「全檔任何地方出現 "stale":」★
    # (第一版全檔比對,拿掉圖示之後別處還有同樣的字串,突變體沒翻紅——翻紅釘抓到的。)
    i_mark = src.index('mark = {"active":')
    mark_seg = src[i_mark:src.index("}", i_mark)]
    check("★圖示字典要有 stale★(不然畫面印問號)", '"stale"' in mark_seg, mark_seg)
    check("★分母排除清單要含 stale★",
          '"registered-trust-unknown", "stale"' in src, "排除清單沒有 stale")
    print("  ✓ t_enforcement_stale_is_not_counted_as_down")


def t_gate_event_silent_when_repo_has_no_ledger():
    """★「這個 repo 根本沒有這本帳」不是「寫不進去」★(2026-09-08 r1 通才席 major)。

    沒跑過 `lumos init` 的 repo 本來就沒有 `docs/`。第一版把這個情境跟
    「磁碟滿/權限錯」用同一句話講,而且是★結構性、每次都會發生、永遠不會自己好★
    ——那種警告久了會被忽略,恰好抵銷這批想建立的信任。
    既有的姐妹寫入器面對同一情境是靜靜略過,這裡對齊它。
    """
    import shutil as _sh, tempfile as _tf, subprocess as _sp
    m = _load_lumos_inproc()
    root = Path(_tf.mkdtemp(prefix="gctl-noledger-"))
    try:
        _sp.run(["git", "init", "-q", str(root)], check=True, capture_output=True)
        r = m._gate_event(root, "anchor", "blocked", "x", hard=True)
        check("★沒有 docs/ 時回「不適用」,不是「失敗」★", r is None, repr(r))
        import io, contextlib
        buf = io.StringIO()
        with contextlib.redirect_stderr(buf):
            m._gate_event_or_warn(root, "anchor", "blocked", "x", hard=True)
        check("★而且不准噴 telemetry-write-failed★(那句話是留給真的故障的)",
              "telemetry-write-failed" not in buf.getvalue(), buf.getvalue())
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_gate_event_silent_when_repo_has_no_ledger")


def t_installed_hook_copy_really_records_events():
    """★用真的安裝流程裝進隔離家目錄,跑安裝副本,事件檔要長出來★(2026-09-08 r1 通才席)。

    通才席的原話:來源樹的測試「從沒測過裝到 ~/.claude/hooks/ 之後 import 得不得到——
    來源樹全綠,安裝副本全死,測試看不見這個落差」。我第一版的守衛只驗複製清單,
    仍然是「看清單」不是「看安裝」。★這一支就是那個落差本身★:
    HOME 指到暫存目錄 → 跑真的 `lumos install` → 跑安裝出來的那支 hook → 事件檔必須出現。

    另外釘一件今天實測到的:在 Lumos 來源 repo 自己身上跑 `init --force` 會★刻意跳過 hook 安裝★
    (它印「當前就是來源本身,跳過 vendor/hooks」)——所以部署 hook 的指令是 `lumos install`,
    這一支走的就是它。
    """
    import shutil as _sh, tempfile as _tf, subprocess as _sp, os as _os, json as _j
    _need_src("scripts/lumos", "scripts/hooks/claude/_hookevent.py")
    lumos = Path(GRAPHCTL).resolve()
    home = Path(_tf.mkdtemp(prefix="gctl-inst-home-"))
    repo = Path(_tf.mkdtemp(prefix="gctl-inst-repo-"))
    try:
        env = dict(_os.environ); env["HOME"] = str(home); env.pop("LUMOS_PROBE", None)
        r = _sp.run([sys.executable, str(lumos), "install"], capture_output=True, text=True,
                    env=env, timeout=600, cwd=str(lumos.parent.parent))
        hooks = home / ".claude" / "hooks"
        check("★前置★ 真的裝進了隔離家目錄", (hooks / "lumos-entry-hook.py").exists(),
              r.stdout[-400:] + r.stderr[-400:])
        check("★共用模組要一起被裝過去★(來源樹綠、安裝副本死的那個洞)",
              (hooks / "_hookevent.py").exists(), str(sorted(x.name for x in hooks.glob("*.py"))))
        # 跑安裝出來的那支 hook(不是來源樹那支),在一個 git repo 裡
        _sp.run(["git", "init", "-q", str(repo)], check=True, capture_output=True)
        r2 = _sp.run([sys.executable, str(hooks / "lumos-entry-hook.py"), "--budget", "10"],
                     input=_j.dumps({"cwd": str(repo)}), capture_output=True, text=True,
                     env=env, cwd=str(repo), timeout=120)
        check("★安裝副本跑得動★", r2.returncode == 0, r2.stderr[-300:])
        ev = repo / "governance" / "runtime" / "hook-events.jsonl"
        check("★安裝副本跑完要留下事件★(沒留=import 失敗被靜靜吞掉)", ev.exists(),
              "事件檔沒長出來;stderr=" + r2.stderr[-300:])
        if ev.exists():
            rows = [_j.loads(l) for l in ev.read_text(encoding="utf-8").splitlines() if l.strip()]
            check("★事件是 ok,而且來自安裝副本的指紋★",
                  rows and rows[-1]["kind"] == "ok" and rows[-1].get("fp"), str(rows[-1:]))
    finally:
        _sh.rmtree(home, ignore_errors=True); _sh.rmtree(repo, ignore_errors=True)
    print("  ✓ t_installed_hook_copy_really_records_events")


def t_installed_hooks_bring_their_local_imports():
    """★被複製的 hook 所 import 的本地模組,也必須在複製清單裡★(2026-09-08 r1 外家席 blocker)。

    真的踩到了:五支 hook 都 `from _hookevent import guard`,但安裝清單只列那五支主檔。
    安裝副本 import 一定失敗 → 走 try/except 退回不記事件 → `enforcement` 對那五列
    永遠 unknown。★裝了等於沒裝★,而且來源樹的測試照樣全綠——**因為它們測的是來源樹,
    不是安裝副本**。

    ★這條寫成通則,不是只釘那一個檔名★:下次任何一支 hook 多 import 一個本地模組,
    忘了加進清單一樣會翻紅。
    """
    import ast as _ast, re as _re
    _need_src("scripts/lumos")
    root = Path(GRAPHCTL).resolve().parent.parent
    src = (root / "scripts" / "lumos").read_text(encoding="utf-8")
    # ★非貪婪括號會被註解裡的括號截斷★:清單裡有中文註解、註解裡有「(…)」,
    # 第一版用 `\((.*?)\)` 只抓到第一個右括號為止,於是漏掉後面的項目、報了一個假的紅。
    # 改成抓到「_GLOBAL_HOOKS =」那一行之前的整段。
    i0 = src.index("_GLOBAL_CLAUDE_HOOKS = (")
    i1 = src.index("_GLOBAL_HOOKS", i0)
    m = _re.match(r"(?s).*", src[i0:i1])
    check("★前置★ 找得到複製清單", m is not None, "找不到 _GLOBAL_CLAUDE_HOOKS")
    if not m:
        return
    listed = set(_re.findall(r'"([^"]+\.py)"', src[i0:i1]))
    check("★前置★ 清單非空", len(listed) >= 5, str(sorted(listed)))
    hookdir = root / "scripts" / "hooks" / "claude"
    missing = []
    for fn in sorted(listed):
        f = hookdir / fn
        if not f.exists():
            missing.append(f"{fn}(清單上有,檔案卻不在)")
            continue
        try:
            tree = _ast.parse(f.read_text(encoding="utf-8"))
        except SyntaxError:
            continue
        for n in _ast.walk(tree):
            names = []
            if isinstance(n, _ast.ImportFrom) and n.level == 0 and n.module:
                names = [n.module]
            elif isinstance(n, _ast.Import):
                names = [a.name for a in n.names]
            for nm in names:
                top = nm.split(".")[0]
                if (hookdir / (top + ".py")).exists() and (top + ".py") not in listed:
                    missing.append(f"{fn} import 了 {top}.py,但它不在複製清單裡")
    check("★每個被複製的 hook,它 import 的本地模組也要在清單裡★", not missing,
          ";".join(sorted(set(missing))))
    # ★複製清單之外,錨點名單也要收★:那支模組會跟著複製到 ~/.claude/hooks/,
    # 一樣是「你一打開資料夾就自動跑」的程式的一部分。2026-09-08 漏這一條當場擋住推送,
    # 而錨點那道★永遠不可跳★。(第一版只驗複製清單,拿掉錨點登記的突變體沒翻紅——翻紅釘抓到的。)
    i_af = src.index("ANCHOR_FILES = [")
    anchors = set(_re.findall(r'"([^"]+)"', src[i_af:src.index("]", i_af)]))
    for fn in sorted(listed):
        rel = "scripts/hooks/claude/" + fn
        if (hookdir / fn).exists():
            check("★%s 也要在錨點名單裡★" % fn, rel in anchors,
                  "ANCHOR_FILES 沒有 %s" % rel)
    print("  ✓ t_installed_hooks_bring_their_local_imports")


def t_hook_swallowed_timeout_is_not_recorded_as_ok():
    """★hook 內部吞掉的逾時,不准被記成「成功跑完」★(2026-09-08 r1 外家席 blocker)。

    `guard()` 只看得到 `main()` 有沒有丟例外。而派工鏡頭那支有一條
    「捕捉逾時 → 附一行說明 → 正常 return 0」的路徑——★那種情況下會被記成 ok★,
    於是一支每次都逾時的 hook 會穩定顯示「近期跑過 N 次」。
    而 `KINDS` 裡宣告的 `timeout` 原本沒有任何接線寫得到。

    處置:吞掉的那一方自己呼叫 `mark("timeout")`,`guard()` 記那個 kind。
    """
    import json as _j, shutil as _sh, tempfile as _tf, subprocess as _sp
    _need_src("scripts/hooks/claude/_hookevent.py", "scripts/hooks/claude/dispatch-lens-hook.py")
    hookdir = Path(GRAPHCTL).resolve().parent / "hooks" / "claude"
    root = Path(_tf.mkdtemp(prefix="gctl-swallow-"))
    try:
        _sp.run(["git", "init", "-q", str(root)], check=True, capture_output=True)
        probe = root / "p.py"
        probe.write_text(
            "import sys\n"
            "sys.path.insert(0, %r)\n" % str(hookdir) +
            "from _hookevent import guard, mark\n"
            "def main():\n"
            "    mark('timeout', '假裝內部逾時後正常回來')\n"
            "    return 0\n"
            "sys.exit(guard('H', __file__, main))\n", encoding="utf-8")
        _sp.run([sys.executable, str(probe)], cwd=str(root), capture_output=True, timeout=60)
        rows = [_j.loads(l) for l in
                (root / "governance" / "runtime" / "hook-events.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()]
        check("★內部吞掉逾時 → 記 timeout,不記 ok★",
              rows and rows[-1]["kind"] == "timeout", str(rows))
        check("★而且那筆不能被 _hook_recent_ok 當成「跑過」★",
              _load_lumos()._hook_recent_ok(root, "H", probe)[0] != "ok", str(rows))

        # 真的那支 hook 有沒有在它吞逾時的地方講一聲
        # ★搜尋窗要對準真的那一條吞逾時路徑★:第一版用第一個 `except (subprocess.TimeoutExpired`
        # 當起點,而檔裡不只一處,窗口落在別的地方,報了一個假的紅。
        # 改成:先確認那個 mark 呼叫存在,再確認它跟「附了超時說明行」那句在同一段。
        dl = (hookdir / "dispatch-lens-hook.py").read_text(encoding="utf-8")
        check("★派工鏡頭那支要有 mark(\"timeout\") 的呼叫★",
              '_mark("timeout"' in dl, "找不到 mark 呼叫")
        if '_mark("timeout"' in dl:
            i_m = dl.index('_mark("timeout"')
            check("★而且要落在「附了超時說明行」那一段裡★(不是隨便放一處)",
                  "超時說明行" in dl[max(0, i_m - 900):i_m + 300], dl[max(0, i_m-400):i_m+200])
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_hook_swallowed_timeout_is_not_recorded_as_ok")


def t_hook_event_write_failure_is_announced():
    """★hook 事件寫不進去也要喊 telemetry-write-failed★(2026-09-08 r1 外家席 major)。

    S7 原本只蓋到治理帳那本。`record()` 把寫入錯誤吞成 False,而 `guard()` 完全不看回傳值
    ——磁碟滿、權限錯時 stderr 一個字都沒有,操作者只會看到 enforcement 慢慢變 stale,
    ★分不出是 hook 沒跑,還是帳壞了★。
    """
    import shutil as _sh, tempfile as _tf, subprocess as _sp, os as _os
    _need_src("scripts/hooks/claude/_hookevent.py")
    hookdir = Path(GRAPHCTL).resolve().parent / "hooks" / "claude"
    root = Path(_tf.mkdtemp(prefix="gctl-hwfail-"))
    try:
        _sp.run(["git", "init", "-q", str(root)], check=True, capture_output=True)
        rt = root / "governance" / "runtime"; rt.mkdir(parents=True)
        log = rt / "hook-events.jsonl"; log.write_text("", encoding="utf-8")
        _os.chmod(log, 0o444)
        probe = root / "p.py"
        probe.write_text(
            "import sys\n"
            "sys.path.insert(0, %r)\n" % str(hookdir) +
            "from _hookevent import guard\n"
            "def main():\n    return 0\n"
            "sys.exit(guard('H', __file__, main))\n", encoding="utf-8")
        r = _sp.run([sys.executable, str(probe)], cwd=str(root), capture_output=True, text=True, timeout=60)
        check("★寫不進去要在 stderr 明講★", "telemetry-write-failed" in r.stderr, r.stderr[-300:])
        check("★但 hook 自己的工作不受影響(rc 照舊)★", r.returncode == 0, str(r.returncode))
        check("★訊息要講明本業不受影響★", "不受影響" in r.stderr, r.stderr[-200:])
        _os.chmod(log, 0o644)
    finally:
        _sh.rmtree(root, ignore_errors=True)
    print("  ✓ t_hook_event_write_failure_is_announced")


def t_double_skip_does_not_fully_open_the_gate():
    """★兩個跳閘不准疊成完整放行★(2026-09-08 r1 外家席 major,我實測屬實)。

    `--skip-bound-tests --note …` 讓合約測試閘回 skipped,再加 `LUMOS_SKIP_CODE_LOOP=1`
    跳掉留痕要求——兩層疊起來就是完整放行,★直接推翻「合約測試閘不可跳」這句話★。

    處置不是把話改小,是不准疊:合約測試閘已經被跳過時,那個環境變數失效。
    """
    import json as _j, os as _os, shutil as _sh, subprocess as _sp
    lumos_real = str(Path(__file__).resolve().parent / "lumos")
    d = _mk_bound_tests_repo(tempfile.mkdtemp(prefix="gctl-dskip-"))
    try:
        (Path(d) / "app" / "pay.py").write_text(
            "def charge(x):\n    f = open('/dev/null')\n    return abs(x)\n", encoding="utf-8")
        _sp.run(["git", "-C", str(d), "add", "-A"], capture_output=True)
        _sp.run(["git", "-C", str(d), "-c", "user.email=t@t", "-c", "user.name=t",
                 "commit", "-qm", "high", "--no-verify"], capture_output=True)
        e = dict(_os.environ); e.pop("LUMOS_SKIP_BOUND_TESTS", None)
        e["LUMOS_SKIP_CODE_LOOP"] = "1"
        r = _sp.run([sys.executable, lumos_real, "code-loop", "check", "--diff", "HEAD~1..HEAD",
                     "--json", "--repo", str(d), "--skip-bound-tests", "--note", "外部 DB 不在"],
                    capture_output=True, text=True, env=e, timeout=180)
        v = _j.loads(r.stdout)
        check("★兩個跳閘一起用時不准完整放行★",
              r.returncode == 1 and v["blocked"], r.stdout + r.stderr[-400:])
        check("★而且要講清楚為什麼不接受★", "兩個跳閘" in r.stderr or "已經被跳過" in r.stderr,
              r.stderr[-300:])
    finally:
        _sh.rmtree(d, ignore_errors=True)
    print("  ✓ t_double_skip_does_not_fully_open_the_gate")


