def t_doctor_lists_unmentioned_home_pairs():
    """[S15] 代碼審 r1:健檢那半(掃全部已提交節點的舊帳)原本零測試覆蓋——整段拿掉照樣全綠。
    它跟提交前那半是兩份獨立實作,各自要有測試釘住。"""
    print("t_doctor_lists_unmentioned_home_pairs")
    import subprocess as sp
    root = _nh_repo()
    _nh_base(root)
    _nh_file(root, "src/silent.py")
    _nh_node(root, "沒提到它管的檔", about=["src/silent.py"], body="這篇講一些別的事。")
    _nh_node(root, "有提到它管的檔", about=["src/a.py"], body="實作在 `src/a.py`。")
    _nh_commit(root, "上線前就在的舊帳")
    r = sp.run([sys.executable, GRAPHCTL, "doctor", "--verbose"], capture_output=True, text=True, cwd=str(root))
    seg = r.stdout[r.stdout.find("[S11]"):]
    seg = seg[:seg.find("\n[", 1)] if "\n[" in seg[1:] else seg
    check("①健檢列出「管了卻沒提到檔名」的舊帳",
          "沒提到它管的檔" in seg and "src/silent.py" in seg, seg[-800:])
    check("②有提到的那篇不列", "有提到它管的檔" not in seg, seg[-800:])
    check("③是提醒不是擋(健檢不因為這段就判不健康)", r.returncode == 0, f"rc={r.returncode}")


def t_nodehome_new_home_unmentioned_reminds():
    """[S15] 這次新掛進某篇 about_code 的檔,那篇的摘要與正文卻連檔名都沒提到 → 提醒(不擋)。
    家從此一定推,隨手塞一支檔進去就等於把無關的篇推到別人眼前;寫入當下講一句最便宜。"""
    print("t_nodehome_new_home_unmentioned_reminds")
    root = _nh_repo()
    _nh_base(root)
    _nh_file(root, "src/c.py"); _nh_file(root, "src/d.py")
    # A 多管一支 c.py,正文有寫出來;B 多管一支 d.py,正文完全沒提
    _nh_node(root, "A", about=["src/a.py", "src/c.py"], body="實作在 `src/a.py`,另一半在 `src/c.py`。")
    _nh_node(root, "B", about=["src/b.py", "src/d.py"], body="實作在 `src/b.py`。")
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("①正文沒提到的那支 → 提醒", "src/d.py" in out and "沒提到" in out, out[-700:])
    check("②正文有寫出來的那支 → 不唸", "src/c.py" not in out, out[-700:])
    check("③只提醒不擋", rc == 0, f"rc={rc}\n" + out[-400:])
    check("④指路兩條:寫一句它負責什麼,或改掛真的在講它的那篇",
          "負責" in out and "改掛" in out, out[-700:])


def _nh_regen(root, name, about=(), resp=None, regen="from-scratch/2026-09-12", body="從程式重建。"):
    """蓋了「從程式重建」章的 Systems 節點(regen 欄)。"""
    return _nh_node(root, name, about=about, resp=resp, body=body,
                    extra=f"regen: {regen}")


def t_nodehome_new_regen_node_requires_about_code():
    """[S11] 這次新蓋「從程式重建」章的節點,about_code 空的、又沒寫負責範圍 → 擋。
    還原節點是圖譜重生的起點,一開始就沒說自己管哪些檔,之後每一次寫回都不知道該落哪。"""
    print("t_nodehome_new_regen_node_requires_about_code")
    root = _nh_repo()
    _nh_base(root)
    # 既有節點,這次才第一次蓋章:about_code 空、負責範圍沿用舊文字(沒交代為什麼不管檔)
    _nh_node(root, "老篇", about=["src/b.py"], body="講 `src/b.py`。")
    _nh_commit(root, "先有一篇老的")
