def t_impact_home_knob_off_is_old_behavior():
    """[S7] 旋鈕 LUMOS_IMPACT_HOME=0:完全回到原本——不認家,舊的「關於命中」照舊要預標指紋沒過期,
    舊旋鈕 LUMOS_IMPACT_ABOUT 照舊管它。這是回滾與離線對照用的,不是給使用者的旗標。"""
    print("t_impact_home_knob_off_is_old_behavior")
    m = _load_lumos_module()
    root = _nh_repo()
    _nh_file(root, "src/pay.py")
    _nh_node(root, "有指紋的家", about=["src/pay.py"], body="計價在 `src/pay.py`。")
    v = root / "docs" / "kg-knowledge"
    rel = "Systems/有指紋的家.md"
    txt = (v / rel).read_text(encoding="utf-8")
    (v / rel).write_text(txt.replace("about_code:", f"about_code_stamp: claude/2026-09-12/{m.note_body_hash(v, rel)}\nabout_code:"),
                         encoding="utf-8")
    # 雜湊要對「寫完之後」的正文算,所以重算一次
    txt2 = (v / rel).read_text(encoding="utf-8")
    import re as _re
    (v / rel).write_text(_re.sub(r"about_code_stamp: claude/2026-09-12/\w+",
                                 f"about_code_stamp: claude/2026-09-12/{m.note_body_hash(v, rel)}", txt2),
                         encoding="utf-8")
    _nh_git(root, "add", "-A")
    d0 = _home_impact(root, "src/pay.py", {"LUMOS_IMPACT_HOME": "0"})
    by0 = {x["node"]: x for x in d0["results"]}
    check("①旋鈕關掉:不標家、不保送",
          not by0.get(rel, {}).get("home") and not by0.get(rel, {}).get("pinned"), str(by0.get(rel)))
    check("②舊的「關於命中」照舊出現", by0.get(rel, {}).get("about_hit"), str(by0.get(rel)))
    d_off = _home_impact(root, "src/pay.py", {"LUMOS_IMPACT_HOME": "0", "LUMOS_IMPACT_ABOUT": "0"})
    by_off = {x["node"]: x for x in d_off["results"]}
    check("③舊旋鈕照舊管得動它", "about_hit" not in by_off.get(rel, {}), str(by_off.get(rel)))
    d1 = _home_impact(root, "src/pay.py")
    by1 = {x["node"]: x for x in d1["results"]}
    check("④預設(旋鈕開著)走的是家那條路", by1.get(rel, {}).get("home") and by1[rel]["pinned"], str(by1.get(rel)))


def t_about_stamp_no_longer_affects_ranking():
    """[S9] 旋鈕開著時,舊的「關於命中」整段不跑:預標指紋過不過期都不影響推筆記
    (確認過的家照樣保送、沒確認的家照樣什麼都不做);指紋相關的指令與健檢提醒保留,給舊資料和回滾用。"""
    print("t_about_stamp_no_longer_affects_ranking")
    import subprocess as _sp
    root = _nh_repo()
    _nh_file(root, "src/pay.py")
    # 指紋是壞的(過期):舊制會因此不給關於命中
    _nh_node(root, "指紋過期的家", about=["src/pay.py"], body="計價在 `src/pay.py`。",
             extra="about_code_stamp: claude/2026-09-12/deadbeef")
    _nh_node(root, "指紋過期沒確認", about=["src/pay.py"], body="這篇沒寫出那支檔。",
             extra="about_code_stamp: claude/2026-09-12/deadbeef")
    _nh_git(root, "add", "-A")
    by = {x["node"]: x for x in _home_impact(root, "src/pay.py")["results"]}
    check("①指紋過期也照樣保送(指紋不再影響推筆記)",
          by.get("Systems/指紋過期的家.md", {}).get("pinned") and by["Systems/指紋過期的家.md"].get("home"),
          str(by.get("Systems/指紋過期的家.md")))
    check("②旋鈕開著時不再出現舊的關於命中標記",
          all("about_hit" not in x for x in by.values()), str(by)[:300])
    check("③沒確認的家照樣什麼都不做(指紋壞不壞都一樣)",
          not by.get("Systems/指紋過期沒確認.md", {}).get("home"), str(by.get("Systems/指紋過期沒確認.md")))
    r = _sp.run([sys.executable, GRAPHCTL, "about-code", "--help"], capture_output=True, text=True, cwd=str(root))
    check("④指紋相關的指令保留(舊資料與回滾用)",
          "restamp" in r.stdout and "revert" in r.stdout, r.stdout[:300] + r.stderr[:200])


def t_impact_home_incident_keeps_both_labels():
    """代碼審 r2:一篇同時是事故又是家時,兩個身份都要看得到。
    原本家會把事故蓋掉——事故是最高優先的安全訊號,蓋掉等於把「這裡出過事」藏起來。
    ★兩條顯示路徑都要釘★:推送前的派工鏡頭(--diff)與計劃模式的派工鏡頭(--spec)。"""
    print("t_impact_home_incident_keeps_both_labels")
    import subprocess as _sp
    root = _nh_repo()
    _nh_file(root, "src/pay.py")
    # ★要 Systems 型★:家的定義就是「狀態現行的 Systems 節點」,Issues 當不了家;
    # 一個 Systems 節點掛了事故觸發條件,就會同時是事故又是家——這正是這支測試要驗的組合。
    _nh_node(root, "出過事又管它", about=["src/pay.py"], body="出事的是 `src/pay.py`。",
             summary="FLOW:x\nKEY:出過事")
    n = root / "docs" / "kg-knowledge" / "Systems" / "出過事又管它.md"
    n.write_text(n.read_text(encoding="utf-8").replace("about_code:", "pitfall_when:\n  - glob:src/pay.py\nabout_code:"),
                 encoding="utf-8")
    _nh_git(root, "add", "-A"); _nh_git(root, "commit", "-qm", "base")
    _nh_file(root, "src/pay.py", "x = 2\n")
    _nh_git(root, "add", "-A"); _nh_git(root, "commit", "-qm", "change")
    r = _sp.run([sys.executable, GRAPHCTL, "dispatch-lens", "HEAD~1..HEAD", "--repo", str(root)],
                capture_output=True, text=True)
    line = next((l for l in r.stdout.splitlines() if "出過事又管它" in l), "")
    check("①推送前的鏡頭:事故與家兩個都印得出來", "事故" in line and "家" in line,
          repr(line) + r.stdout[:300])
    _nh_node(root, "某案_計劃", typ="project", folder="Projects", resp=None,
             summary="KEY:試", body="要改 `src/pay.py`。")
    _nh_git(root, "add", "-A"); _nh_git(root, "commit", "-qm", "plan")
    r2 = _sp.run([sys.executable, GRAPHCTL, "dispatch-lens", "--spec",
                  "docs/kg-knowledge/Projects/某案_計劃.md", "--repo", str(root)], capture_output=True, text=True)
    line2 = next((l for l in r2.stdout.splitlines() if "出過事又管它" in l), "")
    check("②計劃模式的鏡頭也一樣(這條路原本把家的身份整個丟掉)",
          "事故" in line2 and "家" in line2, repr(line2) + r2.stdout[:400])


