def t_impact_home_uses_nodehome_definition():
    """[S1] 家對照表只有一支算法:每支檔有家從提交快照餵、推筆記從已載入的圖譜餵,兩邊拿到同一張表。
    [S2] 確認過的家:全文寫出完整路徑,或反引號裡寫出在受版控檔裡唯一的裸檔名;裸檔名不在反引號裡不算
    (沒有副檔名的程式檔,檔名是普通詞——全庫 65 篇 Systems 有 62 篇正文出現裸字 lumos)。"""
    print("t_impact_home_uses_nodehome_definition")
    m = _load_lumos_inproc()
    root = _nh_repo()
    _nh_file(root, "src/pay.py"); _nh_file(root, "src/cart.py"); _nh_file(root, "tools/runner")
    _nh_node(root, "金流", about=["src/pay.py"], body="這篇講 `src/pay.py` 的計價。")
    _nh_node(root, "購物車", about=["src/cart.py"], body="購物車的狀態機;檔在 src/cart.py。")
    _nh_node(root, "跑測試", about=["tools/runner"], body="用 `runner` 跑一次就好(裸檔名在反引號裡)。")
    _nh_node(root, "隨手塞", about=["src/cart.py"], body="這篇完全沒提到那支檔。", summary="FLOW:無關")
    _nh_node(root, "計劃型", about=["src/pay.py"], typ="project", folder="Projects", status="doing")
    _nh_git(root, "add", "-A")
    side = m._nodehome_side(root, "index", "docs/kg-knowledge")
    homes_snap, _own = m._nodehome_homes(root, side)
    env = m.Env(root / "docs" / "kg-knowledge")
    homes_env, _o2 = m._impact_home_map(env)
    check("①兩邊餵同一支純函式,拿到同一張家對照表", homes_snap == homes_env, f"{homes_snap} vs {homes_env}")
    check("②只算 Systems 與 doing/done/stale(計劃型不算家)", homes_env.get("src/pay.py") == ["Systems/金流.md"], str(homes_env))
    top = m._nodehome_top_dirs([p for p in side.all_paths if "/" in p])
    def conf(node, path):
        text = (root / "docs" / "kg-knowledge" / "Systems" / f"{node}.md").read_text(encoding="utf-8")
        return m._home_confirmed(text, path, top, side.all_paths)
    check("③反引號裡寫完整路徑 → 確認", conf("金流", "src/pay.py"), "")
    check("④正文(沒有反引號)寫出完整路徑 → 確認", conf("購物車", "src/cart.py"), "")
    check("⑤反引號裡寫唯一的裸檔名 → 確認(沒有副檔名的檔也一樣)", conf("跑測試", "tools/runner"), "")
    check("⑥完全沒提到 → 不算確認", not conf("隨手塞", "src/cart.py"), "")
    plain = root / "docs" / "kg-knowledge" / "Systems" / "裸字.md"
    _nh_node(root, "裸字", about=["tools/runner"], body="這篇散文裡只寫了 runner 這個字,沒有反引號。")
    check("⑦裸檔名不在反引號裡不算確認(普通詞會誤判)",
          not m._home_confirmed(plain.read_text(encoding="utf-8"), "tools/runner", top, side.all_paths), "")


def t_nodehome_home_definition():
    """[S2] 家:狀態 doing/done/stale 的 Systems 節點 about_code 列了它;planned/deferred/rejected/superseded 不算;
    只看欄位值、不看預標指紋;Issues 不算。"""
    print("t_nodehome_home_definition")
    m = _load_lumos_inproc()
    root = _nh_repo()
    for i, st in enumerate(("doing", "done", "stale", "planned", "deferred", "rejected", "superseded")):
        _nh_file(root, f"src/f{i}.py")
        _nh_node(root, f"N{i}", about=[f"src/f{i}.py"], status=st)
    _nh_file(root, "src/x.py")
    _nh_node(root, "Stamped", about=["src/x.py"], extra="about_code_stamp: claude/2026-09-01/deadbeef")
    _nh_file(root, "src/i.py")
    _nh_node(root, "Inc", about=["src/i.py"], typ="issue", status="open", folder="Issues")
    _nh_git(root, "add", "-A")
    side = m._nodehome_side(root, "index", "docs/kg-knowledge")
    homes, _own = m._nodehome_homes(root, side)
    got = {f"src/f{i}.py": bool(homes.get(f"src/f{i}.py")) for i in range(7)}
    check("①doing/done/stale 算家", got["src/f0.py"] and got["src/f1.py"] and got["src/f2.py"], str(got))
    check("②planned/deferred/rejected/superseded 不算", not any(got[f"src/f{i}.py"] for i in (3, 4, 5, 6)), str(got))
    check("③預標指紋對不上照樣算家(只看欄位值)", bool(homes.get("src/x.py")), str(homes.get("src/x.py")))
    check("④Issues 的 about_code 不算家", not homes.get("src/i.py"), str(homes.get("src/i.py")))


def t_nodehome_check_blocks_new_homeless_file():
    """[S3] 新增的程式檔提交後沒家 → 擋;同一個提交順手建家 → 過;改名成新路徑、about_code 沒跟上 → 擋。"""
    print("t_nodehome_check_blocks_new_homeless_file")
    root = _nh_repo()
    _nh_base(root)
    _nh_file(root, "src/c.py")
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("①新增 src/c.py 沒家 → rc1,訊息講出是哪一支", rc == 1 and "c.py" in out, out[-600:])
    _nh_node(root, "C", about=["src/c.py"])
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("②同一個提交順手建家 → rc0", rc == 0, out[-600:])
    _nh_git(root, "reset", "-q", "--hard")
    _nh_git(root, "clean", "-qfd")
    _nh_git(root, "mv", "src/a.py", "src/a2.py")
    rc, out = _nh_check(root)
    check("③改名成新路徑、about_code 沒跟上 → rc1(新路徑算新增)", rc == 1 and "a2.py" in out, out[-600:])
    _nh_git(root, "reset", "-q", "--hard")
    _nh_git(root, "config", "diff.renames", "copies")      # 使用者設了「偵測複製」也一樣:檢查自己帶 -M,複製照樣標成 A
    _nh_file(root, "src/a3.py", (root / "src" / "a.py").read_text(encoding="utf-8"))
    _nh_file(root, "src/a.py", "x = 1\ny = 2\n")
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("④複製一支既有的檔(同時改原檔)→ 複製出來的那支算新增、沒家 rc1", rc == 1 and "a3.py" in out, out[-600:])


