def t_nodehome_foreign_ref_uses_impact_extraction():
    """[S7] 「這篇寫到哪支檔」跟改檔前推筆記、refcheck 共用同一支抽取——兩邊認得的一定一樣。"""
    print("t_nodehome_foreign_ref_uses_impact_extraction")
    import ast as _ast
    src = Path(GRAPHCTL).read_text(encoding="utf-8")
    tree = _ast.parse(src)
    calls = {}
    for fn in tree.body:
        if isinstance(fn, _ast.FunctionDef):
            names = {c.func.id for c in _ast.walk(fn) if isinstance(c, _ast.Call) and isinstance(c.func, _ast.Name)}
            calls[fn.name] = names
    for who in ("_refcheck_scan", "_impact_reverse_lookup", "_nodehome_refs"):
        check(f"①{who} 呼叫共用抽取 _node_code_ref_tokens", "_node_code_ref_tokens" in calls.get(who, set()), str(sorted(calls.get(who, set())))[:300])
    for who in ("_refcheck_scan", "_impact_reverse_lookup", "_nodehome_refs"):
        body = _ast.get_source_segment(src, next(f for f in tree.body if isinstance(f, _ast.FunctionDef) and f.name == who))
        check(f"②{who} 不再自己跑 INLINE_CODE_RE(不另寫一套)", "INLINE_CODE_RE" not in body, who)
    # 行為面:推筆記與每支檔有家對同一段文字認得的檔一樣
    root = _nh_repo()
    _nh_base(root)
    _nh_node(root, "A", about=["src/a.py"], body="實作在 `src/a.py`,也寫了 `src/b.py:12` 與裸檔名 `b.py`、`src/*.py`、`http://x/src/b.py`。")
    _nh_git(root, "add", "-A")
    m = _load_lumos_inproc()
    side = m._nodehome_side(root, "index", "docs/kg-knowledge")
    req, _bad = m._nodehome_required(root, side, m._nodehome_config(root), frozenset())
    refs = m._nodehome_refs(side.notes["Systems/A.md"]["text"], side, req)
    env = m.Env(root / "docs" / "kg-knowledge")
    hit_b = [n for n, _h in m._impact_reverse_lookup("src/b.py", env, root) if n == "Systems/A.md"]
    check("③推筆記會把 A 推給 src/b.py,每支檔有家也認得 A 寫到 src/b.py", bool(hit_b) and "src/b.py" in refs, f"{hit_b} {refs}")


