    rc, out = _nh_check(root)
    check("①3→4、沒寫 → rc1", rc == 1 and "Systems/Big" in out and "管 4 支檔" in out, out[-600:])
    _nh_node(root, "Big", about=["src/a.py", "src/b.py", "src/c.py", "src/d.py"], body="`src/a.py` `src/b.py` `src/c.py` `src/d.py`")
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("②寫了負責範圍 → rc0", rc == 0, out[-600:])
    _nh_git(root, "reset", "-q", "--hard")
    _nh_node(root, "Big", about=["src/a.py", "src/b.py", "src/c.py", "src/gone.py"], resp=None, body="`src/a.py`")
    _nh_git(root, "add", "-A")
    rc, out = _nh_check(root)
    check("③多的那項是不存在的檔 → 不算變多 → rc0", rc == 0, out[-600:])
    for bad, want in ((True, 3), (0, 3), ("5", 3), (5, 5)):
        r2 = _nh_repo({"node_home": {"max_files": bad}})
