def _nh_doctor(root):
    import subprocess as sp
    r = sp.run([sys.executable, GRAPHCTL, "--vault", str(root / "docs" / "kg-knowledge"), "doctor", "--verbose"],
               capture_output=True, text=True)
    return r.returncode, r.stdout + r.stderr


def t_doctor_nodehome_sections():
    """[S28] 健檢多三段(沒家的檔、寫了別人檔名的節點、管太多沒寫負責範圍):不擋、排在合約條數那段之後、[H] 之前。"""
    print("t_doctor_nodehome_sections")
    root = _nh_repo()
    _nh_base(root)
    _nh_file(root, "src/legacy.py")
    for f in ("c", "d", "e", "f"):
        _nh_file(root, f"lib/{f}.py")
    _nh_node(root, "Big", about=[f"lib/{f}.py" for f in "cdef"], resp=None, body="`lib/c.py`")
    _nh_node(root, "A", about=["src/a.py"], body="`src/a.py` 也寫了 `src/b.py`")
    _nh_commit(root, "舊帳三種都有")
    rc, out = _nh_doctor(root)
    i7, i8, i9, i10, ih = (out.find(x) for x in ("[S7]", "[S8]", "[S9]", "[S10]", "[H]"))
    check("①三段都在,順序 S7 < S8 < S9 < S10 < H", 0 <= i7 < i8 < i9 < i10 < ih, f"{i7} {i8} {i9} {i10} {ih}")
    s8, s9, s10 = out[i8:i9], out[i9:i10], out[i10:ih]
    import re as _re2
    _lines = out.splitlines()
    _prev = {k: next((_lines[j - 1] for j, l in enumerate(_lines) if k in l and j > 0), None) for k in ("[S9]", "[S10]")}
    check("①b S9、S10 前面各空一行(代碼審 r1 邊界席:原本三段黏在一起)",
          all(v is not None and not _re2.sub(r"\x1b\[[0-9;]*m", "", v).strip() for v in _prev.values()), repr(_prev))
    check("②S8 列出沒家的舊檔", "src/legacy.py" in s8, s8[:400])
    check("③S9 列出寫了別人檔名的節點", "Systems/A" in s9 and "src/b.py" in s9, s9[:400])
    check("④S10 列出管超過上限沒寫負責範圍的節點", "Systems/Big" in s10 and "管 4 支" in s10, s10[:400])
    rc2, out2 = _nh_doctor(_nh_repo())
    check("⑤只有軟提醒時 rc 不因這三段改變(空圖譜也不炸)", "Traceback" not in out2, out2[-300:])


def t_doctor_nodehome_sections_share_check_logic():
    """[S29] 健檢三段跟 home check 共用同一套函式(需要家的檔、家、別人的檔、讀快照)。"""
    print("t_doctor_nodehome_sections_share_check_logic")
    import ast as _ast
    src = Path(GRAPHCTL).read_text(encoding="utf-8")
    tree = _ast.parse(src)
    def called(name):
        fn = next(f for f in tree.body if isinstance(f, _ast.FunctionDef) and f.name == name)
        return {c.func.id for c in _ast.walk(fn) if isinstance(c, _ast.Call) and isinstance(c.func, _ast.Name)}
    led, ev = called("_nodehome_ledger"), called("_nodehome_evaluate") | called("cmd_home_check")
    for f in ("_nodehome_side", "_nodehome_required", "_nodehome_homes", "_nodehome_refs", "_nodehome_config"):
        check(f"①健檢與提交前檢查都用 {f}", f in led and f in ev, f"led={f in led} ev={f in ev}")


