def t_nodehome_decisions_compared_by_value():
    """[S12] 決策比解析後的值:只把 content: a 改成 content: \\"a\\" 這種等價寫法,不算內容有變。"""
    print("t_nodehome_decisions_compared_by_value")
    m = _load_lumos_inproc()
    a = m._nodehome_parse_note("---\ntype: system\nstatus: doing\ndecisions:\n  - content: a\n    id: d1\n---\n# t\n")
    b = m._nodehome_parse_note('---\ntype: system\nstatus: doing\ndecisions:\n  - content: "a"\n    id: d1\n---\n# t\n')
    c = m._nodehome_parse_note("---\ntype: system\nstatus: doing\ndecisions:\n  - content: b\n    id: d1\n---\n# t\n")
    check("①等價寫法 → 內容沒變", a["sig"] == b["sig"], f"{a['sig'][1]} vs {b['sig'][1]}")
    check("②值真的變了 → 內容有變", a["sig"] != c["sig"])


