def t_lint_shebang_ext():
    """★沒有副檔名的檔要看第一行★——工具鏈自己的主程式就是這種檔(python3 但沒有 .py)。
    2026-09-13 真的裝了 linter 實跑才撞到:它過得了「要不要掃」那一關,
    但照副檔名對宣告的話任何宣告都對不上它,這個專案最重要的那支檔對整道閘是隱形的。"""
    import json as _j
    import sys as _s
    m = _lng_module()
    root, git = _lng_repo("gctl-lngsb-")
    (root / "tool").write_text("#!/usr/bin/env python3\nBAD = 1\n", encoding="utf-8")
    (root / "plain").write_text("just text, no shebang\n", encoding="utf-8")
    (root / "app.py").write_text("x = 1\n", encoding="utf-8")
    git("add", "-A"); git("commit", "-m", "base")
    head = git("rev-parse", "HEAD").stdout.strip()
    check("有副檔名的照舊", m._lint_file_ext("app.py", root, head) == "py", "")
    check("沒副檔名但有 python shebang → 當 py", m._lint_file_ext("tool", root, head) == "py", "")
    check("沒副檔名也沒 shebang → 不硬猜", m._lint_file_ext("plain", root, head) == "", "")
    check("bash shebang → 當 sh", m._lint_file_ext("x", None, None) == "", "沒有 repo 也不該炸")

    # 接線:沒有副檔名的檔真的會被派給對應的命令
    helper = Path(tempfile.mkdtemp(prefix="gctl-lngsb-h-"))
    cmd = _lng_fake_linter(helper, "s.py", [["BAD", "R", "x"]])
    (root / ".lumos").mkdir(parents=True, exist_ok=True)
    (root / ".lumos" / "lint.json").write_text(_j.dumps({"py": [cmd]}), encoding="utf-8")
    base = head
    (root / "tool").write_text("#!/usr/bin/env python3\nBAD = 1\nBAD = 2\n", encoding="utf-8")
    git("add", "-A"); git("commit", "-m", "two")
    v = m._lint_new_verdict(root, f"{base}..HEAD")
    check("沒副檔名的檔真的被掃到了", v["blocked"] is True and any(c["file"] == "tool" for c in v["new"]),
          str(v["new"])[:200])


def t_lint_snapshot_support():
    """★工具要跑得起來,光有被掃的檔不夠★(2026-09-13 真專案實測撞到):
    eslint 的設定在子目錄、外掛要 node_modules,快照裡只有改動檔的話它直接拒跑。
    所以快照要補:祖先目錄的設定檔(取現在版,兩邊同一份規則)+依賴目錄的連結。"""
    m = _lng_module()
    root, git = _lng_repo("gctl-lngsup-")
    (root / "client" / "src").mkdir(parents=True, exist_ok=True)
    (root / "client" / "src" / "a.js").write_text("var x = 1\n", encoding="utf-8")
    (root / "client" / "eslint.config.mjs").write_text("export default []\n", encoding="utf-8")
    (root / "client" / "package.json").write_text('{"name":"c"}\n', encoding="utf-8")
    (root / "pyproject.toml").write_text("[tool.ruff]\n", encoding="utf-8")
    git("add", "-A"); git("commit", "-m", "base")
    head = git("rev-parse", "HEAD").stdout.strip()
    # 依賴目錄不進版控,用真的目錄
    (root / "client" / "node_modules" / "pkg").mkdir(parents=True, exist_ok=True)

    dest = Path(tempfile.mkdtemp(prefix="gctl-lngsup-d-"))
    m._lint_new_support(root, head, ["client/src/a.js"], dest)
    check("子目錄的設定檔有被補進去", (dest / "client" / "eslint.config.mjs").is_file(),
          str(sorted(x.name for x in (dest / "client").glob("*")) if (dest / "client").is_dir() else []))
    check("同一層的 package.json 也補", (dest / "client" / "package.json").is_file(), "")
    check("專案根的設定檔也補", (dest / "pyproject.toml").is_file(), "")
    check("依賴目錄用連結指回真的專案", (dest / "client" / "node_modules").is_symlink(), "")
    # 被掃的檔本身不該被這一步蓋掉(它是 extract 放進去的)
    check("不會把原始碼一起搬進來", not (dest / "client" / "src" / "a.js").exists(), "")


def t_lint_config_from_head_only():
    """設定檔一律取現在版——基準版那次用舊設定的話,比出來的差集沒有意義(同一份規則比兩次)。"""
    m = _lng_module()
    root, git = _lng_repo("gctl-lngcfg-")
    (root / "app.py").write_text("x = 1\n", encoding="utf-8")
    (root / "ruff.toml").write_text("OLD\n", encoding="utf-8")
    git("add", "-A"); git("commit", "-m", "base")
    base = git("rev-parse", "HEAD").stdout.strip()
    (root / "ruff.toml").write_text("NEW\n", encoding="utf-8")
    git("add", "-A"); git("commit", "-m", "改設定")
    head = git("rev-parse", "HEAD").stdout.strip()
    d_base = Path(tempfile.mkdtemp(prefix="gctl-lngcfg-b-"))
    # 呼叫端固定傳 head_ref,所以基準版那邊也會拿到新設定
    m._lint_new_support(root, head, ["app.py"], d_base)
    got = (d_base / "ruff.toml").read_text(encoding="utf-8").strip()
    check("基準版快照拿到的是現在版的設定", got == "NEW", got)


def t_lint_snapshot_support_applied():
    """★守消費端★:判定真的會把設定檔補進快照。
    只測那支輔助函式不夠——把判定裡呼叫它那兩行拿掉,輔助函式的測試照樣綠(實測過,同一型假守衛第三次)。"""
    import json as _j
    import sys as _s
    m = _lng_module()
    root, git = _lng_repo("gctl-lngsa-")
    helper = Path(tempfile.mkdtemp(prefix="gctl-lngsa-h-"))
    # 假檢查工具:★要在被掃檔案的同一層找到設定檔才肯跑★(仿 eslint 找不到設定就拒跑)
    script = helper / "needcfg.py"
    script.write_text(
        "import sys, json, os\n"
        "out = sys.argv[1]\n"
        "targets = sys.argv[2:]\n"
        "for t in targets:\n"
        "    if not os.path.isfile(os.path.join(os.path.dirname(t), 'tool.config.js')):\n"
        "        sys.exit(3)            # 找不到設定:直接拒跑,連 SARIF 都不吐\n"
        "res = [{'ruleId': 'NEEDCFG', 'message': {'text': 'x'}, 'locations': [\n"
        "    {'physicalLocation': {'artifactLocation': {'uri': t},\n"
        "     'region': {'startLine': 1, 'endLine': 1}}}]} for t in targets\n"
        "       if 'BAD' in open(t, encoding='utf-8').read()]\n"
        "json.dump({'version': '2.1.0', 'runs': [{'tool': {'driver': {'name': 'F'}}, 'results': res}]}, open(out, 'w'))\n",
        encoding="utf-8")
    (root / ".lumos").mkdir(parents=True, exist_ok=True)
    (root / ".lumos" / "lint.json").write_text(_j.dumps({
        "py": [f"{_s.executable} {script} {{LINT_SARIF_OUT}} {{LINT_FILES}}"]}), encoding="utf-8")
    (root / "app.py").write_text("x = 1\n", encoding="utf-8")
    (root / "tool.config.js").write_text("// 設定\n", encoding="utf-8")
    git("add", "-A"); git("commit", "-m", "base")
    base = git("rev-parse", "HEAD").stdout.strip()
    (root / "app.py").write_text("x = 1\nBAD = 2\n", encoding="utf-8")
    git("add", "-A"); git("commit", "-m", "two")
    v = m._lint_new_verdict(root, f"{base}..HEAD")
    check("設定檔有被補進快照,工具才跑得起來", v["blocked"] is True and len(v["new"]) == 1,
          f"status={v['status']} reason={v['reason'][:60]} undone={v['undone']}")


def _mk_mw_fixture(query="斑馬 條紋 計數", contaminate=False, extra=0):
    """見下方 _mk_mw_fixture_body;extra 會多建幾篇只含單一詞的筆記,
    讓「逐詞前三」與「全詞同篇」兩個來源撈得到不同的東西(r1 測試品質席:
    三來源聯集原本零覆蓋——把來源二三清空,四支測試照樣全綠)。"""
    return _mk_mw_fixture_body(query, contaminate, extra)


def _mk_mw_fixture_body(query="斑馬 條紋 計數", contaminate=False, extra=0):
    """多詞評測的小夾具:一個 vault + 一份題庫。回 (vault, poolfile)。

    contaminate=True 時把查詢字面寫進其中一篇筆記——重現「題目被寫進語料」那個坑。"""
    import json as _json
    root = Path(tempfile.mkdtemp(prefix="gctl-mw-"))
    vault = root / "kg"
    (vault / "Systems").mkdir(parents=True)
    (vault / "Systems" / "A.md").write_text(
        "---\ntype: system\nstatus: done\n---\n# A\n斑馬 很多。條紋 很密。計數 很難。\n",
        encoding="utf-8")
    (vault / "Systems" / "B.md").write_text(
        "---\ntype: system\nstatus: done\n---\n# B\n斑馬 出沒。條紋 淺。\n", encoding="utf-8")
    (vault / "Systems" / "C.md").write_text(
        "---\ntype: system\nstatus: done\n---\n# C\n計數 方法。條紋 分析。斑馬 生態。\n",
        encoding="utf-8")
    # 只含單一詞的筆記:全詞同篇那個來源永遠撈不到它們,逐詞那個來源撈得到
    for i in range(extra):
        w = query.split()[i % len(query.split())]
        (vault / "Systems" / f"only{i}.md").write_text(
            "---\ntype: system\nstatus: done\n---\n# only%d\n" % i
            + (w + " ") * (12 + i) + "\n", encoding="utf-8")
    if contaminate:
        f = vault / "Systems" / "D.md"
        f.write_text("---\ntype: system\nstatus: done\n---\n# D\n這篇提到 " + query + " 這串。\n",
                     encoding="utf-8")
    poolfile = root / "pool.json"
    poolfile.write_text(_json.dumps({"M01": {"query": query, "pool": []}}, ensure_ascii=False),
                        encoding="utf-8")
    return vault, poolfile


def t_mw_queries_absent_from_vault():
    """★真守衛★:多詞題庫裡每一題的查詢,都不准逐字出現在圖譜任何一篇筆記裡。

    出身(Issues/評測題目寫進圖譜就毀掉那一題):圖譜本身就是這套評測的語料。
    查詢字串一旦逐字寫進筆記,「整串當片語查」那一臂就有命中,「拆詞各查」那一臂
    便不會啟動(它只在整串全庫零命中時觸發),於是兩臂量出一模一樣的數字,
    ★而且不會有任何錯誤訊息★。2026-09-15 查出十題裡三題已被污染,其中兩題是
    被這套評測自己的設計文件寫進去的——沒人是故意的,寫的人只是把題目記下來。

    所以這條不能靠紀律,要靠這支測試:題庫一改、筆記一寫,都會在這裡翻紅。

    翻紅釘:把任一題的查詢原樣貼進任一篇筆記 → 本條翻紅並印出是哪一篇。"""
    _need_src("governance/eval/multiword/mw-pool.json", "docs/lumos-toolchain-knowledge")
    import json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    pool = _json.loads((repo / "governance" / "eval" / "multiword" / "mw-pool.json")
                       .read_text(encoding="utf-8"))
    vault = repo / "docs" / "lumos-toolchain-knowledge"
    docs = {}
    for f in vault.rglob("*.md"):
        try:
            docs[str(f.relative_to(vault))] = f.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
    check("題庫讀得到而且不是空的", len(pool) > 0, f"題數={len(pool)}")
    check("圖譜讀得到而且不是空的", len(docs) > 20, f"篇數={len(docs)}")
    dirty = []
    for cid in sorted(pool):
        q = pool[cid]["query"]
        hits = sorted(n for n, txt in docs.items() if q in txt)
        if hits:
            dirty.append(f"{cid}「{q}」出現在 {', '.join(hits[:3])}")
    check("★沒有任何一題的查詢逐字出現在圖譜裡★"
          "(出現了就代表那一題的兩臂會量出一樣的數字、測不到東西)",
          not dirty, "；".join(dirty))
    print("  ✓ t_mw_queries_absent_from_vault")


def t_mw_rebuild_pool_refuses_contamination():
    """重組候選池時碰到被污染的題要擋下來,不是照組。

    照組會產出一份「看起來正常、其實那題已經廢了」的池,而標註要花的是人的時間——
    等標完才發現白標,成本比擋下來高得多。

    翻紅釘:把 main() 裡「重組時不接受污染」那個 return 2 拿掉 → 第 3、4 條翻紅。"""
    _need_src("governance/eval/retrieval_eval_multiword.py")
    repo = Path(GRAPHCTL).resolve().parent.parent
    script = repo / "governance" / "eval" / "retrieval_eval_multiword.py"
    q = "斑馬 條紋 計數"

    vault, poolfile = _mk_mw_fixture(q, contaminate=False)
    out = Path(vault).parent / "pool-new.json"
    r = subprocess.run([sys.executable, str(script), "--pool", str(poolfile),
                        "--vault", str(vault), "--rebuild-pool", str(out)],
                       capture_output=True, text=True)
    check("乾淨的題庫組得起來", r.returncode == 0, f"rc={r.returncode}\n{r.stderr[-400:]}")
    check("組出來的檔真的有寫出去", out.exists(), str(out))

    vault2, poolfile2 = _mk_mw_fixture(q, contaminate=True)
    out2 = Path(vault2).parent / "pool-new.json"
    r2 = subprocess.run([sys.executable, str(script), "--pool", str(poolfile2),
                         "--vault", str(vault2), "--rebuild-pool", str(out2)],
                        capture_output=True, text=True)
    check("★查詢被寫進語料時,重組要擋下來(rc2)★", r2.returncode == 2,
          f"rc={r2.returncode}\n{r2.stdout[-300:]}\n{r2.stderr[-400:]}")
    check("★擋下來時要講出是哪一篇筆記污染的★,不然人不知道去改哪裡",
          "D.md" in r2.stderr, r2.stderr[-500:])
    check("擋下來就不准留下半份池檔", not out2.exists(), str(out2))
    print("  ✓ t_mw_rebuild_pool_refuses_contamination")


def t_mw_labels_accept_both_shapes():
    """標註檔兩種格式都要吃,而且吃出同一份結果(Issues/多詞評測吃錯標註檔直接拋例外)。

    同一個目錄裡兩份標註檔檔名只差一個字:一份扁平(節點→分數),一份含各評審意見
    (節點→{最終分, 各席分})。原本只吃扁平那份,餵另一份會拿字典去跟數字比大小、
    直接拋型別錯誤,而訊息完全沒提到是檔案拿錯。

    翻紅釘:把 load_labels 裡取最終分那一段拿掉 → 第 2 條翻紅(拋例外)。"""
    _need_src("governance/eval/retrieval_eval_multiword.py")
    import json as _json
    import importlib.util as _ilu
    repo = Path(GRAPHCTL).resolve().parent.parent
    spec = _ilu.spec_from_file_location(
        "_mw", repo / "governance" / "eval" / "retrieval_eval_multiword.py")
    mod = _ilu.module_from_spec(spec)
    spec.loader.exec_module(mod)
    root = Path(tempfile.mkdtemp(prefix="gctl-mwlab-"))
    flat = root / "flat.json"
    nested = root / "nested.json"
    flat.write_text(_json.dumps({"M01": {"Systems/A.md": 2, "Systems/B.md": 0}},
                                ensure_ascii=False), encoding="utf-8")
    nested.write_text(_json.dumps({"M01": {"Systems/A.md": {"final": 2, "claude": 2, "codex": 1},
                                           "Systems/B.md": {"final": 0, "claude": 0, "codex": 0}}},
                                  ensure_ascii=False), encoding="utf-8")
    a = mod.load_labels(str(flat))
    check("扁平格式讀得出來", a == {"M01": {"Systems/A.md": 2, "Systems/B.md": 0}}, repr(a))
    b = mod.load_labels(str(nested))
    check("★含各評審意見的格式也讀得出來,而且結果跟扁平一樣★", a == b, f"{a!r} vs {b!r}")
    # 未裁決的那種要當「沒標」,不能當 0 分——0 分是「判過,不相干」,兩者不同
    und = root / "und.json"
    und.write_text(_json.dumps({"M01": {"Systems/A.md": {"final": None, "claude": 1}}},
                               ensure_ascii=False), encoding="utf-8")
    c = mod.load_labels(str(und))
    check("★還沒裁決的不進標註★(當 0 分會讓沒判過的看起來像判過不相干)",
          c == {"M01": {}}, repr(c))
    # 合併與寫回沿用既有的標註工具,它產出的是「題庫外殼」那種形狀
    wrap = root / "wrap.json"
    wrap.write_text(_json.dumps({"search": [], "edit": [],
                                 "labels": {"M01": {"Systems/A.md": {"final": 2}}}},
                                ensure_ascii=False), encoding="utf-8")
    # ★用 try 包住★:讀不懂時那支是直接結束整個程式(SystemExit),不包的話
    # 這條一紅就會把整輪測試拖死,而不是乾淨地報一條紅(2026-09-15 翻紅釘時實測到)
    try:
        d = mod.load_labels(str(wrap))
    except SystemExit as e:
        d = f"讀不懂而直接結束:{e}"
    check("★題庫外殼那種形狀也讀得出來★(不然沿用既有寫回工具的產出會讀不進來)",
          d == {"M01": {"Systems/A.md": 2}}, repr(d))
    print("  ✓ t_mw_labels_accept_both_shapes")


def t_mw_pool_order_is_not_rank():
    """候選池的順序要打散,而且同一份輸入每次都一樣。

    池若照名次排,標註的人會先看到「系統認為最相關的」——標出來的答案就不再獨立於
    被它驗證的那套排序(跟 [S8] 同一條錨定路徑,那條在另一支腳本上已經修過)。
    可重現則是為了回溯:標註結果要對得回當初看的是哪一份順序。

    翻紅釘:把 rebuild_pool 裡的 shuffle 拿掉 → 第 2 條翻紅(順序=名次序)。"""
    _need_src("governance/eval/retrieval_eval_multiword.py")
    import json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    script = repo / "governance" / "eval" / "retrieval_eval_multiword.py"
    q = "斑馬 條紋 計數"
    vault, poolfile = _mk_mw_fixture(q, contaminate=False, extra=8)   # r1 測試品質席:3 筆太少,洗牌可能剛好等於名次序
    o1 = Path(vault).parent / "p1.json"
    o2 = Path(vault).parent / "p2.json"
    for o in (o1, o2):
        r = subprocess.run([sys.executable, str(script), "--pool", str(poolfile),
                            "--vault", str(vault), "--rebuild-pool", str(o)],
                           capture_output=True, text=True)
        check(f"組得起來({o.name})", r.returncode == 0, r.stderr[-300:])
    p1 = _json.loads(o1.read_text(encoding="utf-8"))["M01"]["pool"]
    p2 = _json.loads(o2.read_text(encoding="utf-8"))["M01"]["pool"]
    # 名次序=拆詞那一臂自己回的順序
    rank = mw_rank_order(script, vault, q)
    check("夾具有撈到東西,不然這條測不到", len(p1) >= 3, f"池={p1}")
    check("★池的順序不是名次序★", p1 != rank[:len(p1)], f"池={p1} 名次={rank}")
    check("★同一份輸入跑兩次順序一樣★(標註要回溯得到當初看的是什麼)",
          p1 == p2, f"{p1} vs {p2}")
    check("兩次組出來的內容也一樣", sorted(p1) == sorted(p2), f"{sorted(p1)} vs {sorted(p2)}")
    print("  ✓ t_mw_pool_order_is_not_rank")


def mw_rank_order(script, vault, q):
    """拆詞那一臂自己回的順序(給上面那條比對用)。"""
    import importlib.util as _ilu
    spec = _ilu.spec_from_file_location("_mw2", script)
    mod = _ilu.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod.search_files(str(vault), q, any_terms=True)



def t_mw_pool_three_sources_all_contribute():
    """三個來源各自都要真的貢獻候選,少一個要看得出來。

    出身(2026-09-15 代碼審 r1 測試品質席):席位把來源二與來源三整個清空,
    ★四支既有測試照樣全綠★——也就是這批改動的核心行為(三來源聯集,為的是
    不要只標得到現行系統找得到的)完全沒有測試守著。

    翻紅釘:把 rebuild_pool 裡逐詞那一段或全詞同篇那一段的結果改成空清單
    → 對應的那條斷言翻紅。"""
    _need_src("governance/eval/retrieval_eval_multiword.py")
    import json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    script = repo / "governance" / "eval" / "retrieval_eval_multiword.py"
    q = "斑馬 條紋 計數"
    vault, poolfile = _mk_mw_fixture(q, contaminate=False, extra=14)  # 夠多才切得到「拆詞臂前十」的上限,聯集才看得出來
    out = Path(vault).parent / "pool3.json"
    r = subprocess.run([sys.executable, str(script), "--pool", str(poolfile),
                        "--vault", str(vault), "--rebuild-pool", str(out)],
                       capture_output=True, text=True)
    check("組得起來", r.returncode == 0, f"rc={r.returncode}\n{r.stderr[-400:]}")
    if r.returncode != 0:
        print("  ✓ t_mw_pool_three_sources_all_contribute")
        return
    v = _json.loads(out.read_text(encoding="utf-8"))["M01"]
    check("★逐詞那個來源有撈到東西★(它是不經排序器的獨立來源,空了等於只標得到現行系統找得到的)",
          v["n_term"] > 0, _json.dumps(v, ensure_ascii=False))
    check("★全詞同篇那個來源有撈到東西★", v["n_cooccur"] > 0, _json.dumps(v, ensure_ascii=False))
    check("拆詞臂那個來源有撈到東西", v["n_any"] > 0, _json.dumps(v, ensure_ascii=False))
    # ★這裡不能斷言「池比任一來源大」★:小語料裡拆詞臂本來就可能涵蓋全部,
    # 那不是這段程式保證得了的性質(2026-09-15 寫這條時第一版就是這樣寫錯的)。
    # 能保證的是聯集的上下界:不小於最大的單一來源、不大於三者相加。
    check("池不小於最大的單一來源(聯集的下界)",
          v["n_pool"] >= max(v["n_any"], v["n_term"], v["n_cooccur"]),
          _json.dumps(v, ensure_ascii=False))
    check("池不大於三個來源相加(聯集的上界;超過代表有重複沒去掉)",
          v["n_pool"] <= v["n_any"] + v["n_term"] + v["n_cooccur"],
          _json.dumps(v, ensure_ascii=False))
    print("  ✓ t_mw_pool_three_sources_all_contribute")


def t_mw_measure_path_also_blocks_contamination():
    """量測那條路碰到污染也要擋,不是只印警告就照算。

    出身(2026-09-15 代碼審 r1,資安席與正確性席各自抓到):原本只在重組候選池時
    ★擋★,量測時只往 stderr 印一行就繼續算,把 stderr 丟掉就完全看不出來——
    ★而量測正是產出治理數字的那條路★,守衛漏在這裡等於沒有守到要守的東西。

    翻紅釘:把 main 裡量測路徑那個 return 2 拿掉 → 第 1、2 條翻紅。"""
    _need_src("governance/eval/retrieval_eval_multiword.py")
    import json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    script = repo / "governance" / "eval" / "retrieval_eval_multiword.py"
    q = "斑馬 條紋 計數"
    vault, poolfile = _mk_mw_fixture(q, contaminate=True)
    pool = _json.loads(Path(poolfile).read_text(encoding="utf-8"))
    pool["M01"]["pool"] = ["Systems/A.md", "Systems/B.md"]
    Path(poolfile).write_text(_json.dumps(pool, ensure_ascii=False), encoding="utf-8")
    labf = Path(vault).parent / "lab.json"
    labf.write_text(_json.dumps({"M01": {"Systems/A.md": 2, "Systems/B.md": 0}},
                                ensure_ascii=False), encoding="utf-8")
    r = subprocess.run([sys.executable, str(script), "--labels", str(labf),
                        "--pool", str(poolfile), "--vault", str(vault)],
                       capture_output=True, text=True)
    check("★量測路徑碰到污染要擋(rc2)★,不是印個警告就照算", r.returncode == 2,
          f"rc={r.returncode}\n{r.stdout[-300:]}")
    check("★把 stderr 丟掉之後,標準輸出裡不得出現看起來正常的分數★"
          "(原本的洞就是這個:2>/dev/null 之後完全看不出有污染)",
          "整體" not in r.stdout, r.stdout[-400:])
    r2 = subprocess.run([sys.executable, str(script), "--labels", str(labf),
                         "--pool", str(poolfile), "--vault", str(vault),
                         "--allow-contaminated"], capture_output=True, text=True)
    check("明著說要跑污染的題時跑得起來(留一條刻意重現舊結果的路)",
          r2.returncode == 0, f"rc={r2.returncode}\n{r2.stderr[-300:]}")
    # ★2026-09-15 r2 折入後改了位置★:那句警語從錯誤輸出搬到報告本體
    # (資安席:只印在錯誤輸出的話,把錯誤輸出丟掉就跟乾淨結果一字不差)。
    # 這條斷言跟著改成看標準輸出;細節由 t_mw_escape_hatch_cannot_reach_rebuild 守。
    check("而且要在報告本體裡講明那些分數不得當證據",
          "不得當成證據" in r2.stdout, r2.stdout[:300])
    print("  ✓ t_mw_measure_path_also_blocks_contamination")


def t_mw_atomic_write_is_symlink_safe():
    """寫檔的暫存名不可預測、不跟著符號連結走、換名保留原權限。

    出身(2026-09-15 代碼審 r1,資安席實跑重現):原本用固定的「<輸出>.tmp」。
    資安席先把那個固定名字建成指向別的檔的符號連結,再跑一次重組,
    ★受害檔被整個覆寫,而工具印的是成功★。這個 repo 已經為同一個反模式
    付過兩次學費(標註刷新那支、主程式那支),兩處的正解都是不可預測的暫存名。

    翻紅釘:把 write_json_atomic 改回固定的 path.with_suffix(...+'.tmp')
    → 第 2 條翻紅(受害檔被覆寫)。"""
    _need_src("governance/eval/retrieval_eval_multiword.py")
    import importlib.util as _ilu
    repo = Path(GRAPHCTL).resolve().parent.parent
    spec = _ilu.spec_from_file_location(
        "_mw3", repo / "governance" / "eval" / "retrieval_eval_multiword.py")
    mod = _ilu.module_from_spec(spec)
    spec.loader.exec_module(mod)
    root = Path(tempfile.mkdtemp(prefix="gctl-mwatomic-"))
    victim = root / "victim.txt"
    victim.write_text("原本的內容不可以被動到", encoding="utf-8")
    out = root / "out.json"
    # 把「固定暫存名」那個位置先佔成指向受害者的符號連結
    trap = root / "out.json.tmp"
    try:
        trap.symlink_to(victim)
    except OSError:
        # ★跳過要用 _SrcOnly,不能 return★:這個 repo 有一支後設測試在擋
        # 「一條斷言都沒跑就 return」的測試(那種在某些機器上會變成永遠不驗)
        raise _SrcOnly("這個系統建不了符號連結,這條驗不了(非失敗)")
    mod.write_json_atomic(str(out), {"a": 1})
    check("正常寫得出去", out.is_file() and not out.is_symlink(), str(out))
    check("★受害檔沒有被動到★(暫存名可預測時,這裡會被整個覆寫成 JSON)",
          victim.read_text(encoding="utf-8") == "原本的內容不可以被動到",
          victim.read_text(encoding="utf-8")[:80])
    # 覆寫既有檔要保留原權限
    out.chmod(0o600)
    mod.write_json_atomic(str(out), {"a": 2})
    check("★覆寫既有檔時保留原權限★(原本會被換成新建檔的權限,實測 600 變 644)",
          (out.stat().st_mode & 0o777) == 0o600, oct(out.stat().st_mode & 0o777))
    check("內容真的換新了", "2" in out.read_text(encoding="utf-8"), out.read_text(encoding="utf-8"))
    print("  ✓ t_mw_atomic_write_is_symlink_safe")


def t_mw_bad_input_says_what_is_wrong():
    """壞掉的輸入要講人話,不是拋看不懂的例外、也不是安靜產出空東西。

    出身(2026-09-15 代碼審 r1 邊界席,每一條都實跑重現過):
      ①題庫某題缺查詢欄位 → 原本拋 KeyError
      ②查詢只有空白 → 原本在取最小值時崩潰
      ③標註值是字串 → 原本在算分深處拋 TypeError
      ④語料路徑打錯 → ★原本印「重組好了」而且退出碼 0,0 筆候選★(最危險的一種)

    翻紅釘:把 main 裡那幾道前置檢查各拿掉一道 → 對應那條翻紅。"""
    _need_src("governance/eval/retrieval_eval_multiword.py")
    import json as _json
    repo = Path(GRAPHCTL).resolve().parent.parent
    script = repo / "governance" / "eval" / "retrieval_eval_multiword.py"
    vault, poolfile = _mk_mw_fixture("斑馬 條紋 計數")
    root = Path(vault).parent

    def run(pool_obj=None, vault_path=None, labels_obj=None, rebuild=True):
        pf = root / "p.json"
        pf.write_text(_json.dumps(pool_obj if pool_obj is not None else
                                  _json.loads(Path(poolfile).read_text(encoding="utf-8")),
                                  ensure_ascii=False), encoding="utf-8")
        args = [sys.executable, str(script), "--pool", str(pf),
                "--vault", str(vault_path or vault)]
        if rebuild:
            args += ["--rebuild-pool", str(root / "o.json")]
        else:
            lf = root / "l.json"
            lf.write_text(_json.dumps(labels_obj, ensure_ascii=False), encoding="utf-8")
            args += ["--labels", str(lf)]
        return subprocess.run(args, capture_output=True, text=True)

    r = run(pool_obj={"M01": {"pool": []}})
    check("★缺查詢欄位:要講人話不是拋看不懂的例外★",
          r.returncode == 2 and "查詢字串" in (r.stderr + r.stdout),
          f"rc={r.returncode}\n{r.stderr[-200:]}")
    r = run(pool_obj={"M01": {"query": "   ", "pool": []}})
    check("★查詢只有空白:要擋下來不是崩潰★",
          r.returncode == 2 and "Traceback" not in r.stderr,
          f"rc={r.returncode}\n{r.stderr[-200:]}")
    r = run(vault_path=root / "沒這個目錄")
    check("★語料路徑打錯:要擋下來★(原本印「重組好了」而且退出碼 0,是最危險的一種)",
          r.returncode == 2 and "語料目錄" in r.stderr,
          f"rc={r.returncode}\n{r.stdout[-200:]}{r.stderr[-200:]}")
    r = run(rebuild=False, labels_obj={"M01": {"Systems/A.md": "2"}})
    check("★標註值是字串:要講清楚哪一筆不對★",
          r.returncode != 0 and "整數" in (r.stderr + r.stdout),
          f"rc={r.returncode}\n{r.stderr[-200:]}")
    print("  ✓ t_mw_bad_input_says_what_is_wrong")



def t_mw_escape_hatch_cannot_reach_rebuild():
    """那個逃生旗標不得用在重組候選池,而且用在量測時要印在報告本體裡。

    出身(2026-09-15 代碼審 r2):
      ①折入驗收席實測——原本量測與重組共用同一道閘,加了旗標連重組都照組,
        ★而且把造成污染的那篇筆記收進池裡★,等於把壞掉的題目烤進資料,
        後面每一次量測都繼承。
      ②資安席實測——用了旗標之後,標準輸出跟乾淨結果★一字不差★,警告只在
        錯誤輸出;遇到擋就加旗標讓它變綠,事後從報告完全看不出來。

    翻紅釘:把重組那道 return 2 拿掉 → 第 1、2 條翻紅;
            把報告本體那句警語拿掉 → 第 4 條翻紅。"""
    _need_src("governance/eval/retrieval_eval_multiword.py")
    repo = Path(GRAPHCTL).resolve().parent.parent
    script = repo / "governance" / "eval" / "retrieval_eval_multiword.py"
    import json as _json
    q = "斑馬 條紋 計數"
    vault, poolfile = _mk_mw_fixture(q, contaminate=True)
    out = Path(vault).parent / "bypass.json"
    r = subprocess.run([sys.executable, str(script), "--pool", str(poolfile),
                        "--vault", str(vault), "--rebuild-pool", str(out),
                        "--allow-contaminated"], capture_output=True, text=True)
    check("★逃生旗標不得讓重組通過★", r.returncode == 2,
          f"rc={r.returncode}\n{r.stdout[-300:]}")
    check("★擋下來就不准留下池檔★(留了就等於把壞掉的題目烤進資料)",
          not out.exists(), str(out))
    # 量測那條:旗標仍可用,但要印在報告本體
    pool = _json.loads(Path(poolfile).read_text(encoding="utf-8"))
    pool["M01"]["pool"] = ["Systems/A.md", "Systems/B.md"]
    Path(poolfile).write_text(_json.dumps(pool, ensure_ascii=False), encoding="utf-8")
    labf = Path(vault).parent / "lab2.json"
    labf.write_text(_json.dumps({"M01": {"Systems/A.md": 2, "Systems/B.md": 0}},
                                ensure_ascii=False), encoding="utf-8")
    r2 = subprocess.run([sys.executable, str(script), "--labels", str(labf),
                         "--pool", str(poolfile), "--vault", str(vault),
                         "--allow-contaminated"], capture_output=True, text=True)
    check("量測那條仍可用逃生旗標(要留一條重現舊結果的路)", r2.returncode == 0,
          f"rc={r2.returncode}\n{r2.stderr[-300:]}")
    check("★而且要印在報告本體裡★,不是只印在錯誤輸出"
          "(把錯誤輸出丟掉就看不出來的話,這個旗標等於沒有痕跡)",
          "不得當成證據" in r2.stdout, r2.stdout[:400])
    check("報告本體要逐題列出受影響的是哪幾題", "M01" in r2.stdout, r2.stdout[:400])
    print("  ✓ t_mw_escape_hatch_cannot_reach_rebuild")


def t_mw_atomic_write_does_not_widen_perms():
    """目標若是符號連結,不得把連結那組幾乎全開的權限抄到產出的檔上。

    出身(2026-09-15 代碼審 r2 資安席實測):修 r1 那條時加了「覆寫既有檔要保留原權限」,
    但讀權限用的是不解參照的方式——目標若是預先埋好的符號連結,讀到的是★連結自己★
    那組裝飾性位元(某些系統固定回報全開),抄過來會讓產出的檔權限被放寬,
    而且照印成功。內容沒有被寫穿(換名是整個替換、不解參照),被放寬的是權限。

    翻紅釘:把「只有普通檔才抄權限」那個判斷拿掉 → 第 2 條翻紅。"""
    _need_src("governance/eval/retrieval_eval_multiword.py")
    import importlib.util as _ilu
    import os as _os
    repo = Path(GRAPHCTL).resolve().parent.parent
    spec = _ilu.spec_from_file_location(
        "_mw4", repo / "governance" / "eval" / "retrieval_eval_multiword.py")
    mod = _ilu.module_from_spec(spec)
    spec.loader.exec_module(mod)
    root = Path(tempfile.mkdtemp(prefix="gctl-mwperm-"))
    victim = root / "victim.txt"
    victim.write_text("受害者", encoding="utf-8")
    victim.chmod(0o600)
    out = root / "out.json"
    try:
        out.symlink_to(victim)          # 輸出路徑本身先被埋成符號連結
    except OSError:
        # ★跳過要用 _SrcOnly,不能 return★:這個 repo 有一支後設測試在擋
        # 「一條斷言都沒跑就 return」的測試(那種在某些機器上會變成永遠不驗)
        raise _SrcOnly("這個系統建不了符號連結,這條驗不了(非失敗)")
    # ★斷言不能挑「全世界可寫」這個症狀★:符號連結的權限位元在不同系統回報不一樣
    # (這台量到 0o755、另一種系統是 0o777),挑症狀的話在前者就永遠是綠的——
    # 2026-09-15 第一版就是這樣寫的,翻紅釘當場顯示「拆了還綠」。
    # 改成直接斷言「產出的檔沒有沿用連結那組位元」,跟平台無關。
    link_mode = _os.lstat(out).st_mode & 0o777
    mod.write_json_atomic(str(out), {"a": 1})
    check("寫得出去而且把連結整個換成普通檔", out.is_file() and not out.is_symlink(), str(out))
    got = out.stat().st_mode & 0o777
    check("★產出的檔不得沿用符號連結那組權限★",
          got != link_mode, f"連結={oct(link_mode)} 產出={oct(got)}")
    check("受害檔的內容沒有被寫穿", victim.read_text(encoding="utf-8") == "受害者",
          victim.read_text(encoding="utf-8")[:40])
    print("  ✓ t_mw_atomic_write_does_not_widen_perms")



def t_rel_cascade_visited_only_for_empty():
    """★空的連鎖待辦單要能銷帳,但有待辦的不准用這個動詞閉嘴★
    (Issues/空連鎖單巡過無法銷帳;2026-09-01 Enzo 委任裁辦,2026-09-16 做)。

    背景:決策翻案會自動開一張「去看看誰還引用舊決策」的待辦單。單如果★天生是空的★
    (翻案當下沒人引用),就沒有東西可判——但體檢認「有判定才算看過」,於是空單會被
    嘮叨到天荒地老,嘮叨久了人就學會忽略(提醒麻痺)。2026-09-16 實測 15 張零判定的單
    裡★14 張是空的★,正好命中那篇 Issue 自己寫的升級條件「又一張空票出現」。

    ★這個動詞唯一的危險是變成萬用消音鍵★:所以「空不空」必須★當場機械驗★
    ——重放帳本、展開待判鄰居,真的一個都沒有才准記。呼叫的人說了不算。

    翻紅釘:把 visited 的空集合檢查拿掉(改成無條件記) → 第 4 條翻紅
    (有待judging 的單也被消音);把 visited 動詞整個拿掉 → 第 1、2 條翻紅。"""
    v = mkvault()
    write(v, "Projects/決策源.md", "type: project\nstatus: done")
    lm = _lm(); env = lm.Env(v)
    gid = "Projects/決策源.md#d1"

    # ① 天生空的單:沒有任何筆記引用那個決策
    cid_empty = lm.rel_cascade_create(env, gid, "Projects/決策源.md")
    p_empty = v / "governance" / "rel-cascade" / (cid_empty + ".jsonl")
    _, tr = lm._ledger_read(p_empty)
    check("★前置★ 現場成立:這張單真的是空的(零筆判定)", not tr, str(tr))
    r = run(v, "rel-cascade", "visited", "--cascade-id", cid_empty, "--from", gid, expect_rc=0)
    _, tr2 = lm._ledger_read(p_empty)
    check("★空單巡過之後帳本有一筆事件★(體檢數的是有沒有事件,有了就不再嘮叨)",
          len(tr2) == 1, str(tr2))
    check("那筆事件要標成巡過,不能假裝成判定過某個鄰居",
          tr2 and tr2[0].get("event") == "visited", str(tr2))

    # ② 有待判鄰居的單:不准用這個動詞消音
    write(v, "Systems/鄰居甲.md",
          "type: system\nstatus: done\nverified_by:\n  - \"[[Projects/決策源]]\"")
    env2 = lm.Env(v)
    cid_busy = lm.rel_cascade_create(env2, gid, "Projects/決策源.md")
    p_busy = v / "governance" / "rel-cascade" / (cid_busy + ".jsonl")
    r2 = run(v, "rel-cascade", "visited", "--cascade-id", cid_busy, "--from", gid, expect_rc=2)
    _, tr3 = lm._ledger_read(p_busy)
    check("★有待判鄰居時要擋下來★(否則這個動詞會變成萬用消音鍵)",
          not tr3, f"帳本被寫了:{tr3}")
    check("擋下來時要講出還剩幾篇要判",
          "鄰居" in (r2.stdout + r2.stderr) or "待判" in (r2.stdout + r2.stderr),
          (r2.stdout + r2.stderr)[-300:])

    # ③ ★巡過紀錄不准混進判定狀態★(r1 外家席 c1)。原本的說法是「visited 沒有鄰居與
    #   邊型欄位,折疊會自動略過」——那只是★寫入端的慣例★,讀取端一個字都沒保證。
    #   帳本是 append-only 的純文字,任何一筆手改或別的工具寫進來的 visited 只要帶齊
    #   三個粒度欄位,就會蓋掉真正的待判狀態,空單守衛跟著放行。
    fold = lm._ledger_fold
    key = {"neighbor": "Systems/鄰居甲.md", "edge_type": "verified_by",
           "from_decision_id": gid}
    only_pending = [dict(key, event="transition", state="pending")]
    check("★前置★ 現場成立:只有一筆待判時,折疊結果就是那筆待判",
          [t2.get("state") for t2 in fold(only_pending).values()] == ["pending"],
          str(fold(only_pending)))
    mixed = only_pending + [dict(key, event="visited", state="confirmed")]
    check("★帶著粒度欄位的巡過紀錄不得蓋掉待判狀態★(否則它變成萬用消音鍵)",
          [t2.get("state") for t2 in fold(mixed).values()] == ["pending"],
          str(fold(mixed)))

    # ④ ★展不開不等於空★(r1 外家席 c2):起點筆記被刪掉或改名之後,展開鄰居會得到
    #   零筆——但那是「問不到」,不是「真的沒人引用」。當成空單放行等於把還沒確認完的
    #   待辦悄悄消掉。
    cid_gone = lm.rel_cascade_create(lm.Env(v), gid, "Projects/決策源.md")
    (v / "Projects" / "決策源.md").unlink()
    r3 = run(v, "rel-cascade", "visited", "--cascade-id", cid_gone, "--from", gid, expect_rc=2)
    _, tr4 = lm._ledger_read(v / "governance" / "rel-cascade" / (cid_gone + ".jsonl"))
    check("★起點筆記不存在時要擋★(展不開是問不到,不是沒東西可判)",
          not tr4, f"帳本被寫了:{tr4}")
    check("擋下來時要講出是起點不見了,不要只說空單",
          "起點" in (r3.stdout + r3.stderr), (r3.stdout + r3.stderr)[-300:])
    print("  ✓ t_rel_cascade_visited_only_for_empty")



def t_lint_warns_empty_revalidate_when():
    """★驗證紀錄的「什麼時候要回頭重驗」欄位空著,lint 要出聲★
    (Issues/lint不守驗證紀錄空回頭條件;2026-09-01 Enzo 委任裁辦,2026-09-16 做)。

    出身:某一天五篇驗證★全★把回頭條件寫進正文、欄位留空,於是掃描工具全掃不到、
    lint 全綠放行——鐵則四「承認風險要附回頭看的條件」被靜默架空而沒有任何機械提醒。
    是審查席讀出來的,不是工具抓到的。

    ★只出 warning 不擋★(修法本來就這樣裁):舊帳很多,擋了等於每個提交都紅;
    warning 的作用是讓寫的人當下看到,不是回頭清舊帳。

    ★只對 type=verification 且 status=pass 的★:其他型別沒有這兩個欄位;
    status 不是 pass 的(stale/fail)本來就還在處理中,不必催。

    翻紅釘:把那段檢查拿掉 → 第 2、3 條翻紅。"""
    v = mkvault()
    # ① 兩欄都有值:不該叫
    write(v, "Verification/有寫的.md",
          "type: verification\nstatus: pass\nvalid_under: 在某某前提下\n"
          "revalidate_when: 改到某某的時候")
    r = run(v, "lint", "有寫的", expect_rc=0)
    check("兩欄都有值時不出聲(不要製造雜訊)",
          "回頭" not in r.stdout and "重驗" not in r.stdout, r.stdout[:200])
    # ② 回頭條件空:要叫
    write(v, "Verification/沒寫的.md",
          "type: verification\nstatus: pass\nvalid_under: 在某某前提下\nrevalidate_when:")
    r = run(v, "lint", "沒寫的", expect_rc=0)
    check("★回頭條件空著要出聲★(空著=掃描工具永遠掃不到,鐵則被靜默架空)",
          "重驗" in r.stdout or "回頭" in r.stdout, r.stdout[:300])
    # ③ 前提空:也要叫
    write(v, "Verification/前提空的.md",
          "type: verification\nstatus: pass\nvalid_under:\nrevalidate_when: 改到某某的時候")
    r = run(v, "lint", "前提空的", expect_rc=0)
    # ★斷言不可以命中檔名★(r1 外家席 c4、單reviewer 席同題):lint 的第一行固定印節點
    # 路徑,案例叫「前提空的」就讓「前提」兩個字恆真——把整段檢查拆掉它照樣綠。
    # 比對警告本身講的欄位名才有鑑別力。
    check("★前提欄空著也要出聲★(不寫前提=不知道這個結論在什麼條件下才算數)",
          "valid_under 是空的" in r.stdout, r.stdout[:300])
    # ④ 只是提醒,不能擋
    check("★只出提醒不擋★(舊帳很多,擋了等於每個提交都紅)", r.returncode == 0, str(r.returncode))
    # ⑥ ★全部項目都是空白字串的清單★(r1 外家席 c3):它是非空 list,轉成字串之後
    #    帶著括號與引號,舊寫法會判成「有寫」——但掃描端逐項去空白後拿到的是零條,
    #    等於還是掃不到。判空要跟掃描端用同一支 helper。
    write(v, "Verification/全空白的.md",
          "type: verification\nstatus: pass\nvalid_under:\n  - \"\"\n  - \"   \"\n"
          "revalidate_when:\n  - \"\"\n  - \"   \"")
    r = run(v, "lint", "全空白的", expect_rc=0)
    check("★清單裡全是空白字串也算沒寫★(掃描端逐項去空白後拿到零條)",
          "valid_under 是空的" in r.stdout and "revalidate_when 是空的" in r.stdout,
          r.stdout[:400])

    # ⑤ 別的型別不該被這條叫到
    write(v, "Systems/別的型別.md",
          "type: system\nstatus: done\nsummary: |-\n  FLOW:甲到乙\n  KEY:重點一句")
    r = run(v, "lint", "別的型別", expect_rc=0)
    check("其他型別不適用這條(它們沒有這兩個欄位)",
          "重驗" not in r.stdout, r.stdout[:200])
    print("  ✓ t_lint_warns_empty_revalidate_when")



# ─── 規格落成可驗收條件_計劃(半套):lumos spec-gate + 處置閘第五步共用檢查器 ───

def _mk_spec_gate_repo(d, run_cmd="python3 tests/run.py {method}"):
    """半套規格閘 fixture:git repo + .lumos/config.json + 假測試執行器(印「lumos 測試(N 案例)」,支數由方法名決定:
    t_red → 1 支紅;t_green → 1 支綠;t_multi → 2 支;t_zero → 0 支;t_skip → 1 支但 skipped)+ vault docs/x-knowledge。"""
    import subprocess as _sp, json as _j
    d = Path(d)
    _sp.run(["git", "init", "-q", str(d)])
    (d / "tests").mkdir()
    # ★t_multi 旁邊真的要有第二支名字含它的測試★:篩選是子字串比對,「匹配到兩支」指的是
    # 真的有兩支不同的測試被選到。只宣告一支卻回報兩個案例,那是同一支測試的多組輸入(參數化),
    # 不是撞名——fixture 不擺出真正的撞名,那條測試就是在驗一個不存在的情境。
    (d / "tests" / "test_x.py").write_text("def t_red():\n    assert False\n\ndef t_green():\n    assert True\n\ndef t_red2():\n    assert False\n\ndef t_green2():\n    assert True\n\ndef t_flip():\n    pass\n\ndef t_multi():\n    pass\n\ndef t_multi_extra():\n    pass\n\ndef t_param():\n    pass\n\ndef t_nested():\n    pass\n\nclass TestGroup:\n    def t_nested_inner(self):\n        pass\n\ndef t_doc():\n    \"\"\"說明裡夾一段縮排的程式範例:\n\n        def t_doc_helper():\n            pass\n    \"\"\"\n    pass\n\ndef t_zero():\n    pass\n\ndef t_skip():\n    pass\n", encoding="utf-8")
    (d / "tests" / "run.py").write_text(
        "import sys\n"
        "m = sys.argv[1] if len(sys.argv) > 1 else ''\n"
        "import os\n"
        "table = {'t_red': (1, '0 passed, 1 failed', 1), 't_green': (1, '3 passed, 0 failed', 0), 't_multi': (2, '2 passed, 0 failed', 0),\n"
        "         't_red2': (1, '0 passed, 1 failed', 1), 't_green2': (1, '1 passed, 0 failed', 0), 't_flip': (1, '1 passed, 0 failed', 0) if os.path.exists('tests/flip.ok') else (1, '0 passed, 1 failed', 1),\n"
        "         't_zero': (0, '0 passed, 0 failed', 0), 't_skip': (1, '0 passed, 0 failed (skipped=1)', 0),\n"
        "         't_multi_extra': (1, '1 passed, 0 failed', 0), 't_param': (9, '9 passed, 0 failed', 0),\n"
        "         't_nested': (2, '2 passed, 0 failed', 0), 't_doc': (9, '9 passed, 0 failed', 0)}\n"
        "if m not in table:\n    print('no such test', m); sys.exit(2)\n"
        "n, line, rc = table[m]\n"
        "print(f'lumos 測試({n} 案例)')\nprint(line)\nsys.exit(rc)\n", encoding="utf-8")
    (d / ".lumos").mkdir()
    cfg = {"test_profile": "python", "test": {"method_regex": "(?m)^def (t_[A-Za-z0-9_]+)\\s*\\("}}
    if run_cmd:
        cfg["test"]["run_cmd"] = run_cmd
    (d / ".lumos" / "config.json").write_text(_j.dumps(cfg), encoding="utf-8")
    kg = d / "docs" / "x-knowledge"; (kg / "Projects").mkdir(parents=True)
    _sp.run(["git", "-C", str(d), "add", "-A"]); _sp.run(["git", "-C", str(d), "-c", "user.email=t@t", "-c", "user.name=t", "commit", "-qm", "base", "--no-verify"])
    return d, kg


_SG_ROLLBACK = "\n## 回退\n把處置閘第五步改回上一版,指令保留只印不擋,紀律那句改回舊寫法。\n"


def _sg_plan(kg, name, clauses, rollback=_SG_ROLLBACK):
    p = kg / "Projects" / f"{name}_計劃.md"
    p.write_text("---\ntype: project\nstatus: doing\n---\n# " + name + "\n\n" + "\n".join(clauses) + "\n" + rollback, encoding="utf-8")
    return p


