    r = run(kg7, "spec-gate", "--push-check", "HEAD~1..HEAD", "--repo", str(d7))
    check("⑫ 程式檔搬進卷證目錄 → 不豁免,落點外擋", r.returncode == 1 and "落點外" in r.stdout and "governance/replay/run.py" in r.stdout, r.stdout[-500:])
    d8, kg8, p8 = _sc_setup("sc8")
